INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8ee4aa69-44e4-4d40-9cde-af0d59cc6b99', 'es-MX', '1', '{"meta": {"cast": ["dina", "zara", "liruf"], "slug": "true-false", "title": "Cierto o falso: el ahorro crece", "locale": "es-MX", "subject": "mixed", "objectives": ["Decidir si es cierto o falso: ''Si guardo 5 pesos de cada venta, mi ahorro CRECE cada día''."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-true-false", "xp": 10, "type": "true_false", "hints": ["Piensa: si cada día guardas 5 pesos, ¿tienes más o menos que el día anterior?", "El ahorro es lo que has juntado. Si cada día agregas dinero, ¿qué pasa con el total?"], "title": "¿Cierto o falso?", "payload": {"statement_md": "Si guardo 5 pesos de cada venta, mi ahorro CRECE cada día.", "justifications": [{"id": "cierto", "text_md": "Es cierto, porque cada día agrego 5 pesos, así que el total siempre es mayor."}, {"id": "falso", "text_md": "Es falso, porque a veces gasto el ahorro y no crece."}]}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Zara dice: ''Si guardo 5 pesos de cada venta, mi ahorro CRECE cada día''. ¿Es cierto o falso?", "difficulty": 1, "explanation_md": "Es cierto. Si guardas 5 pesos cada día, el total de tu ahorro siempre aumenta. Por ejemplo, el lunes tienes 5, el martes 10, el miércoles 15… ¡crece cada día!", "audio_segment_id": "s1-true-false.prompt"}], "schema_version": 1}', '{"s1-true-false": {"is_true": true, "correct_justification_id": "cierto"}}', '{"units": {"s1-true-false.hint.0": {"url": "http://localhost:4006/files/lesson-audio/586c5f4df3cecbf5dfb8aa669e13fea5c72f4920391cb694104a61bf7baa6e34.mp3", "hash": "7bfb362245ebd9237e64b26d19cc2e932a3a7674981ae343bcf176b2eb629bbb", "bytes": 29664, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/586c5f4df3cecbf5dfb8aa669e13fea5c72f4920391cb694104a61bf7baa6e34.mp3", "duration_ms": 4880}, "s1-true-false.hint.1": {"url": "http://localhost:4006/files/lesson-audio/f18d420c97bb22631d19a15262a426e07cb89a33fbae61c39dfa828853461f73.mp3", "hash": "ebfa9e20759e5b878d0fc2aab0cb8d59158b10af0cf2e1e1fbd736d660e7599d", "bytes": 31968, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/f18d420c97bb22631d19a15262a426e07cb89a33fbae61c39dfa828853461f73.mp3", "duration_ms": 5280}, "s1-true-false.prompt": {"url": "http://localhost:4006/files/lesson-audio/a815047e0de81095d8e1948a2d640c93c98ac9df5b2f7e437da18b63d6c2f752.mp3", "hash": "272e55567672a357adf94c9b019f0750001db7b4402d76402c7ca1af544d77dd", "bytes": 38304, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/a815047e0de81095d8e1948a2d640c93c98ac9df5b2f7e437da18b63d6c2f752.mp3", "duration_ms": 6320}, "s1-true-false.explanation": {"url": "http://localhost:4006/files/lesson-audio/6ba213ed56de8891e4c7ca0d8e92c032b5af428ae0a0ee6128e66bf94dac31e1.mp3", "hash": "763d5936357d73b54bebb9e1e11302e11ea801f14bddda2c68840881c8f99db5", "bytes": 67968, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/6ba213ed56de8891e4c7ca0d8e92c032b5af428ae0a0ee6128e66bf94dac31e1.mp3", "duration_ms": 11280}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c5c3f5b2-2c4b-4aa8-bd76-cdcb594e0dda', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "concept-reveal", "title": "Earning money starts with an idea", "locale": "en-US", "subject": "money", "objectives": ["Understanding that money is earned by offering something others want", "Identifying that a clear goal helps you get started", "Distinguishing between cost and profit"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-concept-reveal", "xp": 0, "type": "concept_reveal", "hints": ["Think about what Liruf spends to make the lemonade.", "What''s left after paying for the ingredients is the profit."], "title": "Cost and profit", "payload": {"cards": [{"icon": "local_atm", "back_md": "What you spend on lemons and sugar", "front_md": "Cost", "image_url": "http://localhost:4006/files/lesson-images/d6f48f33fa608198b2c20b6afa212a677ca0cd35b4dcb2c3f55a5c1e47672281.webp"}, {"icon": "monetization_on", "back_md": "What you have left after paying the cost", "front_md": "Profit", "image_url": "http://localhost:4006/files/lesson-images/94135d4a5cbd3fb921f55d1010664b2074cd4129c3d1d53c9fb8633f6c0120ca.webp"}]}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Tap the cards to discover what ''cost'' and ''profit'' mean.", "difficulty": 1, "explanation_md": "Cost is what you spend on lemons and sugar. Profit is what you have left after paying the cost.", "audio_segment_id": "s1-concept-reveal.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-concept-reveal.hint.0": {"url": "http://localhost:4006/files/lesson-audio/dfce3fe7c28de5ff5eee95e845798cc25c77cfc38bd59d75e42c79f76fab1da7.mp3", "hash": "c49713a7c49d023f6af9c06fada36a99bdaa0e705b16b920110989d53faeb16f", "bytes": 18144, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/dfce3fe7c28de5ff5eee95e845798cc25c77cfc38bd59d75e42c79f76fab1da7.mp3", "duration_ms": 2960}, "s1-concept-reveal.hint.1": {"url": "http://localhost:4006/files/lesson-audio/cadd1f22e120a88745e443f2667e150bf0e8ed04879a9e9b049d54b82ac17d35.mp3", "hash": "69b4aa330e316a3bf00b4757f4630835e6512d162eeef0339f98139b6f8cf209", "bytes": 21888, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/cadd1f22e120a88745e443f2667e150bf0e8ed04879a9e9b049d54b82ac17d35.mp3", "duration_ms": 3600}, "s1-concept-reveal.prompt": {"url": "http://localhost:4006/files/lesson-audio/c69a641fe75ad7e6e27f22b97f0832c2656d99ac3099aa58680450b72c7a597b.mp3", "hash": "c1d3ab883ee0c80d501bf086bafa2a0845f261b3d1242e3e22d4d7094fd88965", "bytes": 20448, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/c69a641fe75ad7e6e27f22b97f0832c2656d99ac3099aa58680450b72c7a597b.mp3", "duration_ms": 3360}, "s1-concept-reveal.card.0.back": {"url": "http://localhost:4006/files/lesson-audio/dc7c98be8132ab48ef99e2bc6e62d91f0fb7d2ef50e79f5a638aeb19a464c13d.mp3", "hash": "35c7cd36c24e13e0722e5a71f90aa27f9cc610ce90fcbe1cb5618e057bf748e1", "bytes": 15264, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/dc7c98be8132ab48ef99e2bc6e62d91f0fb7d2ef50e79f5a638aeb19a464c13d.mp3", "duration_ms": 2480}, "s1-concept-reveal.card.1.back": {"url": "http://localhost:4006/files/lesson-audio/b817d1d9bf243e8e6d0a3761952232b0a79aa10fd3b7fb52ba2a9aa299505e9e.mp3", "hash": "3c0da736340e777f8930ec28ce900931c41a083a8ddb87b9c2aa00fb97cf50a0", "bytes": 18144, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/b817d1d9bf243e8e6d0a3761952232b0a79aa10fd3b7fb52ba2a9aa299505e9e.mp3", "duration_ms": 2960}, "s1-concept-reveal.explanation": {"url": "http://localhost:4006/files/lesson-audio/f652035f621dd4b808e8f8a4ede140b59b2ed462c06a38ef512332355fbc079b.mp3", "hash": "ea8287f0252320ac9225ba84129fce69664d02a95d1d23fee0e94f96e1a3aaeb", "bytes": 35424, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/f652035f621dd4b808e8f8a4ede140b59b2ed462c06a38ef512332355fbc079b.mp3", "duration_ms": 5840}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9ceeee19-c270-4624-a828-92e6f501754e', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "confidence-quiz", "title": "Confiança nas suas contas", "locale": "pt-BR", "subject": "mixed", "objectives": ["Somar dois preços iguais (5+5) para calcular uma venda total", "Refletir sobre o quão seguro você se sente da sua resposta"], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-confidence", "xp": 10, "type": "confidence_quiz", "title": "Quanto Liruf juntou?", "payload": {"options": [{"id": "opt5", "text_md": "5 reais", "rationale_md": "Você contou apenas um copo? Lembre-se de que Liruf vendeu DOIS copos, não um."}, {"id": "opt10", "text_md": "10 reais"}, {"id": "opt0", "text_md": "0 reais", "rationale_md": "Você subtraiu em vez de somar? Os dois copos se SOMAM, não se subtraem."}, {"id": "opt25", "text_md": "25 reais", "rationale_md": "Você multiplicou 5×5? Aqui se SOMAM 5+5, não se multiplicam."}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf vendeu dois copos de limonada a 5 reais cada um. Quantos reais ele juntou?", "difficulty": 1, "explanation_md": "Você somou 5 + 5 e juntou 10 reais. Quando você pratica, pode confiar mais nas suas contas.", "audio_segment_id": "s1-confidence.prompt"}], "schema_version": 1}', '{"s1-confidence": {"correct_option_id": "opt10"}}', '{"units": {"s1-confidence.prompt": {"url": "http://localhost:4006/files/lesson-audio/26f6fb097c5d454a58f2291f536cae1029bc8c0f0a08ae4e6c4da7495d273742.mp3", "hash": "8be0634a697a38e764835a52bbee15461bdd2c2d96f0d57f20b798b9e24b4e62", "bytes": 41184, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/26f6fb097c5d454a58f2291f536cae1029bc8c0f0a08ae4e6c4da7495d273742.mp3", "duration_ms": 6800}, "s1-confidence.choices": {"url": "http://localhost:4006/files/lesson-audio/a6f5eac9b20281e7db217d59e4fd10ef3b44550e141bafc140fd6747f42926ea.mp3", "hash": "76eaaf9068758071393bbad9f2bccfa771baca2e68430f959a5f228bcffee5f0", "bytes": 33408, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/a6f5eac9b20281e7db217d59e4fd10ef3b44550e141bafc140fd6747f42926ea.mp3", "duration_ms": 5520}, "s1-confidence.explanation": {"url": "http://localhost:4006/files/lesson-audio/329d43e028d6543d2bc2697f5fd2e7e3830622b8630041bc80b956ea1a2b9442.mp3", "hash": "f4447addc2f6ff59ffb0c45e9b42639a1834a4aee174f8760394f329de59c942", "bytes": 47376, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/329d43e028d6543d2bc2697f5fd2e7e3830622b8630041bc80b956ea1a2b9442.mp3", "duration_ms": 7840}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08604886-c155-4f4b-85dd-0b5b853997e1', 'es-MX', '1', '{"meta": {"cast": ["liruf"], "slug": "quiz-mcq", "title": "El precio justo de la limonada", "locale": "es-MX", "subject": "mixed", "objectives": ["Elegir el precio justo para un vaso de limonada (5 pesos) entre opciones exageradas (50 pesos ahuyenta clientes; 1 peso no cubre el costo)."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "q1-price-choice", "xp": 15, "type": "quiz_mcq", "title": "El precio justo de la limonada", "payload": {"options": [{"id": "opt-1-peso", "text_md": "1 peso por vaso", "rationale_md": "1 peso es muy poco: Liruf no recuperaría lo que gastó en limones y azúcar, y perdería dinero."}, {"id": "opt-5-pesos", "text_md": "5 pesos por vaso"}, {"id": "opt-50-pesos", "text_md": "50 pesos por vaso", "rationale_md": "50 pesos es demasiado: los clientes comprarían en otro puesto, porque cuesta más que una botella de agua."}], "shuffle": true}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf quiere vender vasos de limonada. ¿Cuál precio es justo para atraer clientes y no perder dinero?", "difficulty": 2, "explanation_md": "El precio justo es de 5 pesos por vaso. Liruf gana un poco y sus clientes pagan un precio razonable.", "audio_segment_id": "q1-price-choice.prompt"}], "schema_version": 1}', '{"q1-price-choice": {"correct_option_id": "opt-5-pesos"}}', '{"units": {"q1-price-choice.prompt": {"url": "http://localhost:4006/files/lesson-audio/ce85eabcb8fb10c20df66f75bfff394581264e614390e86448dd2080b32b520c.mp3", "hash": "e21d7049789f39f5a840882326b60804645cba90747503ef4e015222f1500a5f", "bytes": 46368, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/ce85eabcb8fb10c20df66f75bfff394581264e614390e86448dd2080b32b520c.mp3", "duration_ms": 7680}, "q1-price-choice.choices": {"url": "http://localhost:4006/files/lesson-audio/4b798b677e3637afc91c535c8089cafa3226d4390c373c204a5242a13e9fe55c.mp3", "hash": "fc61b94be9d977d2f57ade1e7ef080e3d3357e083971b1a550a0b94dc1cbe22d", "bytes": 35856, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/4b798b677e3637afc91c535c8089cafa3226d4390c373c204a5242a13e9fe55c.mp3", "duration_ms": 5920}, "q1-price-choice.explanation": {"url": "http://localhost:4006/files/lesson-audio/605b422ef1bab49db402905ff6a9e68648a228bae8fc4581c001941a73b2f577.mp3", "hash": "35497cd84dfb1de1f84fcd4e4fa2123143693af4a56b4e0861d3175a5fe36994", "bytes": 49248, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/605b422ef1bab49db402905ff6a9e68648a228bae8fc4581c001941a73b2f577.mp3", "duration_ms": 8160}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('6e000ee0-e5b3-4521-b30f-cd54bbd72297', 'en-US', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "type-answer", "title": "Write and calculate real numbers for the stand", "locale": "en-US", "subject": "mixed", "objectives": ["Write exact numeric and text answers about the day''s sales (sums up to 80, counts up to 20)."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-type-ahorro", "xp": 10, "type": "type_answer", "hints": ["Add 12 + 8."], "title": "Financial Hangman", "payload": {"max_chars": 3, "placeholder": "Write the number here"}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Rho sold 12 lemonades. Then she sold 8 more. How many lemonades did she sell in total?", "difficulty": 1, "explanation_md": "Rho sold 12 and then 8, which is 20 lemonades in total. Great job adding!", "audio_segment_id": "s1-type-ahorro.prompt"}], "schema_version": 1}', '{"s1-type-ahorro": {"accept": ["20"], "keywords": ["20"], "case_sensitive": false}}', '{"units": {"s1-type-ahorro.hint.0": {"url": "http://localhost:4006/files/lesson-audio/dbc3239fffbd57983437fc93a33a0333c93f4303196508dc66733f2f40f420ed.mp3", "hash": "25a775d9e80a35919af208f5fd25b131dea62ccb78d5a1e77613629c1177113f", "bytes": 12384, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/dbc3239fffbd57983437fc93a33a0333c93f4303196508dc66733f2f40f420ed.mp3", "duration_ms": 2000}, "s1-type-ahorro.prompt": {"url": "http://localhost:4006/files/lesson-audio/617865d32453ad3827b503a8efc3cca815372763058f37a79383ce71005bb49e.mp3", "hash": "97f3d5c49749f13b8e189941a3c3e1f2b871e702616fa06e0557abc59db71a44", "bytes": 41616, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/617865d32453ad3827b503a8efc3cca815372763058f37a79383ce71005bb49e.mp3", "duration_ms": 6880}, "s1-type-ahorro.explanation": {"url": "http://localhost:4006/files/lesson-audio/76e29abc0060fd12ae595e2dcdeb44506260eef22e7a8da3f1b5134acf80e200.mp3", "hash": "ac24a82f7e2af3d9e0e8b638a96e4e530b5161d54b559ec1f8343d55aaa53cbe", "bytes": 39168, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/76e29abc0060fd12ae595e2dcdeb44506260eef22e7a8da3f1b5134acf80e200.mp3", "duration_ms": 6480}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a8fced2e-cab0-454c-866f-d7f94e9da924', 'en-US', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "combo-dinero", "title": "Closing the Sunday cash box", "locale": "en-US", "subject": "mixed", "objectives": ["Counting coins to find the total collected", "Giving correct change when paying with a bill", "Using weekly savings to plan a goal"], "estimated_minutes": 7}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-coin-count", "xp": 15, "type": "coin_count", "title": "Count the day''s coins", "payload": {"target": 20, "currency": "USD", "denominations": [1, 5, 10]}, "narrator": {"emotion": "neutral", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/177ba0c4a3b3375306ba12af4485714ed7f60f8259a1c9f4833bc2d589f32f3f.webp", "prompt_md": "You closed the stand''s cash box. Gather 1, 5, and 10 dollar coins to make the 20 that came in today.", "difficulty": 2, "explanation_md": "You gathered 20 dollars, the same amount that came into Liruf''s stand cash box. Great close of day!", "audio_segment_id": "s1-coin-count.prompt"}, {"id": "s2-make-change", "xp": 20, "type": "make_change", "hints": ["Think: the bill is 20 and the cup costs 5. How much is left over? Then gather coins that add up to that."], "title": "Give the change to the customer", "payload": {"price": 5, "currency": "USD", "paid_with": 20, "denominations": [1, 2, 5, 10]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/7c2b02d3746e8387ac891f80b975058bee7af20bbd44c7993cfcc15d71683543.webp", "prompt_md": "The last customer paid with a 20-dollar bill for a 5-dollar cup. Make the exact change to give back to her.", "difficulty": 3, "explanation_md": "You gave back 15 dollars: the 20-dollar bill minus the 5 for the cup. That way the customer pays the exact amount.", "audio_segment_id": "s2-make-change.prompt"}, {"id": "s3-savings-goal", "xp": 15, "type": "savings_goal", "title": "How many Sundays are left?", "payload": {"goal": 40, "currency": "USD", "weekly_options": [20]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "You need 40 dollars for the guitar. If you save 20 dollars every Sunday, how many Sundays do you need?", "difficulty": 2, "explanation_md": "You need 2 more Sundays: 20 plus 20 is 40, exactly what you need for the guitar.", "audio_segment_id": "s3-savings-goal.prompt"}], "schema_version": 1}', '{"s1-coin-count": {}, "s2-make-change": {}, "s3-savings-goal": {}}', '{"units": {"s1-coin-count.prompt": {"url": "http://localhost:4006/files/lesson-audio/6b08281472ddc7e25e823cf716e925e5d45d98400ac4118711863d078d071621.mp3", "hash": "976515de0088d7143f11a4339325e6eb09fffca5297c2e98a06841e643df6cee", "bytes": 39744, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/6b08281472ddc7e25e823cf716e925e5d45d98400ac4118711863d078d071621.mp3", "duration_ms": 6560}, "s2-make-change.hint.0": {"url": "http://localhost:4006/files/lesson-audio/c2fc1f79af419cd1294a761695709ff908c905a7d1813a04c6d3ec5ad96099c5.mp3", "hash": "e586bb4b01bd399177c563dd7046ec7b898aaf38f8d87d86fa797e65c925313c", "bytes": 38304, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/c2fc1f79af419cd1294a761695709ff908c905a7d1813a04c6d3ec5ad96099c5.mp3", "duration_ms": 6320}, "s2-make-change.prompt": {"url": "http://localhost:4006/files/lesson-audio/dd8410fd5a4378aa949bdf03ea8453ff416eddb6a50aa2d0c28892f4fa499645.mp3", "hash": "7771866601a6aec3a9a1863bc63486e509fe0286d06ad84a953115558af002f3", "bytes": 36288, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/dd8410fd5a4378aa949bdf03ea8453ff416eddb6a50aa2d0c28892f4fa499645.mp3", "duration_ms": 6000}, "s3-savings-goal.prompt": {"url": "http://localhost:4006/files/lesson-audio/2f9d730733ceb6d4c44b6d4c1b2e403e6cb9df04508c76cd697831feed286d56.mp3", "hash": "d7a220a8799260b1c6171e5d3b2196775c95721d972a32412ee141aed0016a92", "bytes": 36288, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/2f9d730733ceb6d4c44b6d4c1b2e403e6cb9df04508c76cd697831feed286d56.mp3", "duration_ms": 6000}, "s1-coin-count.explanation": {"url": "http://localhost:4006/files/lesson-audio/6d672937232e66d7cba46eee1a3ea04393e8d2dd82858d49acbd1e27b5aeab41.mp3", "hash": "370a7b38f87fa4e5cb47f2a5c9270a3755964905e5fab6f2476fc025edccd07f", "bytes": 36864, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/6d672937232e66d7cba46eee1a3ea04393e8d2dd82858d49acbd1e27b5aeab41.mp3", "duration_ms": 6080}, "s2-make-change.explanation": {"url": "http://localhost:4006/files/lesson-audio/0ef019d3dd60e07400725a84751465672cad985e829fdc238ba09fcf161ee13e.mp3", "hash": "86b6286bce8a304c20cad2f4e65acfa2ad040567b77455a2f9eafb3b05bdf97d", "bytes": 40608, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/0ef019d3dd60e07400725a84751465672cad985e829fdc238ba09fcf161ee13e.mp3", "duration_ms": 6720}, "s3-savings-goal.explanation": {"url": "http://localhost:4006/files/lesson-audio/603edf25caf83a9f9f89c2bdad00fc3ccecd38a5b3bbf5a147997a6e8af9baa1.mp3", "hash": "3e2bbc3aba26be7aa8cb05b25d6d1fd436aeda37563953fe9d9d886d5f9a1ba0", "bytes": 36288, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/603edf25caf83a9f9f89c2bdad00fc3ccecd38a5b3bbf5a147997a6e8af9baa1.mp3", "duration_ms": 6000}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('3c639b5e-01f3-469e-95e3-a52a215847f4', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "fact-opinion", "title": "Facts and Opinions", "locale": "en-US", "subject": "mixed", "objectives": ["Differentiate between facts and opinions in phrases from a lemonade stand."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fact-opinion", "xp": 15, "type": "fact_opinion", "hints": ["A fact can be demonstrated with numbers or photos. An opinion is what someone likes or believes."], "title": "Fact or opinion?", "payload": {"statements": [{"id": "s1", "text_md": "Today we sold 12 glasses of lemonade."}, {"id": "s2", "text_md": "The glass costs 5 dollars."}, {"id": "s3", "text_md": "We use lemons to make the lemonade."}, {"id": "s4", "text_md": "Our lemonade is the best in the neighborhood."}, {"id": "s5", "text_md": "The stand has the most cheerful colors."}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/107f1aba4da76d5f0cccb14bbfa54612515b2bad4b54e4ab06d8eae4d2a9a87d.webp", "prompt_md": "Rho says phrases from the stand. Tap those that are FACTS (can be proven).", "difficulty": 2, "explanation_md": "Facts can be proven! ''The glass costs 5 dollars'' is a fact because you can see the price. ''It''s the best'' is an opinion, because another person might not like it.", "audio_segment_id": "s1-fact-opinion.prompt"}], "schema_version": 1}', '{"s1-fact-opinion": {"fact_ids": ["s1", "s2", "s3"]}}', '{"units": {"s1-fact-opinion.hint.0": {"url": "http://localhost:4006/files/lesson-audio/90022751aea03ac45729b1cd4204b4af27a2b0e9bc968d502bcbf64a50865b2a.mp3", "hash": "68e42f962f0dec75e1998fa7417540a44bdd133c045be2142bf73e144c10001d", "bytes": 32544, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/90022751aea03ac45729b1cd4204b4af27a2b0e9bc968d502bcbf64a50865b2a.mp3", "duration_ms": 5360}, "s1-fact-opinion.prompt": {"url": "http://localhost:4006/files/lesson-audio/357a8341ad67833746a58cfd4257f6d2b086b6b5e2952ff64262dc266e1a362e.mp3", "hash": "df4db5c1564401ddadb2b87f180317d5d69d911ff4ac83a8cfb92932ef30c398", "bytes": 27216, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/357a8341ad67833746a58cfd4257f6d2b086b6b5e2952ff64262dc266e1a362e.mp3", "duration_ms": 4480}, "s1-fact-opinion.explanation": {"url": "http://localhost:4006/files/lesson-audio/907dce94c49e34cb4e66977651fe373713c39b035aba9479ff0066f3e512b05d.mp3", "hash": "fbc4136c25bda446a6a78454e668d58e0e67a35140cacf642cfde5076e651f94", "bytes": 53568, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/907dce94c49e34cb4e66977651fe373713c39b035aba9479ff0066f3e512b05d.mp3", "duration_ms": 8880}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08604886-c155-4f4b-85dd-0b5b853997e1', 'pt-BR', '1', '{"meta": {"cast": ["liruf"], "slug": "quiz-mcq", "title": "O preço justo da limonada", "locale": "pt-BR", "subject": "mixed", "objectives": ["Escolher o preço justo para um copo de limonada (5 reais) entre opções exageradas (50 reais afasta os clientes; 1 real não cobre o custo)."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "q1-price-choice", "xp": 15, "type": "quiz_mcq", "title": "O preço justo da limonada", "payload": {"options": [{"id": "opt-1-peso", "text_md": "1 real por copo", "rationale_md": "1 real é muito pouco: Liruf não recuperaria o que gastou em limões e açúcar, e perderia dinheiro."}, {"id": "opt-5-pesos", "text_md": "5 reais por copo"}, {"id": "opt-50-pesos", "text_md": "50 reais por copo", "rationale_md": "50 reais é demais: os clientes comprariam em outro lugar, porque custa mais que uma garrafa de água."}], "shuffle": true}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf quer vender copos de limonada. Qual preço é justo para atrair clientes e não perder dinheiro?", "difficulty": 2, "explanation_md": "O preço justo é de 5 reais por copo. Liruf ganha um pouco e seus clientes pagam um preço razoável.", "audio_segment_id": "q1-price-choice.prompt"}], "schema_version": 1}', '{"q1-price-choice": {"correct_option_id": "opt-5-pesos"}}', '{"units": {"q1-price-choice.prompt": {"url": "http://localhost:4006/files/lesson-audio/dd3129f595d11ef65a0154d938dd61a5830952c99094bef2cdfcaeb9e00ed2e8.mp3", "hash": "1b015fc8da2fd604aebfba1644e457251d2e48d4e04e4a5198739998a7d8319e", "bytes": 40608, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/dd3129f595d11ef65a0154d938dd61a5830952c99094bef2cdfcaeb9e00ed2e8.mp3", "duration_ms": 6720}, "q1-price-choice.choices": {"url": "http://localhost:4006/files/lesson-audio/3192764fbfbf47ca5d525e10d6ee5907a46f5a52e564030babdcb59523a76626.mp3", "hash": "74591a7e5647eb8f17139a33257c7822698812e65e6251522268f92a722ba782", "bytes": 31968, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/3192764fbfbf47ca5d525e10d6ee5907a46f5a52e564030babdcb59523a76626.mp3", "duration_ms": 5280}, "q1-price-choice.explanation": {"url": "http://localhost:4006/files/lesson-audio/c82a61d087c06dc0316c385b503dbd12a80b0d465f3e6c0d9809298b2ab30800.mp3", "hash": "7498c1b8e5fff467f14df530f09f9034766a1ddf7332c270edc8ebecd8723244", "bytes": 47376, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/c82a61d087c06dc0316c385b503dbd12a80b0d465f3e6c0d9809298b2ab30800.mp3", "duration_ms": 7840}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f75b3e23-fb31-40cf-9b58-e918769e51b9', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "yes-no-cases", "title": "Dizer sim ou não, caso a caso", "locale": "pt-BR", "subject": "mixed", "objectives": ["Dizer sim ou não, caso a caso: esse gasto ajuda a barraca? (mais limões: sim; um brinquedo novo hoje: não, ainda não)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-yes-no-cases", "xp": 10, "type": "yes_no_cases", "hints": ["Pense: isso ajuda a vender mais limonada ou a guardar o dinheiro?", "Um gasto que ajuda a barraca é algo que você precisa para fazer ou vender limonada."], "title": "Sim ou não?", "payload": {"cases": [{"id": "c1", "text_md": "Comprar mais limões para fazer mais limonada.", "image_url": "http://localhost:4006/files/lesson-images/5b9d3ca8907f9b50f2a48f3711c3fa08eadf913e82fd0fe677316807bca3207a.webp"}, {"id": "c2", "text_md": "Comprar um brinquedo novo na loja.", "image_url": "http://localhost:4006/files/lesson-images/144cabc8c1fe6d2b3387b2c10c891c1c76418c752a13285be8430dad5e08d1a8.webp"}, {"id": "c3", "text_md": "Comprar uma placa bonita para a barraca.", "image_url": "http://localhost:4006/files/lesson-images/68b2a096e22873a7e0eea5ccd01c71468a174ee0f86ff0d63156484b04b39056.webp"}, {"id": "c4", "text_md": "Comprar doces para você.", "image_url": "http://localhost:4006/files/lesson-images/266ad41249685a701b06ec0318575e64b8fe933926d3673767633f88761d0a61.webp"}], "rule_md": "Diga **sim** se o gasto ajuda a barraca de limonada (mais limões, uma placa, uma jarra nova). Diga **não** se é algo que você não precisa hoje (um brinquedo, um videogame, doces)."}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf tem sua lista. Toque em cada caso: esse gasto ajuda a barraca de limonada?", "difficulty": 1, "explanation_md": "Comprar mais limões ajuda a fazer mais limonada e vender mais. Um brinquedo novo não ajuda a barraca hoje.", "audio_segment_id": "s1-yes-no-cases.prompt"}], "schema_version": 1}', '{"s1-yes-no-cases": {"applies_ids": ["c1", "c3"]}}', '{"units": {"s1-yes-no-cases.hint.0": {"url": "http://localhost:4006/files/lesson-audio/5d5d4c8388c1b1e173eb0d6a90de0c4564ce39b4a0143a3726760ae1b0f3a649.mp3", "hash": "6ff680569fb65a4ae7a223e2f0cb2fee984b8f9bc9d23390f4dbb81846b994f1", "bytes": 28656, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/5d5d4c8388c1b1e173eb0d6a90de0c4564ce39b4a0143a3726760ae1b0f3a649.mp3", "duration_ms": 4720}, "s1-yes-no-cases.hint.1": {"url": "http://localhost:4006/files/lesson-audio/22751b1939c506b5d4ca14af3315b63682c1f21f95234a6c7d360e7683639219.mp3", "hash": "5113e241130d85a484f8d8554c2dd831a0ce94b65c5a73d292785a9dd2f56512", "bytes": 37728, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/22751b1939c506b5d4ca14af3315b63682c1f21f95234a6c7d360e7683639219.mp3", "duration_ms": 6240}, "s1-yes-no-cases.prompt": {"url": "http://localhost:4006/files/lesson-audio/8071db4b63f645d88779b4397141eb56390153bc56a59d9cc52baff618ba62eb.mp3", "hash": "14456c8a5fe5f7959567c397e00dec6a2f85ada8576e004a10762c72be8fd487", "bytes": 37728, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/8071db4b63f645d88779b4397141eb56390153bc56a59d9cc52baff618ba62eb.mp3", "duration_ms": 6240}, "s1-yes-no-cases.choices": {"url": "http://localhost:4006/files/lesson-audio/df0cdcc54cc3ffa6b7fa15b4e1b1179a9a0943574cfbd0d4e44196b70c7e8654.mp3", "hash": "3d32acb8342a7e19ed6a59fbf8c21862217511b1fce99fc5e610101c9cf10d70", "bytes": 65088, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/df0cdcc54cc3ffa6b7fa15b4e1b1179a9a0943574cfbd0d4e44196b70c7e8654.mp3", "duration_ms": 10800}, "s1-yes-no-cases.explanation": {"url": "http://localhost:4006/files/lesson-audio/dc896e9fa4369e18b4032957a0eb6b001425c0c3d278ca6ee5c6ca8921349575.mp3", "hash": "c95dfbdd9b3ced2471b1d2279d599d3b0a35f5688a71f1420dbc0d1ffc338ab2", "bytes": 51264, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/dc896e9fa4369e18b4032957a0eb6b001425c0c3d278ca6ee5c6ca8921349575.mp3", "duration_ms": 8480}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('36624bae-eea6-49e3-8767-c43ffbdf09e7', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "compare-table", "title": "Compare lemon prices", "locale": "en-US", "subject": "mixed", "objectives": ["Read a comparison table of suppliers and choose the best option."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-compare-table", "xp": 5, "type": "compare_table", "hints": ["Think: which one sells the same lemons cheaper? Look at the prices."], "title": "Compare suppliers", "payload": {"cols": [{"id": "precio", "label": "Price for 10 lemons"}, {"id": "mejor", "label": "Best option?"}], "rows": [{"id": "lula", "label": "Doña Lula"}, {"id": "pepe", "label": "Don Pepe"}], "tokens": [{"id": "t1", "text_md": "5 dollars"}, {"id": "t2", "text_md": "6 dollars"}, {"id": "t3", "text_md": "Yes"}, {"id": "t4", "text_md": "No"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/121d01123f500cbc8755936f0c341c29472d8cbefd365b164d9cd932ff533a40.webp", "prompt_md": "Doña Lula: 10 lemons for 5 dollars. Don Pepe: 10 lemons for 6 dollars. Fill in the table and tap ''Yes'' or ''No'' for the best option.", "difficulty": 1, "explanation_md": "Doña Lula charges 5 dollars for 10 lemons, less than Don Pepe''s 6 dollars. That way you get more lemons for your money!", "audio_segment_id": "s1-compare-table.prompt"}], "schema_version": 1}', '{"s1-compare-table": {"cells": {"lula:mejor": "t3", "pepe:mejor": "t4", "lula:precio": "t1", "pepe:precio": "t2"}}}', '{"units": {"s1-compare-table.hint.0": {"url": "http://localhost:4006/files/lesson-audio/69c40c1f5368efe38d744b8262820c21535dc5a515a3dca28a3f3a154a790143.mp3", "hash": "bf3389939d1f0c654ec08f953fc6cc16f89cb3ebedb8d449299e6f621ac26fb4", "bytes": 22464, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/69c40c1f5368efe38d744b8262820c21535dc5a515a3dca28a3f3a154a790143.mp3", "duration_ms": 3680}, "s1-compare-table.prompt": {"url": "http://localhost:4006/files/lesson-audio/4e81b88a0a02183268bc2db4b52e91bae818101720da3afc1a62f3ce48e82910.mp3", "hash": "f4c59cd972cd8df3c40589a4fb84a96dbe787c5ea52a0d668c82448916806abb", "bytes": 53136, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/4e81b88a0a02183268bc2db4b52e91bae818101720da3afc1a62f3ce48e82910.mp3", "duration_ms": 8800}, "s1-compare-table.explanation": {"url": "http://localhost:4006/files/lesson-audio/3a14c304ab47d983fdba75c3c72e5fa0a11afde9ae369422a4352e53fa23c924.mp3", "hash": "6a8fd03272f12370f4e3312ca293db4d8aba4393993d77497bc90304f4932576", "bytes": 42624, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/3a14c304ab47d983fdba75c3c72e5fa0a11afde9ae369422a4352e53fa23c924.mp3", "duration_ms": 7040}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0c46648e-ff7a-4ad4-bf42-5829cc3fd1ac', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "story-dialogue", "title": "Earning money starts with an idea", "locale": "en-US", "subject": "mixed", "objectives": ["Discovering that money can be earned by offering something others want", "Identifying a clear goal (80-dollar guitar) as motivation to start"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-dialogue", "xp": 0, "type": "story_dialogue", "title": "Dina''s idea", "payload": {"lines": [{"action": "idle", "emotion": "thinking", "text_md": "Look at the 80-dollar guitar… it''s so cool, but I don''t have money.", "character": "liruf"}, {"action": "idle", "emotion": "excited", "text_md": "What if you earn it yourself? You could sell lemonade on your street.", "character": "dina"}, {"action": "idle", "emotion": "surprised", "text_md": "Sell lemonade? And people would pay me?", "character": "liruf"}, {"action": "idle", "emotion": "encouraging", "text_md": "Of course. Each cup for 5 dollars. If you sell 16 cups, you''ve got the 80!", "character": "dina"}, {"action": "idle", "emotion": "thinking", "text_md": "16 cups… how many is that? Will it be enough?", "character": "liruf"}, {"action": "idle", "emotion": "happy", "text_md": "Think about it: 5 dollars each. How many do you need to get 80?", "character": "dina"}, {"action": "idle", "emotion": "happy", "text_md": "Yes! I''m going to set up a stand this Saturday.", "character": "liruf"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/bceffd5464fb53b3c6223cef7bc535d96205316fa178e43f9d9214f4e391972b.webp", "prompt_md": "Liruf and Dina talk in front of the music store.", "difficulty": 1, "audio_segment_id": "s1-dialogue.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-dialogue.line.0": {"url": "http://localhost:4006/files/lesson-audio/436cda6ccd30168d116325ca86fef4e3fd76e91f3d5667c62b6f4138e198eb53.mp3", "hash": "c7603cfe3490667cb666a6befbf557c4f69adddd3e36694a05a6d169ea3a274e", "bytes": 23328, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/436cda6ccd30168d116325ca86fef4e3fd76e91f3d5667c62b6f4138e198eb53.mp3", "duration_ms": 3840}, "s1-dialogue.line.1": {"url": "http://localhost:4006/files/lesson-audio/c245d204ce82bc08889e02f20ce9202916d4a3d86a60d8cacb08bc6d39a56fd5.mp3", "hash": "4a25a28000030c24ef29546999330bee62fc34f9d6d96e7411b1a99b2d3e471a", "bytes": 21888, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/c245d204ce82bc08889e02f20ce9202916d4a3d86a60d8cacb08bc6d39a56fd5.mp3", "duration_ms": 3600}, "s1-dialogue.line.2": {"url": "http://localhost:4006/files/lesson-audio/9c58de63d91039e79d18db056494e41125245efabf16529279f82a1eb3fe5cd7.mp3", "hash": "fc49f4753e4e49e09a7850b7c7e59138a24dbf0df933d5de54ecf21878e4960a", "bytes": 15696, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/9c58de63d91039e79d18db056494e41125245efabf16529279f82a1eb3fe5cd7.mp3", "duration_ms": 2560}, "s1-dialogue.line.3": {"url": "http://localhost:4006/files/lesson-audio/8a1d757fc71c945b69d78ce7e2f1cf7fcc7b8edbf351cdf361578c38dcaea40f.mp3", "hash": "8c5bf6f281cb66c1419b1143ecdff39298edde179a793c4cef5c17422f207e38", "bytes": 29088, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/8a1d757fc71c945b69d78ce7e2f1cf7fcc7b8edbf351cdf361578c38dcaea40f.mp3", "duration_ms": 4800}, "s1-dialogue.line.4": {"url": "http://localhost:4006/files/lesson-audio/99ae98a5c43c80ba41c780fd000d2c66bf4f82fe373f97823c3ec90e8c8b3afb.mp3", "hash": "72c2022d863ebec522ebba01e0dbf9e4fc08d20d02a5a36e56f23da9b598f4df", "bytes": 21024, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/99ae98a5c43c80ba41c780fd000d2c66bf4f82fe373f97823c3ec90e8c8b3afb.mp3", "duration_ms": 3440}, "s1-dialogue.line.5": {"url": "http://localhost:4006/files/lesson-audio/71c825bc2430e5f9e068b06ff034ac4d0ae7202a95af69e3e614ad24a06a435e.mp3", "hash": "5b66e433d068764db95b47a3ffe323aad1e2f2887056d2c8569ba7b50e08acc9", "bytes": 24336, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/71c825bc2430e5f9e068b06ff034ac4d0ae7202a95af69e3e614ad24a06a435e.mp3", "duration_ms": 4000}, "s1-dialogue.line.6": {"url": "http://localhost:4006/files/lesson-audio/bd3c120f6699a474eea22d32c207ed221ff2a32935d1a696468d73c6694932a6.mp3", "hash": "41418e5b63ab5c1c731ecb16a7083b9efcd7ac7fc2e2ec9be300c236585a2d34", "bytes": 18576, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/bd3c120f6699a474eea22d32c207ed221ff2a32935d1a696468d73c6694932a6.mp3", "duration_ms": 3040}, "s1-dialogue.prompt": {"url": "http://localhost:4006/files/lesson-audio/dc6ea14eb32b42a82cc924eb84c3d0a2c933e8339b2c4bc2f7931531a8c4cc8b.mp3", "hash": "7d8d716faacdd7b213bc2aee7df8f1fdabe1bdad06b693c77006cbc55d9b15de", "bytes": 16704, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/dc6ea14eb32b42a82cc924eb84c3d0a2c933e8339b2c4bc2f7931531a8c4cc8b.mp3", "duration_ms": 2720}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('35abfab2-f1da-4643-915a-3fdba69f3a63', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "fill-blank", "title": "Llenando el cuaderno de cuentas", "locale": "es-MX", "subject": "mixed", "objectives": ["Calcular la ganancia restando el costo de los ingredientes del precio de venta."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ganancia-liruf", "xp": 5, "type": "fill_blank", "title": "La ganancia de Liruf", "payload": {"bank": [{"id": "a", "text_md": "2"}, {"id": "b", "text_md": "3"}, {"id": "c", "text_md": "5"}, {"id": "d", "text_md": "7"}], "mode": "bank", "text_md": "Vendí un vaso de limonada en 5 pesos y los ingredientes costaron 2 pesos. Mi ganancia es {{1}} pesos."}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf vende limonada. Vende cada vaso a 5 pesos y los ingredientes cuestan 2 pesos. ¿Cuánto gana por vaso?", "difficulty": 1, "explanation_md": "La ganancia es 3 pesos. Resta el costo (2) del precio (5): 5 - 2 = 3. ¡Así Liruf ahorra para su muñeca!", "audio_segment_id": "s1-ganancia-liruf.prompt"}], "schema_version": 1}', '{"s1-ganancia-liruf": {"gaps": [{"gap": 1, "accept": ["3"], "bank_id": "b"}]}}', '{"units": {"s1-ganancia-liruf.prompt": {"url": "http://localhost:4006/files/lesson-audio/3253bbc91882b19b154d9c37d18c496b1b44a5525787d4bfd623825b63f9587a.mp3", "hash": "fc755c8e2afa2e382385fc1ac8158fcf595da37e269663441461c411b2c01f89", "bytes": 51264, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/3253bbc91882b19b154d9c37d18c496b1b44a5525787d4bfd623825b63f9587a.mp3", "duration_ms": 8480}, "s1-ganancia-liruf.explanation": {"url": "http://localhost:4006/files/lesson-audio/ebac89097a351c87e95d8e7d70a40119d5b69d5ad66bff4e89599c660a9d73a9.mp3", "hash": "88640212b8694591adee85f8b2b86897c3c74442997ef709f2b8190611c22497", "bytes": 61776, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/ebac89097a351c87e95d8e7d70a40119d5b69d5ad66bff4e89599c660a9d73a9.mp3", "duration_ms": 10240}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ea98847f-02a1-4527-97a4-36921728b56d', 'pt-BR', '1', '{"meta": {"cast": ["liruf"], "slug": "cause-effect", "title": "Causa e efeito na barraca de limonada", "locale": "pt-BR", "subject": "mixed", "objectives": ["Conectar causas e efeitos na barraca: entender que um dia ensolarado leva a mais vendas e que aumentar o preço pode reduzir os clientes."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "cause-effect-1", "xp": 15, "type": "cause_effect", "hints": ["Pense: Por que os clientes vieram? O que Liruf fez ao vê-los?"], "title": "Causa e efeito na barraca", "payload": {"slots": 5, "events": [{"id": "ev1", "text_md": "O sol está muito forte."}, {"id": "ev2", "text_md": "Muitos clientes chegam à barraca."}, {"id": "ev3", "text_md": "Liruf decide cobrar mais caro."}, {"id": "ev4", "text_md": "A limonada custa 10 reais."}, {"id": "ev5", "text_md": "Liruf vende poucos copos."}]}, "narrator": {"emotion": "neutral", "character": "liruf"}, "prompt_md": "Liruf quer descobrir a razão secreta de suas vendas. Ordene os eventos para formar a cadeia de causa e efeito.", "difficulty": 2, "explanation_md": "O sol forte traz os clientes. Ao vender muito, Liruf decidiu aumentar o preço, mas isso fez com que vendesse menos. Se você misturou as causas, revise o que provoca cada efeito.", "audio_segment_id": "cause-effect-1.prompt"}], "schema_version": 1}', '{"cause-effect-1": {"chain": ["ev1", "ev2", "ev3", "ev4", "ev5"]}}', '{"units": {"cause-effect-1.hint.0": {"url": "http://localhost:4006/files/lesson-audio/2fbae9943b5ed695e838e5b004392657fa1ad75c556c1b03ca75ac6a1526b0d6.mp3", "hash": "fc533763af5a60eac2da149e510a3fae393be3f16c216f77482d6a3916c060b8", "bytes": 24768, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/2fbae9943b5ed695e838e5b004392657fa1ad75c556c1b03ca75ac6a1526b0d6.mp3", "duration_ms": 4080}, "cause-effect-1.prompt": {"url": "http://localhost:4006/files/lesson-audio/6159d6d2feff23e985211f401a5581d3dd8fe2c6f976061f88ae8dbead179df4.mp3", "hash": "63ab187338c6279e6a517a2119b49e6587efc89f1a56c832aaaab4abb74bc945", "bytes": 46368, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/6159d6d2feff23e985211f401a5581d3dd8fe2c6f976061f88ae8dbead179df4.mp3", "duration_ms": 7680}, "cause-effect-1.explanation": {"url": "http://localhost:4006/files/lesson-audio/1796b74021acaa125b3a946f55854e426608e12c47e9bce2d585c9f23badda9f.mp3", "hash": "0ac3169cb059d046cfc8e8882389cfb6b872ac7abb51c5e97cc20e31c624a474", "bytes": 77616, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/1796b74021acaa125b3a946f55854e426608e12c47e9bce2d585c9f23badda9f.mp3", "duration_ms": 12880}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('43eb7cc6-46cc-44ee-9a87-14d05d8f357d', 'es-MX', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "dialogue-choice", "title": "Negociar con clientes", "locale": "es-MX", "subject": "mixed", "objectives": ["Tomar decisiones dentro de historias del puesto y ver sus consecuencias inmediatas en las ventas y el ahorro."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-negociar", "xp": 15, "type": "dialogue_choice", "title": "¿Qué responder a un cliente que pide rebaja?", "payload": {"turns": [{"id": "turn-1", "npc_md": "Cliente: Hola, ¿me vendes una limonada? Oye, ¿me la podrías dejar en 3 pesos?", "replies": [{"id": "r1a", "text_md": "¡Claro! Toma, aquí está. 3 pesos, por ser tú."}, {"id": "r1b", "text_md": "No, cuesta 5 pesos. Si no te gusta, vete a otro lado."}, {"id": "r1c", "text_md": "Cada vaso vale 5 pesos, es un precio justo. Pero si llevas dos, te las dejo a 4 cada una. ¿Te animas?"}, {"id": "r1d", "text_md": "Por 3 pesos te doy un vaso más pequeño, ¿qué dices?"}]}, {"id": "turn-2", "npc_md": "Otro cliente: ¡Qué rica se ve tu limonada! Solo traigo 3 pesos, ¿no tendrás algo para mí?", "replies": [{"id": "r2a", "text_md": "Ni modo, si no traes 5 pesos, no hay limonada. Adiós."}, {"id": "r2b", "text_md": "Con 3 pesos te ofrezco un vaso chico, hecho con el mismo cariño. ¿Te parece?"}, {"id": "r2c", "text_md": "Está bien, llévate el vaso grande por 3 pesos. Eres especial."}, {"id": "r2d", "text_md": "Por 3 pesos te doy medio vaso, pero no creo que quieras."}]}], "persona": {"name": "Liruf", "role_md": "Dueño del puesto de limonada", "character": "liruf"}, "opening_md": "Es un día soleado en el puesto de limonada. Un cliente se acerca."}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/e2151771f933e4afbf29341ef477938c3d3ae0fd7562f4dba050e72ec875155e.webp", "prompt_md": "Un cliente pide rebaja. Ayuda a Liruf a responder con amabilidad sin perder su ganancia.", "difficulty": 2, "explanation_md": "Cuando un cliente pide rebaja, Liruf puede negociar con amabilidad: ofrecer alternativas (como llevarse dos vasos) mantiene la ganancia y deja contento al cliente. Regalar el producto hace perder dinero; ser grosero ahuyenta clientes.", "audio_segment_id": "s1-negociar.prompt"}], "schema_version": 1}', '{"s1-negociar": {"turns": [{"turn_id": "turn-1", "qualities": {"r1a": 10, "r1b": 20, "r1c": 100, "r1d": 60}, "reactions": {"r1a": "El cliente se va contento, pero Liruf ha perdido 2 pesos de ganancia. ¡Eso aleja su guitarra!", "r1b": "El cliente se molesta y se va sin comprar. Liruf pierde una venta y un posible amigo.", "r1c": "El cliente sonríe: ''¡Buen trato! Me llevo dos.'' Liruf gana 8 pesos y un cliente feliz. Negociar con opciones funciona.", "r1d": "El cliente acepta, pero Liruf siente que podría haber ganado más. A veces un trato justo es mejor que rebajar."}}, {"turn_id": "turn-2", "qualities": {"r2a": 10, "r2b": 100, "r2c": 20, "r2d": 30}, "reactions": {"r2a": "El cliente se va triste. Liruf se queda con su limonada y sin venta.", "r2b": "El cliente acepta feliz el vaso chico: ''Gracias, eres muy amable.'' Liruf vende, gana algo y conserva un cliente. ¡Bien negociado!", "r2c": "El cliente se alegra, pero Liruf regala su trabajo. La guitarra se aleja otro día.", "r2d": "El cliente pone cara rara y se va. Una oferta poco amable no convence a nadie."}}]}}', '{"units": {"s1-negociar.prompt": {"url": "http://localhost:4006/files/lesson-audio/a34f16bb11f58d71bf39bbb04db798d873b5078cd81b9c6d202a50b9a00b9cdb.mp3", "hash": "f672f8257d9373b5d37f6f58adf53595e7f184f8e2922f51d17e9bfe14d2fbef", "bytes": 37728, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/a34f16bb11f58d71bf39bbb04db798d873b5078cd81b9c6d202a50b9a00b9cdb.mp3", "duration_ms": 6240}, "s1-negociar.explanation": {"url": "http://localhost:4006/files/lesson-audio/7054fc51a3352204f5bfa7d312277184b00abae9c7460b4981d39d75dc4dde6e.mp3", "hash": "7dd99015d2dd0c69cfe978e7209033441c565874ab96383c09c69f6cd1701220", "bytes": 94464, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/7054fc51a3352204f5bfa7d312277184b00abae9c7460b4981d39d75dc4dde6e.mp3", "duration_ms": 15680}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('bd130a62-6800-475b-8af6-59f14ffebc50', 'en-US', '1', '{"meta": {"cast": ["liruf"], "slug": "number-input", "title": "Calculate Liruf''s sales", "locale": "en-US", "subject": "mixed", "objectives": ["Calculate and write how much Liruf earned in total if he sold 4 cups at 5 dollars each (20 dollars)."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-calculate-total", "xp": 15, "type": "number_input", "hints": ["Think: each cup costs 5 dollars and Liruf sold 4 cups.", "Multiply the number of cups by the price of each one: 4 × 5 = ?"], "title": "How much did Liruf earn?", "payload": {"unit": "dollars", "decimals_hint": 0}, "narrator": {"emotion": "happy", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/1faee46fce56754ef2f209b298ef80f83691e996e238ba800abe38467ba2c483.webp", "prompt_md": "Liruf sold 4 cups of lemonade at 5 dollars each. How much money did he earn in total?", "difficulty": 2, "explanation_md": "Liruf sold 4 cups at 5 dollars each, so he collected 4 times 5 dollars. 4 × 5 = 20. He earned 20 dollars in total.", "audio_segment_id": "s1-calculate-total.prompt"}], "schema_version": 1}', '{"s1-calculate-total": {"value": 20, "tolerance": 0}}', '{"units": {"s1-calculate-total.hint.0": {"url": "http://localhost:4006/files/lesson-audio/6513c9e05f3b426275c5c57a8b60402cec292126a65c1c654e2a300a9d2f8bd5.mp3", "hash": "b8108791e89ee3c09d10ebc1aeaa1c2d8d1247b3d01d7b262e828f77a56f1668", "bytes": 27648, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/6513c9e05f3b426275c5c57a8b60402cec292126a65c1c654e2a300a9d2f8bd5.mp3", "duration_ms": 4560}, "s1-calculate-total.hint.1": {"url": "http://localhost:4006/files/lesson-audio/c695883b07ac4cd9f4ec8bb36b4216d72612a841567aca617307afa8f8a77a1c.mp3", "hash": "e1cc949fe1e7ecbe92547af0640a0019dc21e6c97cee7058f23872cec09d09b4", "bytes": 29088, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/c695883b07ac4cd9f4ec8bb36b4216d72612a841567aca617307afa8f8a77a1c.mp3", "duration_ms": 4800}, "s1-calculate-total.prompt": {"url": "http://localhost:4006/files/lesson-audio/ba6b253dfc7510d918608208eeb8c70744100aa14625f7fd64c91ef1f58c40f8.mp3", "hash": "5b07651ebadab687e6e81f86cad313d43879eb70fc9595556f125d6e4d39626c", "bytes": 32976, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/ba6b253dfc7510d918608208eeb8c70744100aa14625f7fd64c91ef1f58c40f8.mp3", "duration_ms": 5440}, "s1-calculate-total.explanation": {"url": "http://localhost:4006/files/lesson-audio/37e27023f31ca06322000bf0c7b5516012150a07a84a2d5dbf1b78c488faed9e.mp3", "hash": "c0cd0b00a65cc1c1739aa524f90102e5f501f3166e956131f0e246bd8927e142", "bytes": 57888, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/37e27023f31ca06322000bf0c7b5516012150a07a84a2d5dbf1b78c488faed9e.mp3", "duration_ms": 9600}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b45d67a1-26c0-4ffa-b51c-76340c35e459', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "order-steps", "title": "Ordena las compras del puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Ordenar las compras del mercado por prioridad de venta", "Distinguir entre necesidades del puesto y gustos que pueden esperar"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ordenar-compras", "xp": 15, "type": "order_steps", "hints": ["Sin limones no hay limonada.", "Los vasos también son urgentes, pero sin limones no hay nada que vender."], "title": "Prioridad en el mercado", "payload": {"items": [{"id": "limones", "text_md": "Limones", "image_url": "http://localhost:4006/files/lesson-images/aaba518fa154db8e4e43213decf74dcc3f438cd9441885b9a5a8faf03fd2a962.webp"}, {"id": "vasos", "text_md": "Vasos", "image_url": "http://localhost:4006/files/lesson-images/4ad037f5498f6f3336634dc26b700671f304edf3cee5f8580d49cb81d079bc71.webp"}, {"id": "azucar", "text_md": "Azúcar", "image_url": "http://localhost:4006/files/lesson-images/19a0bb5beaf6d69b100b43441414f87e1f2c9950d211918df0fadb7a3c1afe61.webp"}, {"id": "calcomanias", "text_md": "Calcomanías", "image_url": "http://localhost:4006/files/lesson-images/fc123b0b72dab8a58fa5c6f187bd42c09dac17902915f6669601732854c960fc.webp"}], "slots": 4}, "narrator": {"emotion": "thinking", "character": "zara"}, "prompt_md": "Zara tiene $10 para el puesto. ¿Qué compra es más urgente para vender hoy? Toca las tarjetas de la más necesaria a la que puede esperar.", "difficulty": 2, "explanation_md": "Los limones son lo más urgente porque sin ellos no puedes hacer limonada. Los vasos son lo siguiente, porque necesitas dónde servirla. El azúcar ayuda a que sepa rico, pero puedes vender sin ella. Las calcomanías son un lujo que puede esperar. Si pusiste las calcomanías antes, pensaste que eran más importantes que vender, pero el puesto necesita primero lo que genera dinero.", "audio_segment_id": "s1-ordenar-compras.prompt"}], "schema_version": 1}', '{"s1-ordenar-compras": {"order": ["limones", "vasos", "azucar", "calcomanias"]}}', '{"units": {"s1-ordenar-compras.hint.0": {"url": "http://localhost:4006/files/lesson-audio/7b381bafde443d3c7ef5f9ab6f4375a59bdd1414418bdf406077eb0a9868c9fa.mp3", "hash": "d7c5e3cbe35fb57bae38e194db3773579dbfd5cecc7db3f7117d3daa741d7845", "bytes": 12816, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/7b381bafde443d3c7ef5f9ab6f4375a59bdd1414418bdf406077eb0a9868c9fa.mp3", "duration_ms": 2080}, "s1-ordenar-compras.hint.1": {"url": "http://localhost:4006/files/lesson-audio/416d9ba13e336cf75ad19c8957da64009db7fc3b7b412cec696a47e544ea90f2.mp3", "hash": "04a980bd6ed34c236d406903ac81be3340b9ac012080932f994fa6e440247867", "bytes": 26208, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/416d9ba13e336cf75ad19c8957da64009db7fc3b7b412cec696a47e544ea90f2.mp3", "duration_ms": 4320}, "s1-ordenar-compras.prompt": {"url": "http://localhost:4006/files/lesson-audio/528621b7103434176d906054827d8935929fe4915885b2db7d2298eabf8be1db.mp3", "hash": "06afec9dd8f0ffd50c4580cb529fdf9e3a045d196b848a331dca8c7a798825a8", "bytes": 49248, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/528621b7103434176d906054827d8935929fe4915885b2db7d2298eabf8be1db.mp3", "duration_ms": 8160}, "s1-ordenar-compras.explanation": {"url": "http://localhost:4006/files/lesson-audio/8357e5dfb96f8df951021d8103923b0aacb71238a2414c435665b867b8453d31.mp3", "hash": "b71579aba0ac28c21e3e8e48d924ca95cd5d1e0e8d4c63d18268a197fbda00b6", "bytes": 126144, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/8357e5dfb96f8df951021d8103923b0aacb71238a2414c435665b867b8453d31.mp3", "duration_ms": 20960}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c9d7856b-a75e-414e-ae61-e324a19a350d', 'en-US', '1', '{"meta": {"cast": ["rho"], "slug": "measure-read", "title": "The measuring cup", "locale": "en-US", "subject": "money", "objectives": ["Solve construction and measurement challenges applied to the position: organize instructions, read measurements, and balance quantities."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-read", "xp": 5, "type": "measure_read", "hints": ["Carefully observe the liquid line and count the marks from the bottom."], "title": "The fair cup line", "payload": {"max": 400, "min": 0, "unit": "ml", "ticks": 9, "instrument": "beaker", "pointer_value": 250}, "narrator": {"emotion": "encouraging", "character": "rho"}, "image_url": "http://localhost:4006/files/lesson-images/5af6848e564e3482516669c8bfca7a9143d1c5c9e156852000bfcb1740cd0d33.webp", "prompt_md": "Rho says: ''Each fair cup should reach the same mark.'' Read the measuring cup and tell me how many milliliters it marks.", "difficulty": 1, "explanation_md": "The measuring cup shows 250 ml because the liquid reaches exactly that mark. That way each cup receives the same amount and everyone pays the same."}], "schema_version": 1}', '{"s1-read": {"value": 250, "tolerance": 0}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4785eb58-e0ca-4b5c-a796-a6f01b2ab3ae', 'en-US', '1', '{"meta": {"cast": ["zara"], "slug": "pattern-complete", "title": "The Price Ladder", "locale": "en-US", "subject": "mixed", "objectives": ["Identify the visual pattern of the price ladder."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-escalera", "xp": 15, "type": "pattern_complete", "title": "The Cup Ladder", "payload": {"options": [{"id": "vaso-grande", "icon": "local_cafe", "tint": "warning"}, {"id": "vaso-chico", "icon": "local_cafe", "tint": "primary"}, {"id": "vaso-mediano", "icon": "local_cafe", "tint": "accent"}], "sequence": [{"icon": "local_cafe", "tint": "primary"}, {"icon": "local_cafe", "tint": "accent"}, {"icon": "local_cafe", "tint": "warning"}, {"icon": "local_cafe", "tint": "primary"}, {"icon": "local_cafe", "tint": "accent"}], "missing_slots": 1}, "narrator": {"emotion": "happy", "character": "zara"}, "prompt_md": "Which cup comes next in the pattern?", "difficulty": 2, "explanation_md": "Zara arranged the cups in a ladder: small, medium, large. The pattern repeats the three sizes. The large cup was next!", "audio_segment_id": "s1-escalera.prompt"}], "schema_version": 1}', '{"s1-escalera": {"correct": {"0": "vaso-grande"}}}', '{"units": {"s1-escalera.prompt": {"url": "http://localhost:4006/files/lesson-audio/8abef960ce79fcaf365872f468c95d455a9d44d26e315dd54badf2c66d380c07.mp3", "hash": "8a506a80b93d701d8d1e0b54e0c19931045f4521e2857623e0cf10fd2fb7bbc0", "bytes": 15696, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/8abef960ce79fcaf365872f468c95d455a9d44d26e315dd54badf2c66d380c07.mp3", "duration_ms": 2560}, "s1-escalera.explanation": {"url": "http://localhost:4006/files/lesson-audio/26823a48df7caedd9d408a5b275433e41dacfd11dee411dc673f5e0530d28115.mp3", "hash": "178ad4639db8e2b1c9f86012b739a9a91a62650ed6ead76214407765580682fe", "bytes": 53136, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/26823a48df7caedd9d408a5b275433e41dacfd11dee411dc673f5e0530d28115.mp3", "duration_ms": 8800}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f62a6048-4f69-4ab4-9256-d87525c8e112', 'pt-BR', '1', '{"meta": {"cast": ["liruf"], "slug": "make-change", "title": "O troco do seu Beto", "locale": "pt-BR", "subject": "mixed", "objectives": ["Calcular o troco exato usando moedas brasileiras em uma venda real."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-make-change", "xp": 15, "type": "make_change", "hints": ["Seu Beto gastou o preço do copo mais o do biscoito. Pagou com 20 reais. O troco é a diferença que você deve devolver a ele com moedas de 1, 2, 5 ou 10 reais."], "title": "O troco do seu Beto", "payload": {"price": 8, "currency": "BRL", "paid_with": 20, "denominations": [1, 2, 5, 10]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/683200e4e835b613b78a02fc0c46be7c39ea254906ca6cc5d78c8b6f69fdbc3a.webp", "prompt_md": "Seu Beto comprou 1 copo (5 reais) e 1 biscoito (3 reais). Pagou com 20 reais. Monte o troco com moedas.", "difficulty": 2, "explanation_md": "A limonada e o biscoito somam 8 reais. Ao pagar com 20, o troco é 12 reais. Você pode usar uma moeda de 10 e uma de 2, ou duas de 5 e duas de 1, ou qualquer combinação que dê 12. Se devolver menos, seu Beto fica sem o troco completo. Se devolver mais, você perde moedas para a guitarra de 80 reais.", "audio_segment_id": "s1-make-change.prompt"}], "schema_version": 1}', '{"s1-make-change": {}}', '{"units": {"s1-make-change.hint.0": {"url": "http://localhost:4006/files/lesson-audio/be07752329012442842c2c4f5b40a2c6d140b597bcbe03c0eb8101727833846b.mp3", "hash": "a3e43a9a0d3550871ab0d1f28d0719c5ece7b35ad76e6aff3f90829e7c47ceeb", "bytes": 73296, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/be07752329012442842c2c4f5b40a2c6d140b597bcbe03c0eb8101727833846b.mp3", "duration_ms": 12160}, "s1-make-change.prompt": {"url": "http://localhost:4006/files/lesson-audio/f033c65e1a352797ea8606782091a8341b4c4463cafef2e30ad3fcd4748c2ba2.mp3", "hash": "ebc5c87634a0d4e8b2ccd5b1be59fca0ebdd6ba1fb1b357fbb53a97a892bd927", "bytes": 52704, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/f033c65e1a352797ea8606782091a8341b4c4463cafef2e30ad3fcd4748c2ba2.mp3", "duration_ms": 8720}, "s1-make-change.explanation": {"url": "http://localhost:4006/files/lesson-audio/6f02253ecf806965a58339d1546befd5c3cbe2326defbb7ae497d12a7b89c69c.mp3", "hash": "6a8ba8aba25d1b273968a7fd83016a5c4721aa87bb981ffcf48a910e83d0d2bf", "bytes": 139536, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/6f02253ecf806965a58339d1546befd5c3cbe2326defbb7ae497d12a7b89c69c.mp3", "duration_ms": 23200}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a8fced2e-cab0-454c-866f-d7f94e9da924', 'pt-BR', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "combo-dinero", "title": "Fechando o caixa do domingo", "locale": "pt-BR", "subject": "mixed", "objectives": ["Contar moedas para encontrar o total arrecadado", "Dar o troco correto ao pagar com cédula", "Usar a poupança semanal para planejar uma meta"], "estimated_minutes": 7}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-coin-count", "xp": 15, "type": "coin_count", "title": "Conte as moedas do dia", "payload": {"target": 20, "currency": "BRL", "denominations": [1, 5, 10]}, "narrator": {"emotion": "neutral", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/60d6518c95175f621f61fba2a67d23155e246f891d7eece779526a422dc124c3.webp", "prompt_md": "Fechou o caixa da barraca. Junte moedas de 1, 5 e 10 reais para ter os 20 que entraram hoje.", "difficulty": 2, "explanation_md": "Juntou 20 reais, o mesmo que entrou no caixa da barraca de Liruf. Bom fechamento do dia!", "audio_segment_id": "s1-coin-count.prompt"}, {"id": "s2-make-change", "xp": 20, "type": "make_change", "hints": ["Pense: a cédula é de 20 e o copo custa 5. Quanto sobra? Depois junte moedas que somem isso."], "title": "Dê o troco para a cliente", "payload": {"price": 5, "currency": "BRL", "paid_with": 20, "denominations": [1, 2, 5, 10]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/d015f61b9b1392114d4a9a0dde5f46cf77d34f5e4e56124b21c5053ff794acbc.webp", "prompt_md": "A última cliente pagou com cédula de 20 reais um copo de 5 reais. Prepare o troco exato para devolver a ela.", "difficulty": 3, "explanation_md": "Devolveu 15 reais: a cédula de 20 menos os 5 do copo. Assim a cliente paga o justo.", "audio_segment_id": "s2-make-change.prompt"}, {"id": "s3-savings-goal", "xp": 15, "type": "savings_goal", "title": "Quantos domingos faltam?", "payload": {"goal": 40, "currency": "BRL", "weekly_options": [20]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Faltam 40 reais para a guitarra. Se todo domingo você economiza 20 reais, quantos domingos faltam?", "difficulty": 2, "explanation_md": "Você precisa de mais 2 domingos: 20 mais 20 são 40, exatamente o que falta para a guitarra.", "audio_segment_id": "s3-savings-goal.prompt"}], "schema_version": 1}', '{"s1-coin-count": {}, "s2-make-change": {}, "s3-savings-goal": {}}', '{"units": {"s1-coin-count.prompt": {"url": "http://localhost:4006/files/lesson-audio/b53790ef544c4436efd58f7e4a62e2aca8632c9fa67d57a65989141a129126fe.mp3", "hash": "0faa37f7e270ecb4dfe199179dc8d1a3a81258f51167a43f9a4f41ea41074082", "bytes": 49824, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/b53790ef544c4436efd58f7e4a62e2aca8632c9fa67d57a65989141a129126fe.mp3", "duration_ms": 8240}, "s2-make-change.hint.0": {"url": "http://localhost:4006/files/lesson-audio/5fbf268988a5a90643d21181491e4f0ec87a119db45ad51b55c6915d971d1277.mp3", "hash": "e680db8be280247e9a3114a596e27849d3afdef6ff896d279bd9614d6791afff", "bytes": 54576, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/5fbf268988a5a90643d21181491e4f0ec87a119db45ad51b55c6915d971d1277.mp3", "duration_ms": 9040}, "s2-make-change.prompt": {"url": "http://localhost:4006/files/lesson-audio/6e87e0b39e6b439f27aed1efe35e310fbbd67f9d5e9629c15196ce37ad769f5a.mp3", "hash": "55980bc21e3f09ed8f5985f9240fff3a976ad313c4d080040f0963bfeb84e58f", "bytes": 52704, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/6e87e0b39e6b439f27aed1efe35e310fbbd67f9d5e9629c15196ce37ad769f5a.mp3", "duration_ms": 8720}, "s3-savings-goal.prompt": {"url": "http://localhost:4006/files/lesson-audio/95d9270529087c7792a8c5c9ab9a98e54e064b89b5fc6ac48a201341a2ff3ed2.mp3", "hash": "679396fee0824702e06bcfe80db0e86323ad16a3f912b49a7ec752db01a3b096", "bytes": 47808, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/95d9270529087c7792a8c5c9ab9a98e54e064b89b5fc6ac48a201341a2ff3ed2.mp3", "duration_ms": 7920}, "s1-coin-count.explanation": {"url": "http://localhost:4006/files/lesson-audio/705e238e5923c0d55675b68bf647ba92ae8fc248d8a42effd35641114ab88cb6.mp3", "hash": "59bd32ec630b63aa4cea0c97c2da46b5b724a32120a316061392528f3e23c8cc", "bytes": 37728, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/705e238e5923c0d55675b68bf647ba92ae8fc248d8a42effd35641114ab88cb6.mp3", "duration_ms": 6240}, "s2-make-change.explanation": {"url": "http://localhost:4006/files/lesson-audio/d3a5281f104a2a44045be7410a0402e1ef674a53a36c6fbdcfff10cc95d23bf5.mp3", "hash": "8343881718142d7359bc25c043be157714ffacdf5ed4e529d3e0a89c96106f86", "bytes": 49824, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/d3a5281f104a2a44045be7410a0402e1ef674a53a36c6fbdcfff10cc95d23bf5.mp3", "duration_ms": 8240}, "s3-savings-goal.explanation": {"url": "http://localhost:4006/files/lesson-audio/e2a05a38794eb540c29157bf7b533724891fa22e616716e3b03bcba0e7bc0a57.mp3", "hash": "a8acba66d6a336d8177eb4dfa07fcf4efc30303589a361827e8c371e51e7c1a4", "bytes": 41616, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/e2a05a38794eb540c29157bf7b533724891fa22e616716e3b03bcba0e7bc0a57.mp3", "duration_ms": 6880}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('bd130a62-6800-475b-8af6-59f14ffebc50', 'pt-BR', '1', '{"meta": {"cast": ["liruf"], "slug": "number-input", "title": "Calcular as vendas de Liruf", "locale": "pt-BR", "subject": "mixed", "objectives": ["Calcular e escrever quanto Liruf ganhou no total se vendeu 4 copos a 5 reais cada um (20 reais)."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-calculate-total", "xp": 15, "type": "number_input", "hints": ["Pense: cada copo custa 5 reais e Liruf vendeu 4 copos.", "Multiplique o número de copos pelo preço de cada um: 4 × 5 = ?"], "title": "Quanto Liruf ganhou?", "payload": {"unit": "reais", "decimals_hint": 0}, "narrator": {"emotion": "happy", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/fe7179f0bbc4c926310af08a7bdf5835d72f426d5f5c2daaa22d239135e3cd96.webp", "prompt_md": "Liruf vendeu 4 copos de limonada a 5 reais cada um. Quanto dinheiro ele ganhou no total?", "difficulty": 2, "explanation_md": "Liruf vendeu 4 copos a 5 reais cada um, então juntou 4 vezes 5 reais. 4 × 5 = 20. Ele ganhou 20 reais no total.", "audio_segment_id": "s1-calculate-total.prompt"}], "schema_version": 1}', '{"s1-calculate-total": {"value": 20, "tolerance": 0}}', '{"units": {"s1-calculate-total.hint.0": {"url": "http://localhost:4006/files/lesson-audio/90d2539a3c529ae30bb6b7ed5a0e2b76cb6ee5580fe549d4a586d081ea38461d.mp3", "hash": "333dea1e8bb94660b01f5b549924dd152230158a7851e8a078c4c324d59dfded", "bytes": 31968, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/90d2539a3c529ae30bb6b7ed5a0e2b76cb6ee5580fe549d4a586d081ea38461d.mp3", "duration_ms": 5280}, "s1-calculate-total.hint.1": {"url": "http://localhost:4006/files/lesson-audio/b7781f473a722c411d3a61da101d974270e458c9c4d8b2fb858572154f17366a.mp3", "hash": "107f0498e43100bb834032a25e3989e94f4b1744cad44fbc434c65be93d029a3", "bytes": 31968, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/b7781f473a722c411d3a61da101d974270e458c9c4d8b2fb858572154f17366a.mp3", "duration_ms": 5280}, "s1-calculate-total.prompt": {"url": "http://localhost:4006/files/lesson-audio/8cc13504f340693e5ab839f1950ff18e9753ebe910657065989212bed698df56.mp3", "hash": "b0b1b4e5e4ae15e1f4df0d66a67ba8045c7fe4c0996da824fb7b0d388bb49f50", "bytes": 40608, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/8cc13504f340693e5ab839f1950ff18e9753ebe910657065989212bed698df56.mp3", "duration_ms": 6720}, "s1-calculate-total.explanation": {"url": "http://localhost:4006/files/lesson-audio/33413306f44c41bae98093cdfce331e5e8157c495d2e6a443470bd6a0b205683.mp3", "hash": "389832074ffa90153bc03473a4f2c79b5a231426821eac4bd0eecfb005565ee2", "bytes": 71856, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/33413306f44c41bae98093cdfce331e5e8157c495d2e6a443470bd6a0b205683.mp3", "duration_ms": 11920}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('36624bae-eea6-49e3-8767-c43ffbdf09e7', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "compare-table", "title": "Compara precios de limones", "locale": "es-MX", "subject": "mixed", "objectives": ["Leer una tabla comparativa de proveedores y elegir la mejor opción."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-compare-table", "xp": 5, "type": "compare_table", "hints": ["Piensa: ¿cuál de los dos vende más barato los mismos limones? Fíjate en los precios."], "title": "Compara proveedores", "payload": {"cols": [{"id": "precio", "label": "Precio por 10 limones"}, {"id": "mejor", "label": "¿Mejor opción?"}], "rows": [{"id": "lula", "label": "Doña Lula"}, {"id": "pepe", "label": "Don Pepe"}], "tokens": [{"id": "t1", "text_md": "5 pesos"}, {"id": "t2", "text_md": "6 pesos"}, {"id": "t3", "text_md": "Sí"}, {"id": "t4", "text_md": "No"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/20120b0e43fad58a282c95ec7caa53ff6d6cb1f28207a860457c0528ff9fc265.webp", "prompt_md": "Doña Lula: 10 limones por 5 pesos. Don Pepe: 10 limones por 6 pesos. Completa la tabla y toca ''Sí'' o ''No'' para la mejor opción.", "difficulty": 1, "explanation_md": "Doña Lula cobra 5 pesos por 10 limones, menos que los 6 pesos de Don Pepe. ¡Así obtienes más limones por tu dinero!", "audio_segment_id": "s1-compare-table.prompt"}], "schema_version": 1}', '{"s1-compare-table": {"cells": {"lula:mejor": "t3", "pepe:mejor": "t4", "lula:precio": "t1", "pepe:precio": "t2"}}}', '{"units": {"s1-compare-table.hint.0": {"url": "http://localhost:4006/files/lesson-audio/aacb736733e1bc13c497bcace94ef5c90fbb53b565ba40f9900663088f867730.mp3", "hash": "c64c06294bbc3bd6fb871f4987e1f009bd7de7c9dbe6546c5a3ee15a715def0a", "bytes": 37728, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/aacb736733e1bc13c497bcace94ef5c90fbb53b565ba40f9900663088f867730.mp3", "duration_ms": 6240}, "s1-compare-table.prompt": {"url": "http://localhost:4006/files/lesson-audio/3da6e4c31f403f507501e1727d6fce7445a731ff11bd8faeea0e0db90dc86098.mp3", "hash": "0d46a42342d32f1e3696c7a83e0b18068290b0c5d7db65db1eb659e6d12e8348", "bytes": 64656, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/3da6e4c31f403f507501e1727d6fce7445a731ff11bd8faeea0e0db90dc86098.mp3", "duration_ms": 10720}, "s1-compare-table.explanation": {"url": "http://localhost:4006/files/lesson-audio/fbf18dbdca15fb52b8d2f8a557c28badc3ac6851b983bcbcf9ca3b5b98264334.mp3", "hash": "582b8da8fa476c993621b21c3c6d21d48981eea8be12969dcda01570f3a07fe5", "bytes": 51264, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/fbf18dbdca15fb52b8d2f8a557c28badc3ac6851b983bcbcf9ca3b5b98264334.mp3", "duration_ms": 8480}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8f1a89c3-ae63-41f5-a2fa-70d1b7c6aac9', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "coin-count", "title": "Counting coins for the sale", "locale": "en-US", "subject": "mixed", "objectives": ["Practice counting Mexican coins of 1 and 2 dollars to make exactly 5 dollars."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-coin-count", "xp": 5, "type": "coin_count", "title": "Putting together the 5 dollars", "payload": {"target": 5, "currency": "USD", "denominations": [1, 2]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/0cffb448715c8f917aa93804a4e19711e7831dbe05c16bebfb9afe801a60bc44.webp", "prompt_md": "Liruf sold a cup for 5 dollars. Use coins of 1 and 2 to put together exactly 5 dollars.", "difficulty": 1, "explanation_md": "Liruf now knows that 5 dollars can be made with coins of 1 and 2. Counting each payment correctly is important to reach his goal of 80 dollars.", "audio_segment_id": "s1-coin-count.prompt"}], "schema_version": 1}', '{"s1-coin-count": {}}', '{"units": {"s1-coin-count.prompt": {"url": "http://localhost:4006/files/lesson-audio/b668ea267d996225e3c3c486575bc2e83b0a8a653a2ad4078c537582cfdd4fe6.mp3", "hash": "5fcd747b0be1c22656cc891ebc0be4e06b86069db88247bcab6d73749f333b18", "bytes": 33408, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/b668ea267d996225e3c3c486575bc2e83b0a8a653a2ad4078c537582cfdd4fe6.mp3", "duration_ms": 5520}, "s1-coin-count.explanation": {"url": "http://localhost:4006/files/lesson-audio/0c4785c3738cd2605d9297d2f06235645d622601ff461929fdd270fcebbe9fca.mp3", "hash": "2cc9c6a591446bec7663558e63d9138bf8113e7ff713c362e3c9b6a6a256d8f7", "bytes": 45936, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/0c4785c3738cd2605d9297d2f06235645d622601ff461929fdd270fcebbe9fca.mp3", "duration_ms": 7600}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4785eb58-e0ca-4b5c-a796-a6f01b2ab3ae', 'es-MX', '1', '{"meta": {"cast": ["zara"], "slug": "pattern-complete", "title": "La escalera de precios", "locale": "es-MX", "subject": "mixed", "objectives": ["Identificar el patrón visual de la escalera de precios."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-escalera", "xp": 15, "type": "pattern_complete", "title": "La escalera de vasos", "payload": {"options": [{"id": "vaso-grande", "icon": "local_cafe", "tint": "warning"}, {"id": "vaso-chico", "icon": "local_cafe", "tint": "primary"}, {"id": "vaso-mediano", "icon": "local_cafe", "tint": "accent"}], "sequence": [{"icon": "local_cafe", "tint": "primary"}, {"icon": "local_cafe", "tint": "accent"}, {"icon": "local_cafe", "tint": "warning"}, {"icon": "local_cafe", "tint": "primary"}, {"icon": "local_cafe", "tint": "accent"}], "missing_slots": 1}, "narrator": {"emotion": "happy", "character": "zara"}, "prompt_md": "¿Qué vaso sigue en el patrón?", "difficulty": 2, "explanation_md": "Zara ordenó los vasos en escalera: chico, mediano, grande. El patrón repite los tres tamaños. ¡El vaso grande era el siguiente!", "audio_segment_id": "s1-escalera.prompt"}], "schema_version": 1}', '{"s1-escalera": {"correct": {"0": "vaso-grande"}}}', '{"units": {"s1-escalera.prompt": {"url": "http://localhost:4006/files/lesson-audio/7f0703e399f94493231a61581ac9a61bb6eb0e19a893e142350923483c4e47d9.mp3", "hash": "57a8b4afc5f44bf62c5a11e92c0a9ffeecf79fee2ce99d5dd40c7d26d241fa89", "bytes": 10944, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/7f0703e399f94493231a61581ac9a61bb6eb0e19a893e142350923483c4e47d9.mp3", "duration_ms": 1760}, "s1-escalera.explanation": {"url": "http://localhost:4006/files/lesson-audio/6ec001e1da55ec32df4d01d3f71f670805776c2c4578e450c4d658eefbbdc653.mp3", "hash": "32830a17213bc94918b5a43009b01c9db3f3e37368da6d69143e6ab44a5b5249", "bytes": 53136, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/6ec001e1da55ec32df4d01d3f71f670805776c2c4578e450c4d658eefbbdc653.mp3", "duration_ms": 8800}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4785eb58-e0ca-4b5c-a796-a6f01b2ab3ae', 'pt-BR', '1', '{"meta": {"cast": ["zara"], "slug": "pattern-complete", "title": "A escada de preços", "locale": "pt-BR", "subject": "mixed", "objectives": ["Identificar o padrão visual da escada de preços."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-escalera", "xp": 15, "type": "pattern_complete", "title": "A escada de copos", "payload": {"options": [{"id": "vaso-grande", "icon": "local_cafe", "tint": "warning"}, {"id": "vaso-chico", "icon": "local_cafe", "tint": "primary"}, {"id": "vaso-mediano", "icon": "local_cafe", "tint": "accent"}], "sequence": [{"icon": "local_cafe", "tint": "primary"}, {"icon": "local_cafe", "tint": "accent"}, {"icon": "local_cafe", "tint": "warning"}, {"icon": "local_cafe", "tint": "primary"}, {"icon": "local_cafe", "tint": "accent"}], "missing_slots": 1}, "narrator": {"emotion": "happy", "character": "zara"}, "prompt_md": "Qual copo segue no padrão?", "difficulty": 2, "explanation_md": "Zara ordenou os copos em escada: pequeno, médio, grande. O padrão repete os três tamanhos. O copo grande era o próximo!", "audio_segment_id": "s1-escalera.prompt"}], "schema_version": 1}', '{"s1-escalera": {"correct": {"0": "vaso-grande"}}}', '{"units": {"s1-escalera.prompt": {"url": "http://localhost:4006/files/lesson-audio/231d29c78a9934dcdec6b343b021cbb9d1cdfb1a3eb272a1e5191f1e37770426.mp3", "hash": "1e26d3276436b878c2eeec1e617f014d1070c9e1e41de0d439c78ed607d85fd0", "bytes": 13248, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/231d29c78a9934dcdec6b343b021cbb9d1cdfb1a3eb272a1e5191f1e37770426.mp3", "duration_ms": 2160}, "s1-escalera.explanation": {"url": "http://localhost:4006/files/lesson-audio/cbb6643b229401e8e7c4b3cc897e249e719ae1dbc52d9b70ad7e76446d046d7a.mp3", "hash": "66aaf841e7657ed098aa59788e63a315d161626c7471f3115c9cd60c2d4eb44f", "bytes": 54576, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/cbb6643b229401e8e7c4b3cc897e249e719ae1dbc52d9b70ad7e76446d046d7a.mp3", "duration_ms": 9040}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a0b48602-bbeb-4aac-8309-90ec3cdeba90', 'es-MX', '1', '{"meta": {"cast": ["rho"], "slug": "number-line", "title": "En la recta al ahorro", "locale": "es-MX", "subject": "mixed", "objectives": ["Ubicar ahorros y metas en una recta numérica para visualizar el progreso."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-number-line", "xp": 5, "type": "number_line", "title": "¿Cuánto falta?", "payload": {"max": 100, "min": 0, "ticks": 10, "labels": false}, "narrator": {"emotion": "encouraging", "character": "rho"}, "prompt_md": "Liruf tiene 20 pesos ahorrados. Toca en la recta dónde está 20.", "difficulty": 1, "explanation_md": "Tu ahorro está en 20. La meta de 80 pesos está más adelante. Te faltan 60 pesos."}], "schema_version": 1}', '{"s1-number-line": {"value": 20, "full_credit_delta": 0, "zero_credit_delta": 10}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('574fb312-93f9-4f2f-adea-606bbb0ca99d', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "best-decision", "title": "A Melhor Decisão: Dar o Troco", "locale": "pt-BR", "subject": "mixed", "objectives": ["Escolher a melhor maneira de dar o troco quando um cliente paga com uma nota grande, demonstrando honestidade e precisão."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-mejor-decision", "xp": 15, "type": "best_decision", "hints": ["Pense em quanto dinheiro Liruf deve devolver depois de cobrar 5 reais com uma nota de 20."], "title": "A Melhor Decisão de Liruf", "payload": {"options": [{"id": "opt-correcto", "text_md": "Contar o troco devagar: 10, 15 reais, e entregá-lo com um sorriso.", "rationale_md": "Contar o troco passo a passo garante exatidão e demonstra honestidade."}, {"id": "opt-adivinar", "text_md": "Olhar a nota e adivinhar: ''Acho que são 15, pegue''.", "rationale_md": "Adivinhar o troco pode levar a erros e a que o cliente receba menos ou mais dinheiro do que o correto."}, {"id": "opt-extra", "text_md": "Dizer-lhe: ''Aqui tem 20 reais de troco'', porque é mais fácil.", "rationale_md": "Dar 20 reais em vez de 15 seria dar 5 reais extras; Liruf perderia dinheiro de sua venda."}, {"id": "opt-quedar", "text_md": "Guardar a nota e não dar troco, porque é uma nota grande.", "rationale_md": "Não dar o troco é ficar com dinheiro que não lhe pertence; isso é desonesto e o cliente iria embora chateado."}], "scenario_md": "Liruf vende limonada. Um copo custa 5 reais. Uma cliente paga com uma nota de 20."}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/cb3c3b1cac4b3ef38234b9471a3627f372e7e82f717c9a537d6b6bcc826ef349.webp", "prompt_md": "Uma cliente paga seu copo de 5 reais com uma nota de 20. Liruf deve decidir como dar o troco. Qual é a MELHOR opção?", "difficulty": 2, "explanation_md": "O troco correto é 15 reais. Contar as moedas uma por uma evita erros e mostra que Liruf é honesto e cuidadoso com o dinheiro de seus clientes.", "audio_segment_id": "s1-mejor-decision.prompt"}], "schema_version": 1}', '{"s1-mejor-decision": {"qualities": {"opt-extra": 10, "opt-quedar": 0, "opt-adivinar": 20, "opt-correcto": 100}}}', '{"units": {"s1-mejor-decision.hint.0": {"url": "http://localhost:4006/files/lesson-audio/0cb43a2415754ba1888bc669308e17f2430ec4f927428cbab9800b90b1031833.mp3", "hash": "41f828648c6d977bbfb8cd14225f8fe21d8de9da4ee795aa60b4acbd8c847021", "bytes": 35424, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/0cb43a2415754ba1888bc669308e17f2430ec4f927428cbab9800b90b1031833.mp3", "duration_ms": 5840}, "s1-mejor-decision.prompt": {"url": "http://localhost:4006/files/lesson-audio/3eac1fb8991417d9cf4e626656e75488f38d0ce1cb56fa3c663d20f7539c32da.mp3", "hash": "36f439f8b433bdb33dd84a6d3e86ca918eec519b6a40bd302532b8ff6aa39118", "bytes": 55584, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/3eac1fb8991417d9cf4e626656e75488f38d0ce1cb56fa3c663d20f7539c32da.mp3", "duration_ms": 9200}, "s1-mejor-decision.choices": {"url": "http://localhost:4006/files/lesson-audio/62d705de59e57cae6a00f35d5de27258960198e57ba5aaa1b65e296105eb2933.mp3", "hash": "9182b3e9c5f38dfa306e0d9085f744dcade7f5c3ddc827f6453a2be0dbc108cc", "bytes": 102528, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/62d705de59e57cae6a00f35d5de27258960198e57ba5aaa1b65e296105eb2933.mp3", "duration_ms": 17040}, "s1-mejor-decision.explanation": {"url": "http://localhost:4006/files/lesson-audio/ef4d6932233280f3f657b62bdc5f81bff64ce879d8cb571bd4598aaf109fc53a.mp3", "hash": "dd2eafa0923a6a1bac2d0afc10850854a6acccefa6ea89975acd17068d12bbe9", "bytes": 61776, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/ef4d6932233280f3f657b62bdc5f81bff64ce879d8cb571bd4598aaf109fc53a.mp3", "duration_ms": 10240}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c9d7856b-a75e-414e-ae61-e324a19a350d', 'pt-BR', '1', '{"meta": {"cast": ["rho"], "slug": "measure-read", "title": "A jarra medidora", "locale": "pt-BR", "subject": "money", "objectives": ["Resolver desafios de construção e medição aplicados ao cargo: ordenar instruções, ler medidas e equilibrar quantidades."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-read", "xp": 5, "type": "measure_read", "hints": ["Observe com cuidado a linha do líquido e conte as marcas a partir de baixo."], "title": "A linha do copo justo", "payload": {"max": 400, "min": 0, "unit": "ml", "ticks": 9, "instrument": "beaker", "pointer_value": 250}, "narrator": {"emotion": "encouraging", "character": "rho"}, "image_url": "http://localhost:4006/files/lesson-images/61b130a0856f0617572f59e50edcb691ed37af870891464ed68f92d8d91fcad9.webp", "prompt_md": "Rho diz: ''Cada copo justo deve chegar à mesma marca.'' Leia a jarra e me diga quantos mililitros ela marca.", "difficulty": 1, "explanation_md": "A jarra mostra 250 ml porque o líquido chega exatamente a essa marca. Assim cada copo recebe a mesma quantidade e todos pagam o mesmo."}], "schema_version": 1}', '{"s1-read": {"value": 250, "tolerance": 0}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('462e0be5-c40d-4de9-840d-6f696539d27e', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "combo-dialogo-doble-choice", "title": "Vecinos opinan del puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Escuchar atentamente una conversación entre vecinos sobre el puesto de limonada.", "Decidir si una afirmación es cierta o falsa basándose en lo escuchado.", "Identificar la moneda correcta usada en la compra entre imágenes."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-listen", "xp": 0, "type": "story_dialogue", "title": "La mesa de al lado", "payload": {"lines": [{"action": "idle", "emotion": "happy", "text_md": "¿Te acuerdas? El sábado pasado Liruf puso su puesto de limonada por primera vez. Hoy está de vuelta.", "character": "dina"}, {"action": "idle", "emotion": "thinking", "text_md": "Sí, y veo que ahora tiene clientes. ¿A cuánto vende el vaso?", "character": "rho"}, {"action": "idle", "emotion": "excited", "text_md": "A 5 pesos. ¡Qué barato! Yo traigo un billete de 20, pero no cambio.", "character": "dina"}, {"action": "idle", "emotion": "happy", "text_md": "Pues yo voy a pedir uno. Aquí traigo una moneda de 10 pesos, así me devuelven 5.", "character": "rho"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/97a5280d1a7fa9c90800b9e02595bab31ace484528065964258c878b532fb1ec.webp", "prompt_md": "Dos vecinos platican en la mesa de al lado. Escucha.", "difficulty": 1, "audio_segment_id": "s1-listen.prompt"}, {"id": "s2-true", "xp": 10, "type": "true_false", "title": "¿Cierto o falso?", "payload": {"statement_md": "Una vecina dijo que la limonada es cara.", "justifications": [{"id": "barato", "text_md": "Porque dijo ''¡Qué barato!'', lo que significa que no es cara."}, {"id": "precio", "text_md": "Porque el vaso cuesta 5 pesos y eso la hace cara."}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "¿Es cierto lo que dice esta frase?", "difficulty": 2, "explanation_md": "Dina dijo ''¡Qué barato!'', así que la limonada NO le parece cara. Prestar atención a las palabras exactas es importante.", "audio_segment_id": "s2-true.prompt"}, {"id": "s3-coin", "xp": 10, "type": "picture_choice", "title": "La moneda que usó", "payload": {"options": [{"id": "c5", "icon": "payments", "label": "Moneda de 5 pesos", "image_url": "http://localhost:4006/files/lesson-images/652da598efa28187d0fceeed66bf0f59a603bfbe50aa719aebe3bc5a5ba4042c.webp", "rationale_md": "Rho iba a comprar un vaso que cuesta 5 pesos, pero usó una moneda de 10 para que le dieran cambio."}, {"id": "c10", "icon": "payments", "label": "Moneda de 10 pesos", "image_url": "http://localhost:4006/files/lesson-images/b555ba34ba4bab919345899f7d495c6b513ad119f0476731740013d29ffcbce9.webp"}, {"id": "c20", "icon": "payments", "label": "Moneda de 20 pesos", "image_url": "http://localhost:4006/files/lesson-images/2e076df510a67a1f72513ab7335ef46f54f6dab72fc4128790a5d55bee653bc5.webp", "rationale_md": "Dina mencionó un billete de 20, pero ella no compró; fue Rho quien compró y usó 10 pesos."}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "¿Con qué moneda pagó Rho?", "difficulty": 2, "explanation_md": "Rho dijo: ''Aquí traigo una moneda de 10 pesos''. Por eso la imagen correcta es la moneda de 10 pesos.", "audio_segment_id": "s3-coin.prompt"}], "schema_version": 1}', '{"s2-true": {"is_true": false, "correct_justification_id": "barato"}, "s3-coin": {"correct_option_id": "c10"}}', '{"units": {"s2-true.prompt": {"url": "http://localhost:4006/files/lesson-audio/7db153d9ca0641600aa110d448c42c73a9dcaa11c5917b016d825a3882710741.mp3", "hash": "a193b7ccc2b0f230a56b4fecfdf88922402c83f3ac76ca71550388ee7249c2c3", "bytes": 14256, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/7db153d9ca0641600aa110d448c42c73a9dcaa11c5917b016d825a3882710741.mp3", "duration_ms": 2320}, "s3-coin.prompt": {"url": "http://localhost:4006/files/lesson-audio/5b16ec06d0f1e03f03d4d899f1e1aa81ef0408a9165d9cf5761babf4767a5c8a.mp3", "hash": "7104f29656b86f8d94664e76252fcd698d3a3ca981cbe8f0cc34e66e4fd513ab", "bytes": 13248, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/5b16ec06d0f1e03f03d4d899f1e1aa81ef0408a9165d9cf5761babf4767a5c8a.mp3", "duration_ms": 2160}, "s3-coin.choices": {"url": "http://localhost:4006/files/lesson-audio/c4ce681976c3c116402a3299db59cf6590f35bc839870e58a81d37dabe3b1ded.mp3", "hash": "299e74965149c13092a4a0a58f1502f5843f28f36d921bd320c80551975cc9c2", "bytes": 38736, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/c4ce681976c3c116402a3299db59cf6590f35bc839870e58a81d37dabe3b1ded.mp3", "duration_ms": 6400}, "s1-listen.line.0": {"url": "http://localhost:4006/files/lesson-audio/9db56fcc46812e0eae3e3a9659b9bec1bdd3f24a561b0d0a7f3eeec34a35e193.mp3", "hash": "c0ee2a56491c0c13a2812ee6c4cd69bae00cded95c1efaf41fd4f32068988e60", "bytes": 42048, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/9db56fcc46812e0eae3e3a9659b9bec1bdd3f24a561b0d0a7f3eeec34a35e193.mp3", "duration_ms": 6960}, "s1-listen.line.1": {"url": "http://localhost:4006/files/lesson-audio/52c75db0a9965afb47d298e4fec7bb4df73287798f5b2f2e9157b78a8d5d1dd9.mp3", "hash": "11e95cf6f4e679a51e93b33e07f4ba412d5187745283d5d99600f705266870ed", "bytes": 29088, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/52c75db0a9965afb47d298e4fec7bb4df73287798f5b2f2e9157b78a8d5d1dd9.mp3", "duration_ms": 4800}, "s1-listen.line.2": {"url": "http://localhost:4006/files/lesson-audio/b8034cf75e6e68e2d33219fd75481152ae2ada11493753e847a077685fcdf87b.mp3", "hash": "4b89ddf3f4b52d8723a537dcd943de7f168b16648f0bf9bdc2dea67d3f7fcd9f", "bytes": 33408, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/b8034cf75e6e68e2d33219fd75481152ae2ada11493753e847a077685fcdf87b.mp3", "duration_ms": 5520}, "s1-listen.line.3": {"url": "http://localhost:4006/files/lesson-audio/6ef7b3263444149f0daa12d66bded52886c85a2ea4343e5d1888761122f4a63f.mp3", "hash": "071937f641002f8df4a60aede5d72ebeb0a8b2a23f05044a7ce1b16515114070", "bytes": 40176, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/6ef7b3263444149f0daa12d66bded52886c85a2ea4343e5d1888761122f4a63f.mp3", "duration_ms": 6640}, "s1-listen.prompt": {"url": "http://localhost:4006/files/lesson-audio/20ecaa0641e99bd9af3fa82f52be64e1b2267fff48ea442b2aca9d039eb025b6.mp3", "hash": "459bbb02176f5e4c200383d0e95f28072d7fe7bba60bd2f310e098863166379f", "bytes": 24336, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/20ecaa0641e99bd9af3fa82f52be64e1b2267fff48ea442b2aca9d039eb025b6.mp3", "duration_ms": 4000}, "s2-true.explanation": {"url": "http://localhost:4006/files/lesson-audio/32fb74e4341d9b328cd85d9417c4f69db0854dc44dc9acb060bf64c5718eb4db.mp3", "hash": "eba4cb6f0ef02237caeef55fcc59429addeb3cdd7991567e53ee9d61f8347875", "bytes": 52704, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/32fb74e4341d9b328cd85d9417c4f69db0854dc44dc9acb060bf64c5718eb4db.mp3", "duration_ms": 8720}, "s3-coin.explanation": {"url": "http://localhost:4006/files/lesson-audio/7fd8f0974fa1b3dfa431a10c51cbc3329149358052a6b7cfcb3fbf036eda2ddb.mp3", "hash": "7cc3b13fb133d648512a8e22850d2de573499ebd25dc83230da6606175f81b2b", "bytes": 46944, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/7fd8f0974fa1b3dfa431a10c51cbc3329149358052a6b7cfcb3fbf036eda2ddb.mp3", "duration_ms": 7760}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9b315200-00f0-4dc4-a2cd-13c1fb40e9aa', 'es-MX', '1', '{"meta": {"cast": ["zara", "liruf"], "slug": "build-sentence", "title": "El letrero del combo", "locale": "es-MX", "subject": "mixed", "objectives": ["Calcular el precio de un combo (2×5 pesos) y armar el letrero del puesto."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 85, "hint_penalty_pct": 10}, "segments": [{"id": "s1-build-sign", "xp": 15, "type": "build_sentence", "hints": ["Piensa: si un vaso cuesta 5 pesos, ¿cuánto cuestan dos vasos?"], "title": "El letrero del combo", "payload": {"slots": 5, "tokens": [{"id": "t1", "text_md": "2"}, {"id": "t2", "text_md": "vasos"}, {"id": "t3", "text_md": "por"}, {"id": "t4", "text_md": "5"}, {"id": "t5", "text_md": "10"}, {"id": "t6", "text_md": "15"}, {"id": "t7", "text_md": "20"}, {"id": "t8", "text_md": "pesos"}]}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "Liruf quiere vender un combo: 2 vasos de limonada. Cada vaso cuesta 5 pesos. Arma el letrero con las palabras y el precio total.", "difficulty": 2, "explanation_md": "El letrero dice ''2 vasos por 10 pesos'' porque 5 + 5 = 10. Si pusieras 5, cobrarías solo un vaso; con 15 o 20, el precio sería muy alto y los clientes no comprarían."}], "schema_version": 1}', '{"s1-build-sign": {"order": ["t1", "t2", "t3", "t5", "t8"]}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1f15af49-9573-4e17-a4ee-0685fa854b90', 'en-US', '1', '{"meta": {"cast": ["liruf"], "slug": "timeline-order", "title": "Liruf''s Daily Schedule", "locale": "en-US", "subject": "mixed", "objectives": ["Order the steps of the sales day in chronological order"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-timeline", "xp": 10, "type": "timeline_order", "hints": ["Think: what did Liruf do first in the morning?", "After preparing, what happened at noon?"], "title": "Liruf''s Daily Schedule", "payload": {"events": [{"id": "comprar", "icon": "shopping_cart", "text_md": "Buy lemons and sugar in the morning", "image_url": "http://localhost:4006/files/lesson-images/b57b624ea4cbdfa3082ab1ec52941c0e3939481b09faefc77f2b0b9ddd8b2a42.webp"}, {"id": "preparar", "icon": "local_dining", "text_md": "Prepare the lemonade", "image_url": "http://localhost:4006/files/lesson-images/0eafd6c8aea3a6aa41b96ca2bf558a2d4d3a6d078fe75e4be7df0e408ca7e884.webp"}, {"id": "vender", "icon": "storefront", "text_md": "Sell lemonade at noon", "image_url": "http://localhost:4006/files/lesson-images/82fa4864bc4c5f7a6b91cb40d718b3d4e9604d5bfd41b46d5f0fd8b4ce29ba8e.webp"}, {"id": "contar", "icon": "payments", "text_md": "Count the money and put it away at closing", "image_url": "http://localhost:4006/files/lesson-images/0833f9741fb423b37e4e49407d7caff9213801697771586c14591f1d7b4b01a1.webp"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf remembers his first day. Tap the events in the order they happened.", "difficulty": 1, "explanation_md": "First you buy the ingredients, then you prepare the lemonade, then you sell it, and finally you count the money and put it away.", "audio_segment_id": "s1-timeline.prompt"}], "schema_version": 1}', '{"s1-timeline": {"order": ["comprar", "preparar", "vender", "contar"]}}', '{"units": {"s1-timeline.hint.0": {"url": "http://localhost:4006/files/lesson-audio/53cd6c212e481a623b1d68a66c8e4fd27282ba73f9e5df03b8f2e0fbe582caa4.mp3", "hash": "0d60007db28a321efabc450b9597643aef3bb37740c8dc1946308209b4c351f5", "bytes": 16128, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/53cd6c212e481a623b1d68a66c8e4fd27282ba73f9e5df03b8f2e0fbe582caa4.mp3", "duration_ms": 2640}, "s1-timeline.hint.1": {"url": "http://localhost:4006/files/lesson-audio/55ade08dcd2b826867cfc6f0bbedfa74fc23e78ee3fa83b6a48ab54f53e2852c.mp3", "hash": "2a086a0accf3d304839468b3fb42a713357a1d33d3b9aa32c1f61925eb8cba5b", "bytes": 13824, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/55ade08dcd2b826867cfc6f0bbedfa74fc23e78ee3fa83b6a48ab54f53e2852c.mp3", "duration_ms": 2240}, "s1-timeline.prompt": {"url": "http://localhost:4006/files/lesson-audio/634802aa36c705de91332d1943fed29b0c5c7538d4a44d15cd7f1ab27ae94e5c.mp3", "hash": "aacd1708c1e93dce65ae359a61809daffc708f96a479fad91bff43b9bdfd7289", "bytes": 25776, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/634802aa36c705de91332d1943fed29b0c5c7538d4a44d15cd7f1ab27ae94e5c.mp3", "duration_ms": 4240}, "s1-timeline.explanation": {"url": "http://localhost:4006/files/lesson-audio/90eae20aa6b77ad2b908e916f9a822fbd6aba67ef2cf8824083a78e7ec696de7.mp3", "hash": "247b763f9ca12a170706ba38312fe561455c1d752c8d2bd289446aecf0b9833a", "bytes": 42048, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/90eae20aa6b77ad2b908e916f9a822fbd6aba67ef2cf8824083a78e7ec696de7.mp3", "duration_ms": 6960}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('462e0be5-c40d-4de9-840d-6f696539d27e', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "combo-dialogo-doble-choice", "title": "Neighbors give their opinion on the stand", "locale": "en-US", "subject": "mixed", "objectives": ["Listen carefully to a conversation between neighbors about the lemonade stand.", "Decide whether a statement is true or false based on what you heard.", "Identify the correct coin used in the purchase from the images."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-listen", "xp": 0, "type": "story_dialogue", "title": "The next table", "payload": {"lines": [{"action": "idle", "emotion": "happy", "text_md": "Do you remember? Last Saturday, Liruf set up their lemonade stand for the first time. Today, they''re back.", "character": "dina"}, {"action": "idle", "emotion": "thinking", "text_md": "Yes, and I see that they now have customers. How much do they sell a cup for?", "character": "rho"}, {"action": "idle", "emotion": "excited", "text_md": "For $5. How cheap! I have a $20 bill, but I don''t have change.", "character": "dina"}, {"action": "idle", "emotion": "happy", "text_md": "Well, I''m going to order one. I have a $10 coin, so they''ll give me $5 back.", "character": "rho"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/3e93d4423e8478634ea5b208165b75834cf7caa6338f23309114e59e95d45b78.webp", "prompt_md": "Two neighbors are chatting at the next table. Listen.", "difficulty": 1, "audio_segment_id": "s1-listen.prompt"}, {"id": "s2-true", "xp": 10, "type": "true_false", "title": "True or false?", "payload": {"statement_md": "A neighbor said that the lemonade is expensive.", "justifications": [{"id": "barato", "text_md": "Because she said ''How cheap!'', which means it''s not expensive."}, {"id": "precio", "text_md": "Because a cup costs $5 and that makes it expensive."}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Is what this sentence says true?", "difficulty": 2, "explanation_md": "Dina said ''How cheap!'', so the lemonade does NOT seem expensive to her. Paying attention to the exact words is important.", "audio_segment_id": "s2-true.prompt"}, {"id": "s3-coin", "xp": 10, "type": "picture_choice", "title": "The coin she used", "payload": {"options": [{"id": "c5", "icon": "payments", "label": "$5 coin", "image_url": "http://localhost:4006/files/lesson-images/652da598efa28187d0fceeed66bf0f59a603bfbe50aa719aebe3bc5a5ba4042c.webp", "rationale_md": "Rho was going to buy a cup that costs $5, but used a $10 coin so they would get change."}, {"id": "c10", "icon": "payments", "label": "$10 coin", "image_url": "http://localhost:4006/files/lesson-images/b555ba34ba4bab919345899f7d495c6b513ad119f0476731740013d29ffcbce9.webp"}, {"id": "c20", "icon": "payments", "label": "$20 coin", "image_url": "http://localhost:4006/files/lesson-images/2e076df510a67a1f72513ab7335ef46f54f6dab72fc4128790a5d55bee653bc5.webp", "rationale_md": "Dina mentioned a $20 bill, but she didn''t buy anything; it was Rho who bought and used $10."}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "What coin did Rho pay with?", "difficulty": 2, "explanation_md": "Rho said: ''I have a $10 coin.'' That''s why the correct image is the $10 coin.", "audio_segment_id": "s3-coin.prompt"}], "schema_version": 1}', '{"s2-true": {"is_true": false, "correct_justification_id": "barato"}, "s3-coin": {"correct_option_id": "c10"}}', '{"units": {"s2-true.prompt": {"url": "http://localhost:4006/files/lesson-audio/f04d18d90cd2c0150beeeb3cf1fbfd3f84ee6674e2266ad85dbf60952f312ca5.mp3", "hash": "c691699f47dbd0f7334dedd5765bed97a45c26df6f1c8d9395b866b1b8400262", "bytes": 12816, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/f04d18d90cd2c0150beeeb3cf1fbfd3f84ee6674e2266ad85dbf60952f312ca5.mp3", "duration_ms": 2080}, "s3-coin.prompt": {"url": "http://localhost:4006/files/lesson-audio/5140d885699fc4567a9c4b8b553ea23440db10c51096242507c37a556944ca71.mp3", "hash": "937647e3b3cdce063c14c330cae59f74fd7f999e5f28752a555156beab08c42a", "bytes": 10944, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/5140d885699fc4567a9c4b8b553ea23440db10c51096242507c37a556944ca71.mp3", "duration_ms": 1760}, "s3-coin.choices": {"url": "http://localhost:4006/files/lesson-audio/184a208bec2ca66ffb33e113ded02124378d3b6552e32d9df81a187e1de51e32.mp3", "hash": "2b86ba78fae974c450aac09d8425abb614762207f35b800d399fdb0f3d526c13", "bytes": 24336, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/184a208bec2ca66ffb33e113ded02124378d3b6552e32d9df81a187e1de51e32.mp3", "duration_ms": 4000}, "s1-listen.line.0": {"url": "http://localhost:4006/files/lesson-audio/e788b7e4f96ed9420f4b243bc68cd863e230251745516d8fec2a7f4ea4f93f6b.mp3", "hash": "29d38639cb548b6ffcbe8482f35302949963e79bbc4f904edc2405404beba455", "bytes": 39168, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/e788b7e4f96ed9420f4b243bc68cd863e230251745516d8fec2a7f4ea4f93f6b.mp3", "duration_ms": 6480}, "s1-listen.line.1": {"url": "http://localhost:4006/files/lesson-audio/154b07e0ddfb72a90eca401c6e418ca18f2f66178639616da5177601a6123bfd.mp3", "hash": "4185df3873279f186a775be494c087f449a995d74ffbaa88ff14fc2bf0b937dc", "bytes": 32544, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/154b07e0ddfb72a90eca401c6e418ca18f2f66178639616da5177601a6123bfd.mp3", "duration_ms": 5360}, "s1-listen.line.2": {"url": "http://localhost:4006/files/lesson-audio/959e1d8587e2465898b3ae344426072c1c75bbe7f34f0d74e43012a848f6130c.mp3", "hash": "346312d29ad95336f244dba21e09682a34b85aed267c6734d862ae8b3f0cc00c", "bytes": 28656, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/959e1d8587e2465898b3ae344426072c1c75bbe7f34f0d74e43012a848f6130c.mp3", "duration_ms": 4720}, "s1-listen.line.3": {"url": "http://localhost:4006/files/lesson-audio/4abed2a685356dc123ccb014f697a0b05a59d0313b48a2606bc1f568845ff86a.mp3", "hash": "648509bdd9aecbba09be037b4b96e63719c8cbd197a45e5645efae7ac049d03b", "bytes": 37296, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/4abed2a685356dc123ccb014f697a0b05a59d0313b48a2606bc1f568845ff86a.mp3", "duration_ms": 6160}, "s1-listen.prompt": {"url": "http://localhost:4006/files/lesson-audio/209c8f8d61ab88f4566948fdcb8a1b57c367fbc379cedf5992030ac394c6cf89.mp3", "hash": "487cd25590897291eddc5d7f4ad28b914540a306a394e5924d0916c1acb3adf9", "bytes": 18576, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/209c8f8d61ab88f4566948fdcb8a1b57c367fbc379cedf5992030ac394c6cf89.mp3", "duration_ms": 3040}, "s2-true.explanation": {"url": "http://localhost:4006/files/lesson-audio/294a559bba64408faf0f1b07f9cd32b7e2d0c83b6a325b48f66ecedcad0f70bb.mp3", "hash": "83ca6c13f8a9a5944467ebd66c4c82d4c9a5f8025e4492446f0a17d8432b9478", "bytes": 41616, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/294a559bba64408faf0f1b07f9cd32b7e2d0c83b6a325b48f66ecedcad0f70bb.mp3", "duration_ms": 6880}, "s3-coin.explanation": {"url": "http://localhost:4006/files/lesson-audio/271f43e0a2ebdc927686ef79545810bfcf77fff61c2902f3943e003a7062f601.mp3", "hash": "8b4212244022f535d7617b2fb55aa61e5c9d17090b8e4f5f6dd9630c474afec1", "bytes": 33984, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/271f43e0a2ebdc927686ef79545810bfcf77fff61c2902f3943e003a7062f601.mp3", "duration_ms": 5600}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a8fced2e-cab0-454c-866f-d7f94e9da924', 'es-MX', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "combo-dinero", "title": "Cerrando la caja del domingo", "locale": "es-MX", "subject": "mixed", "objectives": ["Contar monedas para encontrar el total recolectado", "Dar cambio correcto al pagar con billete", "Usar el ahorro semanal para planificar una meta"], "estimated_minutes": 7}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-coin-count", "xp": 15, "type": "coin_count", "title": "Cuenta las monedas del día", "payload": {"target": 20, "currency": "MXN", "denominations": [1, 5, 10]}, "narrator": {"emotion": "neutral", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/0170c0c7a40205020bbd7b60ec083096ee50fd0c09ad6b8f83d5865691777bd0.webp", "prompt_md": "Cerraste la caja del puesto. Junta monedas de 1, 5 y 10 pesos para tener los 20 que entraron hoy.", "difficulty": 2, "explanation_md": "Juntaste 20 pesos, lo mismo que entró en la caja del puesto de Liruf. ¡Buen cierre de día!", "audio_segment_id": "s1-coin-count.prompt"}, {"id": "s2-make-change", "xp": 20, "type": "make_change", "hints": ["Piensa: el billete es de 20 y el vaso cuesta 5. ¿Cuánto le sobra? Luego junta monedas que sumen eso."], "title": "Da el cambio a la clienta", "payload": {"price": 5, "currency": "MXN", "paid_with": 20, "denominations": [1, 2, 5, 10]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/e2932ef34257c032c724aafcce35068f5817ec68b541a27cd2ac30b334cc276b.webp", "prompt_md": "La última clienta pagó con billete de 20 un vaso de 5 pesos. Arma el cambio justo para devolverle.", "difficulty": 3, "explanation_md": "Devolviste 15 pesos: el billete de 20 menos los 5 del vaso. Así la clienta paga lo justo.", "audio_segment_id": "s2-make-change.prompt"}, {"id": "s3-savings-goal", "xp": 15, "type": "savings_goal", "title": "¿Cuántos domingos faltan?", "payload": {"goal": 40, "currency": "MXN", "weekly_options": [20]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Te faltan 40 pesos para la guitarra. Si cada domingo ahorras 20 pesos, ¿cuántos domingos te faltan?", "difficulty": 2, "explanation_md": "Necesitas 2 domingos más: 20 más 20 son 40, justo lo que te falta para la guitarra.", "audio_segment_id": "s3-savings-goal.prompt"}], "schema_version": 1}', '{"s1-coin-count": {}, "s2-make-change": {}, "s3-savings-goal": {}}', '{"units": {"s1-coin-count.prompt": {"url": "http://localhost:4006/files/lesson-audio/003502dc1a28bbee6c5a3913c3374cde1fb26f0e597d0d0ec8d8b2af6a73ffe9.mp3", "hash": "4b2a5e1c54ca0db1de0011081d0b885bc5f1af6395d98b3d81fa5c3c77202354", "bytes": 45504, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/003502dc1a28bbee6c5a3913c3374cde1fb26f0e597d0d0ec8d8b2af6a73ffe9.mp3", "duration_ms": 7520}, "s2-make-change.hint.0": {"url": "http://localhost:4006/files/lesson-audio/f4342b5430278cf554bd4eecc973949b082d895cf00fc7dffac5cbff9b6727b2.mp3", "hash": "03ba5c6a4975ff49aca2680a6cbb624caa0b062a5c256d7cf32dc82ab273dd39", "bytes": 44064, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/f4342b5430278cf554bd4eecc973949b082d895cf00fc7dffac5cbff9b6727b2.mp3", "duration_ms": 7280}, "s2-make-change.prompt": {"url": "http://localhost:4006/files/lesson-audio/2ab6ce9686f1425b39f18cb1a697cf6a874eb52290a9bb4d93cdd35820a16832.mp3", "hash": "9d8156852c0c89b4d4a582529288ff5d0c36c9cc70bdb6e4df3bee49759666b2", "bytes": 44496, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/2ab6ce9686f1425b39f18cb1a697cf6a874eb52290a9bb4d93cdd35820a16832.mp3", "duration_ms": 7360}, "s3-savings-goal.prompt": {"url": "http://localhost:4006/files/lesson-audio/bc01956f94650de09a7f6c3072a30bf6de07401e991c3f92096d8638b2a842d8.mp3", "hash": "5b71f50a904f083bb513c06a0a55b40708f35b105bfce1a1cd0f8098292fc0e2", "bytes": 46944, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/bc01956f94650de09a7f6c3072a30bf6de07401e991c3f92096d8638b2a842d8.mp3", "duration_ms": 7760}, "s1-coin-count.explanation": {"url": "http://localhost:4006/files/lesson-audio/906e494caf997d6a1247f4cd35248bbce41f2dc2950d347e52112f30adf747d3.mp3", "hash": "a017902448ce210a34170cd8277009dfbc9fe24f3a6a2533c75f8e32eecb303b", "bytes": 38736, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/906e494caf997d6a1247f4cd35248bbce41f2dc2950d347e52112f30adf747d3.mp3", "duration_ms": 6400}, "s2-make-change.explanation": {"url": "http://localhost:4006/files/lesson-audio/922552d7080b5a1bc76a6e7d5abffe8e3248328e5f685110186be567f1b4d483.mp3", "hash": "388ac1d7f0657ac91296c3015e96406b6a0b6f7d45f04f251f6eee0abada21d0", "bytes": 42048, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/922552d7080b5a1bc76a6e7d5abffe8e3248328e5f685110186be567f1b4d483.mp3", "duration_ms": 6960}, "s3-savings-goal.explanation": {"url": "http://localhost:4006/files/lesson-audio/a29b17b2fce97a2a29d7618fbcc169cd51c48aeb8356cf1332486e83cd70376c.mp3", "hash": "23ea614c3a776104fde5c9a0c6334c25d97b2b72b6f84eb87893a01176ca292e", "bytes": 40176, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/a29b17b2fce97a2a29d7618fbcc169cd51c48aeb8356cf1332486e83cd70376c.mp3", "duration_ms": 6640}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08604886-c155-4f4b-85dd-0b5b853997e1', 'en-US', '1', '{"meta": {"cast": ["liruf"], "slug": "quiz-mcq", "title": "The fair price of lemonade", "locale": "en-US", "subject": "mixed", "objectives": ["Choosing the fair price for a glass of lemonade (5 dollars) from exaggerated options (50 dollars scares away customers; 1 dollar doesn''t cover the cost)."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "q1-price-choice", "xp": 15, "type": "quiz_mcq", "title": "The fair price of lemonade", "payload": {"options": [{"id": "opt-1-peso", "text_md": "1 dollar per glass", "rationale_md": "1 dollar is too little: Liruf wouldn''t recover what he spent on lemons and sugar, and would lose money."}, {"id": "opt-5-pesos", "text_md": "5 dollars per glass"}, {"id": "opt-50-pesos", "text_md": "50 dollars per glass", "rationale_md": "50 dollars is too much: customers would buy from another stand, because it costs more than a bottle of water."}], "shuffle": true}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf wants to sell glasses of lemonade. Which price is fair to attract customers and not lose money?", "difficulty": 2, "explanation_md": "The fair price is 5 dollars per glass. Liruf earns a little and his customers pay a reasonable price.", "audio_segment_id": "q1-price-choice.prompt"}], "schema_version": 1}', '{"q1-price-choice": {"correct_option_id": "opt-5-pesos"}}', '{"units": {"q1-price-choice.prompt": {"url": "http://localhost:4006/files/lesson-audio/1443a362548ad59d7b3b715e4f09278a3b6b01346b30896cb2b8514edcf8aa53.mp3", "hash": "d8f468c1b6361f166498285368ed94521cf0244ba67a0335332ac7d3099e77a4", "bytes": 35424, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/1443a362548ad59d7b3b715e4f09278a3b6b01346b30896cb2b8514edcf8aa53.mp3", "duration_ms": 5840}, "q1-price-choice.choices": {"url": "http://localhost:4006/files/lesson-audio/bafc5a524cfa44bd59d2f963a72f831e1fba695b4c0cc50222ee46a5de856173.mp3", "hash": "3060bca09dfbfdd22f14441c488cec563ee7e4fa542fca34435b8d9e9883e715", "bytes": 38736, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/bafc5a524cfa44bd59d2f963a72f831e1fba695b4c0cc50222ee46a5de856173.mp3", "duration_ms": 6400}, "q1-price-choice.explanation": {"url": "http://localhost:4006/files/lesson-audio/9c1201899cf0cc319e8a96f3335ba68b3b2e41bd27916f8f8e5496cb1ea6cc72.mp3", "hash": "fe6db8d14c83147c1dfa9fba941d74abf617fd7aba3bb34707dcc785555daafb", "bytes": 42048, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/9c1201899cf0cc319e8a96f3335ba68b3b2e41bd27916f8f8e5496cb1ea6cc72.mp3", "duration_ms": 6960}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58ff84ee-6d0e-4e43-a182-5b9ffd992543', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "memory-flip", "title": "Memoria de precios del puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Emparejar de memoria cada producto con las monedas que lo pagan, usando los precios del puesto: galleta = 3 (1+2), vaso chico = 5, jarra grande = 20 (10+10)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-memory-flip", "xp": 15, "type": "memory_flip", "hints": ["Recuerda: la galleta vale 3 monedas (1+2), el vaso chico 5, la jarra grande 20 (10+10).", "Fíjate en los montos: 3, 5 y 20. ¿Cuál pago va con cada producto?"], "title": "Empareja producto con pago", "payload": {"pairs": [{"a_md": "Galleta", "b_md": "1 + 2", "a_icon": "cookie", "b_icon": "monetization_on", "a_image_url": "http://localhost:4006/files/lesson-images/7e08eb104527f9e19b43e6f4c46fde6f687edc06508a674a213c437a2c701052.webp", "b_image_url": "http://localhost:4006/files/lesson-images/be4642343f02c86c2c67d6c39e5d452b401a802d7e8dd9cb49a866df9adcb2ec.webp"}, {"a_md": "Vaso chico", "b_md": "5", "a_icon": "local_cafe", "b_icon": "monetization_on", "a_image_url": "http://localhost:4006/files/lesson-images/c4981a45d33ffb26545f219cc83c32f909327aab9e0dffe06b21aa4828b8feac.webp", "b_image_url": "http://localhost:4006/files/lesson-images/4b70952218ce50f65e0d567e7cbe1fcbc48e94e4fe72dd0692ba58d7c72c6bf0.webp"}, {"a_md": "Jarra grande", "b_md": "10 + 10", "a_icon": "water_drop", "b_icon": "monetization_on", "a_image_url": "http://localhost:4006/files/lesson-images/73e4853ef3cef5374997f20b8ace852298c49c69573a6c420466638c0e6e57a7.webp", "b_image_url": "http://localhost:4006/files/lesson-images/48ffc037fb87114996c49ded515200c33de8c574e6cd27d72c590bfb17f1f519.webp"}]}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Toca cada producto y su pago exacto. Galleta cuesta 3, vaso chico 5, jarra grande 20.", "difficulty": 2, "explanation_md": "La galleta cuesta 3 pesos (1+2), el vaso chico 5 pesos y la jarra grande 20 pesos (10+10). Así emparejaste cada producto con su pago exacto.", "audio_segment_id": "s1-memory-flip.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-memory-flip.hint.0": {"url": "http://localhost:4006/files/lesson-audio/03fd67d344a33c9c59f8e3816ea377662230cfb73f1d06099588e95b5c2b7ac8.mp3", "hash": "35d95e0bad3ff400cbafe2cfd9df403daf6ca4b0b7e0d1038b24d5b49bec1d28", "bytes": 47376, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/03fd67d344a33c9c59f8e3816ea377662230cfb73f1d06099588e95b5c2b7ac8.mp3", "duration_ms": 7840}, "s1-memory-flip.hint.1": {"url": "http://localhost:4006/files/lesson-audio/c05fc66dec932ce95baf042b18d04c2f1fa80aef4950d9c1b428873c2030475e.mp3", "hash": "aaa4b30715ba5d8940f9b31a5ed5b479523a2a0c4b5152c5fc9c277b586887f9", "bytes": 31968, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/c05fc66dec932ce95baf042b18d04c2f1fa80aef4950d9c1b428873c2030475e.mp3", "duration_ms": 5280}, "s1-memory-flip.prompt": {"url": "http://localhost:4006/files/lesson-audio/f179c597ce150bc4443b874609e0dc4472f3df2bb5d31032140760269ad79587.mp3", "hash": "2bea11153536dd7fb83bdee02b121f67c17898e011731ff9bca81e084f2b84b7", "bytes": 45504, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/f179c597ce150bc4443b874609e0dc4472f3df2bb5d31032140760269ad79587.mp3", "duration_ms": 7520}, "s1-memory-flip.explanation": {"url": "http://localhost:4006/files/lesson-audio/7235b4b9b2d2d39613c9cdf0befa953f881d68ce8d33bfdb0e7683777d4f21ab.mp3", "hash": "51b821261d4290f41152274a9118313dca0915ac89a6cff68ebd57bf3dcfb02b", "bytes": 66528, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/7235b4b9b2d2d39613c9cdf0befa953f881d68ce8d33bfdb0e7683777d4f21ab.mp3", "duration_ms": 11040}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('85c2a66b-c70b-43e4-8fd5-4862d4acb66b', 'en-US', '1', '{"meta": {"cast": ["rho"], "slug": "rank-choices", "title": "The order of purchases", "locale": "en-US", "subject": "mixed", "objectives": ["Order purchases by priority for a lemonade stand."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-prioridad-compras", "xp": 15, "type": "rank_choices", "hints": ["Think: what can''t you make lemonade without?"], "title": "Purchase priority", "payload": {"items": [{"id": "limones", "text_md": "Fresh lemons", "image_url": "http://localhost:4006/files/lesson-images/0d367160423bc40ecf79647e7efd6d8c4621c48ff5c046bca2a75b2b77eea2f5.webp"}, {"id": "vasos", "text_md": "Paper cups", "image_url": "http://localhost:4006/files/lesson-images/2e58a437914f8f3cb9537d0c15aac981627ba96dab049fc7b9261b9aeb740339.webp"}, {"id": "adornos", "text_md": "Decorations for the stand", "image_url": "http://localhost:4006/files/lesson-images/d2c1668da7be9a5f5b83fd4fb67b6d70cbfb66c1194a2ba4cfe81537006c6053.webp"}], "criterion_md": "What helps most to sell lemonade tomorrow?"}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Arrange from most urgent to least urgent for the stand.", "difficulty": 2, "explanation_md": "To keep selling lemonade, the most urgent thing is to replenish the lemons. Then the cups for serving, and finally the decorations that just decorate.", "audio_segment_id": "s1-prioridad-compras.prompt"}], "schema_version": 1}', '{"s1-prioridad-compras": {"order": ["limones", "vasos", "adornos"], "accept_orders": []}}', '{"units": {"s1-prioridad-compras.hint.0": {"url": "http://localhost:4006/files/lesson-audio/8258bb29a29e8595d5e520bc17fc5202c3eafe600274ef808964b7233d4749dd.mp3", "hash": "8f9c0b617a82d1a987c93cf0b0713771c17261ef59978178952dddb247739806", "bytes": 19584, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/8258bb29a29e8595d5e520bc17fc5202c3eafe600274ef808964b7233d4749dd.mp3", "duration_ms": 3200}, "s1-prioridad-compras.prompt": {"url": "http://localhost:4006/files/lesson-audio/f2cb1581e2e5dc4bc5ff5f940e9893afd7ad39da416c770c986d639629752028.mp3", "hash": "6e45adc4ed695a1279d9f8f378067c9f9943670c20c6179a07d2807dffe20eb4", "bytes": 22896, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/f2cb1581e2e5dc4bc5ff5f940e9893afd7ad39da416c770c986d639629752028.mp3", "duration_ms": 3760}, "s1-prioridad-compras.explanation": {"url": "http://localhost:4006/files/lesson-audio/7f1e2ac7731a0ef9af88c7aa37f2399e1fb8e25f6d4d3324297a1f541869a505.mp3", "hash": "08a8e88323682886f8b13817ddd2977eb2eb2b56bb40ffc196b8c0b0de05c9d7", "bytes": 64224, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/7f1e2ac7731a0ef9af88c7aa37f2399e1fb8e25f6d4d3324297a1f541869a505.mp3", "duration_ms": 10640}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0a2bda3a-e275-46b8-b659-a7ad68a0afb3', 'es-MX', '1', '{"meta": {"cast": ["zara", "liruf"], "slug": "lightning-round", "title": "Ronda Relámpago: Cambio Rápido", "locale": "es-MX", "subject": "mixed", "objectives": ["Practicar el cálculo de cambio rápido para mantener a los clientes felices y juntar dinero para la guitarra."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "lightning-round-practice", "xp": 15, "type": "lightning_round", "hints": ["Suma primero el costo total de los vasos que pidió el cliente."], "title": "¡Cambio Relámpago!", "payload": {"questions": [{"id": "q1", "options": [{"id": "a", "text_md": "10 pesos"}, {"id": "b", "text_md": "15 pesos"}, {"id": "c", "text_md": "20 pesos"}], "prompt_md": "Doña Rosa pide 2 vasos. Paga con un billete de 20 pesos."}, {"id": "q2", "options": [{"id": "a", "text_md": "5 pesos"}, {"id": "b", "text_md": "10 pesos"}, {"id": "c", "text_md": "15 pesos"}], "prompt_md": "Don Pedro pide 3 vasos. Paga con 20 pesos."}, {"id": "q3", "options": [{"id": "a", "text_md": "5 pesos"}, {"id": "b", "text_md": "0 pesos"}, {"id": "c", "text_md": "10 pesos"}], "prompt_md": "Doña Juana pide 1 vaso. Paga con 10 pesos."}, {"id": "q4", "options": [{"id": "a", "text_md": "0 pesos"}, {"id": "b", "text_md": "5 pesos"}, {"id": "c", "text_md": "10 pesos"}], "prompt_md": "Tito pide 2 vasos. Paga con 10 pesos justos."}], "seconds_per_q": 15}, "narrator": {"emotion": "encouraging", "character": "zara"}, "prompt_md": "Cada vaso de limonada cuesta 5 pesos. ¡Ayuda a Liruf a dar el cambio exacto!", "difficulty": 2, "explanation_md": "Recuerda: primero suma el costo de todos los vasos (cada uno cuesta 5 pesos) y luego réstalo del billete. Por ejemplo, 2 vasos y un billete de 20: 20 - (2×5) = 10 pesos de cambio. Un error común es restar sin multiplicar; así te aseguras de dar el cambio exacto.", "audio_segment_id": "lightning-round-practice.prompt"}], "schema_version": 1}', '{"lightning-round-practice": {"correct": {"q1": "a", "q2": "a", "q3": "a", "q4": "a"}}}', '{"units": {"lightning-round-practice.hint.0": {"url": "http://localhost:4006/files/lesson-audio/36582aa3b2fb4280bfc1c4892d54eb7fed4783713841ab549271791c278370e4.mp3", "hash": "77ab92fe5772c65227f68aceef03564bcc1c373c08c528187aac5b9c85714c60", "bytes": 23904, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/36582aa3b2fb4280bfc1c4892d54eb7fed4783713841ab549271791c278370e4.mp3", "duration_ms": 3920}, "lightning-round-practice.prompt": {"url": "http://localhost:4006/files/lesson-audio/af5cb4faa46031eba23306db56b08437331e4d825177588201d4e3d168bc5cce.mp3", "hash": "98aad6075508c72862d6d949e53e13931433e669ddf221e20c3fddfc17cc0bc4", "bytes": 31536, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/af5cb4faa46031eba23306db56b08437331e4d825177588201d4e3d168bc5cce.mp3", "duration_ms": 5200}, "lightning-round-practice.explanation": {"url": "http://localhost:4006/files/lesson-audio/63771688642e4d186dde2c76e2570ef0262908f4b091766d419b9ef0a80fb378.mp3", "hash": "5aa947ce0e23f842cfee3c7ec0307a25adf2c5be6fbd0d0a72216c3665abb237", "bytes": 109728, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/63771688642e4d186dde2c76e2570ef0262908f4b091766d419b9ef0a80fb378.mp3", "duration_ms": 18240}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('df879f53-8479-4b98-9651-889fcae66fdc', 'pt-BR', '1', '{"meta": {"cast": ["rho", "liruf"], "slug": "repaso-true-false", "title": "Revisão: Ganho real?", "locale": "pt-BR", "subject": "mixed", "objectives": ["Diferenciar entre vendas totais e ganho real considerando os custos."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "tf1-repaso-ganancia", "xp": 10, "type": "true_false", "hints": ["Dica: Ganho = dinheiro recebido - dinheiro gasto em fazer os copos."], "title": "Ganhou 50?", "payload": {"statement_md": "Liruf vendeu 10 copos a 5 reais, então ganhou 50.", "justifications": [{"id": "j1", "text_md": "É verdade: 10 copos × 5 reais = 50 reais. Isso foi o que entrou no caixa."}, {"id": "j2", "text_md": "É falso: fazer cada copo custa 2 reais. Ganhou apenas 3 reais por copo; 10 × 3 = 30 reais."}]}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Liruf vendeu 10 copos a 5 reais; fazê-los custa 2 reais. Ganhou 50? Escolha verdadeiro ou falso.", "difficulty": 1, "explanation_md": "Liruf recebeu 50 reais no total, mas fazer os copos lhe custou 20 reais. Por isso, ganhou apenas 30 reais (3 reais por copo).", "audio_segment_id": "tf1-repaso-ganancia.prompt"}], "schema_version": 1}', '{"tf1-repaso-ganancia": {"is_true": false, "correct_justification_id": "j2"}}', '{"units": {"tf1-repaso-ganancia.hint.0": {"url": "http://localhost:4006/files/lesson-audio/bc9a3a789436291832c038dce614b94565b82148efd7e4761439bbfaa9c27c76.mp3", "hash": "aae382bec4f50614c6bf924adeccc600967cb5445d4af91d61655cea66dc6a07", "bytes": 34848, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/bc9a3a789436291832c038dce614b94565b82148efd7e4761439bbfaa9c27c76.mp3", "duration_ms": 5760}, "tf1-repaso-ganancia.prompt": {"url": "http://localhost:4006/files/lesson-audio/d5fb75c33a7e2ff2c66c47aada34e59bdee3e5d53dbf4c9ed1fc2670b7824b6c.mp3", "hash": "650655716a07c9e0d3709366832b7c81fd197bc64ac20791dfe1bab1bf6604fb", "bytes": 56448, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/d5fb75c33a7e2ff2c66c47aada34e59bdee3e5d53dbf4c9ed1fc2670b7824b6c.mp3", "duration_ms": 9360}, "tf1-repaso-ganancia.explanation": {"url": "http://localhost:4006/files/lesson-audio/1df8e92dfb1ad8a1f6641fc2e765640f0b486edc2d0a8c53a542c2fc8adb93b5.mp3", "hash": "24ab8f2cac393d7ebab81f3c1cb70b546af494d44bfda7a5f44d2e16bb9aae03", "bytes": 66096, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/1df8e92dfb1ad8a1f6641fc2e765640f0b486edc2d0a8c53a542c2fc8adb93b5.mp3", "duration_ms": 10960}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('3c639b5e-01f3-469e-95e3-a52a215847f4', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "fact-opinion", "title": "Hechos y Opiniones", "locale": "es-MX", "subject": "mixed", "objectives": ["Diferenciar entre hechos y opiniones en las frases de un puesto de limonada."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fact-opinion", "xp": 15, "type": "fact_opinion", "hints": ["Un hecho se puede demostrar con números o fotos. Una opinión es lo que a alguien le gusta o cree."], "title": "¿Hecho o opinión?", "payload": {"statements": [{"id": "s1", "text_md": "Hoy vendimos 12 vasos de limonada."}, {"id": "s2", "text_md": "El vaso cuesta 5 pesos."}, {"id": "s3", "text_md": "Usamos limones para hacer la limonada."}, {"id": "s4", "text_md": "Nuestra limonada es la mejor del barrio."}, {"id": "s5", "text_md": "El puesto tiene los colores más alegres."}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/55f48d14db6c5b240c03b5db3ee5e9691fc6a56495885d6fb557c5486f70d6c9.webp", "prompt_md": "Rho dice frases del puesto. Toca las que son HECHOS (se pueden comprobar).", "difficulty": 2, "explanation_md": "¡Los hechos se pueden comprobar! ''El vaso cuesta 5 pesos'' es un hecho porque puedes ver el precio. ''Es la mejor'' es una opinión, porque a otra persona podría no gustarle.", "audio_segment_id": "s1-fact-opinion.prompt"}], "schema_version": 1}', '{"s1-fact-opinion": {"fact_ids": ["s1", "s2", "s3"]}}', '{"units": {"s1-fact-opinion.hint.0": {"url": "http://localhost:4006/files/lesson-audio/d70d06f878d27c715b88f568ede18a431492d2f42c7d5a9e8b1c56402003301e.mp3", "hash": "d3e5420810504d01b58cb5fb12a7381d0b3b2870acb4546aa744d2d1e3e3ff95", "bytes": 44496, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/d70d06f878d27c715b88f568ede18a431492d2f42c7d5a9e8b1c56402003301e.mp3", "duration_ms": 7360}, "s1-fact-opinion.prompt": {"url": "http://localhost:4006/files/lesson-audio/ae720102c70b0b85f03dea89990f32205cb24bc7c0a16ead981bdbc95c36de62.mp3", "hash": "8ac08f0bb4d29615f45442a4cf6c7e271982c7b3d14e38f5aa24507d114b9d46", "bytes": 32544, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/ae720102c70b0b85f03dea89990f32205cb24bc7c0a16ead981bdbc95c36de62.mp3", "duration_ms": 5360}, "s1-fact-opinion.explanation": {"url": "http://localhost:4006/files/lesson-audio/56722fe3a8f130f8fb8e59c72acb013b243bff11c2810fd7007da1ec61570fe7.mp3", "hash": "10319bb81b405ee1fc2ff81d58574b867f53cb7be1e007b5dccbf58fe47c0175", "bytes": 63648, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/56722fe3a8f130f8fb8e59c72acb013b243bff11c2810fd7007da1ec61570fe7.mp3", "duration_ms": 10560}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('43eb7cc6-46cc-44ee-9a87-14d05d8f357d', 'en-US', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "dialogue-choice", "title": "Negotiate with customers", "locale": "en-US", "subject": "mixed", "objectives": ["Make decisions within the stand''s stories and see their immediate consequences on sales and savings."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-negociar", "xp": 15, "type": "dialogue_choice", "title": "What to say to a customer who asks for a discount?", "payload": {"turns": [{"id": "turn-1", "npc_md": "Customer: Hi, can you sell me a lemonade? Hey, could you let me have it for 3 dollars?", "replies": [{"id": "r1a", "text_md": "Of course! Here you go. 3 dollars, just for you."}, {"id": "r1b", "text_md": "No, it costs 5 dollars. If you don''t like it, go somewhere else."}, {"id": "r1c", "text_md": "Each glass is worth 5 dollars, it''s a fair price. But if you buy two, I''ll let you have them for 4 each. Are you up for it?"}, {"id": "r1d", "text_md": "For 3 dollars I''ll give you a smaller glass, what do you say?"}]}, {"id": "turn-2", "npc_md": "Another customer: Your lemonade looks so delicious! I only have 3 dollars, don''t you have something for me?", "replies": [{"id": "r2a", "text_md": "Oh well, if you don''t have 5 dollars, no lemonade. Bye."}, {"id": "r2b", "text_md": "For 3 dollars I offer you a small glass, made with the same love. How does that sound?"}, {"id": "r2c", "text_md": "Alright, take the large glass for 3 dollars. You''re special."}, {"id": "r2d", "text_md": "For 3 dollars I''ll give you half a glass, but I don''t think you''d want that."}]}], "persona": {"name": "Liruf", "role_md": "Owner of the lemonade stand", "character": "liruf"}, "opening_md": "It''s a sunny day at the lemonade stand. A customer approaches."}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/d61b5f2ac258c7b2b01b4f4357bccd2763ef457c9abcd48c3e1e78d6898130b5.webp", "prompt_md": "A customer asks for a discount. Help Liruf respond kindly without losing his profit.", "difficulty": 2, "explanation_md": "When a customer asks for a discount, Liruf can negotiate kindly: offering alternatives (like buying two glasses) maintains the profit and leaves the customer happy. Giving away the product loses money; being rude drives customers away.", "audio_segment_id": "s1-negociar.prompt"}], "schema_version": 1}', '{"s1-negociar": {"turns": [{"turn_id": "turn-1", "qualities": {"r1a": 10, "r1b": 20, "r1c": 100, "r1d": 60}, "reactions": {"r1a": "El cliente se va contento, pero Liruf ha perdido 2 pesos de ganancia. ¡Eso aleja su guitarra!", "r1b": "El cliente se molesta y se va sin comprar. Liruf pierde una venta y un posible amigo.", "r1c": "El cliente sonríe: ''¡Buen trato! Me llevo dos.'' Liruf gana 8 pesos y un cliente feliz. Negociar con opciones funciona.", "r1d": "El cliente acepta, pero Liruf siente que podría haber ganado más. A veces un trato justo es mejor que rebajar."}}, {"turn_id": "turn-2", "qualities": {"r2a": 10, "r2b": 100, "r2c": 20, "r2d": 30}, "reactions": {"r2a": "El cliente se va triste. Liruf se queda con su limonada y sin venta.", "r2b": "El cliente acepta feliz el vaso chico: ''Gracias, eres muy amable.'' Liruf vende, gana algo y conserva un cliente. ¡Bien negociado!", "r2c": "El cliente se alegra, pero Liruf regala su trabajo. La guitarra se aleja otro día.", "r2d": "El cliente pone cara rara y se va. Una oferta poco amable no convence a nadie."}}]}}', '{"units": {"s1-negociar.prompt": {"url": "http://localhost:4006/files/lesson-audio/6437dbd4c3eea49e9d9f8bf44fa30f2a8be53cf2d5707adba60f0fbd0f21dfb7.mp3", "hash": "ceb1daaf3a07642f74188b078a8795457065394c33ce2a98ed90913f97d4128a", "bytes": 29664, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/6437dbd4c3eea49e9d9f8bf44fa30f2a8be53cf2d5707adba60f0fbd0f21dfb7.mp3", "duration_ms": 4880}, "s1-negociar.explanation": {"url": "http://localhost:4006/files/lesson-audio/4fcaf35b2a500b140374ee0b12e5ae5746c0e0f77a83dbbfcfac5487660d4e4f.mp3", "hash": "45086f70a5637323bab4218f5a6f43580b4bb175467012ecedca894a35b974c6", "bytes": 79488, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/4fcaf35b2a500b140374ee0b12e5ae5746c0e0f77a83dbbfcfac5487660d4e4f.mp3", "duration_ms": 13200}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ec92e8b8-2834-4bff-88e8-59733b2e617a', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "repaso-quiz-mcq", "title": "Repaso Rápido: Ganancia por Vaso", "locale": "es-MX", "subject": "mixed", "objectives": ["Repasar el cálculo de ganancia por vaso restando el costo de los ingredientes del precio de venta."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-mcq-review", "xp": 5, "type": "quiz_mcq", "title": "Repaso: Ganancia por Vaso", "payload": {"options": [{"id": "3", "text_md": "3 pesos"}, {"id": "7", "text_md": "7 pesos", "rationale_md": "Sumaste el precio y el costo en vez de restarlos."}, {"id": "5", "text_md": "5 pesos", "rationale_md": "Pensaste que todo el precio es ganancia, pero hay que restar los ingredientes."}, {"id": "2", "text_md": "2 pesos", "rationale_md": "Confundiste el costo de los ingredientes con la ganancia."}], "shuffle": true}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf vende vasos a $5. Los ingredientes cuestan $2. ¿Cuánto gana por vaso?", "difficulty": 1, "explanation_md": "Para calcular la ganancia, resta el costo de los ingredientes ($2) al precio de venta ($5). Liruf gana 3 pesos por vaso.", "audio_segment_id": "s1-mcq-review.prompt"}], "schema_version": 1}', '{"s1-mcq-review": {"correct_option_id": "3"}}', '{"units": {"s1-mcq-review.prompt": {"url": "http://localhost:4006/files/lesson-audio/b6676fd23077d447243df5a47cf8237a00a6f2411f2056dbe94ee7c21a4179d3.mp3", "hash": "a6f22048ac4a7ff10e00154cd6291f4aa146b0749cbef717d5006ca6c45e144d", "bytes": 40608, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/b6676fd23077d447243df5a47cf8237a00a6f2411f2056dbe94ee7c21a4179d3.mp3", "duration_ms": 6720}, "s1-mcq-review.choices": {"url": "http://localhost:4006/files/lesson-audio/36d62c7b8c9d176f7a23111726e1129b5df5103c9a2aba792bcb46ab2f24ba46.mp3", "hash": "224ed0870e0b0e788dafc7e33cc86279000079d412aea674b6b03b92aed2386e", "bytes": 30528, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/36d62c7b8c9d176f7a23111726e1129b5df5103c9a2aba792bcb46ab2f24ba46.mp3", "duration_ms": 5040}, "s1-mcq-review.explanation": {"url": "http://localhost:4006/files/lesson-audio/eff19e0b1d5740d0d341d7d774500eeea0777deca1524caf4745bcf26754bb99.mp3", "hash": "30dd7e8451f89b0ded0436a3387692a9bb251b8bde891662119af2b871e125bc", "bytes": 66096, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/eff19e0b1d5740d0d341d7d774500eeea0777deca1524caf4745bcf26754bb99.mp3", "duration_ms": 10960}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7d51bf02-4dd4-4263-9e53-aa5ccb8a1e03', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "interest-peek", "title": "La alcancía que agradece la paciencia", "locale": "es-MX", "subject": "money", "objectives": ["Decidir si dejar dinero en una alcancía que da moneditas extra cada semana conviene más que gastarlo ya.", "Predecir el total después de esperar, entendiendo que crece un poco pero no se duplica."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-interest-peek", "xp": 10, "type": "interest_peek", "hints": ["Cada semana la alcancía da 2 monedas de 1 peso. ¿Cuántas monedas extra da en 2 semanas?", "Empieza con 20. Suma las moneditas extra."], "title": "¿Dejar los 20 o sacarlos ya?", "payload": {"periods": 2, "currency": "MXN", "rate_pct": 10, "principal": 20, "prediction": {"kind": "choice", "options": [{"id": "opt1", "text_md": "Se queda en 20"}, {"id": "opt2", "text_md": "24 pesos"}, {"id": "opt3", "text_md": "Casi 40 pesos"}]}}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf tiene 20 pesos ahorrados para una guitarra que cuesta 80. Rho le dice: ''Si guardas tu dinero en esta alcancía especial, cada semana te da 2 monedas de 1 peso extra por dejarlo ahí.'' Liruf mete sus 20 pesos. Piensa: ''Si espero 2 semanas, ¿tendré más o menos que si gasto todo ahora?'' ¿Cuánto tendrá Liruf después de 2 semanas?", "difficulty": 1, "explanation_md": "La alcancía da 2 monedas de 1 peso cada semana, así que en 2 semanas da 4 pesos extra. 20 + 4 = 24. ¡El dinero crece poquito a poquito hacia la guitarra! Si hubiera gastado todo ahora, no tendría esos 4 pesos extra.", "audio_segment_id": "s1-interest-peek.prompt"}], "schema_version": 1}', '{"s1-interest-peek": {"value": 24, "tolerance": 1, "correct_option_id": "opt2"}}', '{"units": {"s1-interest-peek.hint.0": {"url": "http://localhost:4006/files/lesson-audio/668ab78163ee044ba3efd11e77b6e3eec662ac301caa366cdc069a4a6dc98a2b.mp3", "hash": "3dc18383d9a32c406d7fbe70048d4c251d4877228f2348bcfeef02d3057b0217", "bytes": 40608, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/668ab78163ee044ba3efd11e77b6e3eec662ac301caa366cdc069a4a6dc98a2b.mp3", "duration_ms": 6720}, "s1-interest-peek.hint.1": {"url": "http://localhost:4006/files/lesson-audio/0ec9032c2aa437cfaaac7e397a9407c360275eb841b0372c911b3802ec3b3fd3.mp3", "hash": "ac7225036bac770feb6907a8d2cdac588fcdfe82d73be88200379222db2cac7f", "bytes": 21024, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/0ec9032c2aa437cfaaac7e397a9407c360275eb841b0372c911b3802ec3b3fd3.mp3", "duration_ms": 3440}, "s1-interest-peek.prompt": {"url": "http://localhost:4006/files/lesson-audio/4713ac3a791be4ee9f44e0de9ba4fa32ce5a19be02bf391a7b1aa0027b175ba5.mp3", "hash": "bb23ce2312a94c7ed78d3215c8a47b3b4ddc843eb4ca2970f9243cfe474e18df", "bytes": 131328, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/4713ac3a791be4ee9f44e0de9ba4fa32ce5a19be02bf391a7b1aa0027b175ba5.mp3", "duration_ms": 21840}, "s1-interest-peek.explanation": {"url": "http://localhost:4006/files/lesson-audio/56ed1be12a6d3a85e0602e52b13ba8b9bb1a113b29b8de014b9331aa3ca45dbd.mp3", "hash": "e4009c6e87dc657fc8d8b2b77b6ceafab722fa548a5d58601a4ec344defe357a", "bytes": 100224, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/56ed1be12a6d3a85e0602e52b13ba8b9bb1a113b29b8de014b9331aa3ca45dbd.mp3", "duration_ms": 16640}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f9ad47f4-7031-4552-97cd-a0b426882208', 'en-US', '1', '{"meta": {"cast": ["rho"], "slug": "code-order", "title": "The cash register step by step", "locale": "en-US", "subject": "mixed", "objectives": ["Sort the instructions for operating a homemade cash register."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-code-order", "xp": 15, "type": "code_order", "hints": ["Think: what should the cash register do first when someone wants to buy something?"], "title": "Rho''s cash register", "payload": {"blocks": [{"id": "recibir_pago", "text_md": "Receive the payment"}, {"id": "verificar_monto", "text_md": "Verify the amount"}, {"id": "dar_cambio", "text_md": "Give the change"}, {"id": "anotar_venta", "text_md": "Record the sale"}], "language_hint": "Spanish"}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Rho invented a cardboard cash register. What is the correct order of the instructions?", "difficulty": 2, "explanation_md": "Rho programmed her cash register to first receive the payment, then verify that the amount is correct, then give the necessary change, and finally record the sale. That way, she doesn''t forget any step.", "audio_segment_id": "s1-code-order.prompt"}], "schema_version": 1}', '{"s1-code-order": {"order": ["recibir_pago", "verificar_monto", "dar_cambio", "anotar_venta"]}}', '{"units": {"s1-code-order.hint.0": {"url": "http://localhost:4006/files/lesson-audio/037a9a86c6efab35a6780b4952318dc0b0f95d7e8b4a7e7711b6e34471dc0b0b.mp3", "hash": "44fb9b917dce24b877260a9dea58376b8cef7238d2d8f8e9339a20c4934958d4", "bytes": 31968, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/037a9a86c6efab35a6780b4952318dc0b0f95d7e8b4a7e7711b6e34471dc0b0b.mp3", "duration_ms": 5280}, "s1-code-order.prompt": {"url": "http://localhost:4006/files/lesson-audio/93b5325f619ca9271de9af120491681cd4a25e54eacdc25eef13b784dc605d3f.mp3", "hash": "93e3e4190b2aed605d696f9891f187f41efc7105ae1580487fdc40e4e816fa2e", "bytes": 32976, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/93b5325f619ca9271de9af120491681cd4a25e54eacdc25eef13b784dc605d3f.mp3", "duration_ms": 5440}, "s1-code-order.explanation": {"url": "http://localhost:4006/files/lesson-audio/d241b506c63b48e4d0abe578578e2e085bbc445098ceb8e44f2c7cc465cd8f5f.mp3", "hash": "df801d2fab71ace495c1d33270e667d23311a0dd7a99afd0acb8386b3f381a52", "bytes": 80496, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/d241b506c63b48e4d0abe578578e2e085bbc445098ceb8e44f2c7cc465cd8f5f.mp3", "duration_ms": 13360}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f62a6048-4f69-4ab4-9256-d87525c8e112', 'es-MX', '1', '{"meta": {"cast": ["liruf"], "slug": "make-change", "title": "El cambio de don Beto", "locale": "es-MX", "subject": "mixed", "objectives": ["Calcular el cambio exacto usando monedas mexicanas en una venta real."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-make-change", "xp": 15, "type": "make_change", "hints": ["Don Beto gastó el precio del vaso más el de la galleta. Pagó con 20 pesos. El cambio es la diferencia que debes devolverle con monedas de 1, 2, 5 o 10 pesos."], "title": "El cambio de don Beto", "payload": {"price": 8, "currency": "MXN", "paid_with": 20, "denominations": [1, 2, 5, 10]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/4cfe6c6793262811711f98db960b576575f4c360669d9f410c51c62ded5b9bb3.webp", "prompt_md": "Don Beto compró 1 vaso (5 pesos) y 1 galleta (3 pesos). Pagó con 20 pesos. Arma el cambio con monedas.", "difficulty": 2, "explanation_md": "La limonada y la galleta suman 8 pesos. Al pagar con 20, el cambio es 12 pesos. Puedes usar una moneda de 10 y una de 2, o dos de 5 y dos de 1, o cualquier combinación que dé 12. Si devuelves menos, don Beto se queda sin su cambio completo. Si devuelves más, pierdes monedas para la guitarra de 80 pesos.", "audio_segment_id": "s1-make-change.prompt"}], "schema_version": 1}', '{"s1-make-change": {}}', '{"units": {"s1-make-change.hint.0": {"url": "http://localhost:4006/files/lesson-audio/922cd81daad439cfb794ebd68f1b84f52b98d1361ad684c45e4965b5df4c2eb6.mp3", "hash": "857196191b1f5b91364ccaeb10fa6d11c3516df9fb5e81c60f26a23da6391cc5", "bytes": 73728, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/922cd81daad439cfb794ebd68f1b84f52b98d1361ad684c45e4965b5df4c2eb6.mp3", "duration_ms": 12240}, "s1-make-change.prompt": {"url": "http://localhost:4006/files/lesson-audio/fe32be74f90e9ef3171d1817651e557d2bfda3df861b846f6394874ae9e80fe8.mp3", "hash": "61c3d92765980715b7cce2b37cd4c5bb806e95a9991b33fc58fcfdbac0ee7319", "bytes": 60336, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/fe32be74f90e9ef3171d1817651e557d2bfda3df861b846f6394874ae9e80fe8.mp3", "duration_ms": 10000}, "s1-make-change.explanation": {"url": "http://localhost:4006/files/lesson-audio/0efa2f01922250fa81964e09bfaa3b6c1f330364ab0f17d0b1f8350087efb93b.mp3", "hash": "7794855a4cc817454021144799a9373a97d974efec1bdb3add1ed24ce3abc77d", "bytes": 133344, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/0efa2f01922250fa81964e09bfaa3b6c1f330364ab0f17d0b1f8350087efb93b.mp3", "duration_ms": 22160}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ec92e8b8-2834-4bff-88e8-59733b2e617a', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "repaso-quiz-mcq", "title": "Quick Review: Profit per Cup", "locale": "en-US", "subject": "mixed", "objectives": ["Review the profit per cup calculation by subtracting the cost of ingredients from the selling price."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-mcq-review", "xp": 5, "type": "quiz_mcq", "title": "Review: Profit per Cup", "payload": {"options": [{"id": "3", "text_md": "3 dollars"}, {"id": "7", "text_md": "7 dollars", "rationale_md": "You added the price and the cost instead of subtracting them."}, {"id": "5", "text_md": "5 dollars", "rationale_md": "You thought the whole price is profit, but you have to subtract the ingredients."}, {"id": "2", "text_md": "2 dollars", "rationale_md": "You confused the cost of ingredients with the profit."}], "shuffle": true}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf sells cups for $5. The ingredients cost $2. How much does he earn per cup?", "difficulty": 1, "explanation_md": "To calculate the profit, subtract the cost of ingredients ($2) from the selling price ($5). Liruf earns 3 dollars per cup.", "audio_segment_id": "s1-mcq-review.prompt"}], "schema_version": 1}', '{"s1-mcq-review": {"correct_option_id": "3"}}', '{"units": {"s1-mcq-review.prompt": {"url": "http://localhost:4006/files/lesson-audio/9623c367fb7819d107a26b2cf2de3609db8da9b4dfe792248de7733cf789e790.mp3", "hash": "846b618ffe0c441a0ef2347c8de58410be42bb6e897d8857efebc9172578cfd7", "bytes": 33408, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/9623c367fb7819d107a26b2cf2de3609db8da9b4dfe792248de7733cf789e790.mp3", "duration_ms": 5520}, "s1-mcq-review.choices": {"url": "http://localhost:4006/files/lesson-audio/c410fb6f042b1db5e48eacbc91ea343a0f8ae727b6255ec111bbad69d344ed3c.mp3", "hash": "00be4e3bd4125515573548b19f24f35b276b4f3627f2bb3cd0374321ef47c2cd", "bytes": 19584, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/c410fb6f042b1db5e48eacbc91ea343a0f8ae727b6255ec111bbad69d344ed3c.mp3", "duration_ms": 3200}, "s1-mcq-review.explanation": {"url": "http://localhost:4006/files/lesson-audio/323f59d85a0418c49120e09b8500ff103f1c7bef950a934e9437b429238afa94.mp3", "hash": "a019b216314cdfdfbfee6e26ee3858eaad0ed43249ed6e11db9792c0042bb527", "bytes": 47808, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/323f59d85a0418c49120e09b8500ff103f1c7bef950a934e9437b429238afa94.mp3", "duration_ms": 7920}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f9ad47f4-7031-4552-97cd-a0b426882208', 'pt-BR', '1', '{"meta": {"cast": ["rho"], "slug": "code-order", "title": "A registradora passo a passo", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ordenar as instruções para operar uma registradora caseira."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-code-order", "xp": 15, "type": "code_order", "hints": ["Pense: o que a registradora deve fazer primeiro quando alguém quer comprar algo?"], "title": "A registradora de Rho", "payload": {"blocks": [{"id": "recibir_pago", "text_md": "Recebe o pagamento"}, {"id": "verificar_monto", "text_md": "Verifica o valor"}, {"id": "dar_cambio", "text_md": "Dá o troco"}, {"id": "anotar_venta", "text_md": "Anota a venda"}], "language_hint": "português"}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Rho inventou uma registradora de papelão. Qual é a ordem correta das instruções?", "difficulty": 2, "explanation_md": "Rho programou sua registradora para primeiro receber o pagamento, depois verificar se a quantia está correta, em seguida dar o troco necessário e finalmente anotar a venda. Assim não se esquece de nenhum passo.", "audio_segment_id": "s1-code-order.prompt"}], "schema_version": 1}', '{"s1-code-order": {"order": ["recibir_pago", "verificar_monto", "dar_cambio", "anotar_venta"]}}', '{"units": {"s1-code-order.hint.0": {"url": "http://localhost:4006/files/lesson-audio/d203b10164ccbbcb8b5c99deecf15d13f71a15e339564ce5ed509a7c7ea581ff.mp3", "hash": "f0fe750dca028f00f5f6e6a80848878d0d9dd50f497bc3825507bb213137d5ed", "bytes": 32976, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/d203b10164ccbbcb8b5c99deecf15d13f71a15e339564ce5ed509a7c7ea581ff.mp3", "duration_ms": 5440}, "s1-code-order.prompt": {"url": "http://localhost:4006/files/lesson-audio/62f2e38d72b4ac9a304abae41af8d5bd75e06117bfd492ad1c2fbceac5d0b710.mp3", "hash": "4240f0c0e816f28a56d34f0f41eaebf417015910f5f66794edbf034596e1f579", "bytes": 36864, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/62f2e38d72b4ac9a304abae41af8d5bd75e06117bfd492ad1c2fbceac5d0b710.mp3", "duration_ms": 6080}, "s1-code-order.explanation": {"url": "http://localhost:4006/files/lesson-audio/05df33739dfc8ac803f485ae6bcaa555f09ba2010a0b12834cab27dbe34fc424.mp3", "hash": "e5bf9f43754957da390154f28f4a8417e2e69b940bd4fc8d882779b3f5f45e5b", "bytes": 83376, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/05df33739dfc8ac803f485ae6bcaa555f09ba2010a0b12834cab27dbe34fc424.mp3", "duration_ms": 13840}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('43eb7cc6-46cc-44ee-9a87-14d05d8f357d', 'pt-BR', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "dialogue-choice", "title": "Negociar com clientes", "locale": "pt-BR", "subject": "mixed", "objectives": ["Tomar decisões dentro de histórias da barraca e ver suas consequências imediatas nas vendas e na poupança."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-negociar", "xp": 15, "type": "dialogue_choice", "title": "O que responder a um cliente que pede desconto?", "payload": {"turns": [{"id": "turn-1", "npc_md": "Cliente: Olá, você me vende uma limonada? Ei, será que dá para fazer por 3 reais?", "replies": [{"id": "r1a", "text_md": "Claro! Toma, aqui está. 3 reais, por ser você."}, {"id": "r1b", "text_md": "Não, custa 5 reais. Se não gostar, vá para outro lugar."}, {"id": "r1c", "text_md": "Cada copo vale 5 reais, é um preço justo. Mas se levar dois, faço a 4 reais cada. Topa?"}, {"id": "r1d", "text_md": "Por 3 reais te dou um copo menor, o que você diz?"}]}, {"id": "turn-2", "npc_md": "Outro cliente: Que delícia parece sua limonada! Só trouxe 3 reais, não teria algo para mim?", "replies": [{"id": "r2a", "text_md": "Nem pensar, se não trouxer 5 reais, não tem limonada. Tchau."}, {"id": "r2b", "text_md": "Com 3 reais te ofereço um copo pequeno, feito com o mesmo carinho. O que acha?"}, {"id": "r2c", "text_md": "Tudo bem, leve o copo grande por 3 reais. Você é especial."}, {"id": "r2d", "text_md": "Por 3 reais te dou meio copo, mas acho que você não vai querer."}]}], "persona": {"name": "Liruf", "role_md": "Dono da barraca de limonada", "character": "liruf"}, "opening_md": "É um dia ensolarado na barraca de limonada. Um cliente se aproxima."}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/29e54ee9d052aba56c0f4cd51cd74aa53036988e38f60a71d745d774e860c14d.webp", "prompt_md": "Um cliente pede desconto. Ajude Liruf a responder com gentileza sem perder seu lucro.", "difficulty": 2, "explanation_md": "Quando um cliente pede desconto, Liruf pode negociar com gentileza: oferecer alternativas (como levar dois copos) mantém o lucro e deixa o cliente satisfeito. Dar o produto de graça faz perder dinheiro; ser grosseiro afasta clientes.", "audio_segment_id": "s1-negociar.prompt"}], "schema_version": 1}', '{"s1-negociar": {"turns": [{"turn_id": "turn-1", "qualities": {"r1a": 10, "r1b": 20, "r1c": 100, "r1d": 60}, "reactions": {"r1a": "El cliente se va contento, pero Liruf ha perdido 2 pesos de ganancia. ¡Eso aleja su guitarra!", "r1b": "El cliente se molesta y se va sin comprar. Liruf pierde una venta y un posible amigo.", "r1c": "El cliente sonríe: ''¡Buen trato! Me llevo dos.'' Liruf gana 8 pesos y un cliente feliz. Negociar con opciones funciona.", "r1d": "El cliente acepta, pero Liruf siente que podría haber ganado más. A veces un trato justo es mejor que rebajar."}}, {"turn_id": "turn-2", "qualities": {"r2a": 10, "r2b": 100, "r2c": 20, "r2d": 30}, "reactions": {"r2a": "El cliente se va triste. Liruf se queda con su limonada y sin venta.", "r2b": "El cliente acepta feliz el vaso chico: ''Gracias, eres muy amable.'' Liruf vende, gana algo y conserva un cliente. ¡Bien negociado!", "r2c": "El cliente se alegra, pero Liruf regala su trabajo. La guitarra se aleja otro día.", "r2d": "El cliente pone cara rara y se va. Una oferta poco amable no convence a nadie."}}]}}', '{"units": {"s1-negociar.prompt": {"url": "http://localhost:4006/files/lesson-audio/602b877843681073b8a5d7ecdc9a897af653722571acbd426d71b13f4f3eea62.mp3", "hash": "ca1ff4bcd873e6a7300c682941d6bf07810cf2c500386521442777ba5d567e4d", "bytes": 40176, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/602b877843681073b8a5d7ecdc9a897af653722571acbd426d71b13f4f3eea62.mp3", "duration_ms": 6640}, "s1-negociar.explanation": {"url": "http://localhost:4006/files/lesson-audio/fafd7f2d8d6f3bff0af2e245867db047c6e9e064943552a4c2b5f6fc6bc48e6c.mp3", "hash": "93d5ade8b1566896cb429096b670e0007b5098ae765a33512b489f266364e04f", "bytes": 103104, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/fafd7f2d8d6f3bff0af2e245867db047c6e9e064943552a4c2b5f6fc6bc48e6c.mp3", "duration_ms": 17120}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a0b48602-bbeb-4aac-8309-90ec3cdeba90', 'en-US', '1', '{"meta": {"cast": ["rho"], "slug": "number-line", "title": "Straight to Saving", "locale": "en-US", "subject": "mixed", "objectives": ["Place savings and goals on a number line to visualize progress."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-number-line", "xp": 5, "type": "number_line", "title": "How much more?", "payload": {"max": 100, "min": 0, "ticks": 10, "labels": false}, "narrator": {"emotion": "encouraging", "character": "rho"}, "prompt_md": "Liruf has 20 dollars saved. Tap on the line where 20 is.", "difficulty": 1, "explanation_md": "Your savings are at 20. The goal of 80 dollars is further ahead. You need 60 dollars more."}], "schema_version": 1}', '{"s1-number-line": {"value": 20, "full_credit_delta": 0, "zero_credit_delta": 10}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('99bea18a-9bc0-4fca-91fe-aa5b44c0ea6e', 'es-MX', '1', '{"meta": {"cast": ["liruf", "dina", "rho", "zara"], "slug": "picture-choice", "title": "El lugar más seguro para el dinero", "locale": "es-MX", "subject": "money", "objectives": ["Elegir el lugar más seguro para guardar las ganancias del día"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-lugar-seguro", "xp": 10, "type": "picture_choice", "hints": ["Busca un lugar que tenga candado o llave.", "¿En cuál de estos lugares el dinero no se puede caer ni lo pueden tomar otros?"], "title": "¿Dónde guardar el dinero?", "payload": {"options": [{"id": "alcancia", "icon": "savings", "label": "Alcancía con llave", "image_url": "http://localhost:4006/files/lesson-images/9681bc52834c92a8becdd0f2853e569f8a065b99bd2ee43b8bdacc1f103ff2d3.webp"}, {"id": "bolsillo", "icon": "checkroom", "label": "Bolsillo roto", "image_url": "http://localhost:4006/files/lesson-images/4e2abf237219b8117084640a1b04964166d8a54edd652fb5fcf751357019ea9b.webp", "rationale_md": "El bolsillo roto tiene un agujero: las monedas se caen y se pierden."}, {"id": "mesa", "icon": "table_restaurant", "label": "Mesa del puesto", "image_url": "http://localhost:4006/files/lesson-images/c7a7477fa0d906300135e0eb029415c13f98959267fe79c5560159025bd2faee.webp", "rationale_md": "La mesa del puesto está a la vista de todos: cualquiera puede tomar el dinero."}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf terminó de vender. ¿Dónde guarda su dinero para que esté más seguro?", "difficulty": 1, "explanation_md": "La alcancía con llave protege el dinero de caídas y de personas ajenas. El bolsillo roto deja caer las monedas y la mesa del puesto deja el dinero a la vista de todos.", "audio_segment_id": "s1-lugar-seguro.prompt"}], "schema_version": 1}', '{"s1-lugar-seguro": {"correct_option_id": "alcancia"}}', '{"units": {"s1-lugar-seguro.hint.0": {"url": "http://localhost:4006/files/lesson-audio/0fcadd19b8c68ae491347e1e5a9be0e8e16ba4e2732f7c15f0f91d2ef428595b.mp3", "hash": "d2a339ba3fb912cea5d6af9425b3fc7d1a764fbb00a75ccf7e5a4d380806af0c", "bytes": 18144, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/0fcadd19b8c68ae491347e1e5a9be0e8e16ba4e2732f7c15f0f91d2ef428595b.mp3", "duration_ms": 2960}, "s1-lugar-seguro.hint.1": {"url": "http://localhost:4006/files/lesson-audio/fa0d7be19693e46383f9eaaa510452a39e0ed91e4208cec4abc2526860fcf2bb.mp3", "hash": "790c668a0cd4beee13d9d0cb56111c5dd3bb1663a82ceef208f5f313de986e7f", "bytes": 31104, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/fa0d7be19693e46383f9eaaa510452a39e0ed91e4208cec4abc2526860fcf2bb.mp3", "duration_ms": 5120}, "s1-lugar-seguro.prompt": {"url": "http://localhost:4006/files/lesson-audio/e6b365c0f712505d7469abf24fdb55cf14bc5c9e3ad9fbb15f1cc40a53cf8afa.mp3", "hash": "90ad3de1d5546256248f01e09f69a74409228ebb30e978873b3e1fc3a2dc2eff", "bytes": 31536, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/e6b365c0f712505d7469abf24fdb55cf14bc5c9e3ad9fbb15f1cc40a53cf8afa.mp3", "duration_ms": 5200}, "s1-lugar-seguro.choices": {"url": "http://localhost:4006/files/lesson-audio/976b8703c23444b9a2fc2978b327a1fc9caa0f9250f3e5bbdae9ba3daf72fc22.mp3", "hash": "ae9efcc8b3b806657c089dd124203e91622ce26eedf0698e44cfbb0bfdb2701e", "bytes": 26208, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/976b8703c23444b9a2fc2978b327a1fc9caa0f9250f3e5bbdae9ba3daf72fc22.mp3", "duration_ms": 4320}, "s1-lugar-seguro.explanation": {"url": "http://localhost:4006/files/lesson-audio/65b6413245907558eb5c38a68e738add59e02e4fafca32cfb4194976e27a419f.mp3", "hash": "8c461e749f1f36d5b5619c4ea90ed3f12d52a58e47e4fedaa0b4dd7f3e678141", "bytes": 69408, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/65b6413245907558eb5c38a68e738add59e02e4fafca32cfb4194976e27a419f.mp3", "duration_ms": 11520}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('574fb312-93f9-4f2f-adea-606bbb0ca99d', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "best-decision", "title": "The Best Decision: Giving Change", "locale": "en-US", "subject": "mixed", "objectives": ["Choosing the best way to give change when a customer pays with a large bill, showing honesty and accuracy."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-mejor-decision", "xp": 15, "type": "best_decision", "hints": ["Think about how much money Liruf should give back after charging 5 dollars with a 20-dollar bill."], "title": "Liruf''s Best Decision", "payload": {"options": [{"id": "opt-correcto", "text_md": "Counting the change slowly: 10, 15 dollars, and handing it over with a smile.", "rationale_md": "Counting the change step by step ensures accuracy and shows honesty."}, {"id": "opt-adivinar", "text_md": "Looking at the bill and guessing: ''I think it''s 15, take it.''", "rationale_md": "Guessing the change can lead to mistakes and the customer receiving less or more money than they should."}, {"id": "opt-extra", "text_md": "Telling her: ''Here is 20 dollars change,'' because it''s easier.", "rationale_md": "Giving 20 dollars instead of 15 would be giving away an extra 5 dollars; Liruf would lose money from his sale."}, {"id": "opt-quedar", "text_md": "Keeping the bill and not giving change, because it''s a large bill.", "rationale_md": "Not giving change is keeping money that doesn''t belong to him; that is dishonest and the customer would leave upset."}], "scenario_md": "Liruf sells lemonade. A glass costs 5 dollars. A customer pays with a 20-dollar bill."}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/faf9b8ae9893293a1ba40f784dad8f9266251b3e1767cf9b853204f99da5e64c.webp", "prompt_md": "A customer pays for her 5-dollar glass with a 20-dollar bill. Liruf must decide how to give change. What''s the BEST option?", "difficulty": 2, "explanation_md": "The correct change is 15 dollars. Counting the coins one by one avoids mistakes and shows that Liruf is honest and careful with his customers'' money.", "audio_segment_id": "s1-mejor-decision.prompt"}], "schema_version": 1}', '{"s1-mejor-decision": {"qualities": {"opt-extra": 10, "opt-quedar": 0, "opt-adivinar": 20, "opt-correcto": 100}}}', '{"units": {"s1-mejor-decision.hint.0": {"url": "http://localhost:4006/files/lesson-audio/e45d183c27617f1764d412c5a985d4dbfaab4ac863c33d97abfa30a028bf3ff7.mp3", "hash": "eff4ff3476fa3f3a746ecaa3bc5a3930350ee3c7f6e0be513de432e8d79278a2", "bytes": 30096, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/e45d183c27617f1764d412c5a985d4dbfaab4ac863c33d97abfa30a028bf3ff7.mp3", "duration_ms": 4960}, "s1-mejor-decision.prompt": {"url": "http://localhost:4006/files/lesson-audio/ad60fa42d7109767b1fd429834eb86b845bf4d8776dc6857ced173a8c3fbc963.mp3", "hash": "d7cf52b7d42555e708ce17c53210244b0e8b6b1d35d7700452a1e168c36a3efc", "bytes": 44064, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/ad60fa42d7109767b1fd429834eb86b845bf4d8776dc6857ced173a8c3fbc963.mp3", "duration_ms": 7280}, "s1-mejor-decision.choices": {"url": "http://localhost:4006/files/lesson-audio/46f20debc362afdfb591efb9f9b36cafc61d965c0a35885322130205fa95e48c.mp3", "hash": "cccc94da5db913f9c409586f26ee8c1b949b0eedb4a2fe0956c185714ce88989", "bytes": 85824, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/46f20debc362afdfb591efb9f9b36cafc61d965c0a35885322130205fa95e48c.mp3", "duration_ms": 14240}, "s1-mejor-decision.explanation": {"url": "http://localhost:4006/files/lesson-audio/3beefc64023d43876ed878181dc989b0d2457c5a68161c5291bc0003cce7b50e.mp3", "hash": "e6fbdc49f71639afff21ab0911c58f8909100ca2bfc19e00a3b8bc5a702f0b24", "bytes": 49824, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/3beefc64023d43876ed878181dc989b0d2457c5a68161c5291bc0003cce7b50e.mp3", "duration_ms": 8240}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f8c5e4cf-232b-47dc-8484-3350558f5f27', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "needs-wants", "title": "Stand needs vs wants", "locale": "en-US", "subject": "mixed", "objectives": ["Separate the needs of the lemonade stand from personal wants."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-needs-wants", "xp": 15, "type": "needs_wants", "title": "What does the stand need?", "payload": {"items": [{"id": "limones", "icon": "nutrition", "text_md": "Lemons", "image_url": "http://localhost:4006/files/lesson-images/86f5f26864c96d8960d7101d73818c629328c943488ca4899ef8fef49a235072.webp"}, {"id": "hielo", "icon": "ac_unit", "text_md": "Ice", "image_url": "http://localhost:4006/files/lesson-images/72d08338a18e39e6fe85dbb593b9c6836af10ab7fc518723a490ce1a6b6b88c8.webp"}, {"id": "paleta", "icon": "icecream", "text_md": "Lollipop", "image_url": "http://localhost:4006/files/lesson-images/c6fca32a72d44842fbf1acb06d2e98aa4fe4b355bdd656deb135e7f572bcf52c.webp"}, {"id": "comic", "icon": "auto_stories", "text_md": "Comic", "image_url": "http://localhost:4006/files/lesson-images/60887a6d15168427cc965416d77c215fb060e665e0c6080f8367e3e8fe50f4b2.webp"}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf is setting up his lemonade stand. Classify into stand needs or personal wants.", "difficulty": 2, "explanation_md": "The lemonade stand needs lemons and ice to make and sell lemonade. The lollipop and comic are personal treats that can wait until the business generates profits.", "audio_segment_id": "s1-needs-wants.prompt"}], "schema_version": 1}', '{"s1-needs-wants": {"needs_ids": ["limones", "hielo"]}}', '{"units": {"s1-needs-wants.prompt": {"url": "http://localhost:4006/files/lesson-audio/f7e47ddb3d0d22558c3354594c6eb9a6d7c807971fab6163960e3d62cf577540.mp3", "hash": "62ce17ac1788388a06c30dd980d8bc24c7cf3f8c25e71c3f68df556fa89b586a", "bytes": 30096, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/f7e47ddb3d0d22558c3354594c6eb9a6d7c807971fab6163960e3d62cf577540.mp3", "duration_ms": 4960}, "s1-needs-wants.explanation": {"url": "http://localhost:4006/files/lesson-audio/4569bd1fce6ef64ae75ab968dc50e2d51329ed20f3721d07053229bf5adb4ec3.mp3", "hash": "ea4bc2d92337bef35971c343feebf2464bbc972fd568da9bfb15b266e8ebf666", "bytes": 51696, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/4569bd1fce6ef64ae75ab968dc50e2d51329ed20f3721d07053229bf5adb4ec3.mp3", "duration_ms": 8560}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1f15af49-9573-4e17-a4ee-0685fa854b90', 'es-MX', '1', '{"meta": {"cast": ["liruf"], "slug": "timeline-order", "title": "El orden del día de Liruf", "locale": "es-MX", "subject": "mixed", "objectives": ["Ordenar los pasos del día de venta en orden cronológico"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-timeline", "xp": 10, "type": "timeline_order", "hints": ["Piensa: ¿qué hizo Liruf primero en la mañana?", "Después de preparar, ¿qué pasó al mediodía?"], "title": "El orden del día de Liruf", "payload": {"events": [{"id": "comprar", "icon": "shopping_cart", "text_md": "Comprar limones y azúcar en la mañana", "image_url": "http://localhost:4006/files/lesson-images/75d7e60b838af72b56dd1d0d466c3bfaf6fc95a139b03e5ac2fa67fc631f91aa.webp"}, {"id": "preparar", "icon": "local_dining", "text_md": "Preparar la limonada", "image_url": "http://localhost:4006/files/lesson-images/99c76628985576a1499272c04a1f664174e29795e4150d52bb9b65791f9e2d5a.webp"}, {"id": "vender", "icon": "storefront", "text_md": "Vender limonada al mediodía", "image_url": "http://localhost:4006/files/lesson-images/a153bdd14836a40e0dd175050dce66e4f1b7faf2c22d3c05488207f0dd4ce050.webp"}, {"id": "contar", "icon": "payments", "text_md": "Contar el dinero y guardarlo al cierre", "image_url": "http://localhost:4006/files/lesson-images/2aa68f81979ddbc27c3a9b78ca33735eeb984fc8f95a5fd16f9a9970580f6f70.webp"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf recuerda su primer día. Toca los eventos en el orden en que pasaron.", "difficulty": 1, "explanation_md": "Primero se compran los ingredientes, luego se prepara la limonada, después se vende, y al final se cuenta el dinero y se guarda.", "audio_segment_id": "s1-timeline.prompt"}], "schema_version": 1}', '{"s1-timeline": {"order": ["comprar", "preparar", "vender", "contar"]}}', '{"units": {"s1-timeline.hint.0": {"url": "http://localhost:4006/files/lesson-audio/fa1dcb893c824e35b5ca5cf2a7a79381f36c88917f4e37dbe7abecf84fd3e1b0.mp3", "hash": "fa231904e2ddd1f9ed58bdd8e3c9d2dc279432147d946bb5a49db350e3cdfd24", "bytes": 20016, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/fa1dcb893c824e35b5ca5cf2a7a79381f36c88917f4e37dbe7abecf84fd3e1b0.mp3", "duration_ms": 3280}, "s1-timeline.hint.1": {"url": "http://localhost:4006/files/lesson-audio/87834872c5dcebef0e32ae906a1d4aea563b1a96cdd32eb50f248e2770e2bb6c.mp3", "hash": "6f9118ffa51d89e81ed795f4b73471996909bb7c38e2cd2f4b33051523bd3595", "bytes": 21024, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/87834872c5dcebef0e32ae906a1d4aea563b1a96cdd32eb50f248e2770e2bb6c.mp3", "duration_ms": 3440}, "s1-timeline.prompt": {"url": "http://localhost:4006/files/lesson-audio/d94c1e876ca5b1072089c707011818a29360dda0e6e12d5e3558d6bb665d0bde.mp3", "hash": "282a06bcc7af00c932133076026b095e7525d2c4f999b2eebbb1544999b45221", "bytes": 31968, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/d94c1e876ca5b1072089c707011818a29360dda0e6e12d5e3558d6bb665d0bde.mp3", "duration_ms": 5280}, "s1-timeline.explanation": {"url": "http://localhost:4006/files/lesson-audio/41ceef00e2b5717a21bb41f0970823a41776158d83fcf4b764817b8c72904938.mp3", "hash": "ca9b8e625c49ed14c76e1323ae35354c5191ded9dd27987c6c85160212bb7efb", "bytes": 51696, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/41ceef00e2b5717a21bb41f0970823a41776158d83fcf4b764817b8c72904938.mp3", "duration_ms": 8560}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c5c3f5b2-2c4b-4aa8-bd76-cdcb594e0dda', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "concept-reveal", "title": "Ganhar dinheiro começa com uma ideia", "locale": "pt-BR", "subject": "money", "objectives": ["Entender que o dinheiro se ganha oferecendo algo que outros querem", "Identificar que uma meta clara ajuda a começar", "Distinguir entre custo e lucro"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-concept-reveal", "xp": 0, "type": "concept_reveal", "hints": ["Pense no que Liruf gasta para fazer a limonada.", "O que sobra depois de pagar os ingredientes é o lucro."], "title": "Custo e lucro", "payload": {"cards": [{"icon": "local_atm", "back_md": "O que você gasta em limões e açúcar", "front_md": "Custo", "image_url": "http://localhost:4006/files/lesson-images/145b3aaf364c3555e9f2614261886f99f2012cf79d86cc7686b1d9ddc557d326.webp"}, {"icon": "monetization_on", "back_md": "O que sobra depois de pagar o custo", "front_md": "Lucro", "image_url": "http://localhost:4006/files/lesson-images/03ecc244187fa091488493bc15e6147651dcb78de5c11c824b6c2f792913cd56.webp"}]}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Toque nos cartões para descobrir o que significam ''custo'' e ''lucro''.", "difficulty": 1, "explanation_md": "O custo é o que você gasta em limões e açúcar. O lucro é o que sobra depois de pagar o custo.", "audio_segment_id": "s1-concept-reveal.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-concept-reveal.hint.0": {"url": "http://localhost:4006/files/lesson-audio/8f6259070c2161eb2799cd3c3babcb72fdcf616ceec5d3f3c73761d093c75449.mp3", "hash": "1cdd869e9b661fbaa4889a443b5c5788e107cb65f499be03f5141bf6572e29fc", "bytes": 18144, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/8f6259070c2161eb2799cd3c3babcb72fdcf616ceec5d3f3c73761d093c75449.mp3", "duration_ms": 2960}, "s1-concept-reveal.hint.1": {"url": "http://localhost:4006/files/lesson-audio/8e7218d7cd98cf08098dc72c32142a4ead641ac552f2d802ce2a91113d3e927f.mp3", "hash": "415d7a595f0f5fc0b0623b1aa1b1aa6b3ddee187a9e4963141cb43c15fb4522a", "bytes": 21024, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/8e7218d7cd98cf08098dc72c32142a4ead641ac552f2d802ce2a91113d3e927f.mp3", "duration_ms": 3440}, "s1-concept-reveal.prompt": {"url": "http://localhost:4006/files/lesson-audio/4f88287fad39541036325e17d3f6bc41e5f50285e1bb7c2f8607b3ab020bf9dd.mp3", "hash": "35bcee98816153f0aa8a8d4d8a38ca4f35cdaf2a3c2060c47fed7ca58e052adb", "bytes": 30528, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/4f88287fad39541036325e17d3f6bc41e5f50285e1bb7c2f8607b3ab020bf9dd.mp3", "duration_ms": 5040}, "s1-concept-reveal.card.0.back": {"url": "http://localhost:4006/files/lesson-audio/51d8a9b725b92f4dc44a41373667032de8fa4861e8965398c03750a335f0f474.mp3", "hash": "776ceca44db2dc2c7b8f17a9e3bbaa6debf45aa95f901713b78378e83e95f87c", "bytes": 16128, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/51d8a9b725b92f4dc44a41373667032de8fa4861e8965398c03750a335f0f474.mp3", "duration_ms": 2640}, "s1-concept-reveal.card.1.back": {"url": "http://localhost:4006/files/lesson-audio/3e1df20ae253a1e8d2ca8f5b3ca2a5e1d5792da7e532f0d9b70da27b1ea8cd85.mp3", "hash": "09eeaa346378ea4ee755187d016fbd5145e9e0f6751ec3fd4459334b873557bf", "bytes": 14256, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/3e1df20ae253a1e8d2ca8f5b3ca2a5e1d5792da7e532f0d9b70da27b1ea8cd85.mp3", "duration_ms": 2320}, "s1-concept-reveal.explanation": {"url": "http://localhost:4006/files/lesson-audio/d31392343828213369cac67e4b722edbc109fbf32ecd9e5b0dd0ceef7d9f670a.mp3", "hash": "71688ba998be5611836c700571bc3f0eaf48fe9a556716f5b00e97eab6f98c0c", "bytes": 40176, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/d31392343828213369cac67e4b722edbc109fbf32ecd9e5b0dd0ceef7d9f670a.mp3", "duration_ms": 6640}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('462e0be5-c40d-4de9-840d-6f696539d27e', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "combo-dialogo-doble-choice", "title": "Vizinhos opinam da barraquinha", "locale": "pt-BR", "subject": "mixed", "objectives": ["Escutar atentamente uma conversa entre vizinhos sobre a barraquinha de limonada.", "Decidir se uma afirmação é verdadeira ou falsa com base no que foi ouvido.", "Identificar a moeda correta usada na compra entre imagens."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-listen", "xp": 0, "type": "story_dialogue", "title": "A mesa ao lado", "payload": {"lines": [{"action": "idle", "emotion": "happy", "text_md": "Você se lembra? No sábado passado Liruf montou sua barraquinha de limonada pela primeira vez. Hoje ela está de volta.", "character": "dina"}, {"action": "idle", "emotion": "thinking", "text_md": "Sim, e vejo que agora tem clientes. Por quanto vende o copo?", "character": "rho"}, {"action": "idle", "emotion": "excited", "text_md": "A 5 reais. Que barato! Eu tenho uma nota de 20, mas sem troco.", "character": "dina"}, {"action": "idle", "emotion": "happy", "text_md": "Pois eu vou pedir um. Aqui tenho uma moeda de 10 reais, assim me devolvem 5.", "character": "rho"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/4dbd5cfee244fc840f7f401ac93ca14d2bedfefa7c05487d4a9afad235221696.webp", "prompt_md": "Dois vizinhos conversam na mesa ao lado. Escute.", "difficulty": 1, "audio_segment_id": "s1-listen.prompt"}, {"id": "s2-true", "xp": 10, "type": "true_false", "title": "Verdadeiro ou falso?", "payload": {"statement_md": "Uma vizinha disse que a limonada é cara.", "justifications": [{"id": "barato", "text_md": "Porque disse ''Que barato!'', o que significa que não é cara."}, {"id": "precio", "text_md": "Porque o copo custa 5 reais e isso a torna cara."}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "É verdade o que esta frase diz?", "difficulty": 2, "explanation_md": "Dina disse ''Que barato!'', então a limonada NÃO parece cara para ela. Prestar atenção às palavras exatas é importante.", "audio_segment_id": "s2-true.prompt"}, {"id": "s3-coin", "xp": 10, "type": "picture_choice", "title": "A moeda que usou", "payload": {"options": [{"id": "c5", "icon": "payments", "label": "Moeda de 5 reais", "image_url": "http://localhost:4006/files/lesson-images/652da598efa28187d0fceeed66bf0f59a603bfbe50aa719aebe3bc5a5ba4042c.webp", "rationale_md": "Rho ia comprar um copo que custa 5 reais, mas usou uma moeda de 10 para que lhe dessem troco."}, {"id": "c10", "icon": "payments", "label": "Moeda de 10 reais", "image_url": "http://localhost:4006/files/lesson-images/b555ba34ba4bab919345899f7d495c6b513ad119f0476731740013d29ffcbce9.webp"}, {"id": "c20", "icon": "payments", "label": "Moeda de 20 reais", "image_url": "http://localhost:4006/files/lesson-images/2e076df510a67a1f72513ab7335ef46f54f6dab72fc4128790a5d55bee653bc5.webp", "rationale_md": "Dina mencionou uma nota de 20, mas ela não comprou; foi Rho quem comprou e usou 10 reais."}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Com qual moeda Rho pagou?", "difficulty": 2, "explanation_md": "Rho disse: ''Aqui tenho uma moeda de 10 reais''. Por isso a imagem correta é a moeda de 10 reais.", "audio_segment_id": "s3-coin.prompt"}], "schema_version": 1}', '{"s2-true": {"is_true": false, "correct_justification_id": "barato"}, "s3-coin": {"correct_option_id": "c10"}}', '{"units": {"s2-true.prompt": {"url": "http://localhost:4006/files/lesson-audio/50b455c43fa5c6e4c77cf5807b78e8d48689f7368af7670587772bf2b10564e2.mp3", "hash": "749a35f6c35e9f04774ac6a2154fac51eda9960cd941358b542defc1deba1abe", "bytes": 14688, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/50b455c43fa5c6e4c77cf5807b78e8d48689f7368af7670587772bf2b10564e2.mp3", "duration_ms": 2400}, "s3-coin.prompt": {"url": "http://localhost:4006/files/lesson-audio/2b263fce0bba9d116a8ca2bb27f8fd6928d3c5bd5577dc74369191bd106e9e9f.mp3", "hash": "386d8c6ad9332e046463300f5d31e2efa0dbb61a0849b9250a96f02fc759f213", "bytes": 12816, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/2b263fce0bba9d116a8ca2bb27f8fd6928d3c5bd5577dc74369191bd106e9e9f.mp3", "duration_ms": 2080}, "s3-coin.choices": {"url": "http://localhost:4006/files/lesson-audio/d1628c6da2370cba02677c5d8bc989e254997e124c21d161b5622ceb4103deb1.mp3", "hash": "5878817ac7e05ab16642a0e4b6fe8efccd3e026e6dfd3809e41f35ac1bf46ca3", "bytes": 35424, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/d1628c6da2370cba02677c5d8bc989e254997e124c21d161b5622ceb4103deb1.mp3", "duration_ms": 5840}, "s1-listen.line.0": {"url": "http://localhost:4006/files/lesson-audio/7ecf873f9dff1df03a6071c13aa301ae622ef5c479de8b65e2cb8c9dcbdbe5f9.mp3", "hash": "a46c67b46ee58c83c23fcbe2fcdcd5c1c27b35fd3634e9fabd44b485b1cef4ad", "bytes": 57024, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/7ecf873f9dff1df03a6071c13aa301ae622ef5c479de8b65e2cb8c9dcbdbe5f9.mp3", "duration_ms": 9440}, "s1-listen.line.1": {"url": "http://localhost:4006/files/lesson-audio/cf9a398e2ec75d493c0cf9fa8e55832b2bfd96467e153f9081755d72c70b5272.mp3", "hash": "0a73dee44c9258999dbf922428049bc7ab1f94f298b8a7bc0d6be1911fb9463a", "bytes": 29664, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/cf9a398e2ec75d493c0cf9fa8e55832b2bfd96467e153f9081755d72c70b5272.mp3", "duration_ms": 4880}, "s1-listen.line.2": {"url": "http://localhost:4006/files/lesson-audio/6b9b50534b02a59ac86aa39a0b95f30a925a66a76bae885a0c3624ee9d970ce7.mp3", "hash": "301d1e030e71600feea8c0f89d6dd479c3c85ee264e667584f78d24e80960f49", "bytes": 34848, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/6b9b50534b02a59ac86aa39a0b95f30a925a66a76bae885a0c3624ee9d970ce7.mp3", "duration_ms": 5760}, "s1-listen.line.3": {"url": "http://localhost:4006/files/lesson-audio/9b0d9768f751fb994985f934edf42c3ac80e4d007f0f146418564758a934a1b0.mp3", "hash": "5b2143c85a2df154f1ac4b88101aa0619a3ca5bc73cc749ab3056da090230e63", "bytes": 40608, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/9b0d9768f751fb994985f934edf42c3ac80e4d007f0f146418564758a934a1b0.mp3", "duration_ms": 6720}, "s1-listen.prompt": {"url": "http://localhost:4006/files/lesson-audio/ae39f9027531ae9f96b272dc8cfe35b993e2884558e7ca29ac1fa61c2b828fac.mp3", "hash": "b9ac174abdd02c3eff23599c6ccf836b194ec1bb86edb9b2b675c1d49b22d573", "bytes": 24336, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/ae39f9027531ae9f96b272dc8cfe35b993e2884558e7ca29ac1fa61c2b828fac.mp3", "duration_ms": 4000}, "s2-true.explanation": {"url": "http://localhost:4006/files/lesson-audio/61b8525e8e95890df71a5df6b82ba28a0e07166a4797b2d15c938a32bf5d29bb.mp3", "hash": "d56b72c2acdfef8007cebc55311b6a1bf06b6964422d20fc78b3c81cb6158380", "bytes": 52704, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/61b8525e8e95890df71a5df6b82ba28a0e07166a4797b2d15c938a32bf5d29bb.mp3", "duration_ms": 8720}, "s3-coin.explanation": {"url": "http://localhost:4006/files/lesson-audio/4c404a490efa808a5229ed96438af259622f4c1d1ede2cb37c2e0d236f17532a.mp3", "hash": "3e5b7c7a7f804910a29ce29d93469f2ed4c67e49dc1285ce7a0d37b91413eb66", "bytes": 48816, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/4c404a490efa808a5229ed96438af259622f4c1d1ede2cb37c2e0d236f17532a.mp3", "duration_ms": 8080}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4b45b37b-19f0-4fd5-99c2-0bcf9fabfbcd', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "machine-io", "title": "La máquina de propinas", "locale": "es-MX", "subject": "mixed", "objectives": ["Descubrir la regla de la máquina de propinas: duplica el número de monedas que entran."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-machine-io", "xp": 10, "type": "machine_io", "hints": ["Fíjate en el patrón: entra 1 → sale 2, entra 2 → sale 4. ¿Qué operación convierte el número de entrada en el de salida?"], "title": "La máquina de propinas", "payload": {"options": [{"id": "a", "text_md": "4"}, {"id": "b", "text_md": "6"}, {"id": "c", "text_md": "8"}, {"id": "d", "text_md": "12"}], "examples": [{"in": 1, "out": 2}, {"in": 2, "out": 4}, {"in": 3, "out": 6}], "probe_in": 4}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Entran monedas y salen más monedas. Si entra 1 sale 2, si entra 2 sale 4, si entra 3 sale 6. ¿Qué sale si entra 4?", "difficulty": 1, "explanation_md": "La máquina duplica: cada moneda que entra se convierte en dos. Por eso, al meter 4, salen 8 monedas (4 × 2 = 8).", "audio_segment_id": "s1-machine-io.prompt"}], "schema_version": 1}', '{"s1-machine-io": {"value": 8, "correct_option_id": "c"}}', '{"units": {"s1-machine-io.hint.0": {"url": "http://localhost:4006/files/lesson-audio/693b44d848f5aa810a50e12457aeabc020f1289aa0006c539cd953b4023bdcf5.mp3", "hash": "64735193a605552a5bdc0ea69a7b36feb077750ed1b347ecd85b00203e781b53", "bytes": 59904, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/693b44d848f5aa810a50e12457aeabc020f1289aa0006c539cd953b4023bdcf5.mp3", "duration_ms": 9920}, "s1-machine-io.prompt": {"url": "http://localhost:4006/files/lesson-audio/7624b250708dd3df544b5f916de1d02b898a490bdb915097b5204315a838df84.mp3", "hash": "22ec1ae4f388281e79301cd912aaf967bcdd551aee7d036c059bc3df601f9bbc", "bytes": 59904, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/7624b250708dd3df544b5f916de1d02b898a490bdb915097b5204315a838df84.mp3", "duration_ms": 9920}, "s1-machine-io.explanation": {"url": "http://localhost:4006/files/lesson-audio/1954713d2c0716dc4b25d618cdddb29a8596eda45e53c4774293368bca4f555c.mp3", "hash": "2b5f0340043c1f5c766aed8e9f1fabf458494e596e6fde817395edd8bedbadab", "bytes": 60768, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/1954713d2c0716dc4b25d618cdddb29a8596eda45e53c4774293368bca4f555c.mp3", "duration_ms": 10080}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b45d67a1-26c0-4ffa-b51c-76340c35e459', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "order-steps", "title": "Organize as compras da barraca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Organizar as compras do mercado por prioridade de venda", "Distinguir entre necessidades da barraca e desejos que podem esperar"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ordenar-compras", "xp": 15, "type": "order_steps", "hints": ["Sem limões não tem limonada.", "Os copos também são urgentes, mas sem limões não há nada para vender."], "title": "Prioridade no mercado", "payload": {"items": [{"id": "limones", "text_md": "Limões", "image_url": "http://localhost:4006/files/lesson-images/21bff4a3d02c6ea56efd5ee62d79fd1391b359799f561871bc04d7586830c42b.webp"}, {"id": "vasos", "text_md": "Copos", "image_url": "http://localhost:4006/files/lesson-images/80c3d852648b5f93347e92b79948d114de57183897f0ecd7de7a9e21e0cdf51b.webp"}, {"id": "azucar", "text_md": "Açúcar", "image_url": "http://localhost:4006/files/lesson-images/207c668d9e8aeb7c31ff8f8c47e9c91f5bdb5b988d30fff2af5f9512b9141f3f.webp"}, {"id": "calcomanias", "text_md": "Adesivos", "image_url": "http://localhost:4006/files/lesson-images/25581ecfccd390cefad4bfbd2cfabcf070eb2a0d095c3c29cc53b814c896d8f6.webp"}], "slots": 4}, "narrator": {"emotion": "thinking", "character": "zara"}, "prompt_md": "Zara tem R$10 para a barraca. Qual compra é mais urgente para vender hoje? Toque nos cartões do mais necessário ao que pode esperar.", "difficulty": 2, "explanation_md": "Os limões são o mais urgente porque sem eles você não pode fazer limonada. Os copos são os próximos, porque você precisa de onde servir. O açúcar ajuda a ficar gostoso, mas você pode vender sem ele. Os adesivos são um luxo que pode esperar. Se você colocou os adesivos antes, pensou que eram mais importantes que vender, mas a barraca precisa primeiro do que gera dinheiro.", "audio_segment_id": "s1-ordenar-compras.prompt"}], "schema_version": 1}', '{"s1-ordenar-compras": {"order": ["limones", "vasos", "azucar", "calcomanias"]}}', '{"units": {"s1-ordenar-compras.hint.0": {"url": "http://localhost:4006/files/lesson-audio/a106c7bffdd23c69fe5b476ec4d6b65a59019910e9608827e7c8c5bbf42d4ca3.mp3", "hash": "badae0e5cfd8067da1b70a4d43d8482fd00e5048b6f211003f6ad84a6b40f8c8", "bytes": 13824, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/a106c7bffdd23c69fe5b476ec4d6b65a59019910e9608827e7c8c5bbf42d4ca3.mp3", "duration_ms": 2240}, "s1-ordenar-compras.hint.1": {"url": "http://localhost:4006/files/lesson-audio/5a177fc5f09cfd9f745bbc999797ec1eed4200403840395149fb1a6e8411e297.mp3", "hash": "f351da66d34c0b6f2cb68a2998a70f75bd001b049f08b8a915c4526401a1a633", "bytes": 27216, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/5a177fc5f09cfd9f745bbc999797ec1eed4200403840395149fb1a6e8411e297.mp3", "duration_ms": 4480}, "s1-ordenar-compras.prompt": {"url": "http://localhost:4006/files/lesson-audio/79e227635a8d5e076cea01572a674fcdf8e1c1af9fd39e86fdac0f669aeaef64.mp3", "hash": "fee4164e9dd4166a695524c99e7e56114f9147fbb02846a68e579dc1f32330d7", "bytes": 55584, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/79e227635a8d5e076cea01572a674fcdf8e1c1af9fd39e86fdac0f669aeaef64.mp3", "duration_ms": 9200}, "s1-ordenar-compras.explanation": {"url": "http://localhost:4006/files/lesson-audio/24a27c26de8e1417c2fd9dd110a4b4d3e15f3f66c15b5953b5493fe94230ada8.mp3", "hash": "b772f69099c41ff0f32a60471a96f451784ce3d9488a69c902a6c64d65bb8799", "bytes": 145296, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/24a27c26de8e1417c2fd9dd110a4b4d3e15f3f66c15b5953b5493fe94230ada8.mp3", "duration_ms": 24160}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('6e000ee0-e5b3-4521-b30f-cd54bbd72297', 'pt-BR', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "type-answer", "title": "Escrever e calcular números reais do cargo", "locale": "pt-BR", "subject": "mixed", "objectives": ["Escrever respostas numéricas e de texto exatas sobre as vendas do dia (somas até 80, contagens até 20)."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-type-ahorro", "xp": 10, "type": "type_answer", "hints": ["Some 12 + 8."], "title": "Forca financeira", "payload": {"max_chars": 3, "placeholder": "Escreva o número aqui"}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Rho vendeu 12 limonadas. Depois vendeu mais 8. Quantas limonadas vendeu no total?", "difficulty": 1, "explanation_md": "Rho vendeu 12 e depois 8, que são 20 limonadas no total. Bom trabalho somando!", "audio_segment_id": "s1-type-ahorro.prompt"}], "schema_version": 1}', '{"s1-type-ahorro": {"accept": ["20"], "keywords": ["20"], "case_sensitive": false}}', '{"units": {"s1-type-ahorro.hint.0": {"url": "http://localhost:4006/files/lesson-audio/4b94a02e1f70fd9a2c0b5fb16bca81f610d5a08d4c34fe65c32ca5c3efeb052d.mp3", "hash": "b6b9987cf17c1b0a336511432a9ece61d586991596ea03d679a894c82c1a44a8", "bytes": 11808, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/4b94a02e1f70fd9a2c0b5fb16bca81f610d5a08d4c34fe65c32ca5c3efeb052d.mp3", "duration_ms": 1920}, "s1-type-ahorro.prompt": {"url": "http://localhost:4006/files/lesson-audio/40621396519b4b3c97c0eeb015f723fb322c8eccb3d48f900c796603c627ec84.mp3", "hash": "b9cd76ffb8b74e756497a5d23a45f7ea87dc75168dd23e59f391130b6b0b5a92", "bytes": 45504, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/40621396519b4b3c97c0eeb015f723fb322c8eccb3d48f900c796603c627ec84.mp3", "duration_ms": 7520}, "s1-type-ahorro.explanation": {"url": "http://localhost:4006/files/lesson-audio/d83d26c328cf529fcd2f0e799b79a46ea3317518154979323706826b251b86b0.mp3", "hash": "d8176ebe1c39b7f80fc1e7a7f446566425e4bc7f241d51b6deb6b9d045bb2a76", "bytes": 42048, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/d83d26c328cf529fcd2f0e799b79a46ea3317518154979323706826b251b86b0.mp3", "duration_ms": 6960}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9bdad6a7-ed32-42f2-83c9-554afe044403', 'pt-BR', '1', '{"meta": {"cast": ["liruf", "rho"], "slug": "savings-goal", "title": "Meta de poupança: A guitarra de Liruf", "locale": "pt-BR", "subject": "mixed", "objectives": ["Calcular quantas semanas são necessárias para alcançar uma meta de poupança dividindo o custo total pela poupança semanal", "Comparar diferentes planos de poupança para alcançar uma meta em um prazo determinado"], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-guitar-savings", "xp": 15, "type": "savings_goal", "hints": ["Divida 80 reais pela quantia que você guarda por semana.", "Por exemplo, se você guarda 10 reais, quantas vezes 10 cabe em 80?"], "title": "O plano de poupança de Liruf", "payload": {"goal": 80, "currency": "BRL", "weekly_options": [10, 20, 40]}, "narrator": {"emotion": "happy", "character": "rho"}, "prompt_md": "Liruf quer a guitarra de 80 reais. Quantas semanas precisa guardando 10, 20 ou 40 reais por semana?", "difficulty": 2, "explanation_md": "Guardar mais a cada semana encurta a espera. Com 40 reais, Liruf alcança a guitarra em 2 semanas, bem a tempo para o concurso.", "audio_segment_id": "s1-guitar-savings.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-guitar-savings.hint.0": {"url": "http://localhost:4006/files/lesson-audio/d7f03699618cd78a152a6c915705d1db4c22aa5f1c887dbb9a36eb46eadb28c9.mp3", "hash": "04155169101e0f31cbb745ffa2ec76039a67d2b6d4d604112b1d2c8d93de2644", "bytes": 27216, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/d7f03699618cd78a152a6c915705d1db4c22aa5f1c887dbb9a36eb46eadb28c9.mp3", "duration_ms": 4480}, "s1-guitar-savings.hint.1": {"url": "http://localhost:4006/files/lesson-audio/15cfbccb3c97df722fc25b5178925aa2672ad36ad58c33d8ff0efe3142f1f9a8.mp3", "hash": "887c7798c446314d57a6b691d7f6ccbf7d7c7709dd996d7cefebb365fe2b8499", "bytes": 35856, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/15cfbccb3c97df722fc25b5178925aa2672ad36ad58c33d8ff0efe3142f1f9a8.mp3", "duration_ms": 5920}, "s1-guitar-savings.prompt": {"url": "http://localhost:4006/files/lesson-audio/6a3ac2fb9c15438102bf31a5e25c335e1a15de5d25987ab41212b1de70c58c9a.mp3", "hash": "e4860c7b745be5f568a7bbb943e75d82ca4884cbdf98b17f0c11cf65f2197b5a", "bytes": 53136, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/6a3ac2fb9c15438102bf31a5e25c335e1a15de5d25987ab41212b1de70c58c9a.mp3", "duration_ms": 8800}, "s1-guitar-savings.explanation": {"url": "http://localhost:4006/files/lesson-audio/e76ba0af8d9f6e62313a983243cacf21d9c364abc6cedec5134e7d4adaaeada6.mp3", "hash": "4564084e09f9d5358038141d346f09e5aa5e37825ac942c0ab977bec85aea755", "bytes": 60336, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/e76ba0af8d9f6e62313a983243cacf21d9c364abc6cedec5134e7d4adaaeada6.mp3", "duration_ms": 10000}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('574fb312-93f9-4f2f-adea-606bbb0ca99d', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "best-decision", "title": "La Mejor Decisión: Dar el Cambio", "locale": "es-MX", "subject": "mixed", "objectives": ["Elegir la mejor manera de dar cambio cuando un cliente paga con un billete grande, mostrando honestidad y precisión."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-mejor-decision", "xp": 15, "type": "best_decision", "hints": ["Piensa en cuánto dinero debe devolver Liruf después de cobrar 5 pesos con un billete de 20."], "title": "La Mejor Decisión de Liruf", "payload": {"options": [{"id": "opt-correcto", "text_md": "Contar el cambio despacio: 10, 15 pesos, y entregarlo con una sonrisa.", "rationale_md": "Contar el cambio paso a paso asegura exactitud y demuestra honestidad."}, {"id": "opt-adivinar", "text_md": "Mirar el billete y adivinar: ''Creo que son 15, tómelos''.", "rationale_md": "Adivinar el cambio puede llevar a errores y a que el cliente reciba menos o más dinero del que corresponde."}, {"id": "opt-extra", "text_md": "Decirle: ''Aquí tiene 20 pesos de cambio'', porque es más fácil.", "rationale_md": "Dar 20 pesos en lugar de 15 sería regalar 5 pesos extra; Liruf perdería dinero de su venta."}, {"id": "opt-quedar", "text_md": "Guardar el billete y no dar cambio, porque es un billete grande.", "rationale_md": "No dar el cambio es quedarse con dinero que no le pertenece; eso es deshonesto y el cliente se iría molesto."}], "scenario_md": "Liruf vende limonada. Un vaso cuesta 5 pesos. Una clienta paga con un billete de 20."}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/f02a07832e02df0767a84884819d8cab3dbd5f488b76bab67c6f1f21ee7b282e.webp", "prompt_md": "Una clienta paga su vaso de 5 pesos con un billete de 20. Liruf debe decidir cómo dar el cambio. ¿Cuál es la MEJOR opción?", "difficulty": 2, "explanation_md": "El cambio correcto es 15 pesos. Contar las monedas una por una evita errores y muestra que Liruf es honesto y cuidadoso con el dinero de sus clientes.", "audio_segment_id": "s1-mejor-decision.prompt"}], "schema_version": 1}', '{"s1-mejor-decision": {"qualities": {"opt-extra": 10, "opt-quedar": 0, "opt-adivinar": 20, "opt-correcto": 100}}}', '{"units": {"s1-mejor-decision.hint.0": {"url": "http://localhost:4006/files/lesson-audio/93d32aacdb23dc9ce402bc901dd2db887acae436cff8266bce929c107b72fb12.mp3", "hash": "71ff23351320a76e3b892ef4bff95fe0877dd788f94a1f69b0c0ae84dacf0bca", "bytes": 38736, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/93d32aacdb23dc9ce402bc901dd2db887acae436cff8266bce929c107b72fb12.mp3", "duration_ms": 6400}, "s1-mejor-decision.prompt": {"url": "http://localhost:4006/files/lesson-audio/5d6a17e56079b438b03234d801a6b41f9c031559fa20bd1e67c86d99790101ac.mp3", "hash": "f564f31d0c32cd0a8efc78ae9cac9de8da9d6337006d72bfae85c534436bfb11", "bytes": 48816, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/5d6a17e56079b438b03234d801a6b41f9c031559fa20bd1e67c86d99790101ac.mp3", "duration_ms": 8080}, "s1-mejor-decision.choices": {"url": "http://localhost:4006/files/lesson-audio/1e196db3da1d4a4d13d12592bfba08bbed6e8e118604b2cbaf3f6bd977aab338.mp3", "hash": "c39441f575fcd0de744db1b4c3ac72649a31517ebc25f75fc7f2c186237caa95", "bytes": 111744, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/1e196db3da1d4a4d13d12592bfba08bbed6e8e118604b2cbaf3f6bd977aab338.mp3", "duration_ms": 18560}, "s1-mejor-decision.explanation": {"url": "http://localhost:4006/files/lesson-audio/806a601ba60bc29ec40221146ca8b8d6d23a278a357f3e460c98f734b65f94fd.mp3", "hash": "f233aeaad6aeaa68589f1c9c95d9dd39f0ef82e4768700850f2ea62d23a18267", "bytes": 60336, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/806a601ba60bc29ec40221146ca8b8d6d23a278a357f3e460c98f734b65f94fd.mp3", "duration_ms": 10000}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f8c5e4cf-232b-47dc-8484-3350558f5f27', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "needs-wants", "title": "Necessidades vs desejos da barraca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Separar as necessidades da barraca de limonada dos desejos pessoais."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-needs-wants", "xp": 15, "type": "needs_wants", "title": "O que a barraca precisa?", "payload": {"items": [{"id": "limones", "icon": "nutrition", "text_md": "Limões", "image_url": "http://localhost:4006/files/lesson-images/6f8dc660ca9f2e414c095ad68a8e7299cdbcce3c48d45bf031091ecb0903e2cf.webp"}, {"id": "hielo", "icon": "ac_unit", "text_md": "Gelo", "image_url": "http://localhost:4006/files/lesson-images/e5fc40f81bf36220ccce02b17868150b55f45a703fa6e0d5e9464569dc21b002.webp"}, {"id": "paleta", "icon": "icecream", "text_md": "Picolé", "image_url": "http://localhost:4006/files/lesson-images/123cf3d82a5565ac354f36240f34c3a3d8a3336d29fcd9822dca95e6d717c8ad.webp"}, {"id": "comic", "icon": "auto_stories", "text_md": "Gibi", "image_url": "http://localhost:4006/files/lesson-images/06c454c39c396cbaafd08462405c850c6c558eee1cb73414715dd07985cb058f.webp"}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf prepara sua barraca de limonada. Classifique em necessidades da barraca ou desejos pessoais.", "difficulty": 2, "explanation_md": "A barraca de limonada precisa dos limões e do gelo para fazer e vender limonada. O picolé e o gibi são gostos pessoais que podem esperar até que o negócio gere lucros.", "audio_segment_id": "s1-needs-wants.prompt"}], "schema_version": 1}', '{"s1-needs-wants": {"needs_ids": ["limones", "hielo"]}}', '{"units": {"s1-needs-wants.prompt": {"url": "http://localhost:4006/files/lesson-audio/3bc525acf2c035f9f160c7e2fe6879fa63fa2834f061ee1a2ce17668c0c1cc80.mp3", "hash": "778fb96e10895a14bd56484cbc509743a34ac05205e7ebfd1dacc192d660823b", "bytes": 44928, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/3bc525acf2c035f9f160c7e2fe6879fa63fa2834f061ee1a2ce17668c0c1cc80.mp3", "duration_ms": 7440}, "s1-needs-wants.explanation": {"url": "http://localhost:4006/files/lesson-audio/2d54a57544e24010a333f0cd7b7f596e876ba6329367aac30c1e2c1d5c10b435.mp3", "hash": "2f5e3fda66dfc79cac7bcb03a0715236986963dbe9ce4cf46f8614683f573afb", "bytes": 71424, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/2d54a57544e24010a333f0cd7b7f596e876ba6329367aac30c1e2c1d5c10b435.mp3", "duration_ms": 11840}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f8c5e4cf-232b-47dc-8484-3350558f5f27', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "needs-wants", "title": "Necesidades vs deseos del puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Separar las necesidades del puesto de limonada de los deseos personales."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-needs-wants", "xp": 15, "type": "needs_wants", "title": "¿Qué necesita el puesto?", "payload": {"items": [{"id": "limones", "icon": "nutrition", "text_md": "Limones", "image_url": "http://localhost:4006/files/lesson-images/1be5b55a4cacf2174b4ed0c13f4e27f7e86f095fe85a2da912c97830ae354bad.webp"}, {"id": "hielo", "icon": "ac_unit", "text_md": "Hielo", "image_url": "http://localhost:4006/files/lesson-images/6266599e8d76c27c9bf369b2b0c59010493415893dfd34b51499e18c816e21fe.webp"}, {"id": "paleta", "icon": "icecream", "text_md": "Paleta", "image_url": "http://localhost:4006/files/lesson-images/6a902c8bd79a972f87a4f03ad2a48e351c138e92a4443deaf5dd1f094f099495.webp"}, {"id": "comic", "icon": "auto_stories", "text_md": "Cómic", "image_url": "http://localhost:4006/files/lesson-images/ede5b71ddfb77514ed873c22f9d5659644892e52893ff67ed4595dac793f64a7.webp"}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf prepara su puesto de limonada. Clasifica en necesidades del puesto o deseos personales.", "difficulty": 2, "explanation_md": "El puesto de limonada necesita los limones y el hielo para hacer y vender limonada. La paleta y el cómic son gustos personales que pueden esperar a que el negocio genere ganancias.", "audio_segment_id": "s1-needs-wants.prompt"}], "schema_version": 1}', '{"s1-needs-wants": {"needs_ids": ["limones", "hielo"]}}', '{"units": {"s1-needs-wants.prompt": {"url": "http://localhost:4006/files/lesson-audio/423661e7a5eb7d4cb14485e91af459088164fb60bb43119b0ea228d133a84e66.mp3", "hash": "4895e11f337c0afc8fd43c41da91138b81285ec2167f6839bbb01522df5b1c31", "bytes": 39168, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/423661e7a5eb7d4cb14485e91af459088164fb60bb43119b0ea228d133a84e66.mp3", "duration_ms": 6480}, "s1-needs-wants.explanation": {"url": "http://localhost:4006/files/lesson-audio/45c1bc64779f9eef02e1a6afb62fbff2ea01ca188121a5b868b1813e35eb0743.mp3", "hash": "19f2a243e7f7c1caa62587aed57b44deec668ba1288f1eb4543ae446d12ea5bd", "bytes": 68976, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/45c1bc64779f9eef02e1a6afb62fbff2ea01ca188121a5b868b1813e35eb0743.mp3", "duration_ms": 11440}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('29159ba6-6f90-42be-9578-fda50515f345', 'es-MX', '1', '{"meta": {"cast": ["liruf"], "slug": "budget-fit", "title": "¡De compras con 20 pesos!", "locale": "es-MX", "subject": "mixed", "objectives": ["Planear compras dentro de un presupuesto fijo.", "Sumar y restar para verificar que el total no exceda 20 pesos."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-budget-fit", "xp": 15, "type": "budget_fit", "hints": ["Primero suma el costo de los limones y el azúcar: 8 + 6.", "Resta ese total de 20 para saber cuánto dinero te queda."], "title": "¡De compras con 20 pesos!", "payload": {"items": [{"id": "limones", "icon": "eco", "need": true, "label": "Limones", "price": 8, "image_url": "http://localhost:4006/files/lesson-images/8e2114763dacc523d4ae74e3cb87a6557b23665ecac524fcf96298651f8b62d1.webp"}, {"id": "azucar", "icon": "label", "need": true, "label": "Azúcar", "price": 6, "image_url": "http://localhost:4006/files/lesson-images/0491cbc67e39281f347d48a3d5fbbab8a095f324096e2746453caaabb636dc86.webp"}, {"id": "hielo", "icon": "ac_unit", "need": false, "label": "Hielo", "price": 5, "image_url": "http://localhost:4006/files/lesson-images/9574dc6da4a543fb842926fee0c40acde530504fa7bc70718d4270fb4a8cc69f.webp"}, {"id": "popotes", "icon": "local_drink", "need": false, "label": "Popotes", "price": 3, "image_url": "http://localhost:4006/files/lesson-images/914c8736ac650c278a905f84c142ce4aac7340881dbc35f379ad43aa78f258fb.webp"}, {"id": "jarra", "icon": "local_cafe", "need": false, "label": "Jarra bonita", "price": 8, "image_url": "http://localhost:4006/files/lesson-images/4052aa568eb6daeeedb7576aff035a3dc05800b16079ef4a7d3426062b135373.webp"}], "budget": 20, "currency": "MXN", "must_buy_needs": true}, "narrator": {"emotion": "neutral", "character": "liruf"}, "prompt_md": "Liruf DEBE comprar limones (8 pesos) y azúcar (6 pesos). ¿Qué extra puede añadir sin pasarse de 20 pesos?", "difficulty": 2, "explanation_md": "Con limones, azúcar y hielo gastas 19 pesos, te queda 1 y tienes todo. La jarra te pasaría de 20 y el marchante la quitaría; sin azúcar la limonada sería amarga y nadie la compraría."}], "schema_version": 1}', '{"s1-budget-fit": {}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('97238255-709d-4d86-8930-3ea433f54f7d', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "checkpoint", "title": "The night before opening", "locale": "en-US", "subject": "mixed", "objectives": ["Review the goal of 80 dollars, the price of 5 dollars per cup, and that profit is what''s left after cost.", "Reflect on progress toward the goal."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-checkpoint", "xp": 0, "type": "checkpoint", "hints": [], "title": "Review of the big idea", "payload": {"recap_md": "**The goal:** guitar for 80 dollars. **Price:** 5 dollars per cup. **Profit:** what''s left after cost goes into the guitar jar.", "mood_prompt_md": "Liruf takes a deep breath. Tomorrow she opens her stand. Does the guitar feel closer already?"}, "narrator": {"emotion": "happy", "character": "dina"}, "prompt_md": "The guitar costs 80 dollars. Each cup of lemonade costs 5 dollars. The profit from each cup goes into the guitar jar.", "difficulty": 1, "explanation_md": "Liruf already has the goal of 80 dollars, the price of 5 dollars per cup, and knows that profit is what''s left after paying the cost.", "audio_segment_id": "s1-checkpoint.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-checkpoint.recap": {"url": "http://localhost:4006/files/lesson-audio/e11c1360dad453e368adc120d915f7b8913874d19b763271e1be85ffb51120b7.mp3", "hash": "5d0d9accb0d2b971b9af1ca0b88669c968b32eed9705aa35ef9d1cac795f8705", "bytes": 43056, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/e11c1360dad453e368adc120d915f7b8913874d19b763271e1be85ffb51120b7.mp3", "duration_ms": 7120}, "s1-checkpoint.prompt": {"url": "http://localhost:4006/files/lesson-audio/5c3db1062a8ae7e21331091aa5ec34f46baf3a5e067f84807a1a10354b7a2f62.mp3", "hash": "c0b7da3be981fb7893f6d974181506193f9f0eee9d0a735f72960788a16e922f", "bytes": 40176, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/5c3db1062a8ae7e21331091aa5ec34f46baf3a5e067f84807a1a10354b7a2f62.mp3", "duration_ms": 6640}, "s1-checkpoint.explanation": {"url": "http://localhost:4006/files/lesson-audio/4da7e7dc1bc22e58bfdb7b87ea52f968a5b338f3a5734b82e792dfc025c7f988.mp3", "hash": "4f06d9dde7e26950250ecb02bfd29b1e31995c4549d848f3db5b2770ba6803e1", "bytes": 44496, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/4da7e7dc1bc22e58bfdb7b87ea52f968a5b338f3a5734b82e792dfc025c7f988.mp3", "duration_ms": 7360}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('85c2a66b-c70b-43e4-8fd5-4862d4acb66b', 'pt-BR', '1', '{"meta": {"cast": ["rho"], "slug": "rank-choices", "title": "A ordem das compras", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ordenar compras por prioridade para uma barraca de limonada."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-prioridad-compras", "xp": 15, "type": "rank_choices", "hints": ["Pense: sem o que você não consegue fazer a limonada?"], "title": "Prioridade de compras", "payload": {"items": [{"id": "limones", "text_md": "Limões frescos", "image_url": "http://localhost:4006/files/lesson-images/5f109c64dbf62cd315195d4e14a7fcd3c2d4bf1fdfe4ccfec52178f4a12415fa.webp"}, {"id": "vasos", "text_md": "Copos de papel", "image_url": "http://localhost:4006/files/lesson-images/f0a04b32b0c6c0c7d54ecce743286622aa83733236558ff42a2ee3002e1e6b90.webp"}, {"id": "adornos", "text_md": "Enfeites para a barraca", "image_url": "http://localhost:4006/files/lesson-images/272e74dab94b131515613ac293865f7a52b625ce7f25fcea9f3978e7f9c82073.webp"}], "criterion_md": "O que ajuda mais a vender limonada amanhã?"}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Ordene do mais urgente ao menos urgente para a barraca.", "difficulty": 2, "explanation_md": "Para continuar vendendo limonada, o mais urgente é repor os limões. Depois os copos para servir, e por fim os enfeites que apenas decoram.", "audio_segment_id": "s1-prioridad-compras.prompt"}], "schema_version": 1}', '{"s1-prioridad-compras": {"order": ["limones", "vasos", "adornos"], "accept_orders": []}}', '{"units": {"s1-prioridad-compras.hint.0": {"url": "http://localhost:4006/files/lesson-audio/34a64721ab741469250f7d605a88f0167e7f37d2fed37270d65aadcd8af3c51c.mp3", "hash": "ad0cf93e4a628f54b4f0331b6ca9506d6d2e84a82cb3fe54105a22a54f9534b0", "bytes": 21888, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/34a64721ab741469250f7d605a88f0167e7f37d2fed37270d65aadcd8af3c51c.mp3", "duration_ms": 3600}, "s1-prioridad-compras.prompt": {"url": "http://localhost:4006/files/lesson-audio/1999ea381994bdb56e11bf2b4e11a057d8177b7e65c9663eed4eb80da1addf49.mp3", "hash": "d5c2f85efc0fdc4e8d3e55af06e6cae1be6db85b1306ace882e47020319cd9f4", "bytes": 22896, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/1999ea381994bdb56e11bf2b4e11a057d8177b7e65c9663eed4eb80da1addf49.mp3", "duration_ms": 3760}, "s1-prioridad-compras.explanation": {"url": "http://localhost:4006/files/lesson-audio/eaaeb105d9f0163b77b5f2716f707070a29b5591639c1da2815521686424b181.mp3", "hash": "8a8b4a00b1399121311adda4a5f98e0e91c73509a0b8d4cab530b5dd0ab9150e", "bytes": 62784, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/eaaeb105d9f0163b77b5f2716f707070a29b5591639c1da2815521686424b181.mp3", "duration_ms": 10400}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('64ccde87-2312-4acf-a950-409fd6a622c9', 'pt-BR', '1', '{"meta": {"cast": ["zara"], "slug": "read-chart", "title": "O melhor dia de vendas", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ler o gráfico de barras de copos vendidos por dia e responder qual foi o melhor dia da semana."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "read-chart-1", "xp": 10, "type": "read_chart", "hints": ["Cada barra mostra os copos vendidos naquele dia. Preste atenção na altura."], "title": "O gráfico da Zara", "payload": {"chart": {"kind": "bar", "unit": "vasos", "series": [{"label": "Copos vendidos", "points": [{"x": "Seg", "y": 8}, {"x": "Ter", "y": 12}, {"x": "Qua", "y": 5}, {"x": "Qui", "y": 15}, {"x": "Sex", "y": 10}]}]}, "questions": [{"id": "q1", "options": [{"id": "lunes", "text_md": "Segunda-feira"}, {"id": "martes", "text_md": "Terça-feira"}, {"id": "miercoles", "text_md": "Quarta-feira"}, {"id": "jueves", "text_md": "Quinta-feira"}, {"id": "viernes", "text_md": "Sexta-feira"}], "prompt_md": "Qual dia vendeu mais copos?"}]}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "Zara fez um gráfico de barras com os copos vendidos.", "difficulty": 1, "explanation_md": "Na quinta-feira foram vendidos 15 copos, a quantidade mais alta. A barra mais alta indica o melhor dia de vendas.", "audio_segment_id": "read-chart-1.prompt"}], "schema_version": 1}', '{"read-chart-1": {"correct": {"q1": "jueves"}}}', '{"units": {"read-chart-1.hint.0": {"url": "http://localhost:4006/files/lesson-audio/ff638326346efac5c05d2eb1b8ca6e0c934fe4cd7600aaec0ff76781d8a8ffe9.mp3", "hash": "8b4d5a95168d5cbc0aff91a46fb57544d1eb62016d5a22fc05e7ccf78166a793", "bytes": 34416, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/ff638326346efac5c05d2eb1b8ca6e0c934fe4cd7600aaec0ff76781d8a8ffe9.mp3", "duration_ms": 5680}, "read-chart-1.prompt": {"url": "http://localhost:4006/files/lesson-audio/196420101f4537c4d6e88d3782aab815640ce1720611e7f7efaeb2e5fb5c0566.mp3", "hash": "cf6e00fdf26e811611c74f3404a9c3b54bf8c0a50d207263de5df7e92894edd4", "bytes": 21024, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/196420101f4537c4d6e88d3782aab815640ce1720611e7f7efaeb2e5fb5c0566.mp3", "duration_ms": 3440}, "read-chart-1.explanation": {"url": "http://localhost:4006/files/lesson-audio/e199a5f822f89e8721bcb2d467035181dbaa1be26e041564e05777a4e39529c8.mp3", "hash": "f17cd291b331c1eced638b3db17942cbc0edae86fcda8057db41360c2dabf374", "bytes": 51264, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/e199a5f822f89e8721bcb2d467035181dbaa1be26e041564e05777a4e39529c8.mp3", "duration_ms": 8480}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5cfeb5fa-1115-414d-9498-5cf6271b6245', 'pt-BR', '1', '{"meta": {"cast": ["zara"], "slug": "robot-path", "title": "Entrega de sorvetes", "locale": "pt-BR", "subject": "mixed", "objectives": ["Planejar a rota mais eficiente para completar uma entrega e obter uma recompensa."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-robot-path", "xp": 5, "type": "robot_path", "hints": ["Observe a direção inicial. Se avançar, vai bater; o que você pode fazer primeiro?", "Cada passo extra demora mais, os sorvetes podem derreter!"], "title": "A rota mais curta", "payload": {"goal": {"x": 2, "y": 0}, "grid": {"h": 3, "w": 3}, "start": {"x": 0, "y": 0, "dir": "down"}, "walls": [{"x": 0, "y": 1}], "commands": ["left", "forward", "forward"], "max_commands": 5}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Guie a Zara pela grade para entregar os sorvetes. Use a rota mais curta e ganhe uma gorjeta!", "difficulty": 1, "explanation_md": "Perfeito! Zara virou à esquerda e avançou 2 passos, entregando os sorvetes bem a tempo. Como foi tão rápida, Ana lhe deu uma gorjeta extra.", "audio_segment_id": "s1-robot-path.prompt"}], "schema_version": 1}', '{"s1-robot-path": {}}', '{"units": {"s1-robot-path.hint.0": {"url": "http://localhost:4006/files/lesson-audio/b5c6a8d4e10e37528893c415c07589146e84f23488814168a17e55db653dfea9.mp3", "hash": "fe0e31360abecc6c6306bbd09f5f43bcb8ca955190e2629df194b5b967bf57fd", "bytes": 36864, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/b5c6a8d4e10e37528893c415c07589146e84f23488814168a17e55db653dfea9.mp3", "duration_ms": 6080}, "s1-robot-path.hint.1": {"url": "http://localhost:4006/files/lesson-audio/208cfe2bfbc0c3c90af2d52a25e3fa71c9bbab4a072dcdc5c0a9fb4af2716855.mp3", "hash": "310be16d8f73abc249b1a82683b9e0f25d9ae1240555925e834c907ed2d3f377", "bytes": 24768, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/208cfe2bfbc0c3c90af2d52a25e3fa71c9bbab4a072dcdc5c0a9fb4af2716855.mp3", "duration_ms": 4080}, "s1-robot-path.prompt": {"url": "http://localhost:4006/files/lesson-audio/b1f5626d54e9101c619690a584ecc58b62414b174f679ecb78370efc0d93e506.mp3", "hash": "a1d1638b9b28e61b77547f6c5a8507a968f4ca127de74c70f263f8b6970be018", "bytes": 40176, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/b1f5626d54e9101c619690a584ecc58b62414b174f679ecb78370efc0d93e506.mp3", "duration_ms": 6640}, "s1-robot-path.explanation": {"url": "http://localhost:4006/files/lesson-audio/228d03bc6cf9fe53b67452d8176b5c7f9194d9c34e534e40e3413e567b631245.mp3", "hash": "c22dbd91e6585b80db3b030569a4bef40d7c684521dc312d18db899ccf234b5e", "bytes": 68976, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/228d03bc6cf9fe53b67452d8176b5c7f9194d9c34e534e40e3413e567b631245.mp3", "duration_ms": 11440}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4a340725-6bd9-48c4-9c1a-d8641c86b7a1', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "evidence-hunt", "title": "¿Cuánto costaron los limones?", "locale": "es-MX", "subject": "mixed", "objectives": ["Buscar en el recibo del mercado la evidencia exacta de cuánto costaron los limones."], "estimated_minutes": 5}, "scoring": {"hearts": 3, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-evidence-hunt", "xp": 0, "type": "evidence_hunt", "title": "El recibo del mercado", "payload": {"claim_md": "Los limones costaron 10 pesos.", "sentences": [{"id": "s1", "text_md": "Limones - $10"}, {"id": "s2", "text_md": "Vasos - $5"}, {"id": "s3", "text_md": "Hielo - $3"}, {"id": "s4", "text_md": "Azúcar - $2"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/4fb340ec00377d340e79ef2120c58cee7feae83ed493b13f4031248562a2bc39.webp", "prompt_md": "Liruf necesita saber cuánto costaron los limones. Toca el renglón del recibo que tiene la respuesta.", "difficulty": 1, "explanation_md": "Los limones costaron 10 pesos, justo lo que muestra el recibo en el renglón ''Limones - $10''. ¡Así Liruf puede verificar sus gastos!"}], "schema_version": 1}', '{"s1-evidence-hunt": {"evidence_ids": ["s1"]}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('df879f53-8479-4b98-9651-889fcae66fdc', 'en-US', '1', '{"meta": {"cast": ["rho", "liruf"], "slug": "repaso-true-false", "title": "Review: Real profit?", "locale": "en-US", "subject": "mixed", "objectives": ["Differentiate between total sales and real profit considering costs."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "tf1-repaso-ganancia", "xp": 10, "type": "true_false", "hints": ["Hint: Profit = money received - money spent on making the cups."], "title": "Did she earn 50?", "payload": {"statement_md": "Liruf sold 10 cups at 5 dollars, so she earned 50.", "justifications": [{"id": "j1", "text_md": "True: 10 cups × 5 dollars = 50 dollars. That''s what went into the cash register."}, {"id": "j2", "text_md": "False: making each cup costs 2 dollars. She only earned 3 dollars per cup; 10 × 3 = 30 dollars."}]}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Liruf sold 10 cups at 5 dollars; making them costs 2 dollars. Did she earn 50? Choose true or false.", "difficulty": 1, "explanation_md": "Liruf received 50 dollars in total, but making the cups cost her 20 dollars. That''s why she only earned 30 dollars (3 dollars per cup).", "audio_segment_id": "tf1-repaso-ganancia.prompt"}], "schema_version": 1}', '{"tf1-repaso-ganancia": {"is_true": false, "correct_justification_id": "j2"}}', '{"units": {"tf1-repaso-ganancia.hint.0": {"url": "http://localhost:4006/files/lesson-audio/b1b5cdae6d38dde7028beaa2c5ba8a2d3c0349829be8566c79ce85a959633013.mp3", "hash": "3c58d6fdd2f125c383e6b17423eb41136269d43b34bad6a55610b4a1f7ff780b", "bytes": 31968, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/b1b5cdae6d38dde7028beaa2c5ba8a2d3c0349829be8566c79ce85a959633013.mp3", "duration_ms": 5280}, "tf1-repaso-ganancia.prompt": {"url": "http://localhost:4006/files/lesson-audio/fced3e94da8d1bb58c354747dd54b409698d55fb868cfd21b822483051392b94.mp3", "hash": "e9534cded0ba1a7c66ee9517b3d35767081ff1b7d2a2942551d45f083e0346f6", "bytes": 56448, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/fced3e94da8d1bb58c354747dd54b409698d55fb868cfd21b822483051392b94.mp3", "duration_ms": 9360}, "tf1-repaso-ganancia.explanation": {"url": "http://localhost:4006/files/lesson-audio/81c91a91a206c817a64351a182e82f7870037432b48c4859ca17618488780857.mp3", "hash": "23324a5e7566429fcc4abcf76e06ad061c8481f80a4d513e7c9f8071e8dd317c", "bytes": 62208, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/81c91a91a206c817a64351a182e82f7870037432b48c4859ca17618488780857.mp3", "duration_ms": 10320}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1b29b755-c45e-46e4-a8d8-25624cad27a3', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-arrange-largo", "title": "Fechando a barraca de limonada", "locale": "pt-BR", "subject": "mixed", "objectives": ["Associar pagamentos ao troco correto", "Ordenar os passos para calcular o lucro", "Distinguir necessidades de desejos para a barraca", "Planejar o dia para manter troco na caixa"], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-payments", "xp": 15, "type": "match_pairs", "title": "Associe pagamentos e troco", "payload": {"left": [{"id": "p10", "text_md": "Pagamento com 10 reais", "image_url": "http://localhost:4006/files/lesson-images/9b51973812dafd3243db125fb8e2ce8cb3bdfcd2029509e1b72450b2109e390c.webp"}, {"id": "p20", "text_md": "Pagamento com 20 reais"}, {"id": "p6", "text_md": "Pagamento com 6 reais", "image_url": "http://localhost:4006/files/lesson-images/739442b428e4d91daeb4b9de7d8d2ef3f0440ea01835bf16f12e173f92ee2a91.webp"}], "right": [{"id": "c5", "text_md": "5 reais"}, {"id": "c15", "text_md": "15 reais"}, {"id": "c1", "text_md": "1 real"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Cada copo custa 5 reais. Toque em um pagamento e depois no troco correto.", "difficulty": 2, "explanation_md": "O troco é o que sobra: 10 - 5 = 5 reais, 20 - 5 = 15 reais, e 6 - 5 = 1 real. Liruf sempre deve dar o troco exato.", "audio_segment_id": "s1-match-payments.prompt"}, {"id": "s2-order-profit", "xp": 25, "type": "order_steps", "hints": ["Pense: o que você precisa saber primeiro para calcular o lucro?", "Primeiro conte todo o dinheiro, depois separe o que gastou com os ingredientes."], "title": "Ordene o lucro", "payload": {"items": [{"id": "s1", "text_md": "Contar todo o dinheiro da caixa", "image_url": "http://localhost:4006/files/lesson-images/3d7ce2fe2e961351782bb310d427ca2d4b898a3f84b93549967c327ab4392ee9.webp"}, {"id": "s2", "text_md": "Separar o custo dos ingredientes (limões, copos, açúcar)", "image_url": "http://localhost:4006/files/lesson-images/33220c81287f35a1a970d14ccaf17efad4cc20d68e2426b9323fab0695c8087f.webp"}, {"id": "s3", "text_md": "O dinheiro que sobra é o lucro", "image_url": "http://localhost:4006/files/lesson-images/768f71b5e794c0e4a26ea892948e522d52317792c2b1d21a79839e5e726e55b6.webp"}, {"id": "d1", "text_md": "Gastar o lucro em um brinquedo", "image_url": "http://localhost:4006/files/lesson-images/e7e332176258c88207057260a3645f94f7193687e2881b452a6384cba98daf83.webp"}], "slots": 3}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Ajude Liruf a ordenar os passos para saber seu lucro. Sobra um que não se encaixa.", "difficulty": 3, "explanation_md": "Para saber o lucro, primeiro conte TODO o dinheiro, depois separe o custo dos ingredientes; o que sobra é o lucro. Por exemplo, se juntou 30 reais e gastou 20 com ingredientes, o lucro é de 10 reais.", "audio_segment_id": "s2-order-profit.prompt"}, {"id": "s3-sort-needs", "xp": 15, "type": "sort_buckets", "title": "Necessário ou pode esperar?", "payload": {"items": [{"id": "limones", "text_md": "Limões", "image_url": "http://localhost:4006/files/lesson-images/be2cbbdc9993b7f77d76962c3309747ca26f20530f3b54a514dcb2a5e06a8a02.webp"}, {"id": "vasos", "text_md": "Copos", "image_url": "http://localhost:4006/files/lesson-images/087b8e4fbcee80cdabd7c0258be84f61e7714bd440722cec68e35e328b60c2ee.webp"}, {"id": "hielo", "text_md": "Gelo", "image_url": "http://localhost:4006/files/lesson-images/2499bc61f165d73f1718300429c51f55ce7d627f20a4ca0c7e8d07029f444e77.webp"}, {"id": "calcomania", "text_md": "Adesivo", "image_url": "http://localhost:4006/files/lesson-images/dc7a64fb6cf4dc2356140eff77864ee70163e8b68f9034de1ede96983ea924dc.webp"}], "buckets": [{"id": "necesario", "label": "Necessário para abrir"}, {"id": "esperar", "label": "Pode esperar"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf só tem 20 reais. Toque em cada coisa e coloque em ''Necessário'' se sem ela não vende, ou em ''Pode esperar''.", "difficulty": 2, "explanation_md": "Para vender limonada, Liruf precisa de limões e copos. O gelo e o adesivo podem esperar até que ele tenha mais dinheiro.", "audio_segment_id": "s3-sort-needs.prompt"}, {"id": "s4-timeline-day", "xp": 30, "type": "timeline_order", "hints": ["O que você precisa ter antes de gastar? Dinheiro na caixa.", "Primeiro garanta ter troco, depois venda, depois gaste um pouco e repita."], "title": "Ordem do dia", "payload": {"events": [{"id": "e1", "icon": "savings", "text_md": "Pegar o troco inicial (20 reais)", "image_url": "http://localhost:4006/files/lesson-images/8d63ab046f39a4e6af5a679d0cb7709dcefc8778afb1abfa7ab156dde9c0edec.webp"}, {"id": "e2", "icon": "payments", "text_md": "Vender um copo de limonada", "image_url": "http://localhost:4006/files/lesson-images/fa5f045cd77cd319adba626d6f3db5cff6bc1a391fa37ff5fc52fa4139578a16.webp"}, {"id": "e3", "icon": "ac_unit", "text_md": "Comprar gelo (3 reais)", "image_url": "http://localhost:4006/files/lesson-images/e935625e8eafc05c474c1d88a24f801405f06cacad40894f47c1063373fe4eb9.webp"}, {"id": "e4", "icon": "shopping_cart_checkout", "text_md": "Vender dois copos de limonada", "image_url": "http://localhost:4006/files/lesson-images/298e206208970ecdeedb36a552eb17ecb24af135d9c7ed236d8d34958e7a3e59.webp"}, {"id": "e5", "icon": "agriculture", "text_md": "Comprar limões (8 reais)", "image_url": "http://localhost:4006/files/lesson-images/bb2ead159d20809b5b925b0022df0aaf53545a3039a69910f346c60612cfc9e6.webp"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Ordene os cartões para que Liruf nunca fique sem troco na caixa.", "difficulty": 3, "explanation_md": "Liruf deve ter dinheiro na caixa antes de gastar. Primeiro pegue o troco, depois venda, depois compre algo pequeno, venda novamente e por último compre outro insumo.", "audio_segment_id": "s4-timeline-day.prompt"}], "schema_version": 1}', '{"s3-sort-needs": {"assignments": {"hielo": "esperar", "vasos": "necesario", "limones": "necesario", "calcomania": "esperar"}}, "s2-order-profit": {"order": ["s1", "s2", "s3"]}, "s4-timeline-day": {"order": ["e1", "e2", "e3", "e4", "e5"]}, "s1-match-payments": {"pairs": [["p10", "c5"], ["p20", "c15"], ["p6", "c1"]]}}', '{"units": {"s3-sort-needs.prompt": {"url": "http://localhost:4006/files/lesson-audio/647691420db3de1a0193a581fdadd5a50571937fc04039cabc5e404afe5540cc.mp3", "hash": "f3fafce875fb4fa76f428899ef5eb10ece267f9f13cf3fbee91357d6adc9aacb", "bytes": 51264, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/647691420db3de1a0193a581fdadd5a50571937fc04039cabc5e404afe5540cc.mp3", "duration_ms": 8480}, "s2-order-profit.hint.0": {"url": "http://localhost:4006/files/lesson-audio/12b90be0cdf3078ad4774bb1e471fdd94e3bf308057cdcbe47c4995ddb444cff.mp3", "hash": "12cdde094681987befd91b5f459641bc088d52f663ac737af36b07b929cbab14", "bytes": 25344, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/12b90be0cdf3078ad4774bb1e471fdd94e3bf308057cdcbe47c4995ddb444cff.mp3", "duration_ms": 4160}, "s2-order-profit.hint.1": {"url": "http://localhost:4006/files/lesson-audio/753ec4bf06ce1dc630a9e5732f67b2f8d32b303b49c5959fcf78ce48355f9642.mp3", "hash": "2cd1cb1849e1bc755b96abc4f91a1117d63769ac6a4406c02e0b55e19b9f5bb3", "bytes": 28224, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/753ec4bf06ce1dc630a9e5732f67b2f8d32b303b49c5959fcf78ce48355f9642.mp3", "duration_ms": 4640}, "s2-order-profit.prompt": {"url": "http://localhost:4006/files/lesson-audio/76cc7c0c54f464deac643025566a043a5364f926009362592b8d66463d651dfa.mp3", "hash": "dbd1a69fb01f3f651fc1370d785efe8eda044610c92ce38c76d8d931d8e731de", "bytes": 37728, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/76cc7c0c54f464deac643025566a043a5364f926009362592b8d66463d651dfa.mp3", "duration_ms": 6240}, "s4-timeline-day.hint.0": {"url": "http://localhost:4006/files/lesson-audio/c48ed8bfc0e7137f37d4ff1728679d33cc5bcac5b54d0d609fc301032d113509.mp3", "hash": "993654b5ecf3874a8782d054442b0a52c4cef5f4ee195bd1f0e9bdf192647ff2", "bytes": 25344, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/c48ed8bfc0e7137f37d4ff1728679d33cc5bcac5b54d0d609fc301032d113509.mp3", "duration_ms": 4160}, "s4-timeline-day.hint.1": {"url": "http://localhost:4006/files/lesson-audio/f894cb070c92e5b25225b7ee93417e46c89a7f7467b70ac57cac57a13e577037.mp3", "hash": "8cc72373343fa3c4a290e6fedac2e49e8bacac886ab3fedbb2f9c86a81367fac", "bytes": 32976, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/f894cb070c92e5b25225b7ee93417e46c89a7f7467b70ac57cac57a13e577037.mp3", "duration_ms": 5440}, "s4-timeline-day.prompt": {"url": "http://localhost:4006/files/lesson-audio/0643c7b06a73fe687d282edb00f5f6c7dadd6eff0e1893f653bcb4b9afb07e4a.mp3", "hash": "a8e58b5654695fa9473ddb4be45bb3f26ecd1a4e6f7e554eee54b1625b9f9d36", "bytes": 25344, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/0643c7b06a73fe687d282edb00f5f6c7dadd6eff0e1893f653bcb4b9afb07e4a.mp3", "duration_ms": 4160}, "s1-match-payments.prompt": {"url": "http://localhost:4006/files/lesson-audio/86a155d23e42d5b3f0aa2de35eb523601ca6f83ab0a02ef70d0dc35968006feb.mp3", "hash": "4ffb4e4e3754aee29dbd5cfc16015e2ef65b3cce088dd1f34e69bff024e483e4", "bytes": 40608, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/86a155d23e42d5b3f0aa2de35eb523601ca6f83ab0a02ef70d0dc35968006feb.mp3", "duration_ms": 6720}, "s3-sort-needs.explanation": {"url": "http://localhost:4006/files/lesson-audio/c3510973d7fd4b967db89fa6afdebeaa97d826a5f1b32a54c91a7f5556ca44af.mp3", "hash": "fc0e687de4bfd6662be3a40173847c7fbc8730be383e5b346b22d3d79934c70c", "bytes": 52704, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/c3510973d7fd4b967db89fa6afdebeaa97d826a5f1b32a54c91a7f5556ca44af.mp3", "duration_ms": 8720}, "s2-order-profit.explanation": {"url": "http://localhost:4006/files/lesson-audio/1ad0372fbea601ceb805da807dfcc9db418bf70a937b8d282b2b2c3b8fd11520.mp3", "hash": "1f9910df68e3c1aa742c4af6d71259ab2222f606dac7169d4fa85f3fe3091cc1", "bytes": 84816, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/1ad0372fbea601ceb805da807dfcc9db418bf70a937b8d282b2b2c3b8fd11520.mp3", "duration_ms": 14080}, "s4-timeline-day.explanation": {"url": "http://localhost:4006/files/lesson-audio/1ea5bb07e0c3f8dff5ca0acd3b352a922afd52c4f0fd85ba5931e29781f61532.mp3", "hash": "5ce96c5f44a0f21f5e0ee5112e5f20998165d65df43c3d73d2a48626c3db046c", "bytes": 78624, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/1ea5bb07e0c3f8dff5ca0acd3b352a922afd52c4f0fd85ba5931e29781f61532.mp3", "duration_ms": 13040}, "s1-match-payments.explanation": {"url": "http://localhost:4006/files/lesson-audio/c46c206b81cb2672baf56fa284474e4a390c97cf3e5df14f7dc0e910e2fc3b1f.mp3", "hash": "4e7209e762a88a9ce742bf0d3f57c42924592b20cd7a66e3eb121963cae6a770", "bytes": 72288, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/c46c206b81cb2672baf56fa284474e4a390c97cf3e5df14f7dc0e910e2fc3b1f.mp3", "duration_ms": 12000}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('98f38e44-71ba-4294-87ea-7a6684eb8359', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "balance-scale", "title": "Balance the trade", "locale": "en-US", "subject": "mixed", "objectives": ["Balance a scale for a fair trade using repeated addition."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-balance", "xp": 15, "type": "balance_scale", "hints": ["First, add up the value of the 3 glasses: 5 + 5 + 5. Then find how many cookies at 3 dollars each you need to equal that sum."], "title": "Balance the scale", "payload": {"weights": [{"id": "galleta-1", "label": "Cookie", "value": 3}, {"id": "galleta-2", "label": "Cookie", "value": 3}, {"id": "galleta-3", "label": "Cookie", "value": 3}, {"id": "galleta-4", "label": "Cookie", "value": 3}, {"id": "galleta-5", "label": "Cookie", "value": 3}, {"id": "galleta-6", "label": "Cookie", "value": 3}], "left_fixed": [{"label": "Glass of lemonade", "value": 5}, {"label": "Glass of lemonade", "value": 5}, {"label": "Glass of lemonade", "value": 5}], "unknown_label": "Cookies"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf put 3 glasses (5 dollars each) on the left. Tap cookies (3 dollars each) to balance the scale.", "difficulty": 2, "explanation_md": "Three glasses at 5 dollars each are worth 15 dollars. Five cookies at 3 dollars each also add up to 15. Fair deal!", "audio_segment_id": "s1-balance.prompt"}], "schema_version": 1}', '{"s1-balance": {}}', '{"units": {"s1-balance.hint.0": {"url": "http://localhost:4006/files/lesson-audio/8ec061e2db875bee497eb681c489eaa4b819b0ea57fcdc20c275ca5e1dacc22b.mp3", "hash": "b8cdaeb7bb7be9ac7a17fd72fa5b6b5cbfc8694907ab0e497a63598ef9876457", "bytes": 52704, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/8ec061e2db875bee497eb681c489eaa4b819b0ea57fcdc20c275ca5e1dacc22b.mp3", "duration_ms": 8720}, "s1-balance.prompt": {"url": "http://localhost:4006/files/lesson-audio/f1eeeecd2de926c31bac1ed39c1950efd879f09b92ba495c83bae4b994dcf900.mp3", "hash": "bbeaa39153af14d16c3102cc475fd2acb3228accea54d0ab44cfc5ad6a8ce52f", "bytes": 39744, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/f1eeeecd2de926c31bac1ed39c1950efd879f09b92ba495c83bae4b994dcf900.mp3", "duration_ms": 6560}, "s1-balance.explanation": {"url": "http://localhost:4006/files/lesson-audio/fb623e8c2127d3e015d2c77815bc150cecf95c3b8bde56a530e0eed9576f6216.mp3", "hash": "ae548c366cd3c2269aa7623b222088ee72d2ba5eaf4c1ebdafc2437dd23089e2", "bytes": 44496, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/fb623e8c2127d3e015d2c77815bc150cecf95c3b8bde56a530e0eed9576f6216.mp3", "duration_ms": 7360}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('cf7bec3a-945e-4d4a-828c-5535f3a7e69c', 'en-US', '1', '{"meta": {"cast": ["rho", "liruf"], "slug": "equation-builder", "title": "Liruf''s tally", "locale": "en-US", "subject": "mixed", "objectives": ["Write exact numerical answers about the day''s sales", "Calculate the total using repeated addition"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-equation", "xp": 10, "type": "equation_builder", "title": "Liruf''s goal", "payload": {"slots": 5, "tokens": [{"id": "t1", "text": "5"}, {"id": "t2", "text": "5"}, {"id": "t3", "text": "5"}, {"id": "t4", "text": "3"}, {"id": "t5", "text": "15"}, {"id": "t6", "text": "+"}, {"id": "t7", "text": "+"}], "target_result": 15}, "narrator": {"emotion": "encouraging", "character": "liruf"}, "prompt_md": "Liruf needs 15 dollars for seeds and sold 3 glasses of lemonade at 5 dollars each. Set up the calculation to see if he collected enough.", "difficulty": 1, "explanation_md": "Each glass costs 5 dollars, so we add 5 three times: 5+5+5=15. That way, it''s just enough for the seeds."}], "schema_version": 1}', '{"s1-equation": {"accepted": ["t1 t6 t2 t7 t3"]}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('cf7bec3a-945e-4d4a-828c-5535f3a7e69c', 'pt-BR', '1', '{"meta": {"cast": ["rho", "liruf"], "slug": "equation-builder", "title": "A conta de Liruf", "locale": "pt-BR", "subject": "mixed", "objectives": ["Escrever respostas numéricas exatas sobre as vendas do dia", "Calcular o total usando somas repetidas"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-equation", "xp": 10, "type": "equation_builder", "title": "A meta de Liruf", "payload": {"slots": 5, "tokens": [{"id": "t1", "text": "5"}, {"id": "t2", "text": "5"}, {"id": "t3", "text": "5"}, {"id": "t4", "text": "3"}, {"id": "t5", "text": "15"}, {"id": "t6", "text": "+"}, {"id": "t7", "text": "+"}], "target_result": 15}, "narrator": {"emotion": "encouraging", "character": "liruf"}, "prompt_md": "Liruf precisa de 15 reais para sementes e vendeu 3 copos de limonada a 5 reais cada um. Arme a conta para ver se juntou o suficiente.", "difficulty": 1, "explanation_md": "Cada copo custa 5 reais, por isso somamos 5 três vezes: 5+5+5=15. Assim dá certinho para as sementes."}], "schema_version": 1}', '{"s1-equation": {"accepted": ["t1 t6 t2 t7 t3"]}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58ff84ee-6d0e-4e43-a182-5b9ffd992543', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "memory-flip", "title": "Stand price memory", "locale": "en-US", "subject": "mixed", "objectives": ["Memory match each product with the coins that pay for it, using stand prices: cookie = 3 (1+2), small cup = 5, large pitcher = 20 (10+10)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-memory-flip", "xp": 15, "type": "memory_flip", "hints": ["Remember: the cookie is worth 3 coins (1+2), the small cup 5, the large pitcher 20 (10+10).", "Look at the amounts: 3, 5, and 20. Which payment goes with each product?"], "title": "Match product with payment", "payload": {"pairs": [{"a_md": "Cookie", "b_md": "1 + 2", "a_icon": "cookie", "b_icon": "monetization_on", "a_image_url": "http://localhost:4006/files/lesson-images/7e08eb104527f9e19b43e6f4c46fde6f687edc06508a674a213c437a2c701052.webp", "b_image_url": "http://localhost:4006/files/lesson-images/be4642343f02c86c2c67d6c39e5d452b401a802d7e8dd9cb49a866df9adcb2ec.webp"}, {"a_md": "Small cup", "b_md": "5", "a_icon": "local_cafe", "b_icon": "monetization_on", "a_image_url": "http://localhost:4006/files/lesson-images/c4981a45d33ffb26545f219cc83c32f909327aab9e0dffe06b21aa4828b8feac.webp", "b_image_url": "http://localhost:4006/files/lesson-images/4b70952218ce50f65e0d567e7cbe1fcbc48e94e4fe72dd0692ba58d7c72c6bf0.webp"}, {"a_md": "Large pitcher", "b_md": "10 + 10", "a_icon": "water_drop", "b_icon": "monetization_on", "a_image_url": "http://localhost:4006/files/lesson-images/73e4853ef3cef5374997f20b8ace852298c49c69573a6c420466638c0e6e57a7.webp", "b_image_url": "http://localhost:4006/files/lesson-images/48ffc037fb87114996c49ded515200c33de8c574e6cd27d72c590bfb17f1f519.webp"}]}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Tap each product and its exact payment. Cookie costs 3, small cup 5, large pitcher 20.", "difficulty": 2, "explanation_md": "The cookie costs 3 dollars (1+2), the small cup 5 dollars, and the large pitcher 20 dollars (10+10). That''s how you matched each product with its exact payment.", "audio_segment_id": "s1-memory-flip.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-memory-flip.hint.0": {"url": "http://localhost:4006/files/lesson-audio/d499e576a02eb2142db979dafa211ee43dc039a6f00c12e0edf4a8e9dd52596d.mp3", "hash": "92e6a3411380cfeb3b997dadc6230dd7827e2db713db8e737454e1b904b59129", "bytes": 57456, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/d499e576a02eb2142db979dafa211ee43dc039a6f00c12e0edf4a8e9dd52596d.mp3", "duration_ms": 9520}, "s1-memory-flip.hint.1": {"url": "http://localhost:4006/files/lesson-audio/30a1c8fb39825acc6441f1b0d3dda40b5a9a9c9af92ab3ea7e384807ff12d369.mp3", "hash": "9a36d8b31a912e32e0c19216bc86fb78e98740cf3c2bda564b4575f426008fe1", "bytes": 34848, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/30a1c8fb39825acc6441f1b0d3dda40b5a9a9c9af92ab3ea7e384807ff12d369.mp3", "duration_ms": 5760}, "s1-memory-flip.prompt": {"url": "http://localhost:4006/files/lesson-audio/21696ca22533451608a1c0dc05049eb6998c0891aeef75f88f7e102767f6b8b6.mp3", "hash": "34788f9152bab3032ba1b39448a2ff9a7816eab6618031423f67d5a347d0d732", "bytes": 47376, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/21696ca22533451608a1c0dc05049eb6998c0891aeef75f88f7e102767f6b8b6.mp3", "duration_ms": 7840}, "s1-memory-flip.explanation": {"url": "http://localhost:4006/files/lesson-audio/0746823a515853eaa883b80a9d305179a25e7b72b58ee2fd92359fe4470085dc.mp3", "hash": "b6d3435560ce22c77b1efdd73c22839266fb68c189ee92932eb464eac8d05f2b", "bytes": 78624, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/0746823a515853eaa883b80a9d305179a25e7b72b58ee2fd92359fe4470085dc.mp3", "duration_ms": 13040}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0754f3ae-1483-4dd4-bc05-e1f681fd5bcf', 'pt-BR', '1', '{"meta": {"cast": ["liruf"], "slug": "combo-narrativa-choice", "title": "O preço do dia", "locale": "pt-BR", "subject": "mixed", "objectives": ["Encadear várias habilidades na mesma lição: ouvir a situação, decidir, calcular e cobrar."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-story-scene", "xp": 0, "type": "story_scene", "title": "Abertura do sábado", "payload": {"art": {"icon": "storefront", "tint": "primary", "image_url": "http://localhost:4006/files/lesson-images/365208bf3c84fce67572809737545abb9808011ef32a8357d154b5a9c082901d.webp"}, "action": "idle", "body_md": "Ontem descobri que a máquina de gorjetas duplica: entra 1 moeda e saem 2. Hoje abro minha barraca e há 20 clientes na fila! Preciso de R$120 para um jogo. Que preço coloco em cada copo?", "emotion": "excited", "backdrop": "band", "character": "liruf"}, "narrator": {"emotion": "excited", "character": "liruf"}, "prompt_md": "É sábado de limonada! Toque para ver a cena.", "difficulty": 1, "audio_segment_id": "s1-story-scene.prompt"}, {"id": "s2-quiz-mcq", "xp": 12, "type": "quiz_mcq", "hints": ["Pense: que número multiplicado por 20 dá 120?"], "title": "Escolha o preço", "payload": {"options": [{"id": "op1", "text_md": "5 reais", "rationale_md": "Com R$5 cada copo, 20 copos dão apenas R$100. Faltariam R$20 para o jogo."}, {"id": "op2", "text_md": "6 reais"}, {"id": "op3", "text_md": "8 reais", "rationale_md": "Com R$8 cada copo, juntaria R$160, muito mais do que precisa. Cobrar a mais pode não ser justo."}], "shuffle": true}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf tem 20 clientes e precisa de R$120 para um jogo. A que preço deve vender cada copo?", "difficulty": 2, "explanation_md": "Se vender 20 copos a R$6 cada um, junta 20 × 6 = R$120 exatos, o que Liruf precisa para o jogo.", "audio_segment_id": "s2-quiz-mcq.prompt"}], "schema_version": 1}', '{"s2-quiz-mcq": {"correct_option_id": "op2"}}', '{"units": {"s2-quiz-mcq.hint.0": {"url": "http://localhost:4006/files/lesson-audio/8ff688dcbccc59a5ff25e35d9ca8fbb2fdcca408e9fe66e1ae64cc2fc38abdff.mp3", "hash": "8cd6c2b93e1c708988d96d8d1eb8c10d5e9f2e76a03144d5e56aa0f1ba12945f", "bytes": 25776, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/8ff688dcbccc59a5ff25e35d9ca8fbb2fdcca408e9fe66e1ae64cc2fc38abdff.mp3", "duration_ms": 4240}, "s2-quiz-mcq.prompt": {"url": "http://localhost:4006/files/lesson-audio/daf001fb1dbcad9104495bfdc66569c875ae3992228b96345f762b1bcd141d27.mp3", "hash": "0866984ebe456d388408398c0ec84adabc41851f8794db1487c870ad6a82d619", "bytes": 48384, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/daf001fb1dbcad9104495bfdc66569c875ae3992228b96345f762b1bcd141d27.mp3", "duration_ms": 8000}, "s1-story-scene.body": {"url": "http://localhost:4006/files/lesson-audio/454c14c0c5aa84664ff3c2c3d3d148038b15174160a767590ab1758dd4173263.mp3", "hash": "345a3da274a131cebdb67bf7fc5b5119e0c9030bd467fb9c1e84a00099e56051", "bytes": 85248, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/454c14c0c5aa84664ff3c2c3d3d148038b15174160a767590ab1758dd4173263.mp3", "duration_ms": 14160}, "s2-quiz-mcq.choices": {"url": "http://localhost:4006/files/lesson-audio/b9275e1f6643fa84791dbc5cbf49235834f96710ca6577cb9e476031d1edac64.mp3", "hash": "abea89ae777b2ba3d51eb5f774a637af274fee0e50c32c5ed2d05d0ae8807927", "bytes": 24336, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/b9275e1f6643fa84791dbc5cbf49235834f96710ca6577cb9e476031d1edac64.mp3", "duration_ms": 4000}, "s1-story-scene.prompt": {"url": "http://localhost:4006/files/lesson-audio/03b90a776678ed8ba4539e4f59e41dc677bf05e3da38979630bd29b3e9bc5ea1.mp3", "hash": "297a040d1f2da69a16dac7f69c14662e971764cbafa5ff4187df4a7405fbde36", "bytes": 21456, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/03b90a776678ed8ba4539e4f59e41dc677bf05e3da38979630bd29b3e9bc5ea1.mp3", "duration_ms": 3520}, "s2-quiz-mcq.explanation": {"url": "http://localhost:4006/files/lesson-audio/2108f0ba1d44fc90075c51fa91bf1979ca262c6b9d52e40b05de0457d837baa2.mp3", "hash": "da87f064ab2b59e2d93693935754cd0f56e2fdae15a43bb51cceaf11b70e65ec", "bytes": 57456, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/2108f0ba1d44fc90075c51fa91bf1979ca262c6b9d52e40b05de0457d837baa2.mp3", "duration_ms": 9520}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7d51bf02-4dd4-4263-9e53-aa5ccb8a1e03', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "interest-peek", "title": "O cofrinho que agradece a paciência", "locale": "pt-BR", "subject": "money", "objectives": ["Decidir se deixar dinheiro em um cofrinho que dá moedinhas extras toda semana vale mais do que gastá-lo agora.", "Prever o total depois de esperar, entendendo que cresce um pouco, mas não dobra."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-interest-peek", "xp": 10, "type": "interest_peek", "hints": ["Cada semana o cofrinho dá 2 moedas de 1 real. Quantas moedas extras ele dá em 2 semanas?", "Começa com 20. Soma as moedinhas extras."], "title": "Deixar os 20 ou tirá-los agora?", "payload": {"periods": 2, "currency": "MXN", "rate_pct": 10, "principal": 20, "prediction": {"kind": "choice", "options": [{"id": "opt1", "text_md": "Fica em 20"}, {"id": "opt2", "text_md": "24 reais"}, {"id": "opt3", "text_md": "Quase 40 reais"}]}}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf tem 20 reais guardados para um violão que custa 80. Rho diz: ''Se você guardar seu dinheiro neste cofrinho especial, toda semana ele te dá 2 moedas de 1 real extra por deixá-lo lá.'' Liruf coloca seus 20 reais. Ele pensa: ''Se eu esperar 2 semanas, terei mais ou menos do que se gastar tudo agora?'' Quanto Liruf terá depois de 2 semanas?", "difficulty": 1, "explanation_md": "O cofrinho dá 2 moedas de 1 real por semana, então em 2 semanas dá 4 reais extras. 20 + 4 = 24. O dinheiro cresce pouquinho a pouquinho em direção ao violão! Se tivesse gasto tudo agora, não teria esses 4 reais extras.", "audio_segment_id": "s1-interest-peek.prompt"}], "schema_version": 1}', '{"s1-interest-peek": {"value": 24, "tolerance": 1, "correct_option_id": "opt2"}}', '{"units": {"s1-interest-peek.hint.0": {"url": "http://localhost:4006/files/lesson-audio/15c8d42a81e76e915fe3887eff8a429983acd363dc96705d1e4ec0e628271e2c.mp3", "hash": "196538f34b2819eb47de5903748f77e7b49d10d4e2c8ca5d7ae70a964f276120", "bytes": 41184, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/15c8d42a81e76e915fe3887eff8a429983acd363dc96705d1e4ec0e628271e2c.mp3", "duration_ms": 6800}, "s1-interest-peek.hint.1": {"url": "http://localhost:4006/files/lesson-audio/94246887ec011f654238fff79533392c4fa267c9a6a7176754cf81c2c0fba8f2.mp3", "hash": "68205f29a78766e858fb87c5bed3698e0edd3e76f3e3815689d9c9fdf3bf0983", "bytes": 21024, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/94246887ec011f654238fff79533392c4fa267c9a6a7176754cf81c2c0fba8f2.mp3", "duration_ms": 3440}, "s1-interest-peek.prompt": {"url": "http://localhost:4006/files/lesson-audio/8d2446827b5dfe079ef7c4af2f81ab70d70f224adcc231c88e5428650ba17a0e.mp3", "hash": "a49d13c1d700898ab76f3de6d66edef95a7a3fc75e1a1d6b73c925bba2331ffd", "bytes": 152064, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/8d2446827b5dfe079ef7c4af2f81ab70d70f224adcc231c88e5428650ba17a0e.mp3", "duration_ms": 25280}, "s1-interest-peek.explanation": {"url": "http://localhost:4006/files/lesson-audio/502978ab8beb65b2716a40ddd32d3108471507f848c1584c75807ed5a8039f28.mp3", "hash": "10d7c733f96ddee36b970195711bac0efc7e1d2b84b73366148a2065d5f44a1a", "bytes": 110736, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/502978ab8beb65b2716a40ddd32d3108471507f848c1584c75807ed5a8039f28.mp3", "duration_ms": 18400}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f75b3e23-fb31-40cf-9b58-e918769e51b9', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "yes-no-cases", "title": "Say yes or no, case by case", "locale": "en-US", "subject": "mixed", "objectives": ["Say yes or no, case by case: does this expense help the stand? (more lemons: yes; a new toy today: no, not yet)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-yes-no-cases", "xp": 10, "type": "yes_no_cases", "hints": ["Think: does this help sell more lemonade or save the money?", "An expense that helps the stand is something you need to make or sell lemonade."], "title": "Yes or no?", "payload": {"cases": [{"id": "c1", "text_md": "Buying more lemons to make more lemonade.", "image_url": "http://localhost:4006/files/lesson-images/09da691b033011955582e525b75686f4f51e3a91ea6b6cca2c1a41e089abe682.webp"}, {"id": "c2", "text_md": "Buying a new toy at the store.", "image_url": "http://localhost:4006/files/lesson-images/5817df14613008ff1165939218f4bc96207549a68917dc18a3f503e9f203757b.webp"}, {"id": "c3", "text_md": "Buying a nice sign for the stand.", "image_url": "http://localhost:4006/files/lesson-images/fcaea50216e433445c9f0bd20de7522f570e0b711b5a2ece5aa8a7e2e553b551.webp"}, {"id": "c4", "text_md": "Buying candy for yourself.", "image_url": "http://localhost:4006/files/lesson-images/355464f038e0288601d6bdff1d1798f9c4f938b4e96eaf499cdd3675f4041c54.webp"}], "rule_md": "Say **yes** if the expense helps the lemonade stand (more lemons, a sign, a new pitcher). Say **no** if it''s something you don''t need today (a toy, a video game, candy)."}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf has his list. Tap each case: does this expense help the lemonade stand?", "difficulty": 1, "explanation_md": "Buying more lemons helps make more lemonade and sell more. A new toy does not help the stand today.", "audio_segment_id": "s1-yes-no-cases.prompt"}], "schema_version": 1}', '{"s1-yes-no-cases": {"applies_ids": ["c1", "c3"]}}', '{"units": {"s1-yes-no-cases.hint.0": {"url": "http://localhost:4006/files/lesson-audio/7c5e422ab80c78a97c4f38a0e37808e586ac861afb83eb27088f349486bbd4d8.mp3", "hash": "9ee2df9329dd1e63de47bcc09d2b7ca5eb1855aee9a528fe69ca14718457f696", "bytes": 21024, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/7c5e422ab80c78a97c4f38a0e37808e586ac861afb83eb27088f349486bbd4d8.mp3", "duration_ms": 3440}, "s1-yes-no-cases.hint.1": {"url": "http://localhost:4006/files/lesson-audio/4e20d0dcdcc7eb0dab16c3fe0221e32adb33341bb337cdb8492ab0009770ac22.mp3", "hash": "c4c1fa4484e4d51c437e3d2296dd18209f66a8b3c66952e08599b6f614a9af28", "bytes": 23328, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/4e20d0dcdcc7eb0dab16c3fe0221e32adb33341bb337cdb8492ab0009770ac22.mp3", "duration_ms": 3840}, "s1-yes-no-cases.prompt": {"url": "http://localhost:4006/files/lesson-audio/9404d06c36508956978e05c1bfabfec722f3c387ba385281191fbd480ac5259d.mp3", "hash": "292eee2d8eabd16b34e9fdbe5e8b19236c19cc1b1c6b77efe0f05335654c8fb4", "bytes": 28224, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/9404d06c36508956978e05c1bfabfec722f3c387ba385281191fbd480ac5259d.mp3", "duration_ms": 4640}, "s1-yes-no-cases.choices": {"url": "http://localhost:4006/files/lesson-audio/eb1471b56aacc9e4bfb3749c1b933d6d8f0497d9314680aa4fb1a3a34b139c6a.mp3", "hash": "c9558917f1719198eaa2fa29aa428700f7609495eed8108e02788021c77d886c", "bytes": 42048, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/eb1471b56aacc9e4bfb3749c1b933d6d8f0497d9314680aa4fb1a3a34b139c6a.mp3", "duration_ms": 6960}, "s1-yes-no-cases.explanation": {"url": "http://localhost:4006/files/lesson-audio/88fadbe5bc6153edf42afffac86f36ada28fcd8a039efdc486ea3d551e5be7a4.mp3", "hash": "32bea1abbecbe3e34651e61bd897100820b8ae432fcb8ea51b472f121f5dc76c", "bytes": 32976, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/88fadbe5bc6153edf42afffac86f36ada28fcd8a039efdc486ea3d551e5be7a4.mp3", "duration_ms": 5440}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8ee4aa69-44e4-4d40-9cde-af0d59cc6b99', 'en-US', '1', '{"meta": {"cast": ["dina", "zara", "liruf"], "slug": "true-false", "title": "True or false: savings grow", "locale": "en-US", "subject": "mixed", "objectives": ["Decide if it''s true or false: ''If I save 5 dollars from each sale, my savings GROW every day.''"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-true-false", "xp": 10, "type": "true_false", "hints": ["Think: if you save 5 dollars each day, do you have more or less than the day before?", "Savings is what you''ve accumulated. If you add money each day, what happens to the total?"], "title": "True or false?", "payload": {"statement_md": "If I save 5 dollars from each sale, my savings GROW every day.", "justifications": [{"id": "cierto", "text_md": "It''s true, because each day I add 5 dollars, so the total is always larger."}, {"id": "falso", "text_md": "It''s false, because sometimes I spend the savings and it doesn''t grow."}]}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Zara says: ''If I save 5 dollars from each sale, my savings GROW every day.'' Is it true or false?", "difficulty": 1, "explanation_md": "It''s true. If you save 5 dollars each day, your total savings always increases. For example, on Monday you have 5, on Tuesday 10, on Wednesday 15… it grows every day!", "audio_segment_id": "s1-true-false.prompt"}], "schema_version": 1}', '{"s1-true-false": {"is_true": true, "correct_justification_id": "cierto"}}', '{"units": {"s1-true-false.hint.0": {"url": "http://localhost:4006/files/lesson-audio/62d90a12448eb1a1e23bcb5110d85db6a6d66848b19606e86b557e13986aa960.mp3", "hash": "04df0cd95072888cda3f41041534e8145a560361a78dc893d77afc8f00b1c83f", "bytes": 37296, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/62d90a12448eb1a1e23bcb5110d85db6a6d66848b19606e86b557e13986aa960.mp3", "duration_ms": 6160}, "s1-true-false.hint.1": {"url": "http://localhost:4006/files/lesson-audio/9c36801accdc663906928dcfb8409cf5b897cab4c98dfd02768866f756b89b7e.mp3", "hash": "02743248e26ca89a89ab31af8aedf653fb78d308eda23485b37630aa7b8fb33e", "bytes": 34848, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/9c36801accdc663906928dcfb8409cf5b897cab4c98dfd02768866f756b89b7e.mp3", "duration_ms": 5760}, "s1-true-false.prompt": {"url": "http://localhost:4006/files/lesson-audio/ee37b6497f7e2743dfa9e3b087469a2e7808a440cb49eb208b3ab02ceb386e6d.mp3", "hash": "0e9fbc143d88e32484443533d5fcfe4629df696fe13825dd86c7ffaae5d620a0", "bytes": 48384, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/ee37b6497f7e2743dfa9e3b087469a2e7808a440cb49eb208b3ab02ceb386e6d.mp3", "duration_ms": 8000}, "s1-true-false.explanation": {"url": "http://localhost:4006/files/lesson-audio/7c5b80613d29d04c068e040d3459ff7b7a2da0b6b3c90b5bbad0834edcb5963e.mp3", "hash": "d65daa52d92986669b1b64c9d0493d4b9499a2c08c55ffd0175c5867a674fe24", "bytes": 80496, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/7c5b80613d29d04c068e040d3459ff7b7a2da0b6b3c90b5bbad0834edcb5963e.mp3", "duration_ms": 13360}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a0b48602-bbeb-4aac-8309-90ec3cdeba90', 'pt-BR', '1', '{"meta": {"cast": ["rho"], "slug": "number-line", "title": "Na reta da poupança", "locale": "pt-BR", "subject": "mixed", "objectives": ["Localizar poupanças e metas em uma reta numérica para visualizar o progresso."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-number-line", "xp": 5, "type": "number_line", "title": "Quanto falta?", "payload": {"max": 100, "min": 0, "ticks": 10, "labels": false}, "narrator": {"emotion": "encouraging", "character": "rho"}, "prompt_md": "Liruf tem 20 reais poupados. Toque na reta onde está 20.", "difficulty": 1, "explanation_md": "Sua poupança está em 20. A meta de 80 reais está mais adiante. Faltam 60 reais."}], "schema_version": 1}', '{"s1-number-line": {"value": 20, "full_credit_delta": 0, "zero_credit_delta": 10}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7f76a2de-27d1-4660-8203-c9ddad8fb861', 'en-US', '1', '{"meta": {"cast": ["zara"], "slug": "estimate-slider", "title": "Estimate glasses of lemonade", "locale": "en-US", "subject": "mixed", "objectives": ["Estimate amounts using a slider bar", "Develop number sense by estimating before counting"], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-estimate-slider", "xp": 10, "type": "estimate_slider", "hints": ["Think of a medium pitcher: not too small and not too big.", "If each glass is 5 dollars, the pitcher won''t make 100 glasses or just 1."], "title": "How many glasses come out?", "payload": {"max": 20, "min": 1, "step": 1, "unit": "vasos", "scale": "linear"}, "narrator": {"emotion": "thinking", "character": "zara"}, "image_url": "http://localhost:4006/files/lesson-images/b4fea712674e789663c57746d67ecbf115155cc1f3ba649f0161761b85ebd060.webp", "prompt_md": "Zara filled the pitcher. Without counting, slide to estimate: how many 5-dollar glasses do you think come out of this pitcher?", "difficulty": 1, "explanation_md": "The pitcher has room for about 8 glasses. Zara estimated well by thinking of a number neither too small nor too big.", "audio_segment_id": "s1-estimate-slider.prompt"}], "schema_version": 1}', '{"s1-estimate-slider": {"value": 8, "full_credit_delta": 2, "zero_credit_delta": 5}}', '{"units": {"s1-estimate-slider.hint.0": {"url": "http://localhost:4006/files/lesson-audio/47729452e2ebcb4d958200a05d1e3631766e976d0d96b2ecb1a08b5064078535.mp3", "hash": "da6b1aef97ee158c9e4d4468a014e5b44ddec28147504aeaf90c738d3dea6bbe", "bytes": 23328, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/47729452e2ebcb4d958200a05d1e3631766e976d0d96b2ecb1a08b5064078535.mp3", "duration_ms": 3840}, "s1-estimate-slider.hint.1": {"url": "http://localhost:4006/files/lesson-audio/679e330cd618dc9f8a9f63c42e5f516ad2acf726e210cc9a00ac2814686b4aed.mp3", "hash": "fa3b80a0e9ba29e8038dd57ceccdf5b8a1459b2af5e864127d489d3efbe9323b", "bytes": 34416, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/679e330cd618dc9f8a9f63c42e5f516ad2acf726e210cc9a00ac2814686b4aed.mp3", "duration_ms": 5680}, "s1-estimate-slider.prompt": {"url": "http://localhost:4006/files/lesson-audio/7f35340a2a12f6f65c427711367433633afe647a162b2369a60f3a64bf766f32.mp3", "hash": "2de852af61373031c53ca6e6199b74d509c3c476a5b0276f527406d55265f4f2", "bytes": 51264, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/7f35340a2a12f6f65c427711367433633afe647a162b2369a60f3a64bf766f32.mp3", "duration_ms": 8480}, "s1-estimate-slider.explanation": {"url": "http://localhost:4006/files/lesson-audio/da523c888a8332af0b9d2c354429289141c4fee20b34d3ebe3b00f18989ea219.mp3", "hash": "49e254808272f41ac8f061d31022eca5458e2fccdf3230ade5674f4708904e69", "bytes": 47376, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/da523c888a8332af0b9d2c354429289141c4fee20b34d3ebe3b00f18989ea219.mp3", "duration_ms": 7840}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8d0292b9-0597-4d9c-8b65-84f2fd19b142', 'es-MX', '1', '{"meta": {"cast": ["liruf"], "slug": "red-flags", "title": "Señales de alerta", "locale": "es-MX", "subject": "mixed", "objectives": ["Identificar señales de alerta en ofertas que parecen demasiado buenas para ser verdad."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "red-flags-1", "xp": 15, "type": "red_flags", "hints": [], "title": "Detecta las señales", "payload": {"flags": [{"id": "f1", "text_md": "Ven al parque mañana a las 3."}, {"id": "f2", "text_md": "Invierte 20 pesos hoy y mañana recibirás 100 pesos."}, {"id": "f3", "text_md": "Pregunta por Don Mago."}, {"id": "f4", "text_md": "Es solo por hoy, ¡aprovéchala ya!"}, {"id": "f5", "text_md": "No le cuentes a tus papás, es nuestro secreto."}], "artifact_md": "¡Oferta mágica! Ven al parque mañana a las 3. Invierte 20 pesos hoy y mañana recibirás 100 pesos. Pregunta por Don Mago. Es solo por hoy, ¡aprovéchala ya! No le cuentes a tus papás, es nuestro secreto.", "artifact_kind": "ad"}, "narrator": {"emotion": "neutral", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/901dfc2284558107050b8919f27a66ddba5a567be95fd2ac3fdbaa690f03f968.webp", "prompt_md": "Después de revisar el recibo del mercado, Liruf se encontró con un volante sospechoso. Toca las frases que son señales de alerta.", "difficulty": 2, "explanation_md": "Las ofertas que prometen ganancias demasiado altas en muy poco tiempo, como 100 pesos por solo 20, suelen ser engaños. Cuando un desconocido te pide que lo mantengas en secreto, ¡algo no está bien!"}], "schema_version": 1}', '{"red-flags-1": {"redflag_ids": ["f2", "f4", "f5"]}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8ee4aa69-44e4-4d40-9cde-af0d59cc6b99', 'pt-BR', '1', '{"meta": {"cast": ["dina", "zara", "liruf"], "slug": "true-false", "title": "Certo ou falso: a poupança cresce", "locale": "pt-BR", "subject": "mixed", "objectives": ["Decidir se é certo ou falso: ''Se eu guardar 5 reais de cada venda, minha poupança CRESCE a cada dia''."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-true-false", "xp": 10, "type": "true_false", "hints": ["Pense: se a cada dia você guarda 5 reais, você tem mais ou menos do que no dia anterior?", "A poupança é o que você juntou. Se a cada dia você adiciona dinheiro, o que acontece com o total?"], "title": "Certo ou falso?", "payload": {"statement_md": "Se eu guardar 5 reais de cada venda, minha poupança CRESCE a cada dia.", "justifications": [{"id": "cierto", "text_md": "É certo, porque a cada dia eu adiciono 5 reais, então o total sempre é maior."}, {"id": "falso", "text_md": "É falso, porque às vezes eu gasto a poupança e ela não cresce."}]}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Zara diz: ''Se eu guardar 5 reais de cada venda, minha poupança CRESCE a cada dia''. É certo ou falso?", "difficulty": 1, "explanation_md": "É certo. Se você guarda 5 reais a cada dia, o total da sua poupança sempre aumenta. Por exemplo, na segunda você tem 5, na terça 10, na quarta 15… cresce a cada dia!", "audio_segment_id": "s1-true-false.prompt"}], "schema_version": 1}', '{"s1-true-false": {"is_true": true, "correct_justification_id": "cierto"}}', '{"units": {"s1-true-false.hint.0": {"url": "http://localhost:4006/files/lesson-audio/4276561554145aca49c9af04765faf91b16e35c581e9ecece251c777efab967b.mp3", "hash": "6578bb8c515af8532991e8e825dcd542165ce7082cc5cfb4ca85c98690762c90", "bytes": 38736, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/4276561554145aca49c9af04765faf91b16e35c581e9ecece251c777efab967b.mp3", "duration_ms": 6400}, "s1-true-false.hint.1": {"url": "http://localhost:4006/files/lesson-audio/a127fa4e9ac17088a9236a50fe52baa99cbdaaaa61e152c5ba4eb72a0028681e.mp3", "hash": "71520a51f8c11de4a1a995f87ae7c180544f58438d128abac276a22ed474f95b", "bytes": 39744, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/a127fa4e9ac17088a9236a50fe52baa99cbdaaaa61e152c5ba4eb72a0028681e.mp3", "duration_ms": 6560}, "s1-true-false.prompt": {"url": "http://localhost:4006/files/lesson-audio/f3a515780d89944db2f748c3668cb160813890c015c54e6074aa598767932aec.mp3", "hash": "09636b0bd473f7be309cc57c5eb2d08ab41bac205d2f9acf14ad9a80b5d66f4e", "bytes": 48384, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/f3a515780d89944db2f748c3668cb160813890c015c54e6074aa598767932aec.mp3", "duration_ms": 8000}, "s1-true-false.explanation": {"url": "http://localhost:4006/files/lesson-audio/340e977143a129da124e104a83fc336032cebcb7476ff6e9814be8da44f222c8.mp3", "hash": "c925e1c5198e1e9efa66891b46ae356c248d746259b28b0c54119369a856c8da", "bytes": 77184, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/340e977143a129da124e104a83fc336032cebcb7476ff6e9814be8da44f222c8.mp3", "duration_ms": 12800}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c3cd699b-431a-4c74-8563-19360a968d77', 'es-MX', '1', '{"meta": {"cast": ["liruf"], "slug": "debug-hunt", "title": "El cartel confuso", "locale": "es-MX", "subject": "mixed", "objectives": ["Encontrar el error en el cartel de promoción y corregirlo."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-debug", "xp": 10, "type": "debug_hunt", "title": "El cartel confuso", "payload": {"blocks": [{"id": "b1", "text_md": "Promoción de Limonada"}, {"id": "b2", "text_md": "1 vaso: 5 pesos"}, {"id": "b3", "text_md": "2 vasos por 8 pesos"}, {"id": "b4", "text_md": "¡sale más caro que comprarlos sueltos!"}, {"id": "b5", "text_md": "En el puesto de Liruf"}], "intro_md": "Liruf puso un cartel de promoción, pero algo no cuadra. Un cliente se quejó: ''¡Tu oferta es más cara que comprar dos vasos sueltos!'' Revisa el cartel."}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Toca el bloque del cartel que tiene el error.", "difficulty": 1, "explanation_md": "El bloque ''sale más caro'' está equivocado: 2 vasos por 8 pesos cuesta 4 cada uno, mientras que 1 vaso suelto cuesta 5. ¡Es más barato! Liruf puede cambiar el texto a ''¡sale más barato!''"}], "schema_version": 1}', '{"s1-debug": {"fix_md": "Cambia el texto ''sale más caro'' a ''sale más barato'', porque 2 vasos por 8 pesos es más barato que comprar dos vasos sueltos (10 pesos).", "bug_ids": ["b4"]}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1b29b755-c45e-46e4-a8d8-25624cad27a3', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-arrange-largo", "title": "Cerrando el puesto de limonada", "locale": "es-MX", "subject": "mixed", "objectives": ["Emparejar pagos con el cambio correcto", "Ordenar los pasos para calcular la ganancia", "Distinguir necesidades de deseos para el puesto", "Planificar el día para mantener cambio en la caja"], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-payments", "xp": 15, "type": "match_pairs", "title": "Empareja pagos y cambio", "payload": {"left": [{"id": "p10", "text_md": "Pago con 10 pesos", "image_url": "http://localhost:4006/files/lesson-images/a3aae884c1d4b53554aecfc17122b031aa3956334d2332949f86f84b6bf1ea5f.webp"}, {"id": "p20", "text_md": "Pago con 20 pesos", "image_url": "http://localhost:4006/files/lesson-images/63488eaa21b571c729f54ccae2d360afd3747c1914921cbc4f015e5f530434aa.webp"}, {"id": "p6", "text_md": "Pago con 6 pesos", "image_url": "http://localhost:4006/files/lesson-images/ebaf5ec5f08d789a7b5a1acf240d5626d64a267746fc74f64c0283eac738add6.webp"}], "right": [{"id": "c5", "text_md": "5 pesos"}, {"id": "c15", "text_md": "15 pesos"}, {"id": "c1", "text_md": "1 peso"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Cada vaso cuesta 5 pesos. Toca un pago y luego el cambio correcto.", "difficulty": 2, "explanation_md": "El cambio es lo que sobra: 10 - 5 = 5 pesos, 20 - 5 = 15 pesos, y 6 - 5 = 1 peso. Liruf siempre debe dar el cambio exacto.", "audio_segment_id": "s1-match-payments.prompt"}, {"id": "s2-order-profit", "xp": 25, "type": "order_steps", "hints": ["Piensa: ¿qué necesitas saber primero para calcular la ganancia?", "Primero cuenta todo el dinero, luego aparta lo que gastaste en ingredientes."], "title": "Ordena la ganancia", "payload": {"items": [{"id": "s1", "text_md": "Contar todo el dinero de la caja", "image_url": "http://localhost:4006/files/lesson-images/7afe2ee317cad97aac423dec81850c57735f0ccd232742d10fab998c09eadfe3.webp"}, {"id": "s2", "text_md": "Apartar el costo de los ingredientes (limones, vasos, azúcar)", "image_url": "http://localhost:4006/files/lesson-images/59d31f77c6325fd8efcdc2617a3f1c054b30e0685e8631df169b345d90b2bb5c.webp"}, {"id": "s3", "text_md": "El dinero que queda es la ganancia", "image_url": "http://localhost:4006/files/lesson-images/96cddd491db875cf37497a299d8a608ef42137281a27cc6f61886b30ba329e03.webp"}, {"id": "d1", "text_md": "Gastar la ganancia en un juguete", "image_url": "http://localhost:4006/files/lesson-images/ac61c79ff60480fc6543808738c9180f94a9e8a4922867a826c26f1ae995ed27.webp"}], "slots": 3}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Ayuda a Liruf a ordenar los pasos para saber su ganancia. Sobra uno que no va.", "difficulty": 3, "explanation_md": "Para saber la ganancia, primero cuentas TODO el dinero, luego apartas el costo de los ingredientes; lo que sobra es la ganancia. Por ejemplo, si juntó 30 pesos y gastó 20 en ingredientes, su ganancia es 10 pesos.", "audio_segment_id": "s2-order-profit.prompt"}, {"id": "s3-sort-needs", "xp": 15, "type": "sort_buckets", "title": "¿Necesario o puede esperar?", "payload": {"items": [{"id": "limones", "text_md": "Limones", "image_url": "http://localhost:4006/files/lesson-images/33be3f6c14b1830061ab6b48315abab67dabb919a0da14d9bf09dcd15449c7a3.webp"}, {"id": "vasos", "text_md": "Vasos", "image_url": "http://localhost:4006/files/lesson-images/f3d3d73c5b0ba756803fc723d3be20810e0e25dfc5fa38a28a31b418db756e13.webp"}, {"id": "hielo", "text_md": "Hielo", "image_url": "http://localhost:4006/files/lesson-images/1903b5e1638e0c644764ffa240790fc313ac55c8f92b9eaa3bde3a4aa0203855.webp"}, {"id": "calcomania", "text_md": "Calcomanía", "image_url": "http://localhost:4006/files/lesson-images/de9aa792eb53e20fbf71b7c618d0edfe130428b36eac9d2379e5cb01b9123993.webp"}], "buckets": [{"id": "necesario", "label": "Necesario para abrir"}, {"id": "esperar", "label": "Puede esperar"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf solo tiene 20 pesos. Toca cada cosa y ponla en ''Necesario'' si sin eso no vende, o en ''Puede esperar''.", "difficulty": 2, "explanation_md": "Para vender limonada, Liruf necesita limones y vasos. El hielo y la calcomanía pueden esperar hasta que tenga más dinero.", "audio_segment_id": "s3-sort-needs.prompt"}, {"id": "s4-timeline-day", "xp": 30, "type": "timeline_order", "hints": ["¿Qué necesitas tener antes de gastar? Dinero en la caja.", "Primero asegura tener cambio, luego vende, luego gasta un poco, y repite."], "title": "Orden del día", "payload": {"events": [{"id": "e1", "icon": "savings", "text_md": "Sacar el cambio inicial (20 pesos)", "image_url": "http://localhost:4006/files/lesson-images/3e4697ba3001a7896447599ac50e6add1c17ef4048fd21056ce217b6e09e4f9c.webp"}, {"id": "e2", "icon": "payments", "text_md": "Vender un vaso de limonada", "image_url": "http://localhost:4006/files/lesson-images/e532d8f8b4b1c2971d530bd0a44ed162764ad57c7a64fbf3235aee1ffc11f1f5.webp"}, {"id": "e3", "icon": "ac_unit", "text_md": "Comprar hielo (3 pesos)", "image_url": "http://localhost:4006/files/lesson-images/5073bbb7482a2c29c66aab6e71b6faec45759fcdfb8628d4fef540ad1d3259fa.webp"}, {"id": "e4", "icon": "shopping_cart_checkout", "text_md": "Vender dos vasos de limonada", "image_url": "http://localhost:4006/files/lesson-images/f02cf741b8285238e260b20cff47e12b565930985c58b1e8210d5bd7f2aa4690.webp"}, {"id": "e5", "icon": "agriculture", "text_md": "Comprar limones (8 pesos)", "image_url": "http://localhost:4006/files/lesson-images/eb015228c0f0a3ea7c8c862a489f3a3786b759917b0df2a5a571db8472a4befe.webp"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Ordena las tarjetas para que Liruf nunca se quede sin cambio en la caja.", "difficulty": 3, "explanation_md": "Liruf debe tener dinero en la caja antes de gastar. Primero saca cambio, luego vende, después compra algo pequeño, vuelve a vender y por último compra otro insumo.", "audio_segment_id": "s4-timeline-day.prompt"}], "schema_version": 1}', '{"s3-sort-needs": {"assignments": {"hielo": "esperar", "vasos": "necesario", "limones": "necesario", "calcomania": "esperar"}}, "s2-order-profit": {"order": ["s1", "s2", "s3"]}, "s4-timeline-day": {"order": ["e1", "e2", "e3", "e4", "e5"]}, "s1-match-payments": {"pairs": [["p10", "c5"], ["p20", "c15"], ["p6", "c1"]]}}', '{"units": {"s3-sort-needs.prompt": {"url": "http://localhost:4006/files/lesson-audio/a0ec08c6898d1cf1013ea1fe5160bd20a1c0a7f184f06294bfd8182d64c57d85.mp3", "hash": "9efab17c18c9c5d748118e8de72b7dbedd09bd46a021f1a69df85c458b3dadc1", "bytes": 52128, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/a0ec08c6898d1cf1013ea1fe5160bd20a1c0a7f184f06294bfd8182d64c57d85.mp3", "duration_ms": 8640}, "s2-order-profit.hint.0": {"url": "http://localhost:4006/files/lesson-audio/2d0522135588357fc39a7041f5d5077ec83a3cd21b779be2b2c34e4e7bd755dd.mp3", "hash": "d65c5bfd9e587b96d21941cce69a0cde29d6a2e569165b5034d712f62a57aeea", "bytes": 26208, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/2d0522135588357fc39a7041f5d5077ec83a3cd21b779be2b2c34e4e7bd755dd.mp3", "duration_ms": 4320}, "s2-order-profit.hint.1": {"url": "http://localhost:4006/files/lesson-audio/c8e2085153c3686e44debbeca19a949b425f6900a6a20ff48b2e5a5c59064b80.mp3", "hash": "3f8392a2e85707497f65c97e3d032aa91d3aadc857f3207fa943e73ca1c6bbb1", "bytes": 27648, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/c8e2085153c3686e44debbeca19a949b425f6900a6a20ff48b2e5a5c59064b80.mp3", "duration_ms": 4560}, "s2-order-profit.prompt": {"url": "http://localhost:4006/files/lesson-audio/602a9660ceb7bf7762b8a46f4610ab34a8c7d68faa6e9393ac334d78efa48e56.mp3", "hash": "c0630e0f0d6315039e4660c6edaec5c0c84befc3577b02d604de82c6783019c9", "bytes": 33984, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/602a9660ceb7bf7762b8a46f4610ab34a8c7d68faa6e9393ac334d78efa48e56.mp3", "duration_ms": 5600}, "s4-timeline-day.hint.0": {"url": "http://localhost:4006/files/lesson-audio/66169089421a33dd4ccde0ecf6006f2437d26b80a94f9e05316dd08302e229c9.mp3", "hash": "9607fcbebed33fd62dbbec0487b17c6507e36b22bbabd7da334991580fba29ea", "bytes": 27648, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/66169089421a33dd4ccde0ecf6006f2437d26b80a94f9e05316dd08302e229c9.mp3", "duration_ms": 4560}, "s4-timeline-day.hint.1": {"url": "http://localhost:4006/files/lesson-audio/6c6eec524e4472230e87416fb6762af31097ef1f0c2fc980527a1780593f3a0e.mp3", "hash": "e84224bac62ea63ff8756a7c7925704697250ac45238da52f527a8da16f8c098", "bytes": 35856, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/6c6eec524e4472230e87416fb6762af31097ef1f0c2fc980527a1780593f3a0e.mp3", "duration_ms": 5920}, "s4-timeline-day.prompt": {"url": "http://localhost:4006/files/lesson-audio/20eefaaa5537a8741548478671c87f41de638e72090f63af1068d8277deeadd6.mp3", "hash": "a58836ba12e0b1c093f9e9ee95b62dcae2e1f834ed08dd48e87c8260f4343798", "bytes": 26208, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/20eefaaa5537a8741548478671c87f41de638e72090f63af1068d8277deeadd6.mp3", "duration_ms": 4320}, "s1-match-payments.prompt": {"url": "http://localhost:4006/files/lesson-audio/8dab55f2c4d3b16b678b7e06b267be4fa2dd6e3fd5eaf5992418059b99edbfeb.mp3", "hash": "b4b4b9812d29e2cca7be593aa3942a82b367a27e53e88b2f4196ed4df623b5d9", "bytes": 32544, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/8dab55f2c4d3b16b678b7e06b267be4fa2dd6e3fd5eaf5992418059b99edbfeb.mp3", "duration_ms": 5360}, "s3-sort-needs.explanation": {"url": "http://localhost:4006/files/lesson-audio/337aff609fbdd9cd1650b37ccfaa2d31b6397f89fa3526cec001da2780abd377.mp3", "hash": "0d0be3c9385222854a27a6ff503b30ee396748ef341c203f4316dfd6ee8fe708", "bytes": 52704, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/337aff609fbdd9cd1650b37ccfaa2d31b6397f89fa3526cec001da2780abd377.mp3", "duration_ms": 8720}, "s2-order-profit.explanation": {"url": "http://localhost:4006/files/lesson-audio/2dfbfe5467a9e1dae1630f97d3973e563c6cd69d37b3ff301b62d0bcd6ab6039.mp3", "hash": "0e52642ed2862ce8734d41f19eebd41fef527cf3db0a9fce17fd13ce6a77c5c8", "bytes": 90576, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/2dfbfe5467a9e1dae1630f97d3973e563c6cd69d37b3ff301b62d0bcd6ab6039.mp3", "duration_ms": 15040}, "s4-timeline-day.explanation": {"url": "http://localhost:4006/files/lesson-audio/b3039f856b64d5f317119eb6da035c50e252307385bd34c44b0ec6b7ca5aa2bb.mp3", "hash": "826ec1e42ab44dd07f2bfda9813b76ac61f134ff668524f0547fa5997bca235e", "bytes": 71424, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/b3039f856b64d5f317119eb6da035c50e252307385bd34c44b0ec6b7ca5aa2bb.mp3", "duration_ms": 11840}, "s1-match-payments.explanation": {"url": "http://localhost:4006/files/lesson-audio/6cac03caad2841faaecb581be09f7139a6a2d8cbb33c29a4680c588724148f03.mp3", "hash": "5fdb1c008b2a8a0cc709b16dde628b47efe4aac64f7cc1c165ef88814b9d0fc1", "bytes": 75744, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/6cac03caad2841faaecb581be09f7139a6a2d8cbb33c29a4680c588724148f03.mp3", "duration_ms": 12560}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c3cd699b-431a-4c74-8563-19360a968d77', 'en-US', '1', '{"meta": {"cast": ["liruf"], "slug": "debug-hunt", "title": "The Confusing Sign", "locale": "en-US", "subject": "mixed", "objectives": ["Find the mistake on the promotional sign and correct it."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-debug", "xp": 10, "type": "debug_hunt", "title": "The Confusing Sign", "payload": {"blocks": [{"id": "b1", "text_md": "Lemonade Promotion"}, {"id": "b2", "text_md": "1 cup: 5 dollars"}, {"id": "b3", "text_md": "2 cups for 8 dollars"}, {"id": "b4", "text_md": "It''s more expensive than buying them separately!"}, {"id": "b5", "text_md": "At Liruf''s stand"}], "intro_md": "Liruf put up a promotional sign, but something doesn''t add up. A customer complained: ''Your offer is more expensive than buying two cups separately!'' Check the sign."}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Tap the block on the sign that has the mistake.", "difficulty": 1, "explanation_md": "The ''more expensive'' block is wrong: 2 cups for 8 dollars costs 4 dollars each, while 1 single cup costs 5 dollars. It''s cheaper! Liruf can change the text to ''It''s cheaper!''"}], "schema_version": 1}', '{"s1-debug": {"fix_md": "Cambia el texto ''sale más caro'' a ''sale más barato'', porque 2 vasos por 8 pesos es más barato que comprar dos vasos sueltos (10 pesos).", "bug_ids": ["b4"]}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1b29b755-c45e-46e4-a8d8-25624cad27a3', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-arrange-largo", "title": "Closing the lemonade stand", "locale": "en-US", "subject": "mixed", "objectives": ["Matching payments with the correct change", "Sorting the steps to calculate profit", "Distinguishing needs from wants for the stand", "Planning the day to keep change in the cash register"], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-payments", "xp": 15, "type": "match_pairs", "title": "Match payments and change", "payload": {"left": [{"id": "p10", "text_md": "Payment with 10 dollars", "image_url": "http://localhost:4006/files/lesson-images/391db331c96bb92badfdd4167e740ec52e8372abe62986750d6ba2edebe3ea73.webp"}, {"id": "p20", "text_md": "Payment with 20 dollars", "image_url": "http://localhost:4006/files/lesson-images/9774a8b39835d40e5e94975de704f59d5a99903167c53044778d18fed1faa182.webp"}, {"id": "p6", "text_md": "Payment with 6 dollars", "image_url": "http://localhost:4006/files/lesson-images/a1acb9f7abcb34f7e4e4c82de4d070b9fa3ab714ea4ab59d7bfa79ddf67113b0.webp"}], "right": [{"id": "c5", "text_md": "5 dollars"}, {"id": "c15", "text_md": "15 dollars"}, {"id": "c1", "text_md": "1 dollar"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Each glass costs 5 dollars. Tap a payment and then the correct change.", "difficulty": 2, "explanation_md": "Change is what''s left over: 10 - 5 = 5 dollars, 20 - 5 = 15 dollars, and 6 - 5 = 1 dollar. Liruf must always give exact change.", "audio_segment_id": "s1-match-payments.prompt"}, {"id": "s2-order-profit", "xp": 25, "type": "order_steps", "hints": ["Think: what do you need to know first to calculate profit?", "First count all the money, then set aside what you spent on ingredients."], "title": "Sort the profit", "payload": {"items": [{"id": "s1", "text_md": "Count all the money in the cash register", "image_url": "http://localhost:4006/files/lesson-images/76bb1db5bd71163c7fd8a67f65adfac696dad4a29b99a7a4d3b5f92ca5161791.webp"}, {"id": "s2", "text_md": "Set aside the cost of ingredients (lemons, cups, sugar)", "image_url": "http://localhost:4006/files/lesson-images/370ce739e294531a9a512b63a8cca454f184997aca77a50c385fbd85b744cb92.webp"}, {"id": "s3", "text_md": "The money left over is profit", "image_url": "http://localhost:4006/files/lesson-images/cf8b184553860313f5b7b2ba2d9c2d4555bd961120573da13ca1575c22de8c94.webp"}, {"id": "d1", "text_md": "Spend the profit on a toy", "image_url": "http://localhost:4006/files/lesson-images/69ff21347c9172d197c363a9cb9bafe8ca690c0d2e625ca08809defe6b8621cb.webp"}], "slots": 3}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Help Liruf sort the steps to find out his profit. One step doesn''t belong.", "difficulty": 3, "explanation_md": "To find out profit, first you count ALL the money, then set aside the cost of ingredients; what''s left is profit. For example, if he collected 30 dollars and spent 20 on ingredients, his profit is 10 dollars.", "audio_segment_id": "s2-order-profit.prompt"}, {"id": "s3-sort-needs", "xp": 15, "type": "sort_buckets", "title": "Necessary or can wait?", "payload": {"items": [{"id": "limones", "text_md": "Lemons", "image_url": "http://localhost:4006/files/lesson-images/9294665dea482646474b603f1b530f7b8f0c1abac2e8d9c415164ddb0bd2e280.webp"}, {"id": "vasos", "text_md": "Cups", "image_url": "http://localhost:4006/files/lesson-images/1288c2db07d55a29d5592321e86fb4f97a515cead837498912a4992d65ebce30.webp"}, {"id": "hielo", "text_md": "Ice", "image_url": "http://localhost:4006/files/lesson-images/079fe4c45486930698f7cbd414675550421372cafc22e7f0097fa59a4ddbc260.webp"}, {"id": "calcomania", "text_md": "Sticker", "image_url": "http://localhost:4006/files/lesson-images/10be55e79482f1848d8972d8d20dbc386701492490bfbac24fc1e683ec74ce36.webp"}], "buckets": [{"id": "necesario", "label": "Necessary to open"}, {"id": "esperar", "label": "Can wait"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf only has 20 dollars. Tap each item and put it in ''Necessary'' if without it he can''t sell, or in ''Can wait''.", "difficulty": 2, "explanation_md": "To sell lemonade, Liruf needs lemons and cups. The ice and the sticker can wait until he has more money.", "audio_segment_id": "s3-sort-needs.prompt"}, {"id": "s4-timeline-day", "xp": 30, "type": "timeline_order", "hints": ["What do you need to have before spending? Money in the cash register.", "First make sure to have change, then sell, then spend a little, and repeat."], "title": "Order of the day", "payload": {"events": [{"id": "e1", "icon": "savings", "text_md": "Get the initial change (20 dollars)", "image_url": "http://localhost:4006/files/lesson-images/b0f5b31444370665aea7749d06c160001622d92766a6af0608bce62fc028c82e.webp"}, {"id": "e2", "icon": "payments", "text_md": "Sell a glass of lemonade", "image_url": "http://localhost:4006/files/lesson-images/44f95c1a3ea2230c9c53ce97321655fe20185a9520b6bbdf4c3d41606c541e66.webp"}, {"id": "e3", "icon": "ac_unit", "text_md": "Buy ice (3 dollars)", "image_url": "http://localhost:4006/files/lesson-images/6bed4f74473a9b56fc8c871f63216b8cec36d7a4bd2042bc081aa74248acfec4.webp"}, {"id": "e4", "icon": "shopping_cart_checkout", "text_md": "Sell two glasses of lemonade", "image_url": "http://localhost:4006/files/lesson-images/fbaab5f6c93b9fffe7a0ea8a9cd8eac7b2b9d4742a7ac6790a35002c1dd2db99.webp"}, {"id": "e5", "icon": "agriculture", "text_md": "Buy lemons (8 dollars)", "image_url": "http://localhost:4006/files/lesson-images/5f814964d050c4814cc20c3cd2998db452f6eaf35ae45c54511601de066b22c9.webp"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Sort the cards so Liruf never runs out of change in the cash register.", "difficulty": 3, "explanation_md": "Liruf must have money in the cash register before spending. First get change, then sell, then buy something small, sell again, and finally buy another supply.", "audio_segment_id": "s4-timeline-day.prompt"}], "schema_version": 1}', '{"s3-sort-needs": {"assignments": {"hielo": "esperar", "vasos": "necesario", "limones": "necesario", "calcomania": "esperar"}}, "s2-order-profit": {"order": ["s1", "s2", "s3"]}, "s4-timeline-day": {"order": ["e1", "e2", "e3", "e4", "e5"]}, "s1-match-payments": {"pairs": [["p10", "c5"], ["p20", "c15"], ["p6", "c1"]]}}', '{"units": {"s3-sort-needs.prompt": {"url": "http://localhost:4006/files/lesson-audio/6a796f43c177fac747d2b65080538bd66da44742e0494ba0dc30fa6f04e311de.mp3", "hash": "12196324caddf97cac319bca8e1c8e6cc29d1e95f3ecc5cd61da9189e9101abf", "bytes": 46944, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/6a796f43c177fac747d2b65080538bd66da44742e0494ba0dc30fa6f04e311de.mp3", "duration_ms": 7760}, "s2-order-profit.hint.0": {"url": "http://localhost:4006/files/lesson-audio/fa5f82d154cc7352e89e3c8b93090b7c332e76b0d0382fee539d49d9c2bca69e.mp3", "hash": "2eeb9de3d6b37672ce713fc63ee0373cbefe337f6990d33f3619d809f6fc48e1", "bytes": 19008, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/fa5f82d154cc7352e89e3c8b93090b7c332e76b0d0382fee539d49d9c2bca69e.mp3", "duration_ms": 3120}, "s2-order-profit.hint.1": {"url": "http://localhost:4006/files/lesson-audio/619522c0796e9c368a648eecab2096a9f1392bfee24850d6cf9845e9a523931d.mp3", "hash": "951200137852dde3bd463877a7f154ffaac43dbe28fc8ba3c461e9a099628a65", "bytes": 22896, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/619522c0796e9c368a648eecab2096a9f1392bfee24850d6cf9845e9a523931d.mp3", "duration_ms": 3760}, "s2-order-profit.prompt": {"url": "http://localhost:4006/files/lesson-audio/8bad99f2cdadfcf315e3ebfc4d507eebba3c5547548680c88de8765acd114b10.mp3", "hash": "1a36ac20b90b3ac7c34f75355956fbfd5b38ebe3fbdd43ca9b40c370b87629c9", "bytes": 24336, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/8bad99f2cdadfcf315e3ebfc4d507eebba3c5547548680c88de8765acd114b10.mp3", "duration_ms": 4000}, "s4-timeline-day.hint.0": {"url": "http://localhost:4006/files/lesson-audio/03de39fc1d0b299b832d9c72ad21c16f918703f3735434acbe9fc69ad87aba45.mp3", "hash": "8b2df869bfcacbb7b857f9f5c4432a9f62c524d681c6e7e171229eba43770a86", "bytes": 22464, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/03de39fc1d0b299b832d9c72ad21c16f918703f3735434acbe9fc69ad87aba45.mp3", "duration_ms": 3680}, "s4-timeline-day.hint.1": {"url": "http://localhost:4006/files/lesson-audio/6b6b485b92108551424bb1e98619e63e4ac6111e0c791e6f52d18063b2290d78.mp3", "hash": "12a476ea80d6cd7f562871ad4e9acb5ab6775a87ea338eafa965b442862d34e8", "bytes": 27216, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/6b6b485b92108551424bb1e98619e63e4ac6111e0c791e6f52d18063b2290d78.mp3", "duration_ms": 4480}, "s4-timeline-day.prompt": {"url": "http://localhost:4006/files/lesson-audio/05b5794c5b21b571af8041962966f15589c4db5260ee00b4547e7405334bf608.mp3", "hash": "af2b26c4b5e2ee1dc47ca59610e8c84970baadd2dbde123b1b2b8619d46e5e80", "bytes": 23904, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/05b5794c5b21b571af8041962966f15589c4db5260ee00b4547e7405334bf608.mp3", "duration_ms": 3920}, "s1-match-payments.prompt": {"url": "http://localhost:4006/files/lesson-audio/f1d802e908198194d513f5a781d505e9a00afec10b9709b3a9410c1c1c30efa1.mp3", "hash": "1a0c07433d21b79da630b4dd5f88fe6a0d674f33d585c6e69294435389b2d0d7", "bytes": 27648, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/f1d802e908198194d513f5a781d505e9a00afec10b9709b3a9410c1c1c30efa1.mp3", "duration_ms": 4560}, "s3-sort-needs.explanation": {"url": "http://localhost:4006/files/lesson-audio/fd17cec9d4e7a98ed1fc2440ad7a1fa5b1cb7fdf922750b5de93e00cb82d1ac4.mp3", "hash": "68a3dfda06d73333508cdfa662235e1021bd616daf88bf7135b48be60cf7789d", "bytes": 37296, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/fd17cec9d4e7a98ed1fc2440ad7a1fa5b1cb7fdf922750b5de93e00cb82d1ac4.mp3", "duration_ms": 6160}, "s2-order-profit.explanation": {"url": "http://localhost:4006/files/lesson-audio/a423887a9b323b0f1a23d9d36133c885dd2a78f83ab4d54e9f17e0d311d647b1.mp3", "hash": "f1acb41c8e169708a95eb0fa2c6af92a3a730d4fdea77cc3358ff2e69402a448", "bytes": 72288, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/a423887a9b323b0f1a23d9d36133c885dd2a78f83ab4d54e9f17e0d311d647b1.mp3", "duration_ms": 12000}, "s4-timeline-day.explanation": {"url": "http://localhost:4006/files/lesson-audio/4a56ca8fd390263330726dc2c21686d8b3264eeb9f5630de458e0404f5d941b2.mp3", "hash": "472e76ac31ae774d8e17ad27cc1e1e3f31633861621ebf7db7d65d6fee0af1f0", "bytes": 51264, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/4a56ca8fd390263330726dc2c21686d8b3264eeb9f5630de458e0404f5d941b2.mp3", "duration_ms": 8480}, "s1-match-payments.explanation": {"url": "http://localhost:4006/files/lesson-audio/82de2bc64321aba8542e54d4bdb26aed7c8023d10d1e1229f6f9c8ee5b26fd5a.mp3", "hash": "a0443a1c8d0e6f9967b6d8ccf000e543ee190efc8d7c0ba6a3450cb33140ae38", "bytes": 71856, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/82de2bc64321aba8542e54d4bdb26aed7c8023d10d1e1229f6f9c8ee5b26fd5a.mp3", "duration_ms": 11920}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8d0292b9-0597-4d9c-8b65-84f2fd19b142', 'en-US', '1', '{"meta": {"cast": ["liruf"], "slug": "red-flags", "title": "Warning signs", "locale": "en-US", "subject": "mixed", "objectives": ["Identify warning signs in offers that seem too good to be true."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "red-flags-1", "xp": 15, "type": "red_flags", "hints": [], "title": "Spot the signs", "payload": {"flags": [{"id": "f1", "text_md": "Come to the park tomorrow at 3."}, {"id": "f2", "text_md": "Invest 20 dollars today and tomorrow you''ll receive 100 dollars."}, {"id": "f3", "text_md": "Ask for Mr. Wizard."}, {"id": "f4", "text_md": "It''s only for today, take advantage now!"}, {"id": "f5", "text_md": "Don''t tell your parents, it''s our secret."}], "artifact_md": "Magical offer! Come to the park tomorrow at 3. Invest 20 dollars today and tomorrow you''ll receive 100 dollars. Ask for Mr. Wizard. It''s only for today, take advantage now! Don''t tell your parents, it''s our secret.", "artifact_kind": "ad"}, "narrator": {"emotion": "neutral", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/ac7ce4ac0bf19a4d194a5e776e8856ee36ad41a9accf24c4fbf3e81b0d7cc8fc.webp", "prompt_md": "After reviewing the market receipt, Liruf found a suspicious flyer. Tap the phrases that are warning signs.", "difficulty": 2, "explanation_md": "Offers that promise very high returns in a very short time, like 100 dollars for just 20, are usually scams. When a stranger asks you to keep it a secret, something is not right!"}], "schema_version": 1}', '{"red-flags-1": {"redflag_ids": ["f2", "f4", "f5"]}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9b315200-00f0-4dc4-a2cd-13c1fb40e9aa', 'en-US', '1', '{"meta": {"cast": ["zara", "liruf"], "slug": "build-sentence", "title": "The combo sign", "locale": "en-US", "subject": "mixed", "objectives": ["Calculate the price of a combo (2×5 dollars) and make the stand''s sign."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 85, "hint_penalty_pct": 10}, "segments": [{"id": "s1-build-sign", "xp": 15, "type": "build_sentence", "hints": ["Think: if one glass costs 5 dollars, how much do two glasses cost?"], "title": "The combo sign", "payload": {"slots": 5, "tokens": [{"id": "t1", "text_md": "2"}, {"id": "t2", "text_md": "glasses"}, {"id": "t3", "text_md": "for"}, {"id": "t4", "text_md": "5"}, {"id": "t5", "text_md": "10"}, {"id": "t6", "text_md": "15"}, {"id": "t7", "text_md": "20"}, {"id": "t8", "text_md": "dollars"}]}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "Liruf wants to sell a combo: 2 glasses of lemonade. Each glass costs 5 dollars. Make the sign with the words and the total price.", "difficulty": 2, "explanation_md": "The sign says ''2 glasses for 10 dollars'' because 5 + 5 = 10. If you put 5, you''d charge for only one glass; with 15 or 20, the price would be too high and customers wouldn''t buy."}], "schema_version": 1}', '{"s1-build-sign": {"order": ["t1", "t2", "t3", "t5", "t8"]}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('bd130a62-6800-475b-8af6-59f14ffebc50', 'es-MX', '1', '{"meta": {"cast": ["liruf"], "slug": "number-input", "title": "Calcular las ventas de Liruf", "locale": "es-MX", "subject": "mixed", "objectives": ["Calcular y escribir cuánto ganó Liruf en total si vendió 4 vasos a 5 pesos cada uno (20 pesos)."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-calculate-total", "xp": 15, "type": "number_input", "hints": ["Piensa: cada vaso cuesta 5 pesos y Liruf vendió 4 vasos.", "Multiplica el número de vasos por el precio de cada uno: 4 × 5 = ?"], "title": "¿Cuánto ganó Liruf?", "payload": {"unit": "pesos", "decimals_hint": 0}, "narrator": {"emotion": "happy", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/965d2782cf47d4cdffa0b43ab7dea3361052e116182f5503ae8fa60eb240b2c2.webp", "prompt_md": "Liruf vendió 4 vasos de limonada a 5 pesos cada uno. ¿Cuánto dinero ganó en total?", "difficulty": 2, "explanation_md": "Liruf vendió 4 vasos a 5 pesos cada uno, así que juntó 4 veces 5 pesos. 4 × 5 = 20. Ganó 20 pesos en total.", "audio_segment_id": "s1-calculate-total.prompt"}], "schema_version": 1}', '{"s1-calculate-total": {"value": 20, "tolerance": 0}}', '{"units": {"s1-calculate-total.hint.0": {"url": "http://localhost:4006/files/lesson-audio/f4bbcbe3e73138007926e096cebdd6d68cb20010e84ae11693b2bece22f2037a.mp3", "hash": "11959d2d183367044443346f830a2d9f0f7e76982b7aaf1de4c8bf0acf777f62", "bytes": 31968, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/f4bbcbe3e73138007926e096cebdd6d68cb20010e84ae11693b2bece22f2037a.mp3", "duration_ms": 5280}, "s1-calculate-total.hint.1": {"url": "http://localhost:4006/files/lesson-audio/802ef568ec241923ad676ab36c93f5daf6909e64e449ff8a2176769bdff1b26a.mp3", "hash": "aa416397de9b4743afaacfe733167fe02a337c04a1ba5b74af662a42312f51d5", "bytes": 33984, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/802ef568ec241923ad676ab36c93f5daf6909e64e449ff8a2176769bdff1b26a.mp3", "duration_ms": 5600}, "s1-calculate-total.prompt": {"url": "http://localhost:4006/files/lesson-audio/ce15fc194a645982ef4c6ddc18f0f0cb292d88e0fceb93629259cada1ed4f73f.mp3", "hash": "8aea5349625da39db18273d18b1da037b7def70b803e161219f621dd52bcca38", "bytes": 42624, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/ce15fc194a645982ef4c6ddc18f0f0cb292d88e0fceb93629259cada1ed4f73f.mp3", "duration_ms": 7040}, "s1-calculate-total.explanation": {"url": "http://localhost:4006/files/lesson-audio/0b6b367383b22232f44d699fd9f5a661ec61e641d8917f86bc3a74d978fbe7a0.mp3", "hash": "45fca5472634d3195db9b788d410bd9a12d0373e55396372c61717cbe8a64a6b", "bytes": 69984, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/0b6b367383b22232f44d699fd9f5a661ec61e641d8917f86bc3a74d978fbe7a0.mp3", "duration_ms": 11600}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('59260361-67d7-4d0e-9c68-8c5e00637103', 'es-MX', '1', '{"meta": {"cast": ["liruf"], "slug": "price-compare", "title": "Comparar precios de limones", "locale": "es-MX", "subject": "mixed", "objectives": ["Comparar precios de limones en dos puestos y elegir el más barato para gastar menos (costo más bajo = más ganancia)."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-price-compare", "xp": 5, "type": "price_compare", "hints": ["Mira cuántos pesos cuesta cada oferta y elige la más barata."], "title": "¡Limones más baratos!", "payload": {"offers": [{"id": "puesto-a", "qty": 6, "unit": "limones", "label": "Limones Puesto A", "price": 10, "image_url": "http://localhost:4006/files/lesson-images/83e7fa26fb37d64d32c3c9b2aa6429943176e19b486a5e9ccb344eefa67bb0c8.webp"}, {"id": "puesto-b", "qty": 6, "unit": "limones", "label": "Limones Puesto B", "price": 12, "image_url": "http://localhost:4006/files/lesson-images/a26fbfcb4d0c97e975c3a0c4372aad859d6f8ab438a8978191a6cef2fb72fa29.webp"}], "currency": "MXN"}, "narrator": {"emotion": "encouraging", "character": "liruf"}, "prompt_md": "Después de separar necesidades, dos puestos venden limones. Toca la oferta que gasta menos dinero.", "difficulty": 1, "explanation_md": "Los limones del Puesto A cuestan 10 pesos, menos que los 12 pesos del Puesto B. Elegir la más barata deja más dinero para la meta de la guitarra.", "audio_segment_id": "s1-price-compare.prompt"}], "schema_version": 1}', '{"s1-price-compare": {"best_offer_id": "puesto-a"}}', '{"units": {"s1-price-compare.hint.0": {"url": "http://localhost:4006/files/lesson-audio/60789fc2467c3f5b953d3989a0c643b59cf9cb8cecd2166ca924ea50e00e4499.mp3", "hash": "3ffedb14cb5d35d3a92e04dce0611a0687b0443f27f5811737e4cf69543ae446", "bytes": 27216, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/60789fc2467c3f5b953d3989a0c643b59cf9cb8cecd2166ca924ea50e00e4499.mp3", "duration_ms": 4480}, "s1-price-compare.prompt": {"url": "http://localhost:4006/files/lesson-audio/55b18f86391642a79f07435386cb6e0df0116ff9f0356def463cf97b41912248.mp3", "hash": "9b38699e69847833b33a4be0fc7bdcd2a0b54f9a0e4145e865bc414495aa81b2", "bytes": 42048, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/55b18f86391642a79f07435386cb6e0df0116ff9f0356def463cf97b41912248.mp3", "duration_ms": 6960}, "s1-price-compare.explanation": {"url": "http://localhost:4006/files/lesson-audio/150eccbcaec82d3d94aa808b747a59fa6015fa7ff52fa8adfce4cd96f564a06e.mp3", "hash": "6210af39f7811c171daecc43f688131536d6314406e858d7c5cbfaa7bc35530e", "bytes": 64224, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/150eccbcaec82d3d94aa808b747a59fa6015fa7ff52fa8adfce4cd96f564a06e.mp3", "duration_ms": 10640}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c3cd699b-431a-4c74-8563-19360a968d77', 'pt-BR', '1', '{"meta": {"cast": ["liruf"], "slug": "debug-hunt", "title": "O cartaz confuso", "locale": "pt-BR", "subject": "mixed", "objectives": ["Encontrar o erro no cartaz de promoção e corrigi-lo."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-debug", "xp": 10, "type": "debug_hunt", "title": "O cartaz confuso", "payload": {"blocks": [{"id": "b1", "text_md": "Promoção de Limonada"}, {"id": "b2", "text_md": "1 copo: 5 reais"}, {"id": "b3", "text_md": "2 copos por 8 reais"}, {"id": "b4", "text_md": "¡sai mais caro que comprá-los avulsos!"}, {"id": "b5", "text_md": "Na barraca de Liruf"}], "intro_md": "Liruf colocou um cartaz de promoção, mas algo não bate. Um cliente reclamou: ''Sua oferta é mais cara do que comprar dois copos avulsos!'' Revise o cartaz."}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Toque o bloco do cartaz que tem o erro.", "difficulty": 1, "explanation_md": "O bloco ''sai mais caro'' está errado: 2 copos por 8 reais custa 4 cada um, enquanto 1 copo avulso custa 5. É mais barato! Liruf pode mudar o texto para ''sai mais barato!''"}], "schema_version": 1}', '{"s1-debug": {"fix_md": "Cambia el texto ''sale más caro'' a ''sale más barato'', porque 2 vasos por 8 pesos es más barato que comprar dos vasos sueltos (10 pesos).", "bug_ids": ["b4"]}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('59260361-67d7-4d0e-9c68-8c5e00637103', 'en-US', '1', '{"meta": {"cast": ["liruf"], "slug": "price-compare", "title": "Compare prices of lemons", "locale": "en-US", "subject": "mixed", "objectives": ["Compare prices of lemons at two stalls and choose the cheapest to spend less (lower cost = more profit)."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-price-compare", "xp": 5, "type": "price_compare", "hints": ["See how many dollars each offer costs and choose the cheapest."], "title": "Cheaper lemons!", "payload": {"offers": [{"id": "puesto-a", "qty": 6, "unit": "limones", "label": "Stall A lemons", "price": 10, "image_url": "http://localhost:4006/files/lesson-images/b1a64753edd3fc8ca780884a20a619f4a88c468213c94ed0eedf88f0bef1df38.webp"}, {"id": "puesto-b", "qty": 6, "unit": "limones", "label": "Stall B lemons", "price": 12, "image_url": "http://localhost:4006/files/lesson-images/074ef954c38ead9e7a7c6b6114b7325a9edd92ee53e0031449759c2c3769ca91.webp"}], "currency": "USD"}, "narrator": {"emotion": "encouraging", "character": "liruf"}, "prompt_md": "After separating needs, two stalls sell lemons. Tap the offer that costs less.", "difficulty": 1, "explanation_md": "The lemons from Stall A cost 10 dollars, less than the 12 dollars from Stall B. Choosing the cheapest leaves more money for the guitar goal.", "audio_segment_id": "s1-price-compare.prompt"}], "schema_version": 1}', '{"s1-price-compare": {"best_offer_id": "puesto-a"}}', '{"units": {"s1-price-compare.hint.0": {"url": "http://localhost:4006/files/lesson-audio/080c70613d1bf4acf77b88599af5df7e230d87af292374093df494623f84a914.mp3", "hash": "cae96cd082a2468ba04d28dc007d08b1b21c70e7879d6cbdce72e6f7ab4c1a56", "bytes": 24336, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/080c70613d1bf4acf77b88599af5df7e230d87af292374093df494623f84a914.mp3", "duration_ms": 4000}, "s1-price-compare.prompt": {"url": "http://localhost:4006/files/lesson-audio/35db2ae9da584b94fff9790091bd8aea1966fdb646edd80a268e5860c3d91983.mp3", "hash": "c9b7242c051431e13e4d3b212c3c09521ea190b00c8c9ff8f1fc9f7663446b66", "bytes": 31536, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/35db2ae9da584b94fff9790091bd8aea1966fdb646edd80a268e5860c3d91983.mp3", "duration_ms": 5200}, "s1-price-compare.explanation": {"url": "http://localhost:4006/files/lesson-audio/b7a902e86d4f2c782e881ab46e03e4a4a500bfd8350ea2d08e3ce10ac2bf8692.mp3", "hash": "36105ca36cac7637bcccdff2b26f23869753124cb365877e00960d3c56e95953", "bytes": 50688, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/b7a902e86d4f2c782e881ab46e03e4a4a500bfd8350ea2d08e3ce10ac2bf8692.mp3", "duration_ms": 8400}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9bdad6a7-ed32-42f2-83c9-554afe044403', 'en-US', '1', '{"meta": {"cast": ["liruf", "rho"], "slug": "savings-goal", "title": "Savings goal: Liruf''s guitar", "locale": "en-US", "subject": "mixed", "objectives": ["Calculate how many weeks are needed to reach a savings goal by dividing the total cost by the weekly savings", "Compare different savings plans to reach a goal within a set timeframe"], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-guitar-savings", "xp": 15, "type": "savings_goal", "hints": ["Divide 80 dollars by the amount you save each week.", "For example, if you save 10 dollars, how many times does 10 fit into 80?"], "title": "Liruf''s savings plan", "payload": {"goal": 80, "currency": "USD", "weekly_options": [10, 20, 40]}, "narrator": {"emotion": "happy", "character": "rho"}, "prompt_md": "Liruf wants the 80-dollar guitar. How many weeks does he need if he saves 10, 20, or 40 dollars per week?", "difficulty": 2, "explanation_md": "Saving more each week shortens the wait. With 40 dollars, Liruf gets the guitar in 2 weeks, just in time for the contest.", "audio_segment_id": "s1-guitar-savings.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-guitar-savings.hint.0": {"url": "http://localhost:4006/files/lesson-audio/cbf4c6e5bb2fcf78f8f424287525f24f7c336168997601fbe055e57135c537b9.mp3", "hash": "300de059a685106ef9a3741d44e48957ca58aed95748b5460746eb3192e99766", "bytes": 21456, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/cbf4c6e5bb2fcf78f8f424287525f24f7c336168997601fbe055e57135c537b9.mp3", "duration_ms": 3520}, "s1-guitar-savings.hint.1": {"url": "http://localhost:4006/files/lesson-audio/74ce6a42b3ce4f99fe8525d8db3c29aac8eda639adae6f91de1445561449cbdf.mp3", "hash": "0583c377dba670b0be074dc16a4b1834326ebaf20db24110181d5722bb60fff8", "bytes": 34848, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/74ce6a42b3ce4f99fe8525d8db3c29aac8eda639adae6f91de1445561449cbdf.mp3", "duration_ms": 5760}, "s1-guitar-savings.prompt": {"url": "http://localhost:4006/files/lesson-audio/15bd11e154fa6356fdc3a3c35af2612aafab21970bf181ed6f9d482c2ad82ed1.mp3", "hash": "3dea2b16af9d9d2b7bb5640cbc0fd067af1c425b0064118dfd7cc700c991ee88", "bytes": 49248, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/15bd11e154fa6356fdc3a3c35af2612aafab21970bf181ed6f9d482c2ad82ed1.mp3", "duration_ms": 8160}, "s1-guitar-savings.explanation": {"url": "http://localhost:4006/files/lesson-audio/5344d3a6d289c3ef6ca1debe156b2ffec94826a3e1ad7013da48a15bfd3521c1.mp3", "hash": "38eedd9de974a993c7feefbea5651f597d8a3661523327e1bd718db15f4bf778", "bytes": 56448, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/5344d3a6d289c3ef6ca1debe156b2ffec94826a3e1ad7013da48a15bfd3521c1.mp3", "duration_ms": 9360}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8d0292b9-0597-4d9c-8b65-84f2fd19b142', 'pt-BR', '1', '{"meta": {"cast": ["liruf"], "slug": "red-flags", "title": "Sinais de alerta", "locale": "pt-BR", "subject": "mixed", "objectives": ["Identificar sinais de alerta em ofertas que parecem boas demais para ser verdade."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "red-flags-1", "xp": 15, "type": "red_flags", "hints": [], "title": "Detecte os sinais", "payload": {"flags": [{"id": "f1", "text_md": "Venha ao parque amanhã às 3."}, {"id": "f2", "text_md": "Invista 20 reais hoje e amanhã receberá 100 reais."}, {"id": "f3", "text_md": "Pergunte pelo Sr. Mago."}, {"id": "f4", "text_md": "É só por hoje, aproveite já!"}, {"id": "f5", "text_md": "Não conte para seus pais, é nosso segredo."}], "artifact_md": "Oferta mágica! Venha ao parque amanhã às 3. Invista 20 reais hoje e amanhã receberá 100 reais. Pergunte pelo Sr. Mago. É só por hoje, aproveite já! Não conte para seus pais, é nosso segredo.", "artifact_kind": "ad"}, "narrator": {"emotion": "neutral", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/17db420912a1e4bae73362330df7136cdd585ee6504dee11d20425112e364f96.webp", "prompt_md": "Após revisar o recibo do mercado, Liruf encontrou um folheto suspeito. Toque nas frases que são sinais de alerta.", "difficulty": 2, "explanation_md": "As ofertas que prometem ganhos altos demais em muito pouco tempo, como 100 reais por apenas 20, costumam ser enganos. Quando um desconhecido pede para você manter segredo, algo não está certo!"}], "schema_version": 1}', '{"red-flags-1": {"redflag_ids": ["f2", "f4", "f5"]}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5bcbf28d-86a2-47d1-9003-23897d9d4f57', 'es-MX', '1', '{"meta": {"cast": ["zara"], "slug": "group-sets", "title": "Separa el dinero", "locale": "es-MX", "subject": "mixed", "objectives": ["Agrupar monedas y billetes para contarlos más fácilmente."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "grouping-money", "xp": 10, "type": "group_sets", "hints": ["Observa la forma: las monedas son redondas, los billetes son rectangulares."], "title": "Separa el dinero", "payload": {"items": [{"id": "coin1", "text_md": "Moneda de $1", "image_url": "http://localhost:4006/files/lesson-images/24c7efa8981c991d0be8e71c3bc49384cbe5bf4f9e19484395858cf8099db360.webp"}, {"id": "coin5", "text_md": "Moneda de $5", "image_url": "http://localhost:4006/files/lesson-images/03cc6e0694a4118a84dbc2e3d8adb52b169d455da6f3b041e362438d3dacdd33.webp"}, {"id": "coin10", "text_md": "Moneda de $10", "image_url": "http://localhost:4006/files/lesson-images/fc06ff3e39eae041923f7a7ec66bcce213b01fb77cde417f3ab6036ef548ad42.webp"}, {"id": "bill20", "text_md": "Billete de $20"}, {"id": "bill50", "text_md": "Billete de $50"}], "set_a": "Monedas", "set_b": "Billetes"}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "Después de vender limonada, la caja está revuelta. Para contarla rápido, separa las monedas de los billetes.", "difficulty": 1, "explanation_md": "Agrupar por tipo facilita contar el dinero. Así sabes cuánto tienes en monedas y cuánto en billetes.", "audio_segment_id": "grouping-money.prompt"}], "schema_version": 1}', '{"grouping-money": {"zones": {"coin1": "a", "coin5": "a", "bill20": "b", "bill50": "b", "coin10": "a"}}}', '{"units": {"grouping-money.hint.0": {"url": "http://localhost:4006/files/lesson-audio/848e61f89e54a9fc4c1782fabd90ae853d82df59ccbf9fc637601f936602d48f.mp3", "hash": "fc4ddd271531157697bce52a90bb65e1ea9ca1ba39d9bf193c3a5c3329308a69", "bytes": 30096, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/848e61f89e54a9fc4c1782fabd90ae853d82df59ccbf9fc637601f936602d48f.mp3", "duration_ms": 4960}, "grouping-money.prompt": {"url": "http://localhost:4006/files/lesson-audio/da1a0b0c8a3aff9c087d7d13b96a7289afa44b7ba7c39bf6d35992a3b6daaeba.mp3", "hash": "82142e874d5f8c7b27703db02a65805e93689a0132bab42a902398e8648b84d5", "bytes": 42048, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/da1a0b0c8a3aff9c087d7d13b96a7289afa44b7ba7c39bf6d35992a3b6daaeba.mp3", "duration_ms": 6960}, "grouping-money.explanation": {"url": "http://localhost:4006/files/lesson-audio/4224a272a194fdb4d876351f17f978b4413dd7f0cde4f03de6d219d5a9cf9efc.mp3", "hash": "ba7b6461706091627997a684bc1acdb2c70a43e642227e1e51638f296d21ecb3", "bytes": 38304, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/4224a272a194fdb4d876351f17f978b4413dd7f0cde4f03de6d219d5a9cf9efc.mp3", "duration_ms": 6320}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b979bce6-8935-480e-8471-33053faa2321', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "sort-buckets", "title": "Clasifica las compras del puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Clasificar compras en necesidades del puesto y gustos que pueden esperar"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-clasifica", "xp": 10, "type": "sort_buckets", "hints": ["Necesidad es lo que el puesto necesita para vender limonada: limones, vasos, hielo.", "Gusto es algo que te gusta pero no es urgente: stickers, globos, juguetes."], "title": "Necesidad o gusto", "payload": {"items": [{"id": "limones", "text_md": "Limones", "image_url": "http://localhost:4006/files/lesson-images/7d9472b044ee532f11a80b6786f3eba28c63e2599c11c8be981b5243e2c7d5cb.webp"}, {"id": "vasos", "text_md": "Vasos", "image_url": "http://localhost:4006/files/lesson-images/0639608c7c8f6cd9e63e97af1b17b0cd62dae847d6a4d42848ab2143b81bacaf.webp"}, {"id": "stickers", "text_md": "Stickers", "image_url": "http://localhost:4006/files/lesson-images/6864fbb6a2bfc7d7630f86e9709565b218e611ffb8f90b9f037396f3d34501a2.webp"}, {"id": "globos", "text_md": "Globos", "image_url": "http://localhost:4006/files/lesson-images/3ef6823477bf5d5253cbe527dd70266b70e5dceb98d300b6949140a9545241b9.webp"}], "buckets": [{"id": "necesidad", "label": "Necesidad del puesto"}, {"id": "gusto", "label": "Gusto que puede esperar"}]}, "narrator": {"emotion": "excited", "character": "dina"}, "prompt_md": "Toca cada compra y ponla en la cubeta correcta: necesidad del puesto o gusto que puede esperar.", "difficulty": 1, "explanation_md": "Los limones y vasos son necesidades del puesto para hacer y servir limonada. Los stickers y globos son gustos que pueden esperar.", "audio_segment_id": "s1-clasifica.prompt"}], "schema_version": 1}', '{"s1-clasifica": {"assignments": {"vasos": "necesidad", "globos": "gusto", "limones": "necesidad", "stickers": "gusto"}}}', '{"units": {"s1-clasifica.hint.0": {"url": "http://localhost:4006/files/lesson-audio/5ca69314a41d6056eb64f24caefb2d1868f8d6316b00b736091f4ef14c68df74.mp3", "hash": "833cc36f096d09cf840ab1d0c19f224aee04848a076c60cc98c8c5ad8e5f83f6", "bytes": 36864, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/5ca69314a41d6056eb64f24caefb2d1868f8d6316b00b736091f4ef14c68df74.mp3", "duration_ms": 6080}, "s1-clasifica.hint.1": {"url": "http://localhost:4006/files/lesson-audio/cb5a23fdd0abd33a7a10a695a7fd379321553501daea821d30d95f7d43f6b8e9.mp3", "hash": "1da6135c2dff85282a543289b4f8ce6ae5a2579cd27a3846d9cdfc00bb2a7592", "bytes": 36288, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/cb5a23fdd0abd33a7a10a695a7fd379321553501daea821d30d95f7d43f6b8e9.mp3", "duration_ms": 6000}, "s1-clasifica.prompt": {"url": "http://localhost:4006/files/lesson-audio/06bf20ce5361e73bb88cde4e7cbd5246187e093e745b0cf0a4f15528721bfe5e.mp3", "hash": "3469c006199c391dec0fae856b279a619920edc947dd3651a694edd8f23120cb", "bytes": 37296, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/06bf20ce5361e73bb88cde4e7cbd5246187e093e745b0cf0a4f15528721bfe5e.mp3", "duration_ms": 6160}, "s1-clasifica.explanation": {"url": "http://localhost:4006/files/lesson-audio/5b8304dd72f09173c170c69ef593170ada2da76111898cfaa13841c047ad09cb.mp3", "hash": "b50e95362612de6f76763e9bf913f089be88a3582c5f8e2aa3d3ab1845a5c894", "bytes": 52704, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/5b8304dd72f09173c170c69ef593170ada2da76111898cfaa13841c047ad09cb.mp3", "duration_ms": 8720}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('97238255-709d-4d86-8930-3ea433f54f7d', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "checkpoint", "title": "A noite antes de abrir", "locale": "pt-BR", "subject": "mixed", "objectives": ["Revisar a meta de 80 reais, o preço de 5 reais por copo, e que o lucro é o que sobra depois do custo.", "Refletir sobre o progresso em direção à meta."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-checkpoint", "xp": 0, "type": "checkpoint", "hints": [], "title": "Revisão da grande ideia", "payload": {"recap_md": "**A meta:** violão de 80 reais. **Preço:** 5 reais por copo. **Lucro:** o que sobra depois do custo, vai para o pote do violão.", "mood_prompt_md": "Liruf respira fundo. Amanhã ele abre sua barraca. Já sente o violão mais perto?"}, "narrator": {"emotion": "happy", "character": "dina"}, "prompt_md": "O violão custa 80 reais. Cada copo de limonada custa 5 reais. O lucro de cada copo vai para o pote do violão.", "difficulty": 1, "explanation_md": "Liruf já tem a meta de 80 reais, o preço de 5 reais por copo, e sabe que o lucro é o que sobra após pagar o custo.", "audio_segment_id": "s1-checkpoint.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-checkpoint.recap": {"url": "http://localhost:4006/files/lesson-audio/dffde3b0bb2c986e19c58bfaeeb805f521471b77e2f40a74b281840d983190d6.mp3", "hash": "65d6c70e9167d9eaeada4e7f32b41f979169797a9aacda58ec38672095506ffc", "bytes": 59328, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/dffde3b0bb2c986e19c58bfaeeb805f521471b77e2f40a74b281840d983190d6.mp3", "duration_ms": 9840}, "s1-checkpoint.prompt": {"url": "http://localhost:4006/files/lesson-audio/58e22d07eaab07ebc0208ed96186205fbbacf676fc35e2b08f7900cf8d720418.mp3", "hash": "1b0034bac37d535a3d744d409ecb4e5d7f7892283c573ae63ae8c10b97a1a038", "bytes": 57888, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/58e22d07eaab07ebc0208ed96186205fbbacf676fc35e2b08f7900cf8d720418.mp3", "duration_ms": 9600}, "s1-checkpoint.explanation": {"url": "http://localhost:4006/files/lesson-audio/26ff8643c2388e9b03d3c41e9a58b291e4076fdbc408ea06d56aaeba11581bcc.mp3", "hash": "77b2987684dc1b5376789f0417a9be90ba363fa485331f3c7a18fe7aa323a13f", "bytes": 57456, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/26ff8643c2388e9b03d3c41e9a58b291e4076fdbc408ea06d56aaeba11581bcc.mp3", "duration_ms": 9520}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('376d331c-9296-4bfd-9d4f-d2f052be4db4', 'es-MX', '1', '{"meta": {"cast": ["liruf"], "slug": "piggy-split", "title": "Repartiendo la ganancia", "locale": "es-MX", "subject": "mixed", "objectives": ["Practicar cómo repartir la ganancia diaria entre la meta de ahorro y los gastos del negocio."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-piggy-split", "xp": 15, "type": "piggy_split", "hints": ["Recuerda: los ingredientes cuestan 4 pesos justos. ¡Tienes que cubrirlos para seguir vendiendo!"], "title": "Repartiendo la ganancia", "payload": {"jars": [{"id": "guitar", "icon": "savings", "label": "Para la guitarra", "hint_md": "¿Cuánto ahorras hoy para tu guitarra?", "image_url": "http://localhost:4006/files/lesson-images/2a3c6b51b4d0046f19529cde1e3641659efd725cc79afdcd299669f8f09588b2.webp"}, {"id": "ingredients", "icon": "shopping_basket", "label": "Para reponer ingredientes", "hint_md": "¿Cuánto necesitas para los ingredientes?", "image_url": "http://localhost:4006/files/lesson-images/f439f75ef9f0ad039775a6b2b00bd25963c5805e58a6661fab9ae4b45e51e159.webp"}], "step": 1, "unit": "MXN", "income": 10}, "narrator": {"emotion": "encouraging", "character": "liruf"}, "prompt_md": "Liruf ganó $10 con su limonada y necesita $4 de ingredientes para seguir. Reparte el dinero entre su guitarra y los ingredientes.", "difficulty": 2, "explanation_md": "Los ingredientes cuestan 4 pesos. Si pones menos, no podrías hacer limonada mañana. Si pones más, te quedaría menos para la guitarra. Lo justo es cubrir los costos y ahorrar el resto. ¡Así avanzas hacia tu sueño!", "audio_segment_id": "s1-piggy-split.prompt"}], "schema_version": 1}', '{"s1-piggy-split": {"targets": {"guitar": {"max": 6, "min": 6}, "ingredients": {"max": 4, "min": 4}}, "rationale_md": "Los ingredientes cuestan 4 pesos exactos. Así que necesitas poner eso en el frasco de ingredientes y el resto (6 pesos) en la guitarra. ¡Cubrir costos es la base para seguir ahorrando!"}}', '{"units": {"s1-piggy-split.hint.0": {"url": "http://localhost:4006/files/lesson-audio/66084d9a47b4ef906d7ae43e4555226054c92dd596af27f6038ea98e4dd961cf.mp3", "hash": "5f0a2ce22d336616381f2af1f9017bbdb1e7f62cca22874a12405a9f43225068", "bytes": 41616, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/66084d9a47b4ef906d7ae43e4555226054c92dd596af27f6038ea98e4dd961cf.mp3", "duration_ms": 6880}, "s1-piggy-split.prompt": {"url": "http://localhost:4006/files/lesson-audio/2d143c9f2c9b43a9d3436e61b4e63f5ae5045b54e3cb2841a9e837fe746ae1c1.mp3", "hash": "83e423866a4ed90e25c4cce77816ebafa08aaa147874b570d91e6cc07ff2bb41", "bytes": 57024, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/2d143c9f2c9b43a9d3436e61b4e63f5ae5045b54e3cb2841a9e837fe746ae1c1.mp3", "duration_ms": 9440}, "s1-piggy-split.explanation": {"url": "http://localhost:4006/files/lesson-audio/936b8fb4b20dc78c643fb6903fc3b4f7b86a8785847b3cc6566b197f5bbc961d.mp3", "hash": "9917193f004f1622ab4ad0f1240b1e47ce9fbb59fb6cdfb0300eee0fb409d2f3", "bytes": 92448, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/936b8fb4b20dc78c643fb6903fc3b4f7b86a8785847b3cc6566b197f5bbc961d.mp3", "duration_ms": 15360}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('105d5cdf-c98a-4076-a3ed-440deb643d64', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "would-you-rather", "title": "Seller''s Dilemma", "locale": "en-US", "subject": "mixed", "objectives": ["Making decisions between immediate gains and future savings."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "wyr1-dilema", "xp": 10, "type": "would_you_rather", "title": "Seller''s Dilemma", "payload": {"a": {"icon": "cake", "text_md": "Spend 10 on candy now", "image_url": "http://localhost:4006/files/lesson-images/438e6097a1ac2154ee2ebf1bbb8f8f2263e7a09b4fba7632638845bfd3c3d034.webp"}, "b": {"icon": "savings", "text_md": "Wait 1 week and receive 5 dollars", "image_url": "http://localhost:4006/files/lesson-images/90559e36376d60abf729bfe900c27374f1004fb58254f5b91eebba89c61766fb.webp"}, "followup_md": "How did you reach your decision? Share your reasoning with Dina."}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Dina has 20 dollars; she wants a book that costs 25. Today she can spend 10 on candy, or wait a week and get 5 more. What should she do?", "difficulty": 2, "explanation_md": "Sometimes waiting allows us to reach a bigger goal. Dina needs 25 dollars for her book; by not spending and saving, she gets just enough to buy it.", "audio_segment_id": "wyr1-dilema.prompt"}], "schema_version": 1}', '{"wyr1-dilema": {"qualities": {"a": 0, "b": 100}, "reveal_md": "Si Dina gasta 10 en un dulce, le quedarán 10. Con los 5 extra después, tendrá 15, no suficiente para el libro (25). Si espera, juntará 20+5=25 y podrá comprarlo. ¡Esperar es la mejor opción!"}}', '{"units": {"wyr1-dilema.prompt": {"url": "http://localhost:4006/files/lesson-audio/0216a67f244b85d3b8b437e3b99672e3a4a026676890f5b160db8bf01711e493.mp3", "hash": "d9f41ebca555762590c8d8f563b54c638ce4a54215d02156639280705e71edf2", "bytes": 51696, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/0216a67f244b85d3b8b437e3b99672e3a4a026676890f5b160db8bf01711e493.mp3", "duration_ms": 8560}, "wyr1-dilema.choices": {"url": "http://localhost:4006/files/lesson-audio/4cb029dc51a40f213e9b88fd66397f62e1ed490a0be8094fa4fc97bed0155c85.mp3", "hash": "7081a7afa0b5929d85a1910b696b996afa333c8bd8eb55e26288b2e1dff5cef8", "bytes": 26208, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/4cb029dc51a40f213e9b88fd66397f62e1ed490a0be8094fa4fc97bed0155c85.mp3", "duration_ms": 4320}, "wyr1-dilema.explanation": {"url": "http://localhost:4006/files/lesson-audio/4bac79743fa3977466c466c196c826583b4e031daaf025e9cd2ef133270bb732.mp3", "hash": "5dec1a312198f67ad11fda67734e3c1f00d70686a0d7b778894d4c8594699fdf", "bytes": 47808, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/4bac79743fa3977466c466c196c826583b4e031daaf025e9cd2ef133270bb732.mp3", "duration_ms": 7920}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1f15af49-9573-4e17-a4ee-0685fa854b90', 'pt-BR', '1', '{"meta": {"cast": ["liruf"], "slug": "timeline-order", "title": "A ordem do dia de Liruf", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ordenar as etapas do dia de vendas em ordem cronológica"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-timeline", "xp": 10, "type": "timeline_order", "hints": ["Pense: o que Liruf fez primeiro pela manhã?", "Depois de preparar, o que aconteceu ao meio-dia?"], "title": "A ordem do dia de Liruf", "payload": {"events": [{"id": "comprar", "icon": "shopping_cart", "text_md": "Comprar limões e açúcar pela manhã", "image_url": "http://localhost:4006/files/lesson-images/3fde478b7fe63cd1698c6f7ca64a93f23e5db4f59c8dcbbd6dc177fb76b2df87.webp"}, {"id": "preparar", "icon": "local_dining", "text_md": "Preparar a limonada", "image_url": "http://localhost:4006/files/lesson-images/66a63551700e095778061070e29567ca76d2591ca521000ab39788de195443c8.webp"}, {"id": "vender", "icon": "storefront", "text_md": "Vender limonada ao meio-dia", "image_url": "http://localhost:4006/files/lesson-images/173b1a0f39604f1816190abefadedaed9df251204a98c6e978c24f155dbe272e.webp"}, {"id": "contar", "icon": "payments", "text_md": "Contar o dinheiro e guardá-lo no fechamento", "image_url": "http://localhost:4006/files/lesson-images/1ca4439058871f4c15f5b08236ad1954fd9e0ab0467e571d6d3f6060a61950d9.webp"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf lembra do seu primeiro dia. Toque nos eventos na ordem em que aconteceram.", "difficulty": 1, "explanation_md": "Primeiro se compram os ingredientes, depois se prepara a limonada, depois se vende, e no final se conta o dinheiro e se guarda.", "audio_segment_id": "s1-timeline.prompt"}], "schema_version": 1}', '{"s1-timeline": {"order": ["comprar", "preparar", "vender", "contar"]}}', '{"units": {"s1-timeline.hint.0": {"url": "http://localhost:4006/files/lesson-audio/901e1d98d95541bf922d574219e42c4cda3e7b81ae0e0383b1d36d2a1388e505.mp3", "hash": "b5ca8a6c23c4af4e93ce07fd8302e3f63788ae6ce6b8a555416a757be9cadc1a", "bytes": 17568, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/901e1d98d95541bf922d574219e42c4cda3e7b81ae0e0383b1d36d2a1388e505.mp3", "duration_ms": 2880}, "s1-timeline.hint.1": {"url": "http://localhost:4006/files/lesson-audio/f54772de02f9e561412eca1f29ac3c5d89597f2720bfdaea8726a86d37e9a478.mp3", "hash": "50a80f137dea5793a98826797cfc7b3e59f59e8edffdd15fc0f96bda86f501dd", "bytes": 20448, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/f54772de02f9e561412eca1f29ac3c5d89597f2720bfdaea8726a86d37e9a478.mp3", "duration_ms": 3360}, "s1-timeline.prompt": {"url": "http://localhost:4006/files/lesson-audio/991522be9d569bd8226050318fce07e704c6e265424414fc52350249742f92ed.mp3", "hash": "3bf1c589a4b364290c519c5c5d12dfdb980d839a2a14e3bb65b0076b2a380873", "bytes": 32544, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/991522be9d569bd8226050318fce07e704c6e265424414fc52350249742f92ed.mp3", "duration_ms": 5360}, "s1-timeline.explanation": {"url": "http://localhost:4006/files/lesson-audio/fe5895877dd10d72d80e35e1f0f1bfc46a140853cc2af95f5f48fe2ffa1a093b.mp3", "hash": "1eefbe22952cefe4498fff102e03192766ad9d8332f33d11ca38ceb84ac5d66d", "bytes": 49824, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/fe5895877dd10d72d80e35e1f0f1bfc46a140853cc2af95f5f48fe2ffa1a093b.mp3", "duration_ms": 8240}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4a340725-6bd9-48c4-9c1a-d8641c86b7a1', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "evidence-hunt", "title": "How much did the lemons cost?", "locale": "en-US", "subject": "mixed", "objectives": ["Look on the market receipt for the exact evidence of how much the lemons cost."], "estimated_minutes": 5}, "scoring": {"hearts": 3, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-evidence-hunt", "xp": 0, "type": "evidence_hunt", "title": "The market receipt", "payload": {"claim_md": "The lemons cost 10 dollars.", "sentences": [{"id": "s1", "text_md": "Lemons - $10"}, {"id": "s2", "text_md": "Cups - $5"}, {"id": "s3", "text_md": "Ice - $3"}, {"id": "s4", "text_md": "Sugar - $2"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/d4360008fb5b6725ecac5e53114732ec0b9ff0404a1c516ae7dbfd2afdc7abed.webp", "prompt_md": "Liruf needs to know how much the lemons cost. Touch the line on the receipt that has the answer.", "difficulty": 1, "explanation_md": "The lemons cost 10 dollars, just what the receipt shows on the line ''Lemons - $10''. This way Liruf can verify his expenses!"}], "schema_version": 1}', '{"s1-evidence-hunt": {"evidence_ids": ["s1"]}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c9d7856b-a75e-414e-ae61-e324a19a350d', 'es-MX', '1', '{"meta": {"cast": ["rho"], "slug": "measure-read", "title": "La jarra medidora", "locale": "es-MX", "subject": "money", "objectives": ["Resolver retos de construcción y medición aplicados al puesto: ordenar instrucciones, leer medidas y balancear cantidades."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-read", "xp": 5, "type": "measure_read", "hints": ["Observa con cuidado la línea del líquido y cuenta las marcas desde abajo."], "title": "La línea del vaso justo", "payload": {"max": 400, "min": 0, "unit": "ml", "ticks": 9, "instrument": "beaker", "pointer_value": 250}, "narrator": {"emotion": "encouraging", "character": "rho"}, "image_url": "http://localhost:4006/files/lesson-images/62345064ab1108fa4f7287bb35543337b2b7d214683e860b46eaee3897b15eab.webp", "prompt_md": "Rho dice: ''Cada vaso justo debe llegar a la misma marca.'' Lee la jarra y dime cuántos mililitros marca.", "difficulty": 1, "explanation_md": "La jarra muestra 250 ml porque el líquido llega exactamente a esa marca. Así cada vaso recibe la misma cantidad y todos pagan lo mismo."}], "schema_version": 1}', '{"s1-read": {"value": 250, "tolerance": 0}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('98f38e44-71ba-4294-87ea-7a6684eb8359', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "balance-scale", "title": "Equilibra el trueque", "locale": "es-MX", "subject": "mixed", "objectives": ["Equilibrar una balanza para un trueque justo usando sumas repetidas."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-balance", "xp": 15, "type": "balance_scale", "hints": ["Primero suma el valor de los 3 vasos: 5 + 5 + 5. Luego busca cuántas galletas de 3 pesos necesitas para igualar esa suma."], "title": "Equilibra la balanza", "payload": {"weights": [{"id": "galleta-1", "label": "Galleta", "value": 3}, {"id": "galleta-2", "label": "Galleta", "value": 3}, {"id": "galleta-3", "label": "Galleta", "value": 3}, {"id": "galleta-4", "label": "Galleta", "value": 3}, {"id": "galleta-5", "label": "Galleta", "value": 3}, {"id": "galleta-6", "label": "Galleta", "value": 3}], "left_fixed": [{"label": "Vaso de limonada", "value": 5}, {"label": "Vaso de limonada", "value": 5}, {"label": "Vaso de limonada", "value": 5}], "unknown_label": "Galletas"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf puso 3 vasos (5 pesos c/u) a la izquierda. Toca galletas (3 pesos c/u) para igualar la balanza.", "difficulty": 2, "explanation_md": "Tres vasos de 5 pesos valen 15 pesos. Cinco galletas de 3 pesos también suman 15. ¡Trato justo!", "audio_segment_id": "s1-balance.prompt"}], "schema_version": 1}', '{"s1-balance": {}}', '{"units": {"s1-balance.hint.0": {"url": "http://localhost:4006/files/lesson-audio/c3e0b07381d3fc708740d58bc3b28d56c6345208d0dbb0bff3f5fc54103ddce5.mp3", "hash": "bf9e4a1b88feac0014744f6a50af41c61db36dd2b9ccebf70a687227dd4aa73e", "bytes": 61344, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/c3e0b07381d3fc708740d58bc3b28d56c6345208d0dbb0bff3f5fc54103ddce5.mp3", "duration_ms": 10160}, "s1-balance.prompt": {"url": "http://localhost:4006/files/lesson-audio/c9cf1fbe0f86035a075bde1923e960863da73c9f750b05530408be4a1a55cd54.mp3", "hash": "50caab55b577d2dc43c28bd88f35c7f32ebb8e90b839c2c2e57c46da867233f9", "bytes": 57456, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/c9cf1fbe0f86035a075bde1923e960863da73c9f750b05530408be4a1a55cd54.mp3", "duration_ms": 9520}, "s1-balance.explanation": {"url": "http://localhost:4006/files/lesson-audio/23a22f4dafaf3f9e7f9a7c9c703a889328799350faf85161a1b07a05de0b287a.mp3", "hash": "44c91786bdc839cfaf7567263840b9dfb440136caa542199a10237b339515350", "bytes": 45504, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/23a22f4dafaf3f9e7f9a7c9c703a889328799350faf85161a1b07a05de0b287a.mp3", "duration_ms": 7520}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('21c29ede-4ec5-4118-8e88-04f1068e985b', 'en-US', '1', '{"meta": {"cast": ["liruf"], "slug": "count-objects", "title": "Count the coins from the overturned jar", "locale": "en-US", "subject": "mixed", "objectives": ["Count objects in a scene to determine a numerical total."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-count-coins", "xp": 10, "type": "count_objects", "title": "Count the coins from the overturned jar", "payload": {"scene": [{"icon": "monetization_on", "tint": "primary", "count": 8, "label": "coin", "image_url": "http://localhost:4006/files/lesson-images/51eb4fbd85b0102763aa4756514de1a67358073790bcaeb865ee16edcf4983ba.webp"}, {"icon": "cookie", "tint": "accent", "count": 3, "label": "cookie", "image_url": "http://localhost:4006/files/lesson-images/f2975e6e8d715646e735228b20f39c19a408d57acbe156d19e08e426fad7fc66.webp"}, {"icon": "local_drink", "tint": "warning", "count": 2, "label": "glass", "image_url": "http://localhost:4006/files/lesson-images/e7f7f16426e7194c18895bfcec92b380cc27efe30ad87d400a21821b9a14d390.webp"}], "ask_icon": "monetization_on", "ask_label": "coin", "ask_image_url": "http://localhost:4006/files/lesson-images/51eb4fbd85b0102763aa4756514de1a67358073790bcaeb865ee16edcf4983ba.webp"}, "narrator": {"emotion": "excited", "character": "liruf"}, "prompt_md": "Liruf''s sales jar tipped over. Count the coins that fell.", "difficulty": 1, "explanation_md": "You counted 8 coins. Each coin is a glass of 5 dollars that Liruf already sold. Today you add 40 dollars towards the 80-dollar guitar goal!"}], "schema_version": 1}', '{"s1-count-coins": {"value": 8}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5cfeb5fa-1115-414d-9498-5cf6271b6245', 'en-US', '1', '{"meta": {"cast": ["zara"], "slug": "robot-path", "title": "Ice Cream Delivery", "locale": "en-US", "subject": "mixed", "objectives": ["Plan the most efficient route to complete a delivery and earn a reward."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-robot-path", "xp": 5, "type": "robot_path", "hints": ["Look at the starting direction. If you move forward you’ll crash, what can you do first?", "Each extra step takes longer, the ice cream could melt!"], "title": "The Shortest Route", "payload": {"goal": {"x": 2, "y": 0}, "grid": {"h": 3, "w": 3}, "start": {"x": 0, "y": 0, "dir": "down"}, "walls": [{"x": 0, "y": 1}], "commands": ["left", "forward", "forward"], "max_commands": 5}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Guide Zara through the grid to deliver the ice cream. Use the shortest route and earn a tip!", "difficulty": 1, "explanation_md": "Perfect! Zara turned left and moved forward 2 steps, delivering the ice cream just in time. Because she was so fast, Ana gave her an extra tip.", "audio_segment_id": "s1-robot-path.prompt"}], "schema_version": 1}', '{"s1-robot-path": {}}', '{"units": {"s1-robot-path.hint.0": {"url": "http://localhost:4006/files/lesson-audio/aaeb8fb0a2d4185995bd6195653124bb49f52172cb592b2fce15fc58cff48472.mp3", "hash": "560d67d4fc36ed6992e2559f98e5db3de467c92a112a646544e8c0ded3d1da7f", "bytes": 32976, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/aaeb8fb0a2d4185995bd6195653124bb49f52172cb592b2fce15fc58cff48472.mp3", "duration_ms": 5440}, "s1-robot-path.hint.1": {"url": "http://localhost:4006/files/lesson-audio/2aacb4f7da08214d0b247cc858488e12a20604ef67872bb65be375e035c4d745.mp3", "hash": "f77ed1de01699841491095ad00ab51b9478b334b54ffce3265dfd485db3e5fed", "bytes": 21456, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/2aacb4f7da08214d0b247cc858488e12a20604ef67872bb65be375e035c4d745.mp3", "duration_ms": 3520}, "s1-robot-path.prompt": {"url": "http://localhost:4006/files/lesson-audio/76ed28d094b34c210683240aec4299294acd1cab330511c065cedc275298f614.mp3", "hash": "2eb28dffac7f1324f8f118c783e42fc4d78df7f4809131264d38d193158e991b", "bytes": 35424, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/76ed28d094b34c210683240aec4299294acd1cab330511c065cedc275298f614.mp3", "duration_ms": 5840}, "s1-robot-path.explanation": {"url": "http://localhost:4006/files/lesson-audio/6be39af29b5d5e49a33fadb9e44044ecfc351437a4c2ca5524dbea76f6de9970.mp3", "hash": "09d1a27184356ee37a82d048594fba0e2cafecc19311fd5e079d5e7b57806509", "bytes": 59904, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/6be39af29b5d5e49a33fadb9e44044ecfc351437a4c2ca5524dbea76f6de9970.mp3", "duration_ms": 9920}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('000a07f3-d716-40f9-bb5f-2d175c582162', 'en-US', '1', '{"meta": {"cast": ["liruf"], "slug": "spot-error", "title": "Find the error: Liruf''s account", "locale": "en-US", "subject": "mixed", "objectives": ["Identify that 5+5+5 cannot equal 20 and correct the sales sum."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "e1-spot-error", "xp": 15, "type": "spot_error", "title": "Find the error", "payload": {"steps": [{"id": "s1", "text_md": "Monday: I sold 1 cup of lemonade → 5 dollars."}, {"id": "s2", "text_md": "Tuesday: I sold another cup → 5 dollars."}, {"id": "s3", "text_md": "Wednesday: I sold one more cup → 5 dollars."}, {"id": "s4", "text_md": "Total: 5 + 5 + 5 = 20 dollars."}], "context_md": "Liruf wrote down what he sold this week."}, "narrator": {"emotion": "thinking", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/2da8db3d6eda630eaf681258ff6dd2eca6611ccd033df74b49a73a4c44752965.webp", "prompt_md": "Liruf reviews his sales notebook. Tap the step where he made a mistake.", "difficulty": 2, "explanation_md": "Each cup costs 5 dollars. Three cups add up to 5+5+5=15. Liruf got confused and wrote 20. Let''s review!", "audio_segment_id": "e1-spot-error.prompt"}], "schema_version": 1}', '{"e1-spot-error": {"error_ids": ["s4"], "correction_md": "La suma es 5 + 5 + 5 = 15, no 20. Liruf le puso un 5 extra."}}', '{"units": {"e1-spot-error.prompt": {"url": "http://localhost:4006/files/lesson-audio/c1feebc16f6fd7ab9224a9d0fcc9db0cab265070952536d6885fcfe8b4c2afc1.mp3", "hash": "a0ea1f007d7d5fcb574aa7eaa41d4848145421c6f16f5f593b62df86e1c8b0fe", "bytes": 24768, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/c1feebc16f6fd7ab9224a9d0fcc9db0cab265070952536d6885fcfe8b4c2afc1.mp3", "duration_ms": 4080}, "e1-spot-error.explanation": {"url": "http://localhost:4006/files/lesson-audio/d82d5e3301905fbd3fc8d7dcc77b68c1019fe8bdd71cb9441d1149be116ad0fb.mp3", "hash": "ded7a5fca2041f960f2f859650d9e9cac3582741d8d5f041150f2d11e1976786", "bytes": 61344, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/d82d5e3301905fbd3fc8d7dcc77b68c1019fe8bdd71cb9441d1149be116ad0fb.mp3", "duration_ms": 10160}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5bcbf28d-86a2-47d1-9003-23897d9d4f57', 'pt-BR', '1', '{"meta": {"cast": ["zara"], "slug": "group-sets", "title": "Separe o dinheiro", "locale": "pt-BR", "subject": "mixed", "objectives": ["Agrupar moedas e notas para contá-las mais facilmente."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "grouping-money", "xp": 10, "type": "group_sets", "hints": ["Observe a forma: as moedas são redondas, as notas são retangulares."], "title": "Separe o dinheiro", "payload": {"items": [{"id": "coin1", "text_md": "Moeda de R$1", "image_url": "http://localhost:4006/files/lesson-images/7b5d7793619c0a39410a9f10205763a3ce8d3e742eed9a1ac5cfb8f9459d3ca7.webp"}, {"id": "coin5", "text_md": "Moeda de R$5", "image_url": "http://localhost:4006/files/lesson-images/5dd87d1abd77d4a36f8842a1955f07f4b5adfbe4a7054273a7e3d766e5a70293.webp"}, {"id": "coin10", "text_md": "Moeda de R$10", "image_url": "http://localhost:4006/files/lesson-images/5c30e700d42e3c85c439c58396e3b99d212c7fb9cdfa5706029130ec1bb07921.webp"}, {"id": "bill20", "text_md": "Nota de R$20"}, {"id": "bill50", "text_md": "Nota de R$50"}], "set_a": "Moedas", "set_b": "Notas"}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "Depois de vender limonada, a caixa está bagunçada. Para contá-la rápido, separe as moedas das notas.", "difficulty": 1, "explanation_md": "Agrupar por tipo facilita contar o dinheiro. Assim você sabe quanto tem em moedas e quanto em notas.", "audio_segment_id": "grouping-money.prompt"}], "schema_version": 1}', '{"grouping-money": {"zones": {"coin1": "a", "coin5": "a", "bill20": "b", "bill50": "b", "coin10": "a"}}}', '{"units": {"grouping-money.hint.0": {"url": "http://localhost:4006/files/lesson-audio/0d93727e98d1418000ee7dcb5983fe50545ee14fe4defcc95c4d9b73672489d2.mp3", "hash": "5e07ff656b9146592b4e684b9bfc10ed1070c118de309e9996e9eba1f0667683", "bytes": 30096, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/0d93727e98d1418000ee7dcb5983fe50545ee14fe4defcc95c4d9b73672489d2.mp3", "duration_ms": 4960}, "grouping-money.prompt": {"url": "http://localhost:4006/files/lesson-audio/57b85e3896d38f83304455d9a8bbf09b85a96e22f5e4acd01d99926b3aa6fed6.mp3", "hash": "55b7d12c6d2ea058c53edecdf717e3ab44993f54a9b9f65f3b009e9eddee2791", "bytes": 43056, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/57b85e3896d38f83304455d9a8bbf09b85a96e22f5e4acd01d99926b3aa6fed6.mp3", "duration_ms": 7120}, "grouping-money.explanation": {"url": "http://localhost:4006/files/lesson-audio/c44e14eb85a79b41df46000895af40c8b8794304841bb0c0826ec6220cf3ac14.mp3", "hash": "c4b4ed476c11836f67576ecc40e3808e506edb2a98515669d6f7fc3ea8da3671", "bytes": 41184, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/c44e14eb85a79b41df46000895af40c8b8794304841bb0c0826ec6220cf3ac14.mp3", "duration_ms": 6800}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58ff84ee-6d0e-4e43-a182-5b9ffd992543', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "memory-flip", "title": "Memória de preços da barraca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Combine na memória cada produto com as moedas que o pagam, usando os preços da barraca: biscoito = 3 (1+2), copo pequeno = 5, jarra grande = 20 (10+10)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-memory-flip", "xp": 15, "type": "memory_flip", "hints": ["Lembre-se: o biscoito vale 3 moedas (1+2), o copo pequeno 5, a jarra grande 20 (10+10).", "Observe os valores: 3, 5 e 20. Qual pagamento vai com cada produto?"], "title": "Combine produto com pagamento", "payload": {"pairs": [{"a_md": "Biscoito", "b_md": "1 + 2", "a_icon": "cookie", "b_icon": "monetization_on", "a_image_url": "http://localhost:4006/files/lesson-images/7e08eb104527f9e19b43e6f4c46fde6f687edc06508a674a213c437a2c701052.webp", "b_image_url": "http://localhost:4006/files/lesson-images/be4642343f02c86c2c67d6c39e5d452b401a802d7e8dd9cb49a866df9adcb2ec.webp"}, {"a_md": "Copo pequeno", "b_md": "5", "a_icon": "local_cafe", "b_icon": "monetization_on", "a_image_url": "http://localhost:4006/files/lesson-images/c4981a45d33ffb26545f219cc83c32f909327aab9e0dffe06b21aa4828b8feac.webp", "b_image_url": "http://localhost:4006/files/lesson-images/4b70952218ce50f65e0d567e7cbe1fcbc48e94e4fe72dd0692ba58d7c72c6bf0.webp"}, {"a_md": "Jarra grande", "b_md": "10 + 10", "a_icon": "water_drop", "b_icon": "monetization_on", "a_image_url": "http://localhost:4006/files/lesson-images/73e4853ef3cef5374997f20b8ace852298c49c69573a6c420466638c0e6e57a7.webp", "b_image_url": "http://localhost:4006/files/lesson-images/48ffc037fb87114996c49ded515200c33de8c574e6cd27d72c590bfb17f1f519.webp"}]}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Toque em cada produto e seu pagamento exato. Biscoito custa 3, copo pequeno 5, jarra grande 20.", "difficulty": 2, "explanation_md": "O biscoito custa 3 reais (1+2), o copo pequeno 5 reais e a jarra grande 20 reais (10+10). Assim você combinou cada produto com seu pagamento exato.", "audio_segment_id": "s1-memory-flip.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-memory-flip.hint.0": {"url": "http://localhost:4006/files/lesson-audio/677d0bfd2fdb422acf397a28d0e61e21a38943c603025baf3acb617d1bdfb1cf.mp3", "hash": "9423a478de01cd0dc521afe71c91efbc4aaa1be870793adfce571f4456d390d2", "bytes": 51696, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/677d0bfd2fdb422acf397a28d0e61e21a38943c603025baf3acb617d1bdfb1cf.mp3", "duration_ms": 8560}, "s1-memory-flip.hint.1": {"url": "http://localhost:4006/files/lesson-audio/715e2277c2861f773a642dab3f025ad548ad100f0220e99408b3553f35f86f3c.mp3", "hash": "c03c7edb70301a909985de8d849bc07e99a2b80ae7c3453111bfc160ed10086d", "bytes": 37296, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/715e2277c2861f773a642dab3f025ad548ad100f0220e99408b3553f35f86f3c.mp3", "duration_ms": 6160}, "s1-memory-flip.prompt": {"url": "http://localhost:4006/files/lesson-audio/3e61ea5c7c524287795830fa92c7bb33fc44336ea8f461d497ed6cc719ede242.mp3", "hash": "7e465deafeeda1fb6ba77b6d3f61a4bc9e309eaceb3cdf4e4941ee9e45c0d4f5", "bytes": 46944, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/3e61ea5c7c524287795830fa92c7bb33fc44336ea8f461d497ed6cc719ede242.mp3", "duration_ms": 7760}, "s1-memory-flip.explanation": {"url": "http://localhost:4006/files/lesson-audio/385cf2b86b8a5faa260f241a69e5926750053a9485d774875dc4004f288b8e14.mp3", "hash": "e0ed398a910e1a757ac25eafc2571fce128b80d0b30b5e582eaef305bee48e50", "bytes": 78048, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/385cf2b86b8a5faa260f241a69e5926750053a9485d774875dc4004f288b8e14.mp3", "duration_ms": 12960}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('e0e06311-1e57-4b7b-a3ee-04c82227ceae', 'pt-BR', '1', '{"meta": {"cast": ["liruf"], "slug": "fair-trade", "title": "A troca é justa?", "locale": "pt-BR", "subject": "mixed", "objectives": ["Comparar valores para decidir se uma troca é justa."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fair-trade", "xp": 8, "type": "fair_trade", "hints": ["Quanto valem os 2 copos juntos?"], "title": "A troca é justa?", "payload": {"offer_a": {"qty": 2, "icon": "local_drink", "label": "Copos de limonada", "image_url": "http://localhost:4006/files/lesson-images/29e13e44cec89505455799d682d9bfd45cc70228a4a8827b27050ca296182fb6.webp"}, "offer_b": {"qty": 1, "icon": "shopping_bag", "label": "Saco de limões", "image_url": "http://localhost:4006/files/lesson-images/f454bcb49f9e20430d15de00bf6bf54cf6fade6400b324843d1f4adae64841c0.webp"}, "rate_md": "2 copos por 1 saco"}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Cada copo de limonada custa 5 reais. O saco de limões vale 10. É justo trocar 2 copos pelo saco?", "difficulty": 1, "explanation_md": "Os 2 copos juntos valem 10 reais (5+5). O saco também vale 10. Como os dois lados valem o mesmo, é uma troca justa.", "audio_segment_id": "s1-fair-trade.prompt"}], "schema_version": 1}', '{"s1-fair-trade": {"verdict": "fair"}}', '{"units": {"s1-fair-trade.hint.0": {"url": "http://localhost:4006/files/lesson-audio/abb5faf24a674c91808303ec44dddd54a3bfe788591ca04f96e67fcefd76c968.mp3", "hash": "6c66a326a839618efb33371de1e0ee7c36a1f1b256462869eea29c5d793601df", "bytes": 16128, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/abb5faf24a674c91808303ec44dddd54a3bfe788591ca04f96e67fcefd76c968.mp3", "duration_ms": 2640}, "s1-fair-trade.prompt": {"url": "http://localhost:4006/files/lesson-audio/81fc3332e6a8de8eedfd5c24b567f30ace18677200181a3bbfb412702df65bc4.mp3", "hash": "4152223b9d0d46d1dfa98637ab09e8d2e37d736449a6c73188055c6233a71fd6", "bytes": 49248, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/81fc3332e6a8de8eedfd5c24b567f30ace18677200181a3bbfb412702df65bc4.mp3", "duration_ms": 8160}, "s1-fair-trade.explanation": {"url": "http://localhost:4006/files/lesson-audio/f3e1bb2a74d5961108be93729cbbb595f2a564314085e5fbeeafd74d76c9db93.mp3", "hash": "38f014e1c55623423be9d6bca5eead4fc1a807fa60d80ea262ed8d724134f6f1", "bytes": 64224, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/f3e1bb2a74d5961108be93729cbbb595f2a564314085e5fbeeafd74d76c9db93.mp3", "duration_ms": 10640}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a00c4534-6e88-42ac-ab77-3465a684f47d', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "story-scene", "title": "El plan de Liruf", "locale": "es-MX", "subject": "mixed", "objectives": ["Entender que el dinero se gana ofreciendo algo que otros quieren", "Ver que una meta clara ayuda a empezar"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-plan", "xp": 0, "type": "story_scene", "title": "El plan de Liruf", "payload": {"art": {"icon": "emoji_objects", "tint": "primary", "image_url": "http://localhost:4006/files/lesson-images/7cd71c2fecf9e6a656ed9b3bc07804c1299cc554f30eda229b284026f5206fe5.webp"}, "action": "idle", "body_md": "Liruf dibuja su plan en una cartulina: un vaso de limonada = 5 pesos. Muchos vasos = una guitarra de 80 pesos. Pero… ¿cuántos vasos necesita vender? ¡Mira! Si vende 2 vasos, gana 10 pesos. ¡Ya va avanzando! ¿Cuántos vasos para 80 pesos? ¡Lo resolveremos juntos!", "emotion": "excited", "backdrop": "band", "character": "liruf"}, "narrator": {"emotion": "excited", "character": "liruf"}, "prompt_md": "Cada vaso de limonada cuesta 5 pesos. Liruf necesita 80 pesos para la guitarra.", "difficulty": 1, "audio_segment_id": "s1-plan.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-plan.body": {"url": "http://localhost:4006/files/lesson-audio/c26f18013ed086bd584fcc02552b4c821702863788ab2c949345e4150e8ada14.mp3", "hash": "b3ad86e82adcc4dd79a5c827ce7a27832bab68dc7047b53146cd157472bad093", "bytes": 127584, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/c26f18013ed086bd584fcc02552b4c821702863788ab2c949345e4150e8ada14.mp3", "duration_ms": 21200}, "s1-plan.prompt": {"url": "http://localhost:4006/files/lesson-audio/29bfaa40ec555a4927b43beffcf7cde9e37b3b3f8b85b36fe3ad14c29ba42321.mp3", "hash": "65869c5c387b3bfa860d35b36b56bd6ae2ce43ad427bab5fd2babcdc1f3e3f68", "bytes": 40608, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/29bfaa40ec555a4927b43beffcf7cde9e37b3b3f8b85b36fe3ad14c29ba42321.mp3", "duration_ms": 6720}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9ceeee19-c270-4624-a828-92e6f501754e', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "confidence-quiz", "title": "Confianza en tus cuentas", "locale": "es-MX", "subject": "mixed", "objectives": ["Sumar dos precios iguales (5+5) para calcular una venta total", "Reflexionar sobre qué tan seguro te sientes de tu respuesta"], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-confidence", "xp": 10, "type": "confidence_quiz", "title": "¿Cuánto juntó Liruf?", "payload": {"options": [{"id": "opt5", "text_md": "5 pesos", "rationale_md": "¿Contaste solo un vaso? Recuerda que Liruf vendió DOS vasos, no uno."}, {"id": "opt10", "text_md": "10 pesos"}, {"id": "opt0", "text_md": "0 pesos", "rationale_md": "¿Restaste en vez de sumar? Los dos vasos se SUMAN, no se restan."}, {"id": "opt25", "text_md": "25 pesos", "rationale_md": "¿Multiplicaste 5×5? Aquí se SUMAN 5+5, no se multiplican."}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf vendió dos vasos de limonada a 5 pesos cada uno. ¿Cuántos pesos juntó?", "difficulty": 1, "explanation_md": "Sumaste 5 + 5 y juntaste 10 pesos. Cuando practicas, puedes confiar más en tus cuentas.", "audio_segment_id": "s1-confidence.prompt"}], "schema_version": 1}', '{"s1-confidence": {"correct_option_id": "opt10"}}', '{"units": {"s1-confidence.prompt": {"url": "http://localhost:4006/files/lesson-audio/82a599b6f97591c206348a4e3e448d039877de897074c58b89fc5d512f8368df.mp3", "hash": "9d387871166b633341f9f26c94d4cf7c651cedc56ebad739df1867a97dc4f2b6", "bytes": 33984, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/82a599b6f97591c206348a4e3e448d039877de897074c58b89fc5d512f8368df.mp3", "duration_ms": 5600}, "s1-confidence.choices": {"url": "http://localhost:4006/files/lesson-audio/dfdb9819328f08cc998f5f2ef08d19ee687ae2b54f23b0eedc3269ccb8c1fd79.mp3", "hash": "d6a93b5a4f498c726e1dabe46f4a26d44bac2f453067816fdc2205d5e9bc906c", "bytes": 26208, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/dfdb9819328f08cc998f5f2ef08d19ee687ae2b54f23b0eedc3269ccb8c1fd79.mp3", "duration_ms": 4320}, "s1-confidence.explanation": {"url": "http://localhost:4006/files/lesson-audio/60e3a7a6a8a97c1cac620499a8f58907f9057cddc8d53ec3fc5c5b8b7d3a75c4.mp3", "hash": "6a4938c2504c2c18337c8a6b2c439e95a09fbcf44010d57a9dff8f8dc6667ea5", "bytes": 44496, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/60e3a7a6a8a97c1cac620499a8f58907f9057cddc8d53ec3fc5c5b8b7d3a75c4.mp3", "duration_ms": 7360}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58172086-898d-4095-acf1-3502b8607e76', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "story-branch", "title": "La decisión de Liruf", "locale": "es-MX", "subject": "mixed", "objectives": ["Tomar decisiones de precio en el puesto de limonada y comprender cómo afectan las ventas y el ahorro."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-price-decision", "xp": 0, "type": "story_branch", "hints": ["Cada vaso te cuesta 2 pesos. Resta eso del precio para saber tu ganancia real.", "Si el precio es muy alto, tal vez los vecinos no compren."], "title": "El precio del día", "payload": {"nodes": [{"id": "start", "choices": [{"id": "c3", "next": "price3", "text_md": "3 pesos por vaso"}, {"id": "c5", "next": "price5", "text_md": "5 pesos por vaso"}, {"id": "c10", "next": "price10", "text_md": "10 pesos por vaso"}], "emotion": "thinking", "text_md": "Es mediodía, hace calor y seis vecinos hacen fila en mi puesto. Quiero la guitarra de 80 pesos. ¿Qué precio pongo?", "character": "liruf"}, {"id": "price3", "choices": [{"id": "end3", "next": null, "text_md": "Entendido"}], "emotion": "thinking", "text_md": "¡Todos compraron! Pero solo gané 1 peso por vaso. 6 vecinos = 6 pesos. Me faltan 74 para la guitarra. Muy poquito...", "character": "liruf"}, {"id": "price5", "choices": [{"id": "end5", "next": null, "text_md": "Entendido"}], "emotion": "encouraging", "text_md": "Los 6 vecinos compraron sin pensarlo. Gané 3 pesos por vaso = 18 pesos. ¡Ya solo faltan 62 para la guitarra! Buen avance.", "character": "liruf"}, {"id": "price10", "choices": [{"id": "end10", "next": null, "text_md": "Entendido"}], "emotion": "thinking", "text_md": "Los vecinos hicieron mueca y se fueron por una nieve. No vendí nada. 0 pesos. Sigo igual de lejos de la guitarra. El más caro no siempre es mejor.", "character": "liruf"}], "start_node": "start"}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/63dba89dbdc680555ffd43b6b2a3c32da6fecdc7c8bcf038a99b153677c711be.webp", "prompt_md": "Hay 6 vecinos con sed. Hacer cada vaso cuesta 2 pesos. ¿Qué precio eliges?", "difficulty": 2, "explanation_md": "Con el precio justo ganas 3 pesos por vaso y vendes todos. Eso te acerca más a la guitarra que un precio muy alto o muy bajo.", "audio_segment_id": "s1-price-decision.prompt"}], "schema_version": 1}', '{"s1-price-decision": {"qualities": [{"score": 25, "node_id": "start", "choice_id": "c3"}, {"score": 95, "node_id": "start", "choice_id": "c5"}, {"score": 10, "node_id": "start", "choice_id": "c10"}]}}', '{"units": {"s1-price-decision.hint.0": {"url": "http://localhost:4006/files/lesson-audio/b79fdbc621bcec09e55fe6c20de26f9be950f5a93f24ded728e99de216773f62.mp3", "hash": "c3334876965b3adea75cd2c13eae98d0a0d10a9199ca3dae8b31d358d76afa0e", "bytes": 34848, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/b79fdbc621bcec09e55fe6c20de26f9be950f5a93f24ded728e99de216773f62.mp3", "duration_ms": 5760}, "s1-price-decision.hint.1": {"url": "http://localhost:4006/files/lesson-audio/1734e3b3aeb52543fee28fdaea629c945280a4c2738bbf71db21f3bfebe53976.mp3", "hash": "ec45964273ef57d571aad8959e65ee124910ffd8e74661e3f0da1531b572bd0f", "bytes": 23904, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/1734e3b3aeb52543fee28fdaea629c945280a4c2738bbf71db21f3bfebe53976.mp3", "duration_ms": 3920}, "s1-price-decision.prompt": {"url": "http://localhost:4006/files/lesson-audio/710a7f732051020c6b5155481f223cf18d453deceb7d28cfcb9e1b4a820e7863.mp3", "hash": "6a208a68c086cb857c19f92c0da7aabef44373e60d24ff75d025385012bea501", "bytes": 34416, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/710a7f732051020c6b5155481f223cf18d453deceb7d28cfcb9e1b4a820e7863.mp3", "duration_ms": 5680}, "s1-price-decision.explanation": {"url": "http://localhost:4006/files/lesson-audio/e3ef47fc0ad030aa6aa25f3bebeeb7cc3103ddabb3057a4472365d3b52eb37c2.mp3", "hash": "85b52fd8097b17c12975a16c56ee0e688f1ad0edd762a9f1ef590cb7a4093cb4", "bytes": 56448, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/e3ef47fc0ad030aa6aa25f3bebeeb7cc3103ddabb3057a4472365d3b52eb37c2.mp3", "duration_ms": 9360}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('35abfab2-f1da-4643-915a-3fdba69f3a63', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "fill-blank", "title": "Preenchendo o caderno de contas", "locale": "pt-BR", "subject": "mixed", "objectives": ["Calcular o lucro subtraindo o custo dos ingredientes do preço de venda."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ganancia-liruf", "xp": 5, "type": "fill_blank", "title": "O lucro de Liruf", "payload": {"bank": [{"id": "a", "text_md": "2"}, {"id": "b", "text_md": "3"}, {"id": "c", "text_md": "5"}, {"id": "d", "text_md": "7"}], "mode": "bank", "text_md": "Vendi um copo de limonada por 5 reais e os ingredientes custaram 2 reais. Meu lucro é de {{1}} reais."}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf vende limonada. Vende cada copo a 5 reais e os ingredientes custam 2 reais. Quanto ganha por copo?", "difficulty": 1, "explanation_md": "O lucro é de 3 reais. Subtraia o custo (2) do preço (5): 5 - 2 = 3. Assim Liruf economiza para sua boneca!", "audio_segment_id": "s1-ganancia-liruf.prompt"}], "schema_version": 1}', '{"s1-ganancia-liruf": {"gaps": [{"gap": 1, "accept": ["3"], "bank_id": "b"}]}}', '{"units": {"s1-ganancia-liruf.prompt": {"url": "http://localhost:4006/files/lesson-audio/cc2403920718b72705598941c9d8db613c7d871d284312e370da1a64fa28ea31.mp3", "hash": "cee744b8f67db790d61c5c5d3bb92f708ab5942ad524ed1f5605b6e531cd5453", "bytes": 52704, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/cc2403920718b72705598941c9d8db613c7d871d284312e370da1a64fa28ea31.mp3", "duration_ms": 8720}, "s1-ganancia-liruf.explanation": {"url": "http://localhost:4006/files/lesson-audio/8888d7a0ce592b11a3a832c88f1013b0e74f63445ace8b16004beccc1d9f41fb.mp3", "hash": "7abd65a793bcab0381594225d42c2038781c5bc5eb90db909d650a90df6fed27", "bytes": 70416, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/8888d7a0ce592b11a3a832c88f1013b0e74f63445ace8b16004beccc1d9f41fb.mp3", "duration_ms": 11680}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('376d331c-9296-4bfd-9d4f-d2f052be4db4', 'en-US', '1', '{"meta": {"cast": ["liruf"], "slug": "piggy-split", "title": "Splitting the profit", "locale": "en-US", "subject": "mixed", "objectives": ["Practice how to split the daily profit between your savings goal and business expenses."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-piggy-split", "xp": 15, "type": "piggy_split", "hints": ["Remember: the ingredients cost exactly 4 dollars. You have to cover them to keep selling!"], "title": "Splitting the profit", "payload": {"jars": [{"id": "guitar", "icon": "savings", "label": "For the guitar", "hint_md": "How much do you save today for your guitar?", "image_url": "http://localhost:4006/files/lesson-images/475c4e36e9cb53e61e5a3633ecf48c8d98d71d8e0788289eea1d05697a9245ab.webp"}, {"id": "ingredients", "icon": "shopping_basket", "label": "To restock ingredients", "hint_md": "How much do you need for the ingredients?", "image_url": "http://localhost:4006/files/lesson-images/ff0d2430b6ebaf99d17680723e03f5a62ea718b9a1f61c87df5f870385dfb6f5.webp"}], "step": 1, "unit": "USD", "income": 10}, "narrator": {"emotion": "encouraging", "character": "liruf"}, "prompt_md": "Liruf earned $10 with her lemonade and needs $4 in ingredients to keep going. Split the money between her guitar and the ingredients.", "difficulty": 2, "explanation_md": "The ingredients cost 4 dollars. If you put less, you wouldn''t be able to make lemonade tomorrow. If you put more, you''d have less left for the guitar. The fair thing is to cover the costs and save the rest. That''s how you make progress toward your dream!", "audio_segment_id": "s1-piggy-split.prompt"}], "schema_version": 1}', '{"s1-piggy-split": {"targets": {"guitar": {"max": 6, "min": 6}, "ingredients": {"max": 4, "min": 4}}, "rationale_md": "Los ingredientes cuestan 4 pesos exactos. Así que necesitas poner eso en el frasco de ingredientes y el resto (6 pesos) en la guitarra. ¡Cubrir costos es la base para seguir ahorrando!"}}', '{"units": {"s1-piggy-split.hint.0": {"url": "http://localhost:4006/files/lesson-audio/ed923f6369b6e19df1118c620a8f090e205e8ff0ede6954d4784c4312533d094.mp3", "hash": "fb7af9fc1f2b623396ff274196c0374ba1700c0d762bfd8bc6c5920d01015df5", "bytes": 32544, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/ed923f6369b6e19df1118c620a8f090e205e8ff0ede6954d4784c4312533d094.mp3", "duration_ms": 5360}, "s1-piggy-split.prompt": {"url": "http://localhost:4006/files/lesson-audio/3226aeac78264a6cc21c12c049e5ee9a0923fb1dcc1c3f4e556abd0802ed6e77.mp3", "hash": "4844147a20f03aec395239d6765b3e78d0e730d332b1eb119a2797c153d9d9d7", "bytes": 52128, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/3226aeac78264a6cc21c12c049e5ee9a0923fb1dcc1c3f4e556abd0802ed6e77.mp3", "duration_ms": 8640}, "s1-piggy-split.explanation": {"url": "http://localhost:4006/files/lesson-audio/64b61f41e3b922fba5846793be580ac88fd350449705692dccfe268751762772.mp3", "hash": "11c41cce2b3b5ef95feef549e5649dda6a83b88dc37c496dd3bd30d1382b234f", "bytes": 80928, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/64b61f41e3b922fba5846793be580ac88fd350449705692dccfe268751762772.mp3", "duration_ms": 13440}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('881ae1da-74af-4378-a3cd-da8a9bc0e6b2', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "key-ideas", "title": "Las tres reglas de oro del pequeño vendedor", "locale": "es-MX", "subject": "mixed", "objectives": ["Entender que el dinero se gana ofreciendo algo que otros quieren", "Identificar una meta clara (80 pesos) para empezar a vender", "Reconocer que guardar lo ganado ayuda a alcanzar la meta"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-key-ideas", "xp": 0, "type": "key_ideas", "hints": [], "title": "Las tres reglas de oro", "payload": {"ideas": [{"icon": "flag", "title": "Meta: 80 pesos", "body_md": "Liruf quiere una guitarra que cuesta **80 pesos**. Esa es su meta.", "image_url": "http://localhost:4006/files/lesson-images/67aedfeeb4aa14a2012d47f591bde1f85e1be276d43adbb188bc5d1b111c7c9b.webp"}, {"icon": "storefront", "title": "Ofrecer algo que quieran", "body_md": "Venderá **limonada fría** en el vecindario. ¡A todos les gusta!", "image_url": "http://localhost:4006/files/lesson-images/cbbb04ee1761c4efde853a7e671b6d696ae51c2f9d403529dbb865b8197c6a97.webp"}, {"icon": "savings", "title": "Guardar lo ganado", "body_md": "Cada vaso cuesta **5 pesos**. Guardando todo, llegará a los 80.", "image_url": "http://localhost:4006/files/lesson-images/df498c74db22f8ab3b363b6005fd94435408478bcc0099aea300e77d3b931c65.webp"}]}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Rho escribió en su pizarra las 3 reglas para vender limonada y comprar la guitarra de 80 pesos. Toca cada idea para leerla.", "difficulty": 1, "explanation_md": "Las tres reglas son: tener una meta de 80 pesos, ofrecer limonada fría que la gente quiera, y guardar lo que ganas. ¡Así Liruf logrará su guitarra!", "audio_segment_id": "s1-key-ideas.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-key-ideas.idea.0": {"url": "http://localhost:4006/files/lesson-audio/85064cfaaae882bd6e41f6d6844e451c7907372ab80c3de814ecddd93cc5b53b.mp3", "hash": "8c6f413ab93f12d2f1b4a81b30cbafacbf17c05fc2ef86af58a1bcb36b9a7948", "bytes": 31968, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/85064cfaaae882bd6e41f6d6844e451c7907372ab80c3de814ecddd93cc5b53b.mp3", "duration_ms": 5280}, "s1-key-ideas.idea.1": {"url": "http://localhost:4006/files/lesson-audio/cf5f61034b547f3d3a583d564d808df5cbca84dde7fbe0b65fa2ef186229e6af.mp3", "hash": "eb5727aaf541ef8ff0827befced057f0368ec4e13630d096ce83c3f82b73e587", "bytes": 26784, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/cf5f61034b547f3d3a583d564d808df5cbca84dde7fbe0b65fa2ef186229e6af.mp3", "duration_ms": 4400}, "s1-key-ideas.idea.2": {"url": "http://localhost:4006/files/lesson-audio/8818acd905bde80be59db8d614bc9c7b73a1eb3e5efd1ef392b3f9d714c67667.mp3", "hash": "9176887d69839fbb89ca7a27dcdeef15a81f11846a656ebffc6b988cec405140", "bytes": 32976, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/8818acd905bde80be59db8d614bc9c7b73a1eb3e5efd1ef392b3f9d714c67667.mp3", "duration_ms": 5440}, "s1-key-ideas.prompt": {"url": "http://localhost:4006/files/lesson-audio/f8e991f9a7bdbe3de7c1aeaec679e08cd0a1b47b0fa4f2a94925ad9ef17f7dab.mp3", "hash": "fda963c6231eb84ab75a71398db72e1fae95ad4849f6e45a28a90c3b002072cc", "bytes": 53136, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/f8e991f9a7bdbe3de7c1aeaec679e08cd0a1b47b0fa4f2a94925ad9ef17f7dab.mp3", "duration_ms": 8800}, "s1-key-ideas.explanation": {"url": "http://localhost:4006/files/lesson-audio/2524ff360314289dc6a1c05ec5c04077ac1eaade6efe11ac3cb9985daade1dcd.mp3", "hash": "1fcbd008c3c04e990c66e0e1853e73bcc546d74600970c837139345acfa9ee43", "bytes": 69408, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/2524ff360314289dc6a1c05ec5c04077ac1eaade6efe11ac3cb9985daade1dcd.mp3", "duration_ms": 11520}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('881ae1da-74af-4378-a3cd-da8a9bc0e6b2', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "key-ideas", "title": "As três regras de ouro do pequeno vendedor", "locale": "pt-BR", "subject": "mixed", "objectives": ["Entender que o dinheiro se ganha oferecendo algo que outros querem", "Identificar uma meta clara (80 reais) para começar a vender", "Reconhecer que guardar o que ganhou ajuda a alcançar a meta"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-key-ideas", "xp": 0, "type": "key_ideas", "hints": [], "title": "As três regras de ouro", "payload": {"ideas": [{"icon": "flag", "title": "Meta: 80 reais", "body_md": "Liruf quer um violão que custa **80 reais**. Essa é a sua meta.", "image_url": "http://localhost:4006/files/lesson-images/0b9fcb2893e8a7e5fbdddfb9a2e14c6389b81b4d5729c5652a82539b2122cd62.webp"}, {"icon": "storefront", "title": "Oferecer algo que queiram", "body_md": "Venderá **limonada gelada** na vizinhança. Todo mundo gosta!", "image_url": "http://localhost:4006/files/lesson-images/a67494c0fa41987c1b9ab3c3e405bcc48da7122edba2bcbe5adad724585f4154.webp"}, {"icon": "savings", "title": "Guardar o que ganhou", "body_md": "Cada copo custa **5 reais**. Guardando tudo, chegará aos 80.", "image_url": "http://localhost:4006/files/lesson-images/b003dca96e871906592b1487f7749bfeb95332e233c57032f1681b80bbe656a5.webp"}]}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Rho escreveu no seu quadro as 3 regras para vender limonada e comprar o violão de 80 reais. Toque em cada ideia para lê-la.", "difficulty": 1, "explanation_md": "As três regras são: ter uma meta de 80 reais, oferecer limonada gelada que as pessoas queiram, e guardar o que você ganha. Assim Liruf conseguirá seu violão!", "audio_segment_id": "s1-key-ideas.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-key-ideas.idea.0": {"url": "http://localhost:4006/files/lesson-audio/d6ae16a011e30b0987f8d012e187e22d45764bf0fe420485634636fd586ce3c0.mp3", "hash": "f8064841ad22bcfbfbebd669adb558fe3d10e6dcb8129ba09061a809e5307dd8", "bytes": 33408, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/d6ae16a011e30b0987f8d012e187e22d45764bf0fe420485634636fd586ce3c0.mp3", "duration_ms": 5520}, "s1-key-ideas.idea.1": {"url": "http://localhost:4006/files/lesson-audio/bb37dad4620b142b1c7e8d0d769cd37796e5ea14356c204083ed555686dfaa2b.mp3", "hash": "bc8b0df4bcf598c7515e73095ee668ca88af70d331ddcdf1d8d8018f6d476517", "bytes": 26784, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/bb37dad4620b142b1c7e8d0d769cd37796e5ea14356c204083ed555686dfaa2b.mp3", "duration_ms": 4400}, "s1-key-ideas.idea.2": {"url": "http://localhost:4006/files/lesson-audio/0133a0b23388bf2075aaf0b5b9055676a916f0c936d9cd457fb188b86d91698f.mp3", "hash": "ea758e8b2a0e78c8b566bf5711046272024c9620df6fc2ea0ac94836df8b485e", "bytes": 33408, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/0133a0b23388bf2075aaf0b5b9055676a916f0c936d9cd457fb188b86d91698f.mp3", "duration_ms": 5520}, "s1-key-ideas.prompt": {"url": "http://localhost:4006/files/lesson-audio/beccfc65137492423f17aac1a707fdfd1d783ff5dc4ee01d67d1890f64f53862.mp3", "hash": "5fecccbae2b1b890ba582dd4a5386e291e8089536dca1e7db50468d24b87ccc8", "bytes": 59328, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/beccfc65137492423f17aac1a707fdfd1d783ff5dc4ee01d67d1890f64f53862.mp3", "duration_ms": 9840}, "s1-key-ideas.explanation": {"url": "http://localhost:4006/files/lesson-audio/c0950bfc140087dbe51952f03668f5caf3bae35697e2c5b689255c244bf28a0a.mp3", "hash": "c903f5b854b2f0bfdd869e291997d1133d70ad7e6fe5fed05a27af9f5a1ef260", "bytes": 71424, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/c0950bfc140087dbe51952f03668f5caf3bae35697e2c5b689255c244bf28a0a.mp3", "duration_ms": 11840}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('6e000ee0-e5b3-4521-b30f-cd54bbd72297', 'es-MX', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "type-answer", "title": "Escribir y calcular números reales del puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Escribir respuestas numéricas y de texto exactas sobre las ventas del día (sumas hasta 80, conteos hasta 20)."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-type-ahorro", "xp": 10, "type": "type_answer", "hints": ["Suma 12 + 8."], "title": "Ahorcado financiero", "payload": {"max_chars": 3, "placeholder": "Escribe el número aquí"}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Rho vendió 12 limonadas. Luego vendió 8 más. ¿Cuántas limonadas vendió en total?", "difficulty": 1, "explanation_md": "Rho vendió 12 y luego 8, que son 20 limonadas en total. ¡Buen trabajo sumando!", "audio_segment_id": "s1-type-ahorro.prompt"}], "schema_version": 1}', '{"s1-type-ahorro": {"accept": ["20"], "keywords": ["20"], "case_sensitive": false}}', '{"units": {"s1-type-ahorro.hint.0": {"url": "http://localhost:4006/files/lesson-audio/436996ed50804cb7a29d0608caa349728bd0effc2340043a303287696a8b8ba7.mp3", "hash": "65c8351e0a099d42bdbb2c7f78654cb4e058de6c7b030ee639b74d378401f6f3", "bytes": 11376, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/436996ed50804cb7a29d0608caa349728bd0effc2340043a303287696a8b8ba7.mp3", "duration_ms": 1840}, "s1-type-ahorro.prompt": {"url": "http://localhost:4006/files/lesson-audio/ddfb3b3b43f29792a82cc72566f07504747f9c3e519c032713685d00776b3530.mp3", "hash": "60f7024a13ec5714d3a1bdd5d3bfec69f116292c5472d45f0d92fcd03096f9c0", "bytes": 48816, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/ddfb3b3b43f29792a82cc72566f07504747f9c3e519c032713685d00776b3530.mp3", "duration_ms": 8080}, "s1-type-ahorro.explanation": {"url": "http://localhost:4006/files/lesson-audio/0a2e5c2498b9d3e3a5988893c6e87d2d931618d5200063f22ac83d2263013e1d.mp3", "hash": "a9db650e6b42a3662652c424d2d2097ec52cf35d6142e54fc6f1bc4a4eda1560", "bytes": 40176, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/0a2e5c2498b9d3e3a5988893c6e87d2d931618d5200063f22ac83d2263013e1d.mp3", "duration_ms": 6640}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('21c29ede-4ec5-4118-8e88-04f1068e985b', 'pt-BR', '1', '{"meta": {"cast": ["liruf"], "slug": "count-objects", "title": "Conte as moedas do frasco derramado", "locale": "pt-BR", "subject": "mixed", "objectives": ["Contar objetos em uma cena para determinar um total numérico."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-count-coins", "xp": 10, "type": "count_objects", "title": "Conte as moedas do frasco derramado", "payload": {"scene": [{"icon": "monetization_on", "tint": "primary", "count": 8, "label": "moeda", "image_url": "http://localhost:4006/files/lesson-images/51eb4fbd85b0102763aa4756514de1a67358073790bcaeb865ee16edcf4983ba.webp"}, {"icon": "cookie", "tint": "accent", "count": 3, "label": "biscoito", "image_url": "http://localhost:4006/files/lesson-images/f2975e6e8d715646e735228b20f39c19a408d57acbe156d19e08e426fad7fc66.webp"}, {"icon": "local_drink", "tint": "warning", "count": 2, "label": "copo", "image_url": "http://localhost:4006/files/lesson-images/e7f7f16426e7194c18895bfcec92b380cc27efe30ad87d400a21821b9a14d390.webp"}], "ask_icon": "monetization_on", "ask_label": "moeda", "ask_image_url": "http://localhost:4006/files/lesson-images/51eb4fbd85b0102763aa4756514de1a67358073790bcaeb865ee16edcf4983ba.webp"}, "narrator": {"emotion": "excited", "character": "liruf"}, "prompt_md": "O frasco de vendas do Liruf derramou. Conte as moedas que caíram.", "difficulty": 1, "explanation_md": "Você contou 8 moedas. Cada moeda é um copo de 5 reais que Liruf já vendeu. Hoje você soma 40 reais para a meta do violão de 80!"}], "schema_version": 1}', '{"s1-count-coins": {"value": 8}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('3c639b5e-01f3-469e-95e3-a52a215847f4', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "fact-opinion", "title": "Fatos e Opiniões", "locale": "pt-BR", "subject": "mixed", "objectives": ["Diferenciar entre fatos e opiniões nas frases de uma barraca de limonada."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fact-opinion", "xp": 15, "type": "fact_opinion", "hints": ["Um fato pode ser demonstrado com números ou fotos. Uma opinião é o que alguém gosta ou acredita."], "title": "Fato ou opinião?", "payload": {"statements": [{"id": "s1", "text_md": "Hoje vendemos 12 copos de limonada."}, {"id": "s2", "text_md": "O copo custa 5 reais."}, {"id": "s3", "text_md": "Usamos limões para fazer a limonada."}, {"id": "s4", "text_md": "Nossa limonada é a melhor do bairro."}, {"id": "s5", "text_md": "A barraca tem as cores mais alegres."}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/aad98febc0b35b9bf56012c1cbf8041bcaa6c02ed02671f43f2d2b9032eeb07c.webp", "prompt_md": "Rho diz frases da barraca. Toque nas que são FATOS (podem ser comprovados).", "difficulty": 2, "explanation_md": "Os fatos podem ser comprovados! ''O copo custa 5 reais'' é um fato porque você pode ver o preço. ''É a melhor'' é uma opinião, porque outra pessoa pode não gostar.", "audio_segment_id": "s1-fact-opinion.prompt"}], "schema_version": 1}', '{"s1-fact-opinion": {"fact_ids": ["s1", "s2", "s3"]}}', '{"units": {"s1-fact-opinion.hint.0": {"url": "http://localhost:4006/files/lesson-audio/0a27c8934fe08457aedabe47494cf903db01416c982051c82afd293badf3f63e.mp3", "hash": "7a395762347b990d55c93c20a7b9d40b10469c5b734c4176c554b4d4c8191378", "bytes": 48384, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/0a27c8934fe08457aedabe47494cf903db01416c982051c82afd293badf3f63e.mp3", "duration_ms": 8000}, "s1-fact-opinion.prompt": {"url": "http://localhost:4006/files/lesson-audio/aa3fc27a8b4c5759993a674063b6be9d5989998214ffee64f1d9dfd19c359ae1.mp3", "hash": "cee27ea4953e23958cc90110a3c70c4fb1ae5866ba9be53a713f5e9c22b51fff", "bytes": 33984, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/aa3fc27a8b4c5759993a674063b6be9d5989998214ffee64f1d9dfd19c359ae1.mp3", "duration_ms": 5600}, "s1-fact-opinion.explanation": {"url": "http://localhost:4006/files/lesson-audio/b23278e1cdee9629a1932aecc4fbe5b93c6d996faf8502b15c7888ca20255fd5.mp3", "hash": "2ec8c9fac57aaac70a32728ce9b111b43808a6a501de4e6cc15aa47515164678", "bytes": 68544, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/b23278e1cdee9629a1932aecc4fbe5b93c6d996faf8502b15c7888ca20255fd5.mp3", "duration_ms": 11360}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5bcbf28d-86a2-47d1-9003-23897d9d4f57', 'en-US', '1', '{"meta": {"cast": ["zara"], "slug": "group-sets", "title": "Separate the money", "locale": "en-US", "subject": "mixed", "objectives": ["Group coins and bills to count them more easily."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "grouping-money", "xp": 10, "type": "group_sets", "hints": ["Notice the shape: coins are round, bills are rectangular."], "title": "Separate the money", "payload": {"items": [{"id": "coin1", "text_md": "$1 coin", "image_url": "http://localhost:4006/files/lesson-images/59810040fc4d8b0e62b92b4b2fa453ba1fe54c52280bb93957f0162a959f604a.webp"}, {"id": "coin5", "text_md": "$5 coin", "image_url": "http://localhost:4006/files/lesson-images/b98bb6ba187fd45a94d150345265b50113a3d8684946a6d4eb07205c00fa725d.webp"}, {"id": "coin10", "text_md": "$10 coin", "image_url": "http://localhost:4006/files/lesson-images/6a54e1831d730b4aa5a2d78b48b84c802ba5bafa88502d9554ea7cc2d58b81a2.webp"}, {"id": "bill20", "text_md": "$20 bill"}, {"id": "bill50", "text_md": "$50 bill"}], "set_a": "Coins", "set_b": "Bills"}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "After selling lemonade, the cash register is messy. To count it quickly, separate the coins from the bills.", "difficulty": 1, "explanation_md": "Grouping by type makes it easier to count money. That way you know how much you have in coins and how much in bills.", "audio_segment_id": "grouping-money.prompt"}], "schema_version": 1}', '{"grouping-money": {"zones": {"coin1": "a", "coin5": "a", "bill20": "b", "bill50": "b", "coin10": "a"}}}', '{"units": {"grouping-money.hint.0": {"url": "http://localhost:4006/files/lesson-audio/a0b6b503d2205fd4195ccd95cd5a1aad185e5d3563452791c627e98326ceb7e5.mp3", "hash": "41f11ee7a091117507e182dc5082d7d5b58d50ae8016c804ea9b1d6d5df0e986", "bytes": 26784, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/a0b6b503d2205fd4195ccd95cd5a1aad185e5d3563452791c627e98326ceb7e5.mp3", "duration_ms": 4400}, "grouping-money.prompt": {"url": "http://localhost:4006/files/lesson-audio/5f5747418a596cdf241e4fad7492ff9deeb3e493d14a4acfb7fb66851954ed41.mp3", "hash": "f81bbaa0f4c92b40e125af9cebe41db292a6878dd269b23aac37061bdf7a9c29", "bytes": 40176, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/5f5747418a596cdf241e4fad7492ff9deeb3e493d14a4acfb7fb66851954ed41.mp3", "duration_ms": 6640}, "grouping-money.explanation": {"url": "http://localhost:4006/files/lesson-audio/362a0d167c25af7f90f403bcbb92796e49a2bb1fc28fde037a76d48c748c5e50.mp3", "hash": "c90165a5ac696e74de17b951256e03cc6e558d4f1c821ef76487c7a1a4d7a7f9", "bytes": 45504, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/362a0d167c25af7f90f403bcbb92796e49a2bb1fc28fde037a76d48c748c5e50.mp3", "duration_ms": 7520}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8f1a89c3-ae63-41f5-a2fa-70d1b7c6aac9', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "coin-count", "title": "Contando monedas para la venta", "locale": "es-MX", "subject": "mixed", "objectives": ["Practicar el conteo de monedas mexicanas de 1 y 2 pesos para formar 5 pesos exactos."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-coin-count", "xp": 5, "type": "coin_count", "title": "Juntando los 5 pesos", "payload": {"target": 5, "currency": "MXN", "denominations": [1, 2]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/2230309a617c9ac393d73df1dc52117a5415ccdad79e0c58c90fdadd5f17ccb4.webp", "prompt_md": "Liruf vendió un vaso de 5 pesos. Usa monedas de 1 y 2 para juntar 5 pesos exactos.", "difficulty": 1, "explanation_md": "Liruf ahora sabe que 5 pesos se pueden formar con monedas de 1 y 2. Contar bien cada pago es importante para alcanzar su meta de 80 pesos.", "audio_segment_id": "s1-coin-count.prompt"}], "schema_version": 1}', '{"s1-coin-count": {}}', '{"units": {"s1-coin-count.prompt": {"url": "http://localhost:4006/files/lesson-audio/009f68769386c14680dfb61ffad0c1192b942a96c95d5713872b569fea4e2958.mp3", "hash": "407a03cc2fdfd6f0f4e9cc4daa6e1b71d3849554dd18369acea18fe58c82f963", "bytes": 43056, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/009f68769386c14680dfb61ffad0c1192b942a96c95d5713872b569fea4e2958.mp3", "duration_ms": 7120}, "s1-coin-count.explanation": {"url": "http://localhost:4006/files/lesson-audio/9d0f4ca0f8ecdcbbaf04fdd48cfeed7759a0ac610c956bb800c65e40cce98b8e.mp3", "hash": "c6068aac6911a563e1722907fae158c2540d790294e95c1a2a70b89c222046ca", "bytes": 59904, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/9d0f4ca0f8ecdcbbaf04fdd48cfeed7759a0ac610c956bb800c65e40cce98b8e.mp3", "duration_ms": 9920}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ea98847f-02a1-4527-97a4-36921728b56d', 'es-MX', '1', '{"meta": {"cast": ["liruf"], "slug": "cause-effect", "title": "Causa y efecto en el puesto de limonada", "locale": "es-MX", "subject": "mixed", "objectives": ["Conectar causas y efectos en el puesto: entender que un día soleado lleva a más ventas y que subir el precio puede reducir los clientes."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "cause-effect-1", "xp": 15, "type": "cause_effect", "hints": ["Piensa: ¿Por qué vinieron los clientes? ¿Qué hizo Liruf al verlos?"], "title": "Causa y efecto en el puesto", "payload": {"slots": 5, "events": [{"id": "ev1", "text_md": "El sol está muy fuerte."}, {"id": "ev2", "text_md": "Muchos clientes llegan al puesto."}, {"id": "ev3", "text_md": "Liruf decide cobrar más caro."}, {"id": "ev4", "text_md": "La limonada cuesta 10 pesos."}, {"id": "ev5", "text_md": "Liruf vende pocos vasos."}]}, "narrator": {"emotion": "neutral", "character": "liruf"}, "prompt_md": "Liruf quiere descubrir la razón secreta de sus ventas. Ordena los eventos para formar la cadena de causa y efecto.", "difficulty": 2, "explanation_md": "El sol fuerte trae a los clientes. Al vender mucho, Liruf decidió subir el precio, pero eso hizo que vendiera menos. Si mezclaste las causas, repasa qué provoca cada efecto.", "audio_segment_id": "cause-effect-1.prompt"}], "schema_version": 1}', '{"cause-effect-1": {"chain": ["ev1", "ev2", "ev3", "ev4", "ev5"]}}', '{"units": {"cause-effect-1.hint.0": {"url": "http://localhost:4006/files/lesson-audio/29b9a64d1f103578fcb1a2cfd44adf95553357f89173a41eb0e4775614188b28.mp3", "hash": "59d7289a2362894977b258db1a7856b89dd79c385fa0ca25652dbb3759a818bf", "bytes": 30096, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/29b9a64d1f103578fcb1a2cfd44adf95553357f89173a41eb0e4775614188b28.mp3", "duration_ms": 4960}, "cause-effect-1.prompt": {"url": "http://localhost:4006/files/lesson-audio/e8c5d4f9a2d4353eb1058d16d8a92edcde0bb4dddbf746b9cb2b8297d776ae06.mp3", "hash": "d2629155d4c797c8171f88b808ea2b2365fcebb71d8a84bce5a6a8ee2d41a74b", "bytes": 45504, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/e8c5d4f9a2d4353eb1058d16d8a92edcde0bb4dddbf746b9cb2b8297d776ae06.mp3", "duration_ms": 7520}, "cause-effect-1.explanation": {"url": "http://localhost:4006/files/lesson-audio/4de7ab969600b1d7091701a4147ba646a9b183e6d84092ad80e2910af0af73a9.mp3", "hash": "7272bdc9ac2f2708fa4015abb9be92eec259de570e7bcacb34e3ff26939ddef5", "bytes": 72288, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/4de7ab969600b1d7091701a4147ba646a9b183e6d84092ad80e2910af0af73a9.mp3", "duration_ms": 12000}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('cf7bec3a-945e-4d4a-828c-5535f3a7e69c', 'es-MX', '1', '{"meta": {"cast": ["rho", "liruf"], "slug": "equation-builder", "title": "La cuenta de Liruf", "locale": "es-MX", "subject": "mixed", "objectives": ["Escribir respuestas numéricas exactas sobre las ventas del día", "Calcular el total usando sumas repetidas"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-equation", "xp": 10, "type": "equation_builder", "title": "La meta de Liruf", "payload": {"slots": 5, "tokens": [{"id": "t1", "text": "5"}, {"id": "t2", "text": "5"}, {"id": "t3", "text": "5"}, {"id": "t4", "text": "3"}, {"id": "t5", "text": "15"}, {"id": "t6", "text": "+"}, {"id": "t7", "text": "+"}], "target_result": 15}, "narrator": {"emotion": "encouraging", "character": "liruf"}, "prompt_md": "Liruf necesita 15 pesos para semillas y vendió 3 vasos de limonada a 5 pesos cada uno. Arma la cuenta para ver si juntó lo suficiente.", "difficulty": 1, "explanation_md": "Cada vaso cuesta 5 pesos, por eso sumamos 5 tres veces: 5+5+5=15. Así alcanza justo para las semillas."}], "schema_version": 1}', '{"s1-equation": {"accepted": ["t1 t6 t2 t7 t3"]}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('105d5cdf-c98a-4076-a3ed-440deb643d64', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "would-you-rather", "title": "Dilema do vendedor", "locale": "pt-BR", "subject": "mixed", "objectives": ["Tomar decisões entre ganhos imediatos e poupança futura."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "wyr1-dilema", "xp": 10, "type": "would_you_rather", "title": "Dilema do vendedor", "payload": {"a": {"icon": "cake", "text_md": "Gastar 10 em um doce agora", "image_url": "http://localhost:4006/files/lesson-images/8df84f053616f3675a0afd375c510f5b47202df236f04efa70d41820318180d8.webp"}, "b": {"icon": "savings", "text_md": "Esperar 1 semana e receber 5 reais", "image_url": "http://localhost:4006/files/lesson-images/d8000518694fcba19cdfb85e725040f3ef4dadb4200bdfa2de0f3cfe45c68d0f.webp"}, "followup_md": "Como você chegou à sua decisão? Compartilhe suas contas com Dina."}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Dina tem 20 reais; quer um livro de 25. Hoje pode gastar 10 em um doce, ou esperar uma semana e ter 5 a mais. O que deve fazer?", "difficulty": 2, "explanation_md": "Às vezes esperar nos permite alcançar uma meta maior. Dina precisa de 25 reais para seu livro; ao não gastar e poupar, consegue o exato para comprá-lo.", "audio_segment_id": "wyr1-dilema.prompt"}], "schema_version": 1}', '{"wyr1-dilema": {"qualities": {"a": 0, "b": 100}, "reveal_md": "Si Dina gasta 10 en un dulce, le quedarán 10. Con los 5 extra después, tendrá 15, no suficiente para el libro (25). Si espera, juntará 20+5=25 y podrá comprarlo. ¡Esperar es la mejor opción!"}}', '{"units": {"wyr1-dilema.prompt": {"url": "http://localhost:4006/files/lesson-audio/162f8e16526cf14dd57180f364b6f65f966082dbda57926ba98383496bc0e38c.mp3", "hash": "f13b527a8ac70088269f49dd6677a0b29dc69f3f3a23ea335f7b8e569393d2fc", "bytes": 69984, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/162f8e16526cf14dd57180f364b6f65f966082dbda57926ba98383496bc0e38c.mp3", "duration_ms": 11600}, "wyr1-dilema.choices": {"url": "http://localhost:4006/files/lesson-audio/3801face80f98a2743e5d6a5c2fab37bf231de57a28a0ffc4307baab19411dc4.mp3", "hash": "6b8c3e680738943c6bada6abc679839f61a991c7d91efcaac07dc0f506429cdc", "bytes": 38304, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/3801face80f98a2743e5d6a5c2fab37bf231de57a28a0ffc4307baab19411dc4.mp3", "duration_ms": 6320}, "wyr1-dilema.explanation": {"url": "http://localhost:4006/files/lesson-audio/86ef16f50d831d079b44ba88b86fabe27ba54be09c218159cebc04a68bdac6cc.mp3", "hash": "c12b4a0a70b9de61572e1d9125c89c3e362fe9236653381b5e266413fd480a1b", "bytes": 63216, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/86ef16f50d831d079b44ba88b86fabe27ba54be09c218159cebc04a68bdac6cc.mp3", "duration_ms": 10480}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08f47096-e44f-4b4e-822f-472c6fd87425', 'en-US', '1', '{"meta": {"cast": ["liruf", "rho"], "slug": "speed-tap", "title": "Lightning purchases", "locale": "en-US", "subject": "mixed", "objectives": ["Make quick money decisions by comparing options.", "Distinguish between expenses that help the lemonade stand and treats that don''t."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-speed-tap", "xp": 15, "type": "speed_tap", "hints": ["Ask yourself: does this help me sell more lemonade?"], "title": "Grab the good stuff!", "payload": {"items": [{"id": "limones", "text_md": "Lemons", "image_url": "http://localhost:4006/files/lesson-images/15f9062e604f7e5cd7a5bc34149092d708b75fc1ee33b62fe8e1603aa9def5d1.webp"}, {"id": "calcomania", "text_md": "Dinosaur sticker"}, {"id": "vasos", "text_md": "Cups", "image_url": "http://localhost:4006/files/lesson-images/01afb7dc8c00a066dcfdaf5ddc2b982eb4fc172b00cc8afc93956b530b854c0d.webp"}, {"id": "dulce", "text_md": "Candy", "image_url": "http://localhost:4006/files/lesson-images/a4fe78e68827c028329b417cbfdfb5d02564e10e27019f41d7b6a6826ba13cb1.webp"}, {"id": "azucar", "text_md": "Sugar", "image_url": "http://localhost:4006/files/lesson-images/c3866695c345ed7f84e3b840958e8f33afc286cd95992273a777579151747306.webp"}, {"id": "juguete", "text_md": "Toy", "image_url": "http://localhost:4006/files/lesson-images/6b88d54519c7459b1a6137eae44ee6a7b0a1f3849bd0c73307801175c641200d.webp"}, {"id": "hielo", "text_md": "Ice", "image_url": "http://localhost:4006/files/lesson-images/1f9d54e13f14a08785baf1c06ca6da9199487cdf63a362ad2e61535b92c0ed9c.webp"}, {"id": "cartel", "text_md": "Eye-catching sign", "image_url": "http://localhost:4006/files/lesson-images/e06e7675f882277e849d589b6a9c1a41d78bbe4dc0018b70640654ccf53982d0.webp"}], "seconds": 30, "instruction_md": "Touch the expenses that DO help!"}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Liruf must save for his 80-dollar guitar. Rho deals cards: touch only what helps the stand.", "difficulty": 2, "explanation_md": "Lemons, cups, sugar, ice, and an eye-catching sign help you make and sell more 5-dollar cups. Treats like stickers don''t help the stand."}], "schema_version": 1}', '{"s1-speed-tap": {"target_ids": ["limones", "vasos", "azucar", "hielo", "cartel"]}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9b315200-00f0-4dc4-a2cd-13c1fb40e9aa', 'pt-BR', '1', '{"meta": {"cast": ["zara", "liruf"], "slug": "build-sentence", "title": "O letreiro do combo", "locale": "pt-BR", "subject": "mixed", "objectives": ["Calcular o preço de um combo (2×5 reais) e montar o letreiro da barraca."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 85, "hint_penalty_pct": 10}, "segments": [{"id": "s1-build-sign", "xp": 15, "type": "build_sentence", "hints": ["Pense: se um copo custa 5 reais, quanto custam dois copos?"], "title": "O letreiro do combo", "payload": {"slots": 5, "tokens": [{"id": "t1", "text_md": "2"}, {"id": "t2", "text_md": "copos"}, {"id": "t3", "text_md": "por"}, {"id": "t4", "text_md": "5"}, {"id": "t5", "text_md": "10"}, {"id": "t6", "text_md": "15"}, {"id": "t7", "text_md": "20"}, {"id": "t8", "text_md": "reais"}]}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "Liruf quer vender um combo: 2 copos de limonada. Cada copo custa 5 reais. Monte o letreiro com as palavras e o preço total.", "difficulty": 2, "explanation_md": "O letreiro diz ''2 copos por 10 reais'' porque 5 + 5 = 10. Se você colocasse 5, cobraria apenas um copo; com 15 ou 20, o preço seria muito alto e os clientes não comprariam."}], "schema_version": 1}', '{"s1-build-sign": {"order": ["t1", "t2", "t3", "t5", "t8"]}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('376d331c-9296-4bfd-9d4f-d2f052be4db4', 'pt-BR', '1', '{"meta": {"cast": ["liruf"], "slug": "piggy-split", "title": "Distribuindo os ganhos", "locale": "pt-BR", "subject": "mixed", "objectives": ["Praticar como distribuir os ganhos diários entre a meta de poupança e os gastos do negócio."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-piggy-split", "xp": 15, "type": "piggy_split", "hints": ["Lembre-se: os ingredientes custam 4 reais justos. Você precisa cobri-los para continuar vendendo!"], "title": "Distribuindo os ganhos", "payload": {"jars": [{"id": "guitar", "icon": "savings", "label": "Para a guitarra", "hint_md": "Quanto você poupa hoje para a sua guitarra?", "image_url": "http://localhost:4006/files/lesson-images/50a6e8286e3909408bd8e713b2a45ef1964c63ce0c30b85c1a2fb8ddc5b4a4cc.webp"}, {"id": "ingredients", "icon": "shopping_basket", "label": "Para repor os ingredientes", "hint_md": "Quanto você precisa para os ingredientes?", "image_url": "http://localhost:4006/files/lesson-images/a7e483fb06588a385e04e92648d62bf99acb4274ddd73a350208de0021a79107.webp"}], "step": 1, "unit": "BRL", "income": 10}, "narrator": {"emotion": "encouraging", "character": "liruf"}, "prompt_md": "Liruf ganhou R$10 com sua limonada e precisa de R$4 de ingredientes para continuar. Distribua o dinheiro entre sua guitarra e os ingredientes.", "difficulty": 2, "explanation_md": "Os ingredientes custam 4 reais. Se você colocar menos, não poderia fazer limonada amanhã. Se colocar mais, sobraria menos para a guitarra. O justo é cobrir os custos e poupar o resto. Assim você avança em direção ao seu sonho!", "audio_segment_id": "s1-piggy-split.prompt"}], "schema_version": 1}', '{"s1-piggy-split": {"targets": {"guitar": {"max": 6, "min": 6}, "ingredients": {"max": 4, "min": 4}}, "rationale_md": "Los ingredientes cuestan 4 pesos exactos. Así que necesitas poner eso en el frasco de ingredientes y el resto (6 pesos) en la guitarra. ¡Cubrir costos es la base para seguir ahorrando!"}}', '{"units": {"s1-piggy-split.hint.0": {"url": "http://localhost:4006/files/lesson-audio/1b20e0bde02658528f264145621eecb319eb98fd84627d72d2460773d2541c7b.mp3", "hash": "4a63dd47857fb492481fbbc92c0f5396b72c7bf896ff52e5049d3426c648d3c2", "bytes": 42048, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/1b20e0bde02658528f264145621eecb319eb98fd84627d72d2460773d2541c7b.mp3", "duration_ms": 6960}, "s1-piggy-split.prompt": {"url": "http://localhost:4006/files/lesson-audio/64e856deaef19f45537cd248c56fb65a8b594b7d81c6b4f7b8a499833714b8cc.mp3", "hash": "3f5f15ec9d82d66743e934d0be1c9eb0591c9239d2c24fe81926a3bf2e94ae3c", "bytes": 68976, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/64e856deaef19f45537cd248c56fb65a8b594b7d81c6b4f7b8a499833714b8cc.mp3", "duration_ms": 11440}, "s1-piggy-split.explanation": {"url": "http://localhost:4006/files/lesson-audio/0a5dcf6ec2a6fbd7f648638b9e85736bde33780459c8763b98476b6aba846710.mp3", "hash": "fbbdcdf6448e754addb4105583a5f48cbdd33b590144fb108d434c9bb54c379f", "bytes": 103104, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/0a5dcf6ec2a6fbd7f648638b9e85736bde33780459c8763b98476b6aba846710.mp3", "duration_ms": 17120}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a6e01e69-b662-4c31-9021-3de01a60bbc7', 'pt-BR', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "odd-one-out", "title": "O ingrediente estranho", "locale": "pt-BR", "subject": "mixed", "objectives": ["Detectar qual NÃO é um ingrediente da limonada (limões, açúcar, água… e uma bola?): separar o que realmente custa dinheiro produzir."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-odd-ingredient", "xp": 10, "type": "odd_one_out", "hints": ["Pense no que você precisa para fazer limonada: limões, água, açúcar...", "A bola não se come nem se bebe, não é para a limonada."], "title": "O ingrediente estranho", "payload": {"items": [{"id": "limones", "text_md": "Limões", "image_url": "http://localhost:4006/files/lesson-images/b472fbf35d0c3c0b6d4d49d6056c11b347f65ec3d4205738ea9f6374d27a230f.webp"}, {"id": "azucar", "text_md": "Açúcar", "image_url": "http://localhost:4006/files/lesson-images/ce701d579c5cdd28c3b40cfd76d32d7b5bb3cfa8410dae7f8ae310ce2b5fee50.webp"}, {"id": "agua", "text_md": "Água", "image_url": "http://localhost:4006/files/lesson-images/c7d5d1ed30cd3454f38345cfab4df70ff44ddef1bc46f1d2dd83c2506415dc34.webp"}, {"id": "pelota", "text_md": "Bola", "image_url": "http://localhost:4006/files/lesson-images/8504ccccd2bf82918879f39b6f46eb925470641fee062e38c9cf35fc07a98641.webp"}], "reasons": [{"id": "r1", "text_md": "Não é um ingrediente para fazer limonada."}, {"id": "r2", "text_md": "Sim, é um ingrediente da limonada."}]}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Rho tem R$10 para fazer limonada. O que NÃO precisa comprar?", "difficulty": 1, "explanation_md": "A bola não é um ingrediente da limonada, então não custa dinheiro para fazê-la. Os limões, a água e o açúcar custam dinheiro.", "audio_segment_id": "s1-odd-ingredient.prompt"}], "schema_version": 1}', '{"s1-odd-ingredient": {"odd_item_id": "pelota", "correct_reason_id": "r1"}}', '{"units": {"s1-odd-ingredient.hint.0": {"url": "http://localhost:4006/files/lesson-audio/9c76af99c60ce445dbc6ba9ed5cd491634aa30fb7a9a2b874c9b8775be3b9c5b.mp3", "hash": "ed67e596127471141745e6b666faacd184e7f2a1a77513bdb00645623014138a", "bytes": 33408, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/9c76af99c60ce445dbc6ba9ed5cd491634aa30fb7a9a2b874c9b8775be3b9c5b.mp3", "duration_ms": 5520}, "s1-odd-ingredient.hint.1": {"url": "http://localhost:4006/files/lesson-audio/1d0adea9190c84dfe748697eccce8ae6da6db01ffb681ec69d335aa98c94f0c4.mp3", "hash": "c342cfe787b7dac4ac0caac290ce7becefb921f4b1c463ccdd7b03c4a1c75619", "bytes": 27216, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/1d0adea9190c84dfe748697eccce8ae6da6db01ffb681ec69d335aa98c94f0c4.mp3", "duration_ms": 4480}, "s1-odd-ingredient.prompt": {"url": "http://localhost:4006/files/lesson-audio/dfcb9bf27e54f651d153db930c9f2ea389621b5d55252b5c927d7eb3ebdc9da2.mp3", "hash": "534a674f2e5ccc9901d6995daa28378453964113921af9521274afdf693f0799", "bytes": 32976, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/dfcb9bf27e54f651d153db930c9f2ea389621b5d55252b5c927d7eb3ebdc9da2.mp3", "duration_ms": 5440}, "s1-odd-ingredient.choices": {"url": "http://localhost:4006/files/lesson-audio/65a425c0d5f11ccc84234727e8b25c73f987d84bf67b084f24603d6428838fd2.mp3", "hash": "b5ba5173a71400fbd7c728712c602b49ab782785d5cb1615058e22dfb4e79ae3", "bytes": 27216, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/65a425c0d5f11ccc84234727e8b25c73f987d84bf67b084f24603d6428838fd2.mp3", "duration_ms": 4480}, "s1-odd-ingredient.explanation": {"url": "http://localhost:4006/files/lesson-audio/39592c2bae3b071de90c19fe9d770e6b1af9615d1f2501a605b98e398a72a447.mp3", "hash": "3f00a1edf8c7188d9423825d3bc0693d8885020e449277cc7b355c12193dcec3", "bytes": 60768, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/39592c2bae3b071de90c19fe9d770e6b1af9615d1f2501a605b98e398a72a447.mp3", "duration_ms": 10080}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ea98847f-02a1-4527-97a4-36921728b56d', 'en-US', '1', '{"meta": {"cast": ["liruf"], "slug": "cause-effect", "title": "Cause and effect at the lemonade stand", "locale": "en-US", "subject": "mixed", "objectives": ["Connecting causes and effects at the stand: understanding that a sunny day leads to more sales and that raising the price can reduce customers."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "cause-effect-1", "xp": 15, "type": "cause_effect", "hints": ["Think: Why did the customers come? What did Liruf do upon seeing them?"], "title": "Cause and effect at the stand", "payload": {"slots": 5, "events": [{"id": "ev1", "text_md": "The sun is very strong."}, {"id": "ev2", "text_md": "Many customers arrive at the stand."}, {"id": "ev3", "text_md": "Liruf decides to charge more."}, {"id": "ev4", "text_md": "The lemonade costs 10 dollars."}, {"id": "ev5", "text_md": "Liruf sells few glasses."}]}, "narrator": {"emotion": "neutral", "character": "liruf"}, "prompt_md": "Liruf wants to discover the secret reason for their sales. Order the events to form the cause and effect chain.", "difficulty": 2, "explanation_md": "The strong sun brings the customers. When selling a lot, Liruf decided to raise the price, but that made them sell less. If you mixed up the causes, review what causes each effect.", "audio_segment_id": "cause-effect-1.prompt"}], "schema_version": 1}', '{"cause-effect-1": {"chain": ["ev1", "ev2", "ev3", "ev4", "ev5"]}}', '{"units": {"cause-effect-1.hint.0": {"url": "http://localhost:4006/files/lesson-audio/67c39762caec10d394d114e5b2d3947138a6b488b88c8ceb0dc3dffba261143b.mp3", "hash": "e02601ded91353424c37fca7cf939c6c715776203937b50d59a215d03fdf139b", "bytes": 26208, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/67c39762caec10d394d114e5b2d3947138a6b488b88c8ceb0dc3dffba261143b.mp3", "duration_ms": 4320}, "cause-effect-1.prompt": {"url": "http://localhost:4006/files/lesson-audio/0bdb4facae8036e1ea4ad4170f3b20541de94ff99e2a5ff1c01c70de18da6ea7.mp3", "hash": "77596a1090a34ebde18a0c307ea38b259a44f16120dbb73372e8501148d3d680", "bytes": 39744, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/0bdb4facae8036e1ea4ad4170f3b20541de94ff99e2a5ff1c01c70de18da6ea7.mp3", "duration_ms": 6560}, "cause-effect-1.explanation": {"url": "http://localhost:4006/files/lesson-audio/f65a62a69d91ba87660b22145b030c538b94a619acb0f7da2857b56e9f3754cc.mp3", "hash": "f4a5d042d33e9a91112550a20b63b70dc5bf3207be7724a3cd57f2bf82e1bada", "bytes": 63648, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/f65a62a69d91ba87660b22145b030c538b94a619acb0f7da2857b56e9f3754cc.mp3", "duration_ms": 10560}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('99bea18a-9bc0-4fca-91fe-aa5b44c0ea6e', 'pt-BR', '1', '{"meta": {"cast": ["liruf", "dina", "rho", "zara"], "slug": "picture-choice", "title": "O lugar mais seguro para o dinheiro", "locale": "pt-BR", "subject": "money", "objectives": ["Escolher o lugar mais seguro para guardar os lucros do dia"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-lugar-seguro", "xp": 10, "type": "picture_choice", "hints": ["Procure um lugar que tenha cadeado ou chave.", "Em qual desses lugares o dinheiro não pode cair nem ser pego por outros?"], "title": "Onde guardar o dinheiro?", "payload": {"options": [{"id": "alcancia", "icon": "savings", "label": "Cofrinho com chave", "image_url": "http://localhost:4006/files/lesson-images/9681bc52834c92a8becdd0f2853e569f8a065b99bd2ee43b8bdacc1f103ff2d3.webp"}, {"id": "bolsillo", "icon": "checkroom", "label": "Bolso furado", "image_url": "http://localhost:4006/files/lesson-images/4e2abf237219b8117084640a1b04964166d8a54edd652fb5fcf751357019ea9b.webp", "rationale_md": "O bolso furado tem um buraco: as moedas caem e se perdem."}, {"id": "mesa", "icon": "table_restaurant", "label": "Mesa da barraca", "image_url": "http://localhost:4006/files/lesson-images/c7a7477fa0d906300135e0eb029415c13f98959267fe79c5560159025bd2faee.webp", "rationale_md": "A mesa da barraca está à vista de todos: qualquer um pode pegar o dinheiro."}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf terminou de vender. Onde ele guarda o dinheiro para ficar mais seguro?", "difficulty": 1, "explanation_md": "O cofrinho com chave protege o dinheiro de quedas e de pessoas estranhas. O bolso furado deixa as moedas caírem e a mesa da barraca deixa o dinheiro à vista de todos.", "audio_segment_id": "s1-lugar-seguro.prompt"}], "schema_version": 1}', '{"s1-lugar-seguro": {"correct_option_id": "alcancia"}}', '{"units": {"s1-lugar-seguro.hint.0": {"url": "http://localhost:4006/files/lesson-audio/46f0fcb57bef9b72275248f7a9ab261fd941bb871c2b5ed85ecc92ed80416cfb.mp3", "hash": "183b796ea3f891f89444a1db14f9d2092c5574f93bca65f50f39b103f0d904ba", "bytes": 17136, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/46f0fcb57bef9b72275248f7a9ab261fd941bb871c2b5ed85ecc92ed80416cfb.mp3", "duration_ms": 2800}, "s1-lugar-seguro.hint.1": {"url": "http://localhost:4006/files/lesson-audio/b6f98c4c6c83d06512b952fd938462c00edb25f93b11c258f25edb0a444cdd02.mp3", "hash": "f6e39d67ac9bc6daae709ee0dcb768ede99a7671b4c2fe083d47be420cc869f8", "bytes": 29088, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/b6f98c4c6c83d06512b952fd938462c00edb25f93b11c258f25edb0a444cdd02.mp3", "duration_ms": 4800}, "s1-lugar-seguro.prompt": {"url": "http://localhost:4006/files/lesson-audio/a871ea889420dce62f5a556c36de2caaced93f2e9d71a1de5439d921790b92ae.mp3", "hash": "667b5610f2c2937199d089537ba5a96e38e1a666c18b62c32350b54bef691ee4", "bytes": 32976, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/a871ea889420dce62f5a556c36de2caaced93f2e9d71a1de5439d921790b92ae.mp3", "duration_ms": 5440}, "s1-lugar-seguro.choices": {"url": "http://localhost:4006/files/lesson-audio/c92ee5425143ba0c6ab23ef87525e5da29e590255cf5806c96ace905005aef44.mp3", "hash": "7d104123a6d68ded4a1247d48431c8474b2180e6c95cef249ac77132f7b70187", "bytes": 26784, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/c92ee5425143ba0c6ab23ef87525e5da29e590255cf5806c96ace905005aef44.mp3", "duration_ms": 4400}, "s1-lugar-seguro.explanation": {"url": "http://localhost:4006/files/lesson-audio/6ff47449e471b71c3df778d101a533f5eab5a941c98d7a8a0eba569a425dfa20.mp3", "hash": "d61d1e6067fb5c543e27c48e05c3208e6ae5fa317e77b6ce24cd2a69223529e5", "bytes": 69984, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/6ff47449e471b71c3df778d101a533f5eab5a941c98d7a8a0eba569a425dfa20.mp3", "duration_ms": 11600}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8f1a89c3-ae63-41f5-a2fa-70d1b7c6aac9', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "coin-count", "title": "Contando moedas para a venda", "locale": "pt-BR", "subject": "mixed", "objectives": ["Practicar a contagem de moedas brasileiras de 1 e 2 reais para formar 5 reais exatos."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-coin-count", "xp": 5, "type": "coin_count", "title": "Juntando os 5 reais", "payload": {"target": 5, "currency": "BRL", "denominations": [1, 2]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/c6bcd2467caabd3515b104ec6c6d1060b03dec05d04c1c0d779562e3dd9cce68.webp", "prompt_md": "Liruf vendeu um copo de 5 reais. Use moedas de 1 e 2 para juntar 5 reais exatos.", "difficulty": 1, "explanation_md": "Liruf agora sabe que 5 reais podem ser formados com moedas de 1 e 2. Contar bem cada pagamento é importante para alcançar sua meta de 80 reais.", "audio_segment_id": "s1-coin-count.prompt"}], "schema_version": 1}', '{"s1-coin-count": {}}', '{"units": {"s1-coin-count.prompt": {"url": "http://localhost:4006/files/lesson-audio/79a9d071d2883ea874057c6415335846bed0496b50438c78c7386de109a80e29.mp3", "hash": "e829a0b5192a44db7e924d0642406075e2fc2dfd454bd4360f6364f39787517e", "bytes": 45504, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/79a9d071d2883ea874057c6415335846bed0496b50438c78c7386de109a80e29.mp3", "duration_ms": 7520}, "s1-coin-count.explanation": {"url": "http://localhost:4006/files/lesson-audio/2a7b26288a232830efb76d5c00c8794f922a5fc99c5a85b28abb20b565ba2771.mp3", "hash": "93f69cf916ac54f5142d6a8cdf14896d2bed2148d5a39a4ea3814f5920b16271", "bytes": 65664, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/2a7b26288a232830efb76d5c00c8794f922a5fc99c5a85b28abb20b565ba2771.mp3", "duration_ms": 10880}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('36624bae-eea6-49e3-8767-c43ffbdf09e7', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "compare-table", "title": "Compare preços de limões", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ler uma tabela comparativa de fornecedores e escolher a melhor opção."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-compare-table", "xp": 5, "type": "compare_table", "hints": ["Pense: qual dos dois vende mais barato os mesmos limões? Preste atenção nos preços."], "title": "Compare fornecedores", "payload": {"cols": [{"id": "precio", "label": "Preço por 10 limões"}, {"id": "mejor", "label": "Melhor opção?"}], "rows": [{"id": "lula", "label": "Dona Lula"}, {"id": "pepe", "label": "Seu Pepe"}], "tokens": [{"id": "t1", "text_md": "5 reais"}, {"id": "t2", "text_md": "6 reais"}, {"id": "t3", "text_md": "Sim"}, {"id": "t4", "text_md": "Não"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/1d5c1aee8dc2f9530f5bf4403f4a40c3f25cbefe9d806e3e9467383e3c903aeb.webp", "prompt_md": "Dona Lula: 10 limões por 5 reais. Seu Pepe: 10 limões por 6 reais. Complete a tabela e toque em ''Sim'' ou ''Não'' para a melhor opção.", "difficulty": 1, "explanation_md": "Dona Lula cobra 5 reais por 10 limões, menos que os 6 reais do Seu Pepe. Assim você obtém mais limões pelo seu dinheiro!", "audio_segment_id": "s1-compare-table.prompt"}], "schema_version": 1}', '{"s1-compare-table": {"cells": {"lula:mejor": "t3", "pepe:mejor": "t4", "lula:precio": "t1", "pepe:precio": "t2"}}}', '{"units": {"s1-compare-table.hint.0": {"url": "http://localhost:4006/files/lesson-audio/a0ee4ec20abc3ba1f1af2666918bfd39009ae5147bc7b19c1f11114384ad26b1.mp3", "hash": "f11420a454753a718f16a15302d095d860953cca84538d9bd0ed033c4e9ba829", "bytes": 40608, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/a0ee4ec20abc3ba1f1af2666918bfd39009ae5147bc7b19c1f11114384ad26b1.mp3", "duration_ms": 6720}, "s1-compare-table.prompt": {"url": "http://localhost:4006/files/lesson-audio/b8ce0af63185e493c09035f35bf28f94eeb79fa440a39654f27bed8109c54795.mp3", "hash": "1af68911890bf6d385fa585b669bee1e4e1aaf7118105e20753488e51afed071", "bytes": 68544, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/b8ce0af63185e493c09035f35bf28f94eeb79fa440a39654f27bed8109c54795.mp3", "duration_ms": 11360}, "s1-compare-table.explanation": {"url": "http://localhost:4006/files/lesson-audio/fe04317d37696233d5cb4ed27a7fb7d8169554ba8cb4868b0ffea86e223b8f72.mp3", "hash": "35ad47f163ca1d3037ecc81f6092568b26932d6e2e6614beac7db959e45f57e4", "bytes": 61344, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/fe04317d37696233d5cb4ed27a7fb7d8169554ba8cb4868b0ffea86e223b8f72.mp3", "duration_ms": 10160}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('64ccde87-2312-4acf-a950-409fd6a622c9', 'en-US', '1', '{"meta": {"cast": ["zara"], "slug": "read-chart", "title": "The best sales day", "locale": "en-US", "subject": "mixed", "objectives": ["Read the bar chart of cups sold per day and answer which was the best day of the week."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "read-chart-1", "xp": 10, "type": "read_chart", "hints": ["Each bar shows the cups sold that day. Look at the height."], "title": "Zara''s chart", "payload": {"chart": {"kind": "bar", "unit": "vasos", "series": [{"label": "Cups sold", "points": [{"x": "Mon", "y": 8}, {"x": "Tue", "y": 12}, {"x": "Wed", "y": 5}, {"x": "Thu", "y": 15}, {"x": "Fri", "y": 10}]}]}, "questions": [{"id": "q1", "options": [{"id": "lunes", "text_md": "Monday"}, {"id": "martes", "text_md": "Tuesday"}, {"id": "miercoles", "text_md": "Wednesday"}, {"id": "jueves", "text_md": "Thursday"}, {"id": "viernes", "text_md": "Friday"}], "prompt_md": "Which day sold the most cups?"}]}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "Zara made a bar chart of the cups sold.", "difficulty": 1, "explanation_md": "On Thursday, 15 cups were sold, the highest amount. The tallest bar indicates the best sales day.", "audio_segment_id": "read-chart-1.prompt"}], "schema_version": 1}', '{"read-chart-1": {"correct": {"q1": "jueves"}}}', '{"units": {"read-chart-1.hint.0": {"url": "http://localhost:4006/files/lesson-audio/4f0b45f0a5d5d2b22d5cff134fbcf5b27d17976c14e1716b39f0e3a4a2322936.mp3", "hash": "6d3f8beb8976bbe55dea972275d083956ee6f29238af49d2061646760981fd73", "bytes": 24336, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/4f0b45f0a5d5d2b22d5cff134fbcf5b27d17976c14e1716b39f0e3a4a2322936.mp3", "duration_ms": 4000}, "read-chart-1.prompt": {"url": "http://localhost:4006/files/lesson-audio/cbb81a733208a26d4a91e3fdf734c66f6f24f170a34cc590926f6e6440163681.mp3", "hash": "e35e2dfc06f489a51a891924a23544002c745a06b43aa67f9087f1dfec8f9478", "bytes": 15696, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/cbb81a733208a26d4a91e3fdf734c66f6f24f170a34cc590926f6e6440163681.mp3", "duration_ms": 2560}, "read-chart-1.explanation": {"url": "http://localhost:4006/files/lesson-audio/28f431a75b5d156469edce42ea85fe2b9c301b05c814b8baaccdc192be28b288.mp3", "hash": "01d9747f65bcff52688c597570a89f88f65019f621ea2b7487ff275acae45f8a", "bytes": 43056, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/28f431a75b5d156469edce42ea85fe2b9c301b05c814b8baaccdc192be28b288.mp3", "duration_ms": 7120}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('59260361-67d7-4d0e-9c68-8c5e00637103', 'pt-BR', '1', '{"meta": {"cast": ["liruf"], "slug": "price-compare", "title": "Comparar preços de limões", "locale": "pt-BR", "subject": "mixed", "objectives": ["Comparar preços de limões em duas barracas e escolher o mais barato para gastar menos (custo mais baixo = mais lucro)."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-price-compare", "xp": 5, "type": "price_compare", "hints": ["Veja quantos reais custa cada oferta e escolha a mais barata."], "title": "Limões mais baratos!", "payload": {"offers": [{"id": "puesto-a", "qty": 6, "unit": "limones", "label": "Limões Barraca A", "price": 10, "image_url": "http://localhost:4006/files/lesson-images/a76575c3a8abb5991c47ae579577d8996a3ea60d28542df6d2fccda9f3962d2c.webp"}, {"id": "puesto-b", "qty": 6, "unit": "limones", "label": "Limões Barraca B", "price": 12, "image_url": "http://localhost:4006/files/lesson-images/79350f99a6e6eef17b6c299504931b4917d38a6287cbcdf65df5504ea4f98ef6.webp"}], "currency": "BRL"}, "narrator": {"emotion": "encouraging", "character": "liruf"}, "prompt_md": "Depois de separar as necessidades, duas barracas vendem limões. Toque a oferta que gasta menos dinheiro.", "difficulty": 1, "explanation_md": "Os limões da Barraca A custam 10 reais, menos que os 12 reais da Barraca B. Escolher a mais barata deixa mais dinheiro para a meta da guitarra.", "audio_segment_id": "s1-price-compare.prompt"}], "schema_version": 1}', '{"s1-price-compare": {"best_offer_id": "puesto-a"}}', '{"units": {"s1-price-compare.hint.0": {"url": "http://localhost:4006/files/lesson-audio/df30471764c3fc2b0be57a128914582d3a59b1c91bb73ad8d85ce1b9fa22830c.mp3", "hash": "f534f2cf83dfd13a316f1e350f7b0b942aae1ed1924c3c3c3e0e69a9f4e1f03b", "bytes": 27648, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/df30471764c3fc2b0be57a128914582d3a59b1c91bb73ad8d85ce1b9fa22830c.mp3", "duration_ms": 4560}, "s1-price-compare.prompt": {"url": "http://localhost:4006/files/lesson-audio/3abf4db479bd2f12fd16da3bf6a61f62d4d74ecab320da97f2275132ded35fed.mp3", "hash": "617676bdbafa8686b128bccd3f26bd46a965af177e1b6016d040a4772e770c6b", "bytes": 43488, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/3abf4db479bd2f12fd16da3bf6a61f62d4d74ecab320da97f2275132ded35fed.mp3", "duration_ms": 7200}, "s1-price-compare.explanation": {"url": "http://localhost:4006/files/lesson-audio/d41f11f9959b2df5249fd727bcf73ef17b553724e9428b7f33799d0a6e31be39.mp3", "hash": "8f9fcd0ab823761a797cf19c3487234ee5ea94291adb39df0ad27763a65e487d", "bytes": 61776, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/d41f11f9959b2df5249fd727bcf73ef17b553724e9428b7f33799d0a6e31be39.mp3", "duration_ms": 10240}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b979bce6-8935-480e-8471-33053faa2321', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "sort-buckets", "title": "Classifique as compras da barraca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Classificar compras em necessidades da barraca e desejos que podem esperar"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-clasifica", "xp": 10, "type": "sort_buckets", "hints": ["Necessidade é o que a barraca precisa para vender limonada: limões, copos, gelo.", "Desejo é algo que você gosta, mas não é urgente: adesivos, balões, brinquedos."], "title": "Necessidade ou desejo", "payload": {"items": [{"id": "limones", "text_md": "Limões", "image_url": "http://localhost:4006/files/lesson-images/b0ac1e89fa30646757ee9125d576bd24d38814cb88bbf0c75f837bec4b6bc59c.webp"}, {"id": "vasos", "text_md": "Copos", "image_url": "http://localhost:4006/files/lesson-images/210a051b4acc4c2f99683273be4f19e8f081bd54a90eca34ac30675a8813c476.webp"}, {"id": "stickers", "text_md": "Adesivos", "image_url": "http://localhost:4006/files/lesson-images/86bcf6772328c59781d6b3c6451c68ab9902fd746d5ae19472f4e1165ca16679.webp"}, {"id": "globos", "text_md": "Balões"}], "buckets": [{"id": "necesidad", "label": "Necessidade da barraca"}, {"id": "gusto", "label": "Desejo que pode esperar"}]}, "narrator": {"emotion": "excited", "character": "dina"}, "prompt_md": "Toque em cada compra e coloque no balde correto: necessidade da barraca ou desejo que pode esperar.", "difficulty": 1, "explanation_md": "Os limões e copos são necessidades da barraca para fazer e servir limonada. Os adesivos e balões são desejos que podem esperar.", "audio_segment_id": "s1-clasifica.prompt"}], "schema_version": 1}', '{"s1-clasifica": {"assignments": {"vasos": "necesidad", "globos": "gusto", "limones": "necesidad", "stickers": "gusto"}}}', '{"units": {"s1-clasifica.hint.0": {"url": "http://localhost:4006/files/lesson-audio/2794ddaafc1bd5acbfbfa1615369f06e2d46077c2a1d7be55b041ae1dee18d19.mp3", "hash": "2af91c9e5e7c2de711dcf0ffbfbd63664c54e226c7d19ce0396428e9b97934f9", "bytes": 36864, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/2794ddaafc1bd5acbfbfa1615369f06e2d46077c2a1d7be55b041ae1dee18d19.mp3", "duration_ms": 6080}, "s1-clasifica.hint.1": {"url": "http://localhost:4006/files/lesson-audio/8770eb1c5d3ef583fae1618437af6108b48014a3b61055d6b78594285052913b.mp3", "hash": "ffee33e41f842aa629eb32c0d75ad55a190ee4e9a61a17234b0b98f56e5072ef", "bytes": 46368, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/8770eb1c5d3ef583fae1618437af6108b48014a3b61055d6b78594285052913b.mp3", "duration_ms": 7680}, "s1-clasifica.prompt": {"url": "http://localhost:4006/files/lesson-audio/b21d7a3eacd26db31aa6bd34339c2354b841e16176400c77416487f62fc759f2.mp3", "hash": "65be7dd1a3401f4033922da45d5c34418c021bbe9cdbb7d3414a2493f813d463", "bytes": 44064, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/b21d7a3eacd26db31aa6bd34339c2354b841e16176400c77416487f62fc759f2.mp3", "duration_ms": 7280}, "s1-clasifica.explanation": {"url": "http://localhost:4006/files/lesson-audio/773b4c69d8d7b43326ac539fd3bbdf0aa4a0df969e01028a07f7f3fe9607c319.mp3", "hash": "7052cbd706c36675b56bd6266f258d729f68086ca88a004f3d98a9c943e10cee", "bytes": 52704, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/773b4c69d8d7b43326ac539fd3bbdf0aa4a0df969e01028a07f7f3fe9607c319.mp3", "duration_ms": 8720}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4a340725-6bd9-48c4-9c1a-d8641c86b7a1', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "evidence-hunt", "title": "Quanto custaram os limões?", "locale": "pt-BR", "subject": "mixed", "objectives": ["Procurar no recibo do mercado a evidência exata de quanto custaram os limões."], "estimated_minutes": 5}, "scoring": {"hearts": 3, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-evidence-hunt", "xp": 0, "type": "evidence_hunt", "title": "O recibo do mercado", "payload": {"claim_md": "Os limões custaram 10 reais.", "sentences": [{"id": "s1", "text_md": "Limões - R$10"}, {"id": "s2", "text_md": "Copos - R$5"}, {"id": "s3", "text_md": "Gelo - R$3"}, {"id": "s4", "text_md": "Açúcar - R$2"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/cb9248ff387ceb31ad25329ccf8710063a66fa4019f7f28c27f1a348c15a4f44.webp", "prompt_md": "Liruf precisa saber quanto custaram os limões. Toque na linha do recibo que tem a resposta.", "difficulty": 1, "explanation_md": "Os limões custaram 10 reais, exatamente o que mostra o recibo na linha ''Limões - R$10''. Assim Liruf pode verificar seus gastos!"}], "schema_version": 1}', '{"s1-evidence-hunt": {"evidence_ids": ["s1"]}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0c46648e-ff7a-4ad4-bf42-5829cc3fd1ac', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "story-dialogue", "title": "Ganhar dinheiro começa com uma ideia", "locale": "pt-BR", "subject": "mixed", "objectives": ["Descobrir que o dinheiro pode ser ganho oferecendo algo que os outros querem", "Identificar uma meta clara (violão de 80 reais) como motivação para começar"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-dialogue", "xp": 0, "type": "story_dialogue", "title": "A ideia de Dina", "payload": {"lines": [{"action": "idle", "emotion": "thinking", "text_md": "Olha o violão de 80 reais… é muito legal, mas não tenho dinheiro.", "character": "liruf"}, {"action": "idle", "emotion": "excited", "text_md": "E se você ganhar ele sozinho? Poderia vender limonada na sua rua.", "character": "dina"}, {"action": "idle", "emotion": "surprised", "text_md": "Vender limonada? E as pessoas me pagariam?", "character": "liruf"}, {"action": "idle", "emotion": "encouraging", "text_md": "Claro. Cada copo a 5 reais. Se vender 16 copos, você tem os 80!", "character": "dina"}, {"action": "idle", "emotion": "thinking", "text_md": "16 copos… quantos são? Será que dá?", "character": "liruf"}, {"action": "idle", "emotion": "happy", "text_md": "Pense: 5 reais cada um. Quantos você precisa para juntar 80?", "character": "dina"}, {"action": "idle", "emotion": "happy", "text_md": "Sim! Vou montar uma barraca neste sábado.", "character": "liruf"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/d4d8e4ce8716430a6f4716c3b8337e4a51db670b47a9ad3c1260c647493a5365.webp", "prompt_md": "Liruf e Dina conversam em frente à loja de música.", "difficulty": 1, "audio_segment_id": "s1-dialogue.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-dialogue.line.0": {"url": "http://localhost:4006/files/lesson-audio/bce7b76c40b00af893114735d72981c9e7742e2356033a47a9826f4fb8c260a0.mp3", "hash": "d01d43a6980217e5499961a16e715fec51b431754cfa4a6c2935d5dcde828690", "bytes": 31536, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/bce7b76c40b00af893114735d72981c9e7742e2356033a47a9826f4fb8c260a0.mp3", "duration_ms": 5200}, "s1-dialogue.line.1": {"url": "http://localhost:4006/files/lesson-audio/5dc3b2fd076927da771d3b681f95abfd569503616b4d6e6c3401bcd87e636be5.mp3", "hash": "65aabe1ff4ef3c451def731c303401d9e2a93f127d009845e5c51ae2a8067721", "bytes": 31968, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/5dc3b2fd076927da771d3b681f95abfd569503616b4d6e6c3401bcd87e636be5.mp3", "duration_ms": 5280}, "s1-dialogue.line.2": {"url": "http://localhost:4006/files/lesson-audio/7bd7720d55abc0f7aa0a99153a0fa778ed9afda8c1beaaae7bfb5cfcbb138c71.mp3", "hash": "a34ee9c987388481279a374004b77eb86c81b3fd6404c125f332114f81069275", "bytes": 21456, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/7bd7720d55abc0f7aa0a99153a0fa778ed9afda8c1beaaae7bfb5cfcbb138c71.mp3", "duration_ms": 3520}, "s1-dialogue.line.3": {"url": "http://localhost:4006/files/lesson-audio/b9413e4a1c38bc4cff37c1af2de4c4bb2d57623ef42fa5d4db7527a0ed03a691.mp3", "hash": "29fcd412c2a160ed125ed3dd1fb5e4331bf419a628e821917a16f2ee3116fce8", "bytes": 42048, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/b9413e4a1c38bc4cff37c1af2de4c4bb2d57623ef42fa5d4db7527a0ed03a691.mp3", "duration_ms": 6960}, "s1-dialogue.line.4": {"url": "http://localhost:4006/files/lesson-audio/5db1de2df1f052a505a93bc9ccb6f31d282f86bf923fabb4bba368c225e06d3c.mp3", "hash": "ffadf62e7f8a5771ebc006d50371c0e5b40db9363c226434da850686c6fc0e0e", "bytes": 23328, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/5db1de2df1f052a505a93bc9ccb6f31d282f86bf923fabb4bba368c225e06d3c.mp3", "duration_ms": 3840}, "s1-dialogue.line.5": {"url": "http://localhost:4006/files/lesson-audio/65c4c63664d865e048d03d3d9feae719ede6a1ff32765cc2af8d0b7dcfb3aa47.mp3", "hash": "8c24a2cf948bba5ba36fd42a8e6c5624e22055a10441064e014d9eea39f16ec9", "bytes": 34416, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/65c4c63664d865e048d03d3d9feae719ede6a1ff32765cc2af8d0b7dcfb3aa47.mp3", "duration_ms": 5680}, "s1-dialogue.line.6": {"url": "http://localhost:4006/files/lesson-audio/391ba250fb0ee78de71344cba46ed199721d18621b0810899f5678361252d009.mp3", "hash": "c5b0e9298e8d1eb6e35437c85a4dc93e9753665e453dfb5186e2ecbcb1d4abcf", "bytes": 19584, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/391ba250fb0ee78de71344cba46ed199721d18621b0810899f5678361252d009.mp3", "duration_ms": 3200}, "s1-dialogue.prompt": {"url": "http://localhost:4006/files/lesson-audio/940ea3558e9c1827b416be8df2d58d0bdae6a8076bf7dd1ff1bdfc8363767181.mp3", "hash": "309c714607e99c33e407e91061fa2ddfc3771cbc51c0816262fe9279090620fd", "bytes": 23904, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/940ea3558e9c1827b416be8df2d58d0bdae6a8076bf7dd1ff1bdfc8363767181.mp3", "duration_ms": 3920}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9bdad6a7-ed32-42f2-83c9-554afe044403', 'es-MX', '1', '{"meta": {"cast": ["liruf", "rho"], "slug": "savings-goal", "title": "Meta de ahorro: La guitarra de Liruf", "locale": "es-MX", "subject": "mixed", "objectives": ["Calcular cuántas semanas se necesitan para alcanzar una meta de ahorro dividiendo el costo total entre el ahorro semanal", "Comparar diferentes planes de ahorro para alcanzar una meta en un plazo determinado"], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-guitar-savings", "xp": 15, "type": "savings_goal", "hints": ["Divide 80 pesos entre la cantidad que apartas cada semana.", "Por ejemplo, si apartas 10 pesos, ¿cuántas veces cabe 10 en 80?"], "title": "El plan de ahorro de Liruf", "payload": {"goal": 80, "currency": "MXN", "weekly_options": [10, 20, 40]}, "narrator": {"emotion": "happy", "character": "rho"}, "prompt_md": "Liruf quiere la guitarra de 80 pesos. ¿Cuántas semanas necesita si aparta 10, 20 o 40 pesos por semana?", "difficulty": 2, "explanation_md": "Apartar más cada semana acorta la espera. Con 40 pesos, Liruf alcanza la guitarra en 2 semanas, justo a tiempo para el concurso.", "audio_segment_id": "s1-guitar-savings.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-guitar-savings.hint.0": {"url": "http://localhost:4006/files/lesson-audio/9968a24b92ff8a9edf29450f072ed6cfaab319d6c5810f8fa55b40bb43f0f713.mp3", "hash": "1d40ad40f7930fbe612f7e35e03d4ad03f38f9f20178e1be2e0b5ec7963923a3", "bytes": 28656, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/9968a24b92ff8a9edf29450f072ed6cfaab319d6c5810f8fa55b40bb43f0f713.mp3", "duration_ms": 4720}, "s1-guitar-savings.hint.1": {"url": "http://localhost:4006/files/lesson-audio/7ea2f95099c0174f2ba37a0b76bfd27381a394665249f12e0f1bfbcfc236c4dd.mp3", "hash": "4bacf75dd42781d3ce0a728dccc8c49c9dd0312423f1914e3137a3fb634d5eab", "bytes": 31968, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/7ea2f95099c0174f2ba37a0b76bfd27381a394665249f12e0f1bfbcfc236c4dd.mp3", "duration_ms": 5280}, "s1-guitar-savings.prompt": {"url": "http://localhost:4006/files/lesson-audio/7d5fa1f5a4346ff15cabad69b44962089b2b76b5f3b23dfb0353daa91682789d.mp3", "hash": "fb2c83dbfc95bd08d689683db1ab9e2140469fd144052824f2163918a341f1cc", "bytes": 48816, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/7d5fa1f5a4346ff15cabad69b44962089b2b76b5f3b23dfb0353daa91682789d.mp3", "duration_ms": 8080}, "s1-guitar-savings.explanation": {"url": "http://localhost:4006/files/lesson-audio/18815c2f8498f9ca822a08516ba0baba08e7b7fb6d4fd55b377ec768ae8667d8.mp3", "hash": "6b0c939d995829540a9378f52903141c7940a768d5cac967d08d56ca7593cac0", "bytes": 57888, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/18815c2f8498f9ca822a08516ba0baba08e7b7fb6d4fd55b377ec768ae8667d8.mp3", "duration_ms": 9600}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a00c4534-6e88-42ac-ab77-3465a684f47d', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "story-scene", "title": "Liruf''s Plan", "locale": "en-US", "subject": "mixed", "objectives": ["Understand that money is earned by offering something others want", "See that a clear goal helps you get started"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-plan", "xp": 0, "type": "story_scene", "title": "Liruf''s Plan", "payload": {"art": {"icon": "emoji_objects", "tint": "primary", "image_url": "http://localhost:4006/files/lesson-images/08b5a3b871bfad8c36ab6907e399814ccb1c2e5c66a405ff4dde7294536342fc.webp"}, "action": "idle", "body_md": "Liruf draws his plan on a poster: one glass of lemonade = 5 dollars. Many glasses = an 80-dollar guitar. But… how many glasses does he need to sell? Look! If he sells 2 glasses, he earns 10 dollars. He''s already making progress! How many glasses for 80 dollars? We''ll solve it together!", "emotion": "excited", "backdrop": "band", "character": "liruf"}, "narrator": {"emotion": "excited", "character": "liruf"}, "prompt_md": "Each glass of lemonade costs 5 dollars. Liruf needs 80 dollars for the guitar.", "difficulty": 1, "audio_segment_id": "s1-plan.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-plan.body": {"url": "http://localhost:4006/files/lesson-audio/74ba64abf5f5131b5bbed1e9f8d57ca8b1f6a1a003cc713b33be7a6fd3350b90.mp3", "hash": "7e03d6a775bb62595370a4dd54b2e0e67dcb8182a7cd12ec1630cb815501bfab", "bytes": 103104, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/74ba64abf5f5131b5bbed1e9f8d57ca8b1f6a1a003cc713b33be7a6fd3350b90.mp3", "duration_ms": 17120}, "s1-plan.prompt": {"url": "http://localhost:4006/files/lesson-audio/5e73357ffcc1842af49d3a71c03a5dadb35b99ae9b5d285a9a3fa908083e3c09.mp3", "hash": "ffde9475f91b0193e97c581df8ea81fc9602a17298f37fa9014d1e673c889452", "bytes": 31968, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/5e73357ffcc1842af49d3a71c03a5dadb35b99ae9b5d285a9a3fa908083e3c09.mp3", "duration_ms": 5280}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('881ae1da-74af-4378-a3cd-da8a9bc0e6b2', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "key-ideas", "title": "The three golden rules of the little seller", "locale": "en-US", "subject": "mixed", "objectives": ["Understand that money is earned by offering something others want", "Identify a clear goal (80 dollars) to start selling", "Recognize that saving what you earn helps reach the goal"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-key-ideas", "xp": 0, "type": "key_ideas", "hints": [], "title": "The three golden rules", "payload": {"ideas": [{"icon": "flag", "title": "Goal: 80 dollars", "body_md": "Liruf wants a guitar that costs **80 dollars**. That''s his goal.", "image_url": "http://localhost:4006/files/lesson-images/bacdcf9b011e412976e4fe8d9d1852d36406dbd0f101a1724a07ba57885f6125.webp"}, {"icon": "storefront", "title": "Offer something they want", "body_md": "He will sell **cold lemonade** in the neighborhood. Everyone likes it!", "image_url": "http://localhost:4006/files/lesson-images/6f72aafa39c8619540ef14848999bc2f3192d186f8da138a6a04cc47f4ee0e93.webp"}, {"icon": "savings", "title": "Save what you earn", "body_md": "Each cup costs **5 dollars**. By saving everything, he will reach 80.", "image_url": "http://localhost:4006/files/lesson-images/ddac2cd1d5b00cba96b6ca522a52b3c8790b19b1972d64761b4f06f4db5b7aad.webp"}]}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Rho wrote on her whiteboard the 3 rules for selling lemonade and buying the 80-dollar guitar. Tap each idea to read it.", "difficulty": 1, "explanation_md": "The three rules are: have a goal of 80 dollars, offer cold lemonade that people want, and save what you earn. That''s how Liruf will get his guitar!", "audio_segment_id": "s1-key-ideas.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-key-ideas.idea.0": {"url": "http://localhost:4006/files/lesson-audio/1405815957d619ffa95280c1960e826ee32f7e77a1c450428fac46ff1bbaf302.mp3", "hash": "93a19a6c848810fbe9fdfc5207cca6767424b171317f16c27b6cc12c04e5f6e7", "bytes": 26208, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/1405815957d619ffa95280c1960e826ee32f7e77a1c450428fac46ff1bbaf302.mp3", "duration_ms": 4320}, "s1-key-ideas.idea.1": {"url": "http://localhost:4006/files/lesson-audio/a28b7d0570993f144b24bcb19a054a05d48dd16c248ffff8ba400ed6aed1293a.mp3", "hash": "e371ef33a55f07be7347302d388ec84ef831f2ec8c10ca85f429a4c5166364e2", "bytes": 24336, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/a28b7d0570993f144b24bcb19a054a05d48dd16c248ffff8ba400ed6aed1293a.mp3", "duration_ms": 4000}, "s1-key-ideas.idea.2": {"url": "http://localhost:4006/files/lesson-audio/e139b0c528971298ab3ca7692d4882c29f20c188f02ea6cd6e13f6af5156570d.mp3", "hash": "8746dab618bb68473c5fdd99b38dcb75057b4fdc96901f973807612050261ac0", "bytes": 34848, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/e139b0c528971298ab3ca7692d4882c29f20c188f02ea6cd6e13f6af5156570d.mp3", "duration_ms": 5760}, "s1-key-ideas.prompt": {"url": "http://localhost:4006/files/lesson-audio/42fe781f2118acf8f4decedee61782bcddcdb12e55894f0c64c25d46da23289b.mp3", "hash": "e21d12293bbe5e915eb54f3bcefe1a31e1fbce19a3cff1ebdfab9dc5af43ab71", "bytes": 53568, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/42fe781f2118acf8f4decedee61782bcddcdb12e55894f0c64c25d46da23289b.mp3", "duration_ms": 8880}, "s1-key-ideas.explanation": {"url": "http://localhost:4006/files/lesson-audio/f20c97e0bfc60b9614c518c9ee168b240590a7da431dd6aac6443499a33a28fd.mp3", "hash": "b6745b594a57a75ed84f9465b1d86d8fa22b187f6e718d37c01bd8c5bf6f10a5", "bytes": 70416, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/f20c97e0bfc60b9614c518c9ee168b240590a7da431dd6aac6443499a33a28fd.mp3", "duration_ms": 11680}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('98f38e44-71ba-4294-87ea-7a6684eb8359', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "balance-scale", "title": "Equilibre a troca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Equilibrar uma balança para uma troca justa usando somas repetidas."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-balance", "xp": 15, "type": "balance_scale", "hints": ["Primeiro, some o valor dos 3 copos: 5 + 5 + 5. Depois, descubra quantos biscoitos de 3 reais você precisa para igualar essa soma."], "title": "Equilibre a balança", "payload": {"weights": [{"id": "galleta-1", "label": "Biscoito", "value": 3}, {"id": "galleta-2", "label": "Biscoito", "value": 3}, {"id": "galleta-3", "label": "Biscoito", "value": 3}, {"id": "galleta-4", "label": "Biscoito", "value": 3}, {"id": "galleta-5", "label": "Biscoito", "value": 3}, {"id": "galleta-6", "label": "Biscoito", "value": 3}], "left_fixed": [{"label": "Copo de limonada", "value": 5}, {"label": "Copo de limonada", "value": 5}, {"label": "Copo de limonada", "value": 5}], "unknown_label": "Biscoitos"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf colocou 3 copos (5 reais cada) à esquerda. Toque os biscoitos (3 reais cada) para igualar a balança.", "difficulty": 2, "explanation_md": "Três copos de 5 reais valem 15 reais. Cinco biscoitos de 3 reais também somam 15. Negócio justo!", "audio_segment_id": "s1-balance.prompt"}], "schema_version": 1}', '{"s1-balance": {}}', '{"units": {"s1-balance.hint.0": {"url": "http://localhost:4006/files/lesson-audio/cdd556ec65d056fb27f17ab56930017f2370da3d9cca744eb4968c04c47f2ac1.mp3", "hash": "c605b4d1b7b73914ed10c517ad8e8ca1a0264acb0ea7e8fdd2a8dbedd5d00dcb", "bytes": 69984, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/cdd556ec65d056fb27f17ab56930017f2370da3d9cca744eb4968c04c47f2ac1.mp3", "duration_ms": 11600}, "s1-balance.prompt": {"url": "http://localhost:4006/files/lesson-audio/4c48b4e46901cb2aa27204ad82cc354f73898cf2c01f35fa674cef820765476a.mp3", "hash": "cd8dae7aa205532b18ce9dbcc851a2f2039ed022b3240f68ec218d5c44d36676", "bytes": 56448, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/4c48b4e46901cb2aa27204ad82cc354f73898cf2c01f35fa674cef820765476a.mp3", "duration_ms": 9360}, "s1-balance.explanation": {"url": "http://localhost:4006/files/lesson-audio/e6db0ba48566f7a5a4dcbb0cfd26beee6329efd029b49af1dc6e68d5173a1bfc.mp3", "hash": "de123087869956a7957633744fc4d6bf48a7ceff456d5bde2532d290d7bfbcd7", "bytes": 65664, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/e6db0ba48566f7a5a4dcbb0cfd26beee6329efd029b49af1dc6e68d5173a1bfc.mp3", "duration_ms": 10880}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58172086-898d-4095-acf1-3502b8607e76', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "story-branch", "title": "A decisão de Liruf", "locale": "pt-BR", "subject": "mixed", "objectives": ["Tomar decisões de preço na barraca de limonada e compreender como elas afetam as vendas e a poupança."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-price-decision", "xp": 0, "type": "story_branch", "hints": ["Cada copo custa 2 reais. Subtraia isso do preço para saber seu lucro real.", "Se o preço for muito alto, talvez os vizinhos não comprem."], "title": "O preço do dia", "payload": {"nodes": [{"id": "start", "choices": [{"id": "c3", "next": "price3", "text_md": "3 reais por copo"}, {"id": "c5", "next": "price5", "text_md": "5 reais por copo"}, {"id": "c10", "next": "price10", "text_md": "10 reais por copo"}], "emotion": "thinking", "text_md": "É meio-dia, está calor e seis vizinhos fazem fila na minha barraca. Quero a guitarra de 80 reais. Qual preço coloco?", "character": "liruf"}, {"id": "price3", "choices": [{"id": "end3", "next": null, "text_md": "Entendido"}], "emotion": "thinking", "text_md": "Todos compraram! Mas só ganhei 1 real por copo. 6 vizinhos = 6 reais. Faltam 74 para a guitarra. Muito pouco...", "character": "liruf"}, {"id": "price5", "choices": [{"id": "end5", "next": null, "text_md": "Entendido"}], "emotion": "encouraging", "text_md": "Os 6 vizinhos compraram sem pensar. Ganhei 3 reais por copo = 18 reais. Já só faltam 62 para a guitarra! Bom avanço.", "character": "liruf"}, {"id": "price10", "choices": [{"id": "end10", "next": null, "text_md": "Entendido"}], "emotion": "thinking", "text_md": "Os vizinhos fizeram careta e foram embora para tomar um sorvete. Não vendi nada. 0 reais. Continuo igual de longe da guitarra. O mais caro nem sempre é melhor.", "character": "liruf"}], "start_node": "start"}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/b2314379876518102b7ba059153c2aeb26c457ad80ee2c2c9b2b52d631ae6f00.webp", "prompt_md": "Há 6 vizinhos com sede. Fazer cada copo custa 2 reais. Qual preço você escolhe?", "difficulty": 2, "explanation_md": "Com o preço justo, você ganha 3 reais por copo e vende todos. Isso o aproxima mais da guitarra do que um preço muito alto ou muito baixo.", "audio_segment_id": "s1-price-decision.prompt"}], "schema_version": 1}', '{"s1-price-decision": {"qualities": [{"score": 25, "node_id": "start", "choice_id": "c3"}, {"score": 95, "node_id": "start", "choice_id": "c5"}, {"score": 10, "node_id": "start", "choice_id": "c10"}]}}', '{"units": {"s1-price-decision.hint.0": {"url": "http://localhost:4006/files/lesson-audio/d7899ada0661cfdff0ea5beb7dac4ac1ab09cc7b607d41391061cc5678528196.mp3", "hash": "e4834f365e31d219072776b99a9766db50ad3126450fb1e4770a568fda48aba1", "bytes": 40176, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/d7899ada0661cfdff0ea5beb7dac4ac1ab09cc7b607d41391061cc5678528196.mp3", "duration_ms": 6640}, "s1-price-decision.hint.1": {"url": "http://localhost:4006/files/lesson-audio/68e946e901fe113d32865d96a94d8129a646fd53d83c9f2377dab06c4107966b.mp3", "hash": "d227db9d04da268668807435bdc4901d2bf243222179fd71f9c6ad60b6fd4e74", "bytes": 26208, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/68e946e901fe113d32865d96a94d8129a646fd53d83c9f2377dab06c4107966b.mp3", "duration_ms": 4320}, "s1-price-decision.prompt": {"url": "http://localhost:4006/files/lesson-audio/afdaedf48848027238dc676f48229c7380cce72e1f238f777fd84e443a3993e3.mp3", "hash": "1912698e69c2c63baeaaeb877bd40c417d6fb4570b903d0a67b0e45d83d81393", "bytes": 44064, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/afdaedf48848027238dc676f48229c7380cce72e1f238f777fd84e443a3993e3.mp3", "duration_ms": 7280}, "s1-price-decision.explanation": {"url": "http://localhost:4006/files/lesson-audio/953c9ced790ad2e2fe07a5eb1e08658f80208bb509944bc1dc2343ff847fc462.mp3", "hash": "8ce4f6def714f1d59b369a75580dc51e59f3816026a4b4703e754e1e7b269492", "bytes": 60336, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/953c9ced790ad2e2fe07a5eb1e08658f80208bb509944bc1dc2343ff847fc462.mp3", "duration_ms": 10000}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('99bea18a-9bc0-4fca-91fe-aa5b44c0ea6e', 'en-US', '1', '{"meta": {"cast": ["liruf", "dina", "rho", "zara"], "slug": "picture-choice", "title": "The safest place for money", "locale": "en-US", "subject": "money", "objectives": ["Choosing the safest place to keep the day''s earnings"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-lugar-seguro", "xp": 10, "type": "picture_choice", "hints": ["Look for a place that has a lock or key.", "In which of these places can the money not fall or be taken by others?"], "title": "Where to keep the money?", "payload": {"options": [{"id": "alcancia", "icon": "savings", "label": "Piggy bank with a key", "image_url": "http://localhost:4006/files/lesson-images/9681bc52834c92a8becdd0f2853e569f8a065b99bd2ee43b8bdacc1f103ff2d3.webp"}, {"id": "bolsillo", "icon": "checkroom", "label": "Torn pocket", "image_url": "http://localhost:4006/files/lesson-images/4e2abf237219b8117084640a1b04964166d8a54edd652fb5fcf751357019ea9b.webp", "rationale_md": "The torn pocket has a hole: coins fall out and get lost."}, {"id": "mesa", "icon": "table_restaurant", "label": "Stand table", "image_url": "http://localhost:4006/files/lesson-images/c7a7477fa0d906300135e0eb029415c13f98959267fe79c5560159025bd2faee.webp", "rationale_md": "The stand table is in plain sight of everyone: anyone can take the money."}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf finished selling. Where does he keep his money to keep it safest?", "difficulty": 1, "explanation_md": "The piggy bank with a key protects money from falls and from other people. The torn pocket lets coins fall out, and the stand table leaves money in plain sight of everyone.", "audio_segment_id": "s1-lugar-seguro.prompt"}], "schema_version": 1}', '{"s1-lugar-seguro": {"correct_option_id": "alcancia"}}', '{"units": {"s1-lugar-seguro.hint.0": {"url": "http://localhost:4006/files/lesson-audio/b3206829aa7f3a8fde4e47307e444e7d8bafa4d0841b1d0ee4c723b10f020faa.mp3", "hash": "84ea14498fe3f0e70c936285e8418bd4e1ef02fe1b07dd400c66490eca16f256", "bytes": 14688, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/b3206829aa7f3a8fde4e47307e444e7d8bafa4d0841b1d0ee4c723b10f020faa.mp3", "duration_ms": 2400}, "s1-lugar-seguro.hint.1": {"url": "http://localhost:4006/files/lesson-audio/693c1bb1ca4782f6578bcc1ac1c22d3bad5ba8531ba1feb64b9d02871a3ee14d.mp3", "hash": "2876023933ae940907ecb8b81ed709ac01b85011831721ffaaab7fa8efb77771", "bytes": 24768, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/693c1bb1ca4782f6578bcc1ac1c22d3bad5ba8531ba1feb64b9d02871a3ee14d.mp3", "duration_ms": 4080}, "s1-lugar-seguro.prompt": {"url": "http://localhost:4006/files/lesson-audio/7d527d6c3e38cb2d749e920bbc32a01812eb23dfe4530ef2241659476fc3f4b7.mp3", "hash": "80b66bdef105f53c60da7e18c55cba7bc08919df51b80da0a4d3d12bf32d4285", "bytes": 23904, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/7d527d6c3e38cb2d749e920bbc32a01812eb23dfe4530ef2241659476fc3f4b7.mp3", "duration_ms": 3920}, "s1-lugar-seguro.choices": {"url": "http://localhost:4006/files/lesson-audio/fc8890429f8d77ebac46722dfb8fcf096120ccd239ef38b1537e6f9e801ffd4c.mp3", "hash": "fd9f360a7148cb69d004dc1edef9e2e25af9985598730604c3549c746c41ba88", "bytes": 21456, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/fc8890429f8d77ebac46722dfb8fcf096120ccd239ef38b1537e6f9e801ffd4c.mp3", "duration_ms": 3520}, "s1-lugar-seguro.explanation": {"url": "http://localhost:4006/files/lesson-audio/eb5573778131929aa24ecca0ea1e37a7b41d068b13f3aaa497c4e656b3866b3d.mp3", "hash": "8f66d54d6461b16631b8a4a2fbdc36790758a9413a87aa236b8763fcfecb5f47", "bytes": 57888, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/eb5573778131929aa24ecca0ea1e37a7b41d068b13f3aaa497c4e656b3866b3d.mp3", "duration_ms": 9600}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5cfeb5fa-1115-414d-9498-5cf6271b6245', 'es-MX', '1', '{"meta": {"cast": ["zara"], "slug": "robot-path", "title": "Entrega de helados", "locale": "es-MX", "subject": "mixed", "objectives": ["Planificar la ruta más eficiente para completar una entrega y obtener una recompensa."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-robot-path", "xp": 5, "type": "robot_path", "hints": ["Observa la dirección inicial. Si avanzas chocarás, ¿qué puedes hacer primero?", "Cada paso extra tarda más, ¡los helados se pueden derretir!"], "title": "La ruta más corta", "payload": {"goal": {"x": 2, "y": 0}, "grid": {"h": 3, "w": 3}, "start": {"x": 0, "y": 0, "dir": "down"}, "walls": [{"x": 0, "y": 1}], "commands": ["left", "forward", "forward"], "max_commands": 5}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Guía a Zara por la cuadrícula para entregar los helados. ¡Usa la ruta más corta y gana una propina!", "difficulty": 1, "explanation_md": "¡Perfecto! Zara giró a la izquierda y avanzó 2 pasos, entregando los helados justo a tiempo. Como fue tan rápida, Ana le dio una propina extra.", "audio_segment_id": "s1-robot-path.prompt"}], "schema_version": 1}', '{"s1-robot-path": {}}', '{"units": {"s1-robot-path.hint.0": {"url": "http://localhost:4006/files/lesson-audio/1734dd5c506d6f3ee4b22d22b5a3c3d6cb090ec72af266e70b0df6621f2546ad.mp3", "hash": "f35467a09d245f3f4eb3f2db3e651c913e5beb934b4ad14710a655058965437e", "bytes": 30528, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/1734dd5c506d6f3ee4b22d22b5a3c3d6cb090ec72af266e70b0df6621f2546ad.mp3", "duration_ms": 5040}, "s1-robot-path.hint.1": {"url": "http://localhost:4006/files/lesson-audio/9f4645bd4b32052e2300bc0c75c2ec5b8a3810a1eb70544dfc199e176c175123.mp3", "hash": "9a0ecdf77f426bba26d076fc94eee8e8eaedaa7322ce5049b326d9e854efcf66", "bytes": 23328, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/9f4645bd4b32052e2300bc0c75c2ec5b8a3810a1eb70544dfc199e176c175123.mp3", "duration_ms": 3840}, "s1-robot-path.prompt": {"url": "http://localhost:4006/files/lesson-audio/ab4d71e4925abcbc5b769ad6cd4f2e0ce53b358e0419c656e7a692e489462aa0.mp3", "hash": "121a8b84a677ee8fe30c58b6351a32882f93d6d92e72bae5b933eaf07b65983c", "bytes": 40608, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/ab4d71e4925abcbc5b769ad6cd4f2e0ce53b358e0419c656e7a692e489462aa0.mp3", "duration_ms": 6720}, "s1-robot-path.explanation": {"url": "http://localhost:4006/files/lesson-audio/e04e0a029d6c2e10282544a42b94224e6ab35153f4e18bbf5357d085374729d7.mp3", "hash": "83b59d458b809179b404a0beb185cf0e418dfc39830cda57edb770e62f181624", "bytes": 57024, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/e04e0a029d6c2e10282544a42b94224e6ab35153f4e18bbf5357d085374729d7.mp3", "duration_ms": 9440}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b45d67a1-26c0-4ffa-b51c-76340c35e459', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "order-steps", "title": "Sort the stand''s purchases", "locale": "en-US", "subject": "mixed", "objectives": ["Sort market purchases by sales priority", "Distinguish between stand needs and wants that can wait"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ordenar-compras", "xp": 15, "type": "order_steps", "hints": ["No lemons, no lemonade.", "Cups are also urgent, but without lemons there''s nothing to sell."], "title": "Market priority", "payload": {"items": [{"id": "limones", "text_md": "Lemons", "image_url": "http://localhost:4006/files/lesson-images/d7ae5e946b9b6f00acaa3b5b1f5e7e7c817451d37029297757e1dc10df422a16.webp"}, {"id": "vasos", "text_md": "Cups", "image_url": "http://localhost:4006/files/lesson-images/c030435a1ecab7bc068827b45b3fce6b8835e40a5b2d5cd73efb87de4999da72.webp"}, {"id": "azucar", "text_md": "Sugar", "image_url": "http://localhost:4006/files/lesson-images/404387803949adb997e56810c2c936ad7e7b0b9623e1aed5d95bf3bd5708c498.webp"}, {"id": "calcomanias", "text_md": "Stickers", "image_url": "http://localhost:4006/files/lesson-images/926c405993df1b68c65556fd6b1ad154fbf9ca58f69a6dc0c83729430726fbb8.webp"}], "slots": 4}, "narrator": {"emotion": "thinking", "character": "zara"}, "prompt_md": "Zara has $10 for the stand. Which purchase is most urgent to sell today? Tap the cards from most needed to can wait.", "difficulty": 2, "explanation_md": "Lemons are the most urgent because without them you can''t make lemonade. Cups are next, because you need something to serve it in. Sugar helps it taste good, but you can sell without it. Stickers are a luxury that can wait. If you put stickers first, you thought they were more important than selling, but the stand needs what makes money first.", "audio_segment_id": "s1-ordenar-compras.prompt"}], "schema_version": 1}', '{"s1-ordenar-compras": {"order": ["limones", "vasos", "azucar", "calcomanias"]}}', '{"units": {"s1-ordenar-compras.hint.0": {"url": "http://localhost:4006/files/lesson-audio/62dcc87f8e490761b63a7f12640d436f13a78ba06290850e9151cec66110adfd.mp3", "hash": "29258d8504892ca66b4ef7ccfc97aec2fac97bd85461d1f708805b4070509329", "bytes": 13824, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/62dcc87f8e490761b63a7f12640d436f13a78ba06290850e9151cec66110adfd.mp3", "duration_ms": 2240}, "s1-ordenar-compras.hint.1": {"url": "http://localhost:4006/files/lesson-audio/25da6b96853c249b2e396668b5b7f3811f1be8bbe04c31c739629b7c71d0187d.mp3", "hash": "df4843c09c070220a32eadacf75f3da5fde0fa9a12f143c547c1cfd31aa8cb0f", "bytes": 23328, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/25da6b96853c249b2e396668b5b7f3811f1be8bbe04c31c739629b7c71d0187d.mp3", "duration_ms": 3840}, "s1-ordenar-compras.prompt": {"url": "http://localhost:4006/files/lesson-audio/53cc31eec55ed36739212ea025a34fcc7c4074bde4d2008ac395488dfeebe5c8.mp3", "hash": "227da0c5036b88a1d2d65b2a7737930b0ab8c2002839410a36701e837655649f", "bytes": 50256, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/53cc31eec55ed36739212ea025a34fcc7c4074bde4d2008ac395488dfeebe5c8.mp3", "duration_ms": 8320}, "s1-ordenar-compras.explanation": {"url": "http://localhost:4006/files/lesson-audio/2e6fde88a5a6a431a3da1594f9f870c590a68dd7d8fc637ac5a5dac2df809b57.mp3", "hash": "9f3bf7916a37ead0451b9d397a39d6d1d866cd99161d500a639ff3257001f05a", "bytes": 111168, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/2e6fde88a5a6a431a3da1594f9f870c590a68dd7d8fc637ac5a5dac2df809b57.mp3", "duration_ms": 18480}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('000a07f3-d716-40f9-bb5f-2d175c582162', 'pt-BR', '1', '{"meta": {"cast": ["liruf"], "slug": "spot-error", "title": "Encontre o erro: a conta do Liruf", "locale": "pt-BR", "subject": "mixed", "objectives": ["Identificar que 5+5+5 não pode dar 20 e corrigir a soma de vendas."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "e1-spot-error", "xp": 15, "type": "spot_error", "title": "Encontre o erro", "payload": {"steps": [{"id": "s1", "text_md": "Segunda-feira: vendi 1 copo de limonada → 5 reais."}, {"id": "s2", "text_md": "Terça-feira: vendi outro copo → 5 reais."}, {"id": "s3", "text_md": "Quarta-feira: vendi um copo a mais → 5 reais."}, {"id": "s4", "text_md": "Total: 5 + 5 + 5 = 20 reais."}], "context_md": "Liruf anotou o que vendeu esta semana."}, "narrator": {"emotion": "thinking", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/8181fa9e8a5af59b43a91994efdc3e94185e96124dbb4e90ff93edcc29e45e0f.webp", "prompt_md": "Liruf revê seu caderno de vendas. Toque no passo onde ele se enganou.", "difficulty": 2, "explanation_md": "Cada copo custa 5 reais. Três copos somam 5+5+5=15. Liruf se confundiu e escreveu 20. Vamos revisar!", "audio_segment_id": "e1-spot-error.prompt"}], "schema_version": 1}', '{"e1-spot-error": {"error_ids": ["s4"], "correction_md": "La suma es 5 + 5 + 5 = 15, no 20. Liruf le puso un 5 extra."}}', '{"units": {"e1-spot-error.prompt": {"url": "http://localhost:4006/files/lesson-audio/9ed765b98a0845ac0817667977b61c539a625fc917a7a5f6d4d1028089def70d.mp3", "hash": "89fe038680d931687e4b8dc3ba3f390fb5e8058179f7c78bc101aa31bc3daaf3", "bytes": 31104, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/9ed765b98a0845ac0817667977b61c539a625fc917a7a5f6d4d1028089def70d.mp3", "duration_ms": 5120}, "e1-spot-error.explanation": {"url": "http://localhost:4006/files/lesson-audio/89c91da22770858339acba5d230fb2b62aa7c8317c2461441b41d1c76e148375.mp3", "hash": "1c59c33c8b026c046f408966f16cd9929e190964587c9daecc067587d94ce700", "bytes": 68976, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/89c91da22770858339acba5d230fb2b62aa7c8317c2461441b41d1c76e148375.mp3", "duration_ms": 11440}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('e0e06311-1e57-4b7b-a3ee-04c82227ceae', 'es-MX', '1', '{"meta": {"cast": ["liruf"], "slug": "fair-trade", "title": "¿Es justo el intercambio?", "locale": "es-MX", "subject": "mixed", "objectives": ["Comparar valores para decidir si un trueque es justo."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fair-trade", "xp": 8, "type": "fair_trade", "hints": ["¿Cuánto valen los 2 vasos juntos?"], "title": "¿Es justo el intercambio?", "payload": {"offer_a": {"qty": 2, "icon": "local_drink", "label": "Vasos de limonada", "image_url": "http://localhost:4006/files/lesson-images/f8f4a1d5ab3b79c28b9a86c05de48bd683bf1fe8992365227151e8453d4b98a2.webp"}, "offer_b": {"qty": 1, "icon": "shopping_bag", "label": "Bolsa de limones", "image_url": "http://localhost:4006/files/lesson-images/2e985967622df9696797874a56c247c209e105aa3521231488d5613d0491be28.webp"}, "rate_md": "2 vasos por 1 bolsa"}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Cada vaso de limonada cuesta 5 pesos. La bolsa de limones vale 10. ¿Es justo cambiar 2 vasos por la bolsa?", "difficulty": 1, "explanation_md": "Los 2 vasos juntos valen 10 pesos (5+5). La bolsa también vale 10. Como los dos lados valen lo mismo, es un intercambio justo.", "audio_segment_id": "s1-fair-trade.prompt"}], "schema_version": 1}', '{"s1-fair-trade": {"verdict": "fair"}}', '{"units": {"s1-fair-trade.hint.0": {"url": "http://localhost:4006/files/lesson-audio/6256e74a94405fdbb2791079b88df1103255b2951b56a85950a934fc61fb86c3.mp3", "hash": "9a140a67867bee8315a8235f6b4b84a08db93ff204ea6057ebb7924a8144c78f", "bytes": 15696, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/6256e74a94405fdbb2791079b88df1103255b2951b56a85950a934fc61fb86c3.mp3", "duration_ms": 2560}, "s1-fair-trade.prompt": {"url": "http://localhost:4006/files/lesson-audio/561a360d2c2c8968dce4a8be1e6dc93896c3745255d95cc707e6c5610b6e53cc.mp3", "hash": "d2d231c888cbe0248c05ee61117c92909e2c20e5f14b2f76dee03a5c56719fcb", "bytes": 53136, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/561a360d2c2c8968dce4a8be1e6dc93896c3745255d95cc707e6c5610b6e53cc.mp3", "duration_ms": 8800}, "s1-fair-trade.explanation": {"url": "http://localhost:4006/files/lesson-audio/2e25df80ab5afa489a73c142514d55fcfd275b25d6046b109bc3259ecec65bc0.mp3", "hash": "7cb743679c56e67a350d88f18a077c73a7293b984ea40bbc9f47977b67b51539", "bytes": 59904, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/2e25df80ab5afa489a73c142514d55fcfd275b25d6046b109bc3259ecec65bc0.mp3", "duration_ms": 9920}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c5c3f5b2-2c4b-4aa8-bd76-cdcb594e0dda', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "concept-reveal", "title": "Ganar dinero empieza con una idea", "locale": "es-MX", "subject": "money", "objectives": ["Entender que el dinero se gana ofreciendo algo que otros quieren", "Identificar que una meta clara ayuda a empezar", "Distinguir entre costo y ganancia"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-concept-reveal", "xp": 0, "type": "concept_reveal", "hints": ["Piensa en lo que Liruf gasta para hacer la limonada.", "Lo que sobra después de pagar los ingredientes es la ganancia."], "title": "Costo y ganancia", "payload": {"cards": [{"icon": "local_atm", "back_md": "Lo que gastas en limones y azúcar", "front_md": "Costo", "image_url": "http://localhost:4006/files/lesson-images/9e6ed448fe344d07cd5bd805e50e97c50daf4b5baaf21d2f468f4ff47076a198.webp"}, {"icon": "monetization_on", "back_md": "Lo que te queda después de pagar el costo", "front_md": "Ganancia", "image_url": "http://localhost:4006/files/lesson-images/bf98f0096709245dd53b61c5dcf3e611d979a45ef7718b3acd45620595f5512e.webp"}]}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Toca las tarjetas para descubrir qué significan ''costo'' y ''ganancia''.", "difficulty": 1, "explanation_md": "El costo es lo que gastas en limones y azúcar. La ganancia es lo que te queda después de pagar el costo.", "audio_segment_id": "s1-concept-reveal.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-concept-reveal.hint.0": {"url": "http://localhost:4006/files/lesson-audio/70375ba7af80362f0abb91c07baff0ff04e3437a88bcaa52260946aa227240ce.mp3", "hash": "1ce23d731072ea3aaf7e24ef7a90653f6adeb56b0667f17a2ae6d6926fead709", "bytes": 20448, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/70375ba7af80362f0abb91c07baff0ff04e3437a88bcaa52260946aa227240ce.mp3", "duration_ms": 3360}, "s1-concept-reveal.hint.1": {"url": "http://localhost:4006/files/lesson-audio/c69d9df13831cff11ac9bfd75096c6c79b3a06560e39a9f9d4e350443c3b9c00.mp3", "hash": "9ad92cdf7e72684a2ce4a6d9dfddcd25383f8d7eb55f117dd3cf4f88b4c78c7f", "bytes": 22464, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/c69d9df13831cff11ac9bfd75096c6c79b3a06560e39a9f9d4e350443c3b9c00.mp3", "duration_ms": 3680}, "s1-concept-reveal.prompt": {"url": "http://localhost:4006/files/lesson-audio/6a4545087e9e99b6cb9d6a2e99fb126aa8a0af2ec81007a0a6472eec1db4f2e5.mp3", "hash": "633e2ccef8b5f82ffd4ed90e7b108a9269f08c91472098e421851cdffd261c06", "bytes": 27648, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/6a4545087e9e99b6cb9d6a2e99fb126aa8a0af2ec81007a0a6472eec1db4f2e5.mp3", "duration_ms": 4560}, "s1-concept-reveal.card.0.back": {"url": "http://localhost:4006/files/lesson-audio/86a26c1b745b8d269b718239e344bc40071d69f776cfcd6523a4397b94df1aef.mp3", "hash": "27a4a010d9a63d7bdd0c332ac4e17a661ea148bc449468a643b24d07e5853110", "bytes": 13248, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/86a26c1b745b8d269b718239e344bc40071d69f776cfcd6523a4397b94df1aef.mp3", "duration_ms": 2160}, "s1-concept-reveal.card.1.back": {"url": "http://localhost:4006/files/lesson-audio/484f8fdc3af87e9016f2f847e44090772337441ccf1c85a2eea6d7340c03d5b2.mp3", "hash": "a66a18a75a771fa67d017a15fddbc7e1ea545b25cfebc2f061bc8e5b19ef79b5", "bytes": 14688, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/484f8fdc3af87e9016f2f847e44090772337441ccf1c85a2eea6d7340c03d5b2.mp3", "duration_ms": 2400}, "s1-concept-reveal.explanation": {"url": "http://localhost:4006/files/lesson-audio/105ba65782a66329334cc11e12a6269271db7f4b3eda9fb3c8dfc692132cec17.mp3", "hash": "34513874e13572075c5f2b50845bdab8f81f37363807bc5bce8f658972b5504b", "bytes": 39168, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/105ba65782a66329334cc11e12a6269271db7f4b3eda9fb3c8dfc692132cec17.mp3", "duration_ms": 6480}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('e0e06311-1e57-4b7b-a3ee-04c82227ceae', 'en-US', '1', '{"meta": {"cast": ["liruf"], "slug": "fair-trade", "title": "Is the trade fair?", "locale": "en-US", "subject": "mixed", "objectives": ["Compare values to decide if a barter is fair."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fair-trade", "xp": 8, "type": "fair_trade", "hints": ["How much are the 2 glasses worth together?"], "title": "Is the trade fair?", "payload": {"offer_a": {"qty": 2, "icon": "local_drink", "label": "Glasses of lemonade", "image_url": "http://localhost:4006/files/lesson-images/07d84c0a72b4dbd20be50ca151241fe0137077f3e7ef2dde52e40628c7972511.webp"}, "offer_b": {"qty": 1, "icon": "shopping_bag", "label": "Bag of lemons", "image_url": "http://localhost:4006/files/lesson-images/51cf3e5f45a2c7cd46c3061680d51852845427b685b8a2526936e8b960ab9bc5.webp"}, "rate_md": "2 glasses for 1 bag"}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Each glass of lemonade costs 5 dollars. The bag of lemons is worth 10. Is it fair to trade 2 glasses for the bag?", "difficulty": 1, "explanation_md": "The 2 glasses together are worth 10 dollars (5+5). The bag is also worth 10. Since both sides are worth the same, it''s a fair trade.", "audio_segment_id": "s1-fair-trade.prompt"}], "schema_version": 1}', '{"s1-fair-trade": {"verdict": "fair"}}', '{"units": {"s1-fair-trade.hint.0": {"url": "http://localhost:4006/files/lesson-audio/985c3492d38482cb5091d5bfdb4f7a5efb8b79c2358d3e2eea9517260c76aa5e.mp3", "hash": "afd1a7d1ef0a1ef78385daf80b32bea441db8065b02d1e3e09207a80a25f2934", "bytes": 15264, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/985c3492d38482cb5091d5bfdb4f7a5efb8b79c2358d3e2eea9517260c76aa5e.mp3", "duration_ms": 2480}, "s1-fair-trade.prompt": {"url": "http://localhost:4006/files/lesson-audio/25a53a9aabd25b53897faa69522d93eafbcf34f7240debed9f5ca8acd8990676.mp3", "hash": "b13b576eeeecaf7a81b025e3f5a3e00299d767bcfcda60e0ba3f27e1ae7e4af0", "bytes": 46368, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/25a53a9aabd25b53897faa69522d93eafbcf34f7240debed9f5ca8acd8990676.mp3", "duration_ms": 7680}, "s1-fair-trade.explanation": {"url": "http://localhost:4006/files/lesson-audio/8d133a49222aa991ccd51482cddd847c2b205f3d9720d8e2c7bf067a1985fad3.mp3", "hash": "dcbb739dcc8735af732a05c432799aa510929ccf0de8b9405e0b5e25244506e5", "bytes": 53568, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/8d133a49222aa991ccd51482cddd847c2b205f3d9720d8e2c7bf067a1985fad3.mp3", "duration_ms": 8880}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b831d60b-c492-4356-824e-7fce5f662a0a', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "match-pairs", "title": "O vento levou os preços!", "locale": "pt-BR", "subject": "mixed", "objectives": ["Emparelhar cada produto da barraca com o seu preço correto."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-pairs", "xp": 15, "type": "match_pairs", "payload": {"left": [{"id": "vaso", "text_md": "Copo de limonada", "image_url": "http://localhost:4006/files/lesson-images/2494c2e3f6ea3d8c712f3320119f984868d862e1b8acb4e93040a6a86e7b05f3.webp"}, {"id": "jarra", "text_md": "Jarra de limonada", "image_url": "http://localhost:4006/files/lesson-images/b355fbd0ef02034eefefe19956d00d317b86ca2a8dee63744d739717ae72a740.webp"}, {"id": "galleta", "text_md": "Biscoito", "image_url": "http://localhost:4006/files/lesson-images/b23d64442929a52f2a1c526cad2cff445df178322d135588909af923fbc923c1.webp"}], "right": [{"id": "precio-5", "text_md": "5 reais"}, {"id": "precio-20", "text_md": "20 reais"}, {"id": "precio-3", "text_md": "3 reais"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina vendeu estas três coisas ontem. Você pode ajudá-la a colocar o preço correto em cada uma?", "difficulty": 2, "explanation_md": "A jarra grande dá mais limonada, por isso custa 20 reais. O copo médio custa 5 reais, e o biscoito pequeno só 3 reais. Já estão em ordem!"}], "schema_version": 1}', '{"s1-match-pairs": {"pairs": [["vaso", "precio-5"], ["jarra", "precio-20"], ["galleta", "precio-3"]]}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7f76a2de-27d1-4660-8203-c9ddad8fb861', 'pt-BR', '1', '{"meta": {"cast": ["zara"], "slug": "estimate-slider", "title": "Estimar copos de limonada", "locale": "pt-BR", "subject": "mixed", "objectives": ["Estimar quantidades usando uma barra deslizante", "Desenvolver senso numérico ao estimar antes de contar"], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-estimate-slider", "xp": 10, "type": "estimate_slider", "hints": ["Pense em uma jarra média: nem muito pequena nem muito grande.", "Se cada copo é de 5 reais, a jarra não dá para 100 copos nem para 1 só."], "title": "Quantos copos saem?", "payload": {"max": 20, "min": 1, "step": 1, "unit": "vasos", "scale": "linear"}, "narrator": {"emotion": "thinking", "character": "zara"}, "image_url": "http://localhost:4006/files/lesson-images/c0d37251abaa88e80512292dcf95cf1c88d24627806e163291d8bbb2980cc6dc.webp", "prompt_md": "Zara encheu a jarra. Sem contar, deslize para estimar: quantos copos de 5 reais você acha que saem desta jarra?", "difficulty": 1, "explanation_md": "A jarra tem espaço para uns 8 copos. Zara estimou bem ao pensar em um número nem muito pequeno nem muito grande.", "audio_segment_id": "s1-estimate-slider.prompt"}], "schema_version": 1}', '{"s1-estimate-slider": {"value": 8, "full_credit_delta": 2, "zero_credit_delta": 5}}', '{"units": {"s1-estimate-slider.hint.0": {"url": "http://localhost:4006/files/lesson-audio/c99be357684c3552db6727a0ee8e3a2c239995f18bed61b5e0bdb327a0c4e89a.mp3", "hash": "c8806177f0c33d282e8b24c964fc1519df698b05cb540e336b6fe150463819bf", "bytes": 26208, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/c99be357684c3552db6727a0ee8e3a2c239995f18bed61b5e0bdb327a0c4e89a.mp3", "duration_ms": 4320}, "s1-estimate-slider.hint.1": {"url": "http://localhost:4006/files/lesson-audio/a2e720f8cebf92d4501f73f70dca475801079091a765b4837e572ff190fcf127.mp3", "hash": "f621e82fc3927b610158f12f150e21dea61b17496a3607f57a4eaa19fa1fcd7e", "bytes": 36288, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/a2e720f8cebf92d4501f73f70dca475801079091a765b4837e572ff190fcf127.mp3", "duration_ms": 6000}, "s1-estimate-slider.prompt": {"url": "http://localhost:4006/files/lesson-audio/02403df396175f5d276975759459c142e86763b4df05bd56a7d46ac2dfc59b00.mp3", "hash": "75ff75b9bdf8da9a8cbdbeb4e62904be2ff0840bf0ad5b54f1403fbd15dc249c", "bytes": 48384, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/02403df396175f5d276975759459c142e86763b4df05bd56a7d46ac2dfc59b00.mp3", "duration_ms": 8000}, "s1-estimate-slider.explanation": {"url": "http://localhost:4006/files/lesson-audio/77f3fd6b10f3eb4a1a2091760f6e2d1fa9fabefde22a8f378b2ef9bd632ca5c9.mp3", "hash": "5c5af9eec6213212c33dc2b21a232b2c6fc0bed961439fa9cfaf32be6e656c35", "bytes": 49248, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/77f3fd6b10f3eb4a1a2091760f6e2d1fa9fabefde22a8f378b2ef9bd632ca5c9.mp3", "duration_ms": 8160}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('85c2a66b-c70b-43e4-8fd5-4862d4acb66b', 'es-MX', '1', '{"meta": {"cast": ["rho"], "slug": "rank-choices", "title": "El orden de las compras", "locale": "es-MX", "subject": "mixed", "objectives": ["Ordenar compras por prioridad para un puesto de limonada."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-prioridad-compras", "xp": 15, "type": "rank_choices", "hints": ["Piensa: ¿sin qué no puedes hacer la limonada?"], "title": "Prioridad de compras", "payload": {"items": [{"id": "limones", "text_md": "Limones frescos", "image_url": "http://localhost:4006/files/lesson-images/1751a8890d5e213eda59c5c1039501d304f9863201d31a515824dd6c49a9a1fe.webp"}, {"id": "vasos", "text_md": "Vasos de papel", "image_url": "http://localhost:4006/files/lesson-images/c5e9b8a960b77488909549f26c92052625b096be8348da8aa7103d82aa8224d2.webp"}, {"id": "adornos", "text_md": "Adornos para el puesto", "image_url": "http://localhost:4006/files/lesson-images/5f95b212bdc019b0a5fb19c5d542813a33b7a625e9e2586781ebfab9683df7eb.webp"}], "criterion_md": "¿Qué ayuda más a vender limonada mañana?"}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Ordena de lo más urgente a lo menos urgente para el puesto.", "difficulty": 2, "explanation_md": "Para seguir vendiendo limonada, lo más urgente es reponer los limones. Luego los vasos para servir, y al final los adornos que solo decoran.", "audio_segment_id": "s1-prioridad-compras.prompt"}], "schema_version": 1}', '{"s1-prioridad-compras": {"order": ["limones", "vasos", "adornos"], "accept_orders": []}}', '{"units": {"s1-prioridad-compras.hint.0": {"url": "http://localhost:4006/files/lesson-audio/5aeadb9e32dc1ff2b02bdfc05eb9e7dec087d741810d7f8f7a08f18207070dba.mp3", "hash": "88ceec1093a0a1990b43405dc48b56f2bd23784faa3b17c4f35334f064945019", "bytes": 21024, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/5aeadb9e32dc1ff2b02bdfc05eb9e7dec087d741810d7f8f7a08f18207070dba.mp3", "duration_ms": 3440}, "s1-prioridad-compras.prompt": {"url": "http://localhost:4006/files/lesson-audio/826624b49f74141aeaba8e9f23c077d1412d78763eecb2bba54508933b359eea.mp3", "hash": "44fe86ad0d91955f835299e31cf0f8b0997d5006d812b17f1b70bf82506dc48a", "bytes": 25776, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/826624b49f74141aeaba8e9f23c077d1412d78763eecb2bba54508933b359eea.mp3", "duration_ms": 4240}, "s1-prioridad-compras.explanation": {"url": "http://localhost:4006/files/lesson-audio/c5f5228e3ef92a741e4cb6ad99c1c4f5ffb87b774324e02393a7aff6fe9fe4e9.mp3", "hash": "d90359075b9c9a599abd233a229be9036e09a3777ce70d09887b355e74c95fea", "bytes": 55584, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/c5f5228e3ef92a741e4cb6ad99c1c4f5ffb87b774324e02393a7aff6fe9fe4e9.mp3", "duration_ms": 9200}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('21c29ede-4ec5-4118-8e88-04f1068e985b', 'es-MX', '1', '{"meta": {"cast": ["liruf"], "slug": "count-objects", "title": "Cuenta las monedas del frasco volcado", "locale": "es-MX", "subject": "mixed", "objectives": ["Contar objetos en una escena para determinar un total numérico."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-count-coins", "xp": 10, "type": "count_objects", "title": "Cuenta las monedas del frasco volcado", "payload": {"scene": [{"icon": "monetization_on", "tint": "primary", "count": 8, "label": "moneda", "image_url": "http://localhost:4006/files/lesson-images/51eb4fbd85b0102763aa4756514de1a67358073790bcaeb865ee16edcf4983ba.webp"}, {"icon": "cookie", "tint": "accent", "count": 3, "label": "galleta", "image_url": "http://localhost:4006/files/lesson-images/f2975e6e8d715646e735228b20f39c19a408d57acbe156d19e08e426fad7fc66.webp"}, {"icon": "local_drink", "tint": "warning", "count": 2, "label": "vaso", "image_url": "http://localhost:4006/files/lesson-images/e7f7f16426e7194c18895bfcec92b380cc27efe30ad87d400a21821b9a14d390.webp"}], "ask_icon": "monetization_on", "ask_label": "moneda", "ask_image_url": "http://localhost:4006/files/lesson-images/51eb4fbd85b0102763aa4756514de1a67358073790bcaeb865ee16edcf4983ba.webp"}, "narrator": {"emotion": "excited", "character": "liruf"}, "prompt_md": "El frasco de ventas de Liruf se volcó. Cuenta las monedas que cayeron.", "difficulty": 1, "explanation_md": "Contaste 8 monedas. Cada moneda es un vaso de 5 pesos que Liruf ya vendió. ¡Hoy sumas 40 pesos a la meta de la guitarra de 80!"}], "schema_version": 1}', '{"s1-count-coins": {"value": 8}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58172086-898d-4095-acf1-3502b8607e76', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "story-branch", "title": "Liruf''s decision", "locale": "en-US", "subject": "mixed", "objectives": ["Make pricing decisions at the lemonade stand and understand how they affect sales and savings."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-price-decision", "xp": 0, "type": "story_branch", "hints": ["Each glass costs you 2 dollars. Subtract that from the price to know your real profit.", "If the price is too high, maybe the neighbors won''t buy."], "title": "Today''s price", "payload": {"nodes": [{"id": "start", "choices": [{"id": "c3", "next": "price3", "text_md": "3 dollars per glass"}, {"id": "c5", "next": "price5", "text_md": "5 dollars per glass"}, {"id": "c10", "next": "price10", "text_md": "10 dollars per glass"}], "emotion": "thinking", "text_md": "It''s noon, it''s hot and six neighbors are lining up at my stand. I want the guitar that costs 80 dollars. What price do I set?", "character": "liruf"}, {"id": "price3", "choices": [{"id": "end3", "next": null, "text_md": "Understood"}], "emotion": "thinking", "text_md": "Everyone bought! But I only earned 1 dollar per glass. 6 neighbors = 6 dollars. I am 74 short for the guitar. Very little...", "character": "liruf"}, {"id": "price5", "choices": [{"id": "end5", "next": null, "text_md": "Understood"}], "emotion": "encouraging", "text_md": "All 6 neighbors bought without hesitation. I earned 3 dollars per glass = 18 dollars. Now I only need 62 for the guitar! Good progress.", "character": "liruf"}, {"id": "price10", "choices": [{"id": "end10", "next": null, "text_md": "Understood"}], "emotion": "thinking", "text_md": "The neighbors made a face and left for an ice cream. I sold nothing. 0 dollars. I''m still just as far from the guitar. The most expensive is not always better.", "character": "liruf"}], "start_node": "start"}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/04af4e9fd61602e73220b57f09df37dd6f530e6ece8ba007ea42f893df67db72.webp", "prompt_md": "There are 6 thirsty neighbors. Making each glass costs 2 dollars. What price do you choose?", "difficulty": 2, "explanation_md": "With the fair price, you earn 3 dollars per glass and sell all. That brings you closer to the guitar than a very high or very low price.", "audio_segment_id": "s1-price-decision.prompt"}], "schema_version": 1}', '{"s1-price-decision": {"qualities": [{"score": 25, "node_id": "start", "choice_id": "c3"}, {"score": 95, "node_id": "start", "choice_id": "c5"}, {"score": 10, "node_id": "start", "choice_id": "c10"}]}}', '{"units": {"s1-price-decision.hint.0": {"url": "http://localhost:4006/files/lesson-audio/d303c889b1dfc607a9c9d281ee4d3fc58f719333edcb3421387d867c59baffdc.mp3", "hash": "e8f9a009c0028048460dd34ba6c5f0734329277a275b2d0982ff8fb4e2cfbc30", "bytes": 27216, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/d303c889b1dfc607a9c9d281ee4d3fc58f719333edcb3421387d867c59baffdc.mp3", "duration_ms": 4480}, "s1-price-decision.hint.1": {"url": "http://localhost:4006/files/lesson-audio/d12077adb1de0aa69e6ad9f2cc27cfc5ff1c9ce2fd0e92e079ec86575acef3fe.mp3", "hash": "91bb8a437709338a87c6e980ae6e3af3ccbe5ee0a30b49edfc793730a17aade6", "bytes": 18576, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/d12077adb1de0aa69e6ad9f2cc27cfc5ff1c9ce2fd0e92e079ec86575acef3fe.mp3", "duration_ms": 3040}, "s1-price-decision.prompt": {"url": "http://localhost:4006/files/lesson-audio/3d93d69e0d5a54f30a881f0f9db6ee1e04ba1d78bfabbc517fa6cb398872a6d2.mp3", "hash": "040ba79db709994646860471817d88e2caf87c798a75f397acc3514e21c10d81", "bytes": 32976, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/3d93d69e0d5a54f30a881f0f9db6ee1e04ba1d78bfabbc517fa6cb398872a6d2.mp3", "duration_ms": 5440}, "s1-price-decision.explanation": {"url": "http://localhost:4006/files/lesson-audio/6daa16886ac8aac53a873bf69bfda72fac1b065d3b2104c4dcf44fb2c2b770b7.mp3", "hash": "81af0b45a02a47f7066bb1f58bd3ea72325f846d0ea19065bc6df65a49e65bc7", "bytes": 47808, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/6daa16886ac8aac53a873bf69bfda72fac1b065d3b2104c4dcf44fb2c2b770b7.mp3", "duration_ms": 7920}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f62a6048-4f69-4ab4-9256-d87525c8e112', 'en-US', '1', '{"meta": {"cast": ["liruf"], "slug": "make-change", "title": "Don Beto''s change", "locale": "en-US", "subject": "mixed", "objectives": ["Calculate the exact change using US coins in a real sale."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-make-change", "xp": 15, "type": "make_change", "hints": ["Don Beto spent the price of the cup plus the cookie. He paid with 20 dollars. The change is the difference you must give him back with coins of 1, 2, 5, or 10 dollars."], "title": "Don Beto''s change", "payload": {"price": 8, "currency": "USD", "paid_with": 20, "denominations": [1, 2, 5, 10]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/7a44a4b2dd62fce733c60735a238679bcb7c25611a254222cbb5809eb3a10e29.webp", "prompt_md": "Don Beto bought 1 cup (5 dollars) and 1 cookie (3 dollars). He paid with 20 dollars. Make the change with coins.", "difficulty": 2, "explanation_md": "The lemonade and the cookie add up to 8 dollars. When paying with 20, the change is 12 dollars. You can use one 10-dollar coin and one 2-dollar coin, or two 5-dollar coins and two 1-dollar coins, or any combination that makes 12. If you give back less, Don Beto doesn''t get his full change. If you give back more, you lose coins toward the 80-dollar guitar.", "audio_segment_id": "s1-make-change.prompt"}], "schema_version": 1}', '{"s1-make-change": {}}', '{"units": {"s1-make-change.hint.0": {"url": "http://localhost:4006/files/lesson-audio/7713885b77b516c0c1dd04165eedb7f302100bbb5ae0ee958a2a2642796f076b.mp3", "hash": "3122c68fc95fd62bfdf665e21841ccdfcbaa984ba187e97ec4b74c8424270efb", "bytes": 62208, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/7713885b77b516c0c1dd04165eedb7f302100bbb5ae0ee958a2a2642796f076b.mp3", "duration_ms": 10320}, "s1-make-change.prompt": {"url": "http://localhost:4006/files/lesson-audio/52edaf402c67c1c8c1acb7f6ee5011377f1eba48e0cb8b23abfff3f132f5fc69.mp3", "hash": "bf707fb9c479091b208087edd0a19466534f789737586d9869a8ef14c20709a7", "bytes": 48384, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/52edaf402c67c1c8c1acb7f6ee5011377f1eba48e0cb8b23abfff3f132f5fc69.mp3", "duration_ms": 8000}, "s1-make-change.explanation": {"url": "http://localhost:4006/files/lesson-audio/87073e94a7b8a4d0df04711ac33c32b7154717a5ba5439083ca61e805ca5e3c9.mp3", "hash": "6cb5c09893e463c470ce4f1eaababbd499c5db1b4b3cba031684f5d885979030", "bytes": 127008, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/87073e94a7b8a4d0df04711ac33c32b7154717a5ba5439083ca61e805ca5e3c9.mp3", "duration_ms": 21120}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0a2bda3a-e275-46b8-b659-a7ad68a0afb3', 'en-US', '1', '{"meta": {"cast": ["zara", "liruf"], "slug": "lightning-round", "title": "Lightning Round: Quick Change", "locale": "en-US", "subject": "mixed", "objectives": ["Practice calculating quick change to keep customers happy and save money for the guitar."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "lightning-round-practice", "xp": 15, "type": "lightning_round", "hints": ["First add the total cost of the glasses the customer ordered."], "title": "Lightning Change!", "payload": {"questions": [{"id": "q1", "options": [{"id": "a", "text_md": "10 dollars"}, {"id": "b", "text_md": "15 dollars"}, {"id": "c", "text_md": "20 dollars"}], "prompt_md": "Doña Rosa orders 2 glasses. Pays with a 20-dollar bill."}, {"id": "q2", "options": [{"id": "a", "text_md": "5 dollars"}, {"id": "b", "text_md": "10 dollars"}, {"id": "c", "text_md": "15 dollars"}], "prompt_md": "Don Pedro orders 3 glasses. Pays with 20 dollars."}, {"id": "q3", "options": [{"id": "a", "text_md": "5 dollars"}, {"id": "b", "text_md": "0 dollars"}, {"id": "c", "text_md": "10 dollars"}], "prompt_md": "Doña Juana orders 1 glass. Pays with 10 dollars."}, {"id": "q4", "options": [{"id": "a", "text_md": "0 dollars"}, {"id": "b", "text_md": "5 dollars"}, {"id": "c", "text_md": "10 dollars"}], "prompt_md": "Tito orders 2 glasses. Pays with exactly 10 dollars."}], "seconds_per_q": 15}, "narrator": {"emotion": "encouraging", "character": "zara"}, "prompt_md": "Each glass of lemonade costs 5 dollars. Help Liruf give exact change!", "difficulty": 2, "explanation_md": "Remember: first add up the cost of all the glasses (each one costs 5 dollars) and then subtract it from the bill. For example, 2 glasses and a 20-dollar bill: 20 - (2×5) = 10 dollars in change. A common mistake is to subtract without multiplying; this way you make sure you give the exact change.", "audio_segment_id": "lightning-round-practice.prompt"}], "schema_version": 1}', '{"lightning-round-practice": {"correct": {"q1": "a", "q2": "a", "q3": "a", "q4": "a"}}}', '{"units": {"lightning-round-practice.hint.0": {"url": "http://localhost:4006/files/lesson-audio/3722cfd7a19ec478fb8b82db1875ecbfd384e352cf55a48497e251f4435f7f5c.mp3", "hash": "b23fab927091285e81a9d0dbfc706568ff80951be0a6b1c8ffc44c449d3cc482", "bytes": 24768, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/3722cfd7a19ec478fb8b82db1875ecbfd384e352cf55a48497e251f4435f7f5c.mp3", "duration_ms": 4080}, "lightning-round-practice.prompt": {"url": "http://localhost:4006/files/lesson-audio/d8d7b50661e2e6c80a13bd5bfe4dd2f3a67baf07a8df6c6d970981c3f4aba4a6.mp3", "hash": "a8b615029b97e7a76b64595a9ef47849adcceae92262ac7576f7e51e8c898460", "bytes": 36288, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/d8d7b50661e2e6c80a13bd5bfe4dd2f3a67baf07a8df6c6d970981c3f4aba4a6.mp3", "duration_ms": 6000}, "lightning-round-practice.explanation": {"url": "http://localhost:4006/files/lesson-audio/4314bd619acf0e2bd58005a0635ef6adbc2be713f43188c7cb3cc07715484625.mp3", "hash": "171ca248801d6b571a6497266e1a34ba27b8f4067a76e57ccca3967ce843c9e3", "bytes": 126144, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/4314bd619acf0e2bd58005a0635ef6adbc2be713f43188c7cb3cc07715484625.mp3", "duration_ms": 20960}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0754f3ae-1483-4dd4-bc05-e1f681fd5bcf', 'en-US', '1', '{"meta": {"cast": ["liruf"], "slug": "combo-narrativa-choice", "title": "Today''s Price", "locale": "en-US", "subject": "mixed", "objectives": ["Practice multiple skills in one lesson: listen to the situation, make a decision, calculate, and collect payment."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-story-scene", "xp": 0, "type": "story_scene", "title": "Saturday Opening", "payload": {"art": {"icon": "storefront", "tint": "primary", "image_url": "http://localhost:4006/files/lesson-images/cc8e4ad43f28f4e920710bd3f82c9dd732831796a8a43fce712915dd19880daf.webp"}, "action": "idle", "body_md": "Yesterday I found out that the tip jar doubles: put in 1 coin and 2 come out. Today I open my stand and there are 20 customers in line! I need $120 for a game. What price should I set for each cup?", "emotion": "excited", "backdrop": "band", "character": "liruf"}, "narrator": {"emotion": "excited", "character": "liruf"}, "prompt_md": "It''s Lemonade Saturday! Tap to see the scene.", "difficulty": 1, "audio_segment_id": "s1-story-scene.prompt"}, {"id": "s2-quiz-mcq", "xp": 12, "type": "quiz_mcq", "hints": ["Think: what number multiplied by 20 gives 120?"], "title": "Choose the price", "payload": {"options": [{"id": "op1", "text_md": "5 dollars", "rationale_md": "With $5 per cup, 20 cups only bring in $100. You''d be short $20 for the game."}, {"id": "op2", "text_md": "6 dollars"}, {"id": "op3", "text_md": "8 dollars", "rationale_md": "With $8 per cup, you''d bring in $160, way more than needed. Overcharging might not be fair."}], "shuffle": true}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf has 20 customers and needs $120 for a game. At what price should he sell each cup?", "difficulty": 2, "explanation_md": "If he sells 20 cups at $6 each, he makes 20 × 6 = $120 exactly, what Liruf needs for the game.", "audio_segment_id": "s2-quiz-mcq.prompt"}], "schema_version": 1}', '{"s2-quiz-mcq": {"correct_option_id": "op2"}}', '{"units": {"s2-quiz-mcq.hint.0": {"url": "http://localhost:4006/files/lesson-audio/abe1a46df31c7a321c849c56c0522f27c8dde9a4583da058db981bd39979a21b.mp3", "hash": "9b1bb8493d81282d580d7f476c95b7f21f501040fa762b32768c8eb9d34c70fa", "bytes": 24768, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/abe1a46df31c7a321c849c56c0522f27c8dde9a4583da058db981bd39979a21b.mp3", "duration_ms": 4080}, "s2-quiz-mcq.prompt": {"url": "http://localhost:4006/files/lesson-audio/e12a2a950a5a48cea808b78fb6ff094de5d0a0c6cd24ad36067d7d4bd486c957.mp3", "hash": "33cd81d749121b991da16784746fe1a58fa828658dcbbc1165249e9cdeea539b", "bytes": 41616, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/e12a2a950a5a48cea808b78fb6ff094de5d0a0c6cd24ad36067d7d4bd486c957.mp3", "duration_ms": 6880}, "s1-story-scene.body": {"url": "http://localhost:4006/files/lesson-audio/f900bb8b3bb482744c0cd98836c371697fbf4919e7ed122937f9d3a62da05ec9.mp3", "hash": "02f6bf3650dec4eb60075c450c9338e265b9d0b42bc8059f626641a31c54a5c6", "bytes": 80064, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/f900bb8b3bb482744c0cd98836c371697fbf4919e7ed122937f9d3a62da05ec9.mp3", "duration_ms": 13280}, "s2-quiz-mcq.choices": {"url": "http://localhost:4006/files/lesson-audio/cd2be0ad332408202614ae23ebc22f68fb08eedef25d833b8b13580759be06aa.mp3", "hash": "9afb7bbfea2ce32cecdd1004616e13b9faea894ae13aa692ac06ccd51c54e294", "bytes": 17136, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/cd2be0ad332408202614ae23ebc22f68fb08eedef25d833b8b13580759be06aa.mp3", "duration_ms": 2800}, "s1-story-scene.prompt": {"url": "http://localhost:4006/files/lesson-audio/f535689be28d5c3e0da59399cbcf22a93a825c17875cd6d744d9d42017214133.mp3", "hash": "141faa68f052e6ffef43adb3764ed10557b3b02084b8e88936977d43e8e3a5f0", "bytes": 16704, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/f535689be28d5c3e0da59399cbcf22a93a825c17875cd6d744d9d42017214133.mp3", "duration_ms": 2720}, "s2-quiz-mcq.explanation": {"url": "http://localhost:4006/files/lesson-audio/574406ba7761f176b3952a4bfb2385930f50a3cad67b5f193d9076344711c9a9.mp3", "hash": "8ac3a8aeacbac572a44c8807dea8adddc4cc3552e405aec1a01defe66f3e1cf2", "bytes": 52128, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/574406ba7761f176b3952a4bfb2385930f50a3cad67b5f193d9076344711c9a9.mp3", "duration_ms": 8640}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b831d60b-c492-4356-824e-7fce5f662a0a', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "match-pairs", "title": "¡El viento se llevó los precios!", "locale": "es-MX", "subject": "mixed", "objectives": ["Emparejar cada producto del puesto con su precio correcto."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-pairs", "xp": 15, "type": "match_pairs", "payload": {"left": [{"id": "vaso", "text_md": "Vaso de limonada", "image_url": "http://localhost:4006/files/lesson-images/3c73828d03a7aaa8c5ddbb3c3125881a37494b46449af0496a88439774a9efdd.webp"}, {"id": "jarra", "text_md": "Jarra de limonada", "image_url": "http://localhost:4006/files/lesson-images/22fdd27a2968ba1269db879229637ff5f9078def1b3c2783f67126c379050ed8.webp"}, {"id": "galleta", "text_md": "Galleta", "image_url": "http://localhost:4006/files/lesson-images/0208d79e7aeaaeb5ba7bd1959b17e92b0ec66bd11c422bf8c7f7bf7b90efc0aa.webp"}], "right": [{"id": "precio-5", "text_md": "5 pesos"}, {"id": "precio-20", "text_md": "20 pesos"}, {"id": "precio-3", "text_md": "3 pesos"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina vendió estas tres cosas ayer. ¿Puedes ayudarle a poner el precio correcto a cada una?", "difficulty": 2, "explanation_md": "La jarra grande da más limonada, por eso cuesta 20 pesos. El vaso mediano cuesta 5 pesos, y la galleta pequeña solo 3 pesos. ¡Ya están en orden!"}], "schema_version": 1}', '{"s1-match-pairs": {"pairs": [["vaso", "precio-5"], ["jarra", "precio-20"], ["galleta", "precio-3"]]}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4b45b37b-19f0-4fd5-99c2-0bcf9fabfbcd', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "machine-io", "title": "A máquina de gorjetas", "locale": "pt-BR", "subject": "mixed", "objectives": ["Descobrir a regra da máquina de gorjetas: duplica o número de moedas que entram."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-machine-io", "xp": 10, "type": "machine_io", "hints": ["Observe o padrão: entra 1 → sai 2, entra 2 → sai 4. Qual operação converte o número de entrada no de saída?"], "title": "A máquina de gorjetas", "payload": {"options": [{"id": "a", "text_md": "4"}, {"id": "b", "text_md": "6"}, {"id": "c", "text_md": "8"}, {"id": "d", "text_md": "12"}], "examples": [{"in": 1, "out": 2}, {"in": 2, "out": 4}, {"in": 3, "out": 6}], "probe_in": 4}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Entram moedas e saem mais moedas. Se entra 1 sai 2, se entra 2 sai 4, se entra 3 sai 6. O que sai se entra 4?", "difficulty": 1, "explanation_md": "A máquina duplica: cada moeda que entra se transforma em duas. Por isso, ao colocar 4, saem 8 moedas (4 × 2 = 8).", "audio_segment_id": "s1-machine-io.prompt"}], "schema_version": 1}', '{"s1-machine-io": {"value": 8, "correct_option_id": "c"}}', '{"units": {"s1-machine-io.hint.0": {"url": "http://localhost:4006/files/lesson-audio/67bbf6e94fe97d645122ade9e50826c4c0c955e57287876d299e90ecd1e5a8ca.mp3", "hash": "2d7273bdc6ea24ece0f8bc69b687788b762ae00a80223d943e99659ed60e026b", "bytes": 60336, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/67bbf6e94fe97d645122ade9e50826c4c0c955e57287876d299e90ecd1e5a8ca.mp3", "duration_ms": 10000}, "s1-machine-io.prompt": {"url": "http://localhost:4006/files/lesson-audio/5499756bbc355377bb7f7c6ed7d25bf88f154076be782bf3dd307693205790da.mp3", "hash": "e6a00298eb9aad2a7451028c94c4c80fb0450192b4731466730d7ccfcd3696da", "bytes": 61776, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/5499756bbc355377bb7f7c6ed7d25bf88f154076be782bf3dd307693205790da.mp3", "duration_ms": 10240}, "s1-machine-io.explanation": {"url": "http://localhost:4006/files/lesson-audio/5cf8af48e5070424ab8222c6cf2bdbfff349faf9148443232c86500c3e73f719.mp3", "hash": "758b4c6d07b1bc6163208028e53206086e6540324efd6769326a03e2b68d1f60", "bytes": 64656, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/5cf8af48e5070424ab8222c6cf2bdbfff349faf9148443232c86500c3e73f719.mp3", "duration_ms": 10720}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a6e01e69-b662-4c31-9021-3de01a60bbc7', 'en-US', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "odd-one-out", "title": "The Strange Ingredient", "locale": "en-US", "subject": "mixed", "objectives": ["Detect which is NOT an ingredient for lemonade (lemons, sugar, water… and a ball?): separate what actually costs money to produce."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-odd-ingredient", "xp": 10, "type": "odd_one_out", "hints": ["Think about what you need to make lemonade: lemons, water, sugar...", "The ball is not for eating or drinking, it''s not for lemonade."], "title": "The Strange Ingredient", "payload": {"items": [{"id": "limones", "text_md": "Lemons", "image_url": "http://localhost:4006/files/lesson-images/9b7faf19036b043d950edde01c515b56139ebc13c048cccf0fd8321bda653c40.webp"}, {"id": "azucar", "text_md": "Sugar", "image_url": "http://localhost:4006/files/lesson-images/b7e0ae808c9bbcdd86e5e4d211da345b68d5be6c8ab5e01dececb4bcf98d8ed1.webp"}, {"id": "agua", "text_md": "Water", "image_url": "http://localhost:4006/files/lesson-images/bfa45e7d22d89c1c270432cbe0a301b67a3c806d98a0ab6c4ce37b96f508c16b.webp"}, {"id": "pelota", "text_md": "Ball", "image_url": "http://localhost:4006/files/lesson-images/aa8e9ea5a806406f7a85bcd4d1581677aaa86b62e6d1915ee8797c365648ebf2.webp"}], "reasons": [{"id": "r1", "text_md": "It is not an ingredient for making lemonade."}, {"id": "r2", "text_md": "It is an ingredient for lemonade."}]}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Rho has $10 to make lemonade. What does she NOT need to buy?", "difficulty": 1, "explanation_md": "The ball is not an ingredient for lemonade, so it doesn''t cost money to make it. Lemons, water, and sugar do cost money.", "audio_segment_id": "s1-odd-ingredient.prompt"}], "schema_version": 1}', '{"s1-odd-ingredient": {"odd_item_id": "pelota", "correct_reason_id": "r1"}}', '{"units": {"s1-odd-ingredient.hint.0": {"url": "http://localhost:4006/files/lesson-audio/2daeda7bf5322e12233d4fb65fc50b917987731efcac3d2cb7b6b3562f838fa3.mp3", "hash": "5ca1ca52aa7dd3ab5ed4083ba81fad83d4042f2fb5cd34f0febb483e8a3969ef", "bytes": 30528, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/2daeda7bf5322e12233d4fb65fc50b917987731efcac3d2cb7b6b3562f838fa3.mp3", "duration_ms": 5040}, "s1-odd-ingredient.hint.1": {"url": "http://localhost:4006/files/lesson-audio/000b60b4454241e04766281af9c5469d0fe347fca43b2f355ae6614775b01030.mp3", "hash": "2021a6c0014e73b9b4f869f1396b980e0c07c5ab2b3597a5e74e286147808ac5", "bytes": 25344, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/000b60b4454241e04766281af9c5469d0fe347fca43b2f355ae6614775b01030.mp3", "duration_ms": 4160}, "s1-odd-ingredient.prompt": {"url": "http://localhost:4006/files/lesson-audio/69561fe4c43f9d4c24ae5b218f0773003b9d934d7dfcdc084c7189e041f0b7a0.mp3", "hash": "c7323ed81d24d1ef7f664aa8f60c1c15ff715462900767f6cc1360b56d5f9741", "bytes": 33984, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/69561fe4c43f9d4c24ae5b218f0773003b9d934d7dfcdc084c7189e041f0b7a0.mp3", "duration_ms": 5600}, "s1-odd-ingredient.choices": {"url": "http://localhost:4006/files/lesson-audio/5da3a0b1a277921245407feb67c6d43f0edaba26a04a4a005cf250f8bfd15cb5.mp3", "hash": "3e8da1da7d919271b370b33b88cfc47018742bcaa3fbd0da086a2edd01cca212", "bytes": 19584, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/5da3a0b1a277921245407feb67c6d43f0edaba26a04a4a005cf250f8bfd15cb5.mp3", "duration_ms": 3200}, "s1-odd-ingredient.explanation": {"url": "http://localhost:4006/files/lesson-audio/fe8654e7d06d755ab0974d33caa92dfb81721e9ad2f73022788d50c862b4a28f.mp3", "hash": "5d4507aa3bb38ba0151df3313a2a1818f8edb5c015dc4eeb48155f7ea2567681", "bytes": 56448, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/fe8654e7d06d755ab0974d33caa92dfb81721e9ad2f73022788d50c862b4a28f.mp3", "duration_ms": 9360}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0a2bda3a-e275-46b8-b659-a7ad68a0afb3', 'pt-BR', '1', '{"meta": {"cast": ["zara", "liruf"], "slug": "lightning-round", "title": "Rodada Relâmpago: Troco Rápido", "locale": "pt-BR", "subject": "mixed", "objectives": ["Praticar o cálculo de troco rápido para manter os clientes felizes e juntar dinheiro para a guitarra."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "lightning-round-practice", "xp": 15, "type": "lightning_round", "hints": ["Some primeiro o custo total dos copos que o cliente pediu."], "title": "Troco Relâmpago!", "payload": {"questions": [{"id": "q1", "options": [{"id": "a", "text_md": "10 reais"}, {"id": "b", "text_md": "15 reais"}, {"id": "c", "text_md": "20 reais"}], "prompt_md": "Dona Rosa pede 2 copos. Paga com uma nota de 20 reais."}, {"id": "q2", "options": [{"id": "a", "text_md": "5 reais"}, {"id": "b", "text_md": "10 reais"}, {"id": "c", "text_md": "15 reais"}], "prompt_md": "Seu Pedro pede 3 copos. Paga com 20 reais."}, {"id": "q3", "options": [{"id": "a", "text_md": "5 reais"}, {"id": "b", "text_md": "0 reais"}, {"id": "c", "text_md": "10 reais"}], "prompt_md": "Dona Joana pede 1 copo. Paga com 10 reais."}, {"id": "q4", "options": [{"id": "a", "text_md": "0 reais"}, {"id": "b", "text_md": "5 reais"}, {"id": "c", "text_md": "10 reais"}], "prompt_md": "Tito pede 2 copos. Paga com 10 reais exatos."}], "seconds_per_q": 15}, "narrator": {"emotion": "encouraging", "character": "zara"}, "prompt_md": "Cada copo de limonada custa 5 reais. Ajude Liruf a dar o troco exato!", "difficulty": 2, "explanation_md": "Lembre-se: primeiro some o custo de todos os copos (cada um custa 5 reais) e depois subtraia do valor da nota. Por exemplo, 2 copos e uma nota de 20: 20 - (2×5) = 10 reais de troco. Um erro comum é subtrair sem multiplicar; assim você garante dar o troco exato.", "audio_segment_id": "lightning-round-practice.prompt"}], "schema_version": 1}', '{"lightning-round-practice": {"correct": {"q1": "a", "q2": "a", "q3": "a", "q4": "a"}}}', '{"units": {"lightning-round-practice.hint.0": {"url": "http://localhost:4006/files/lesson-audio/4ca52e43705e1d47ee1a10389f094dd834e515c97e807877a51de577b2a01c33.mp3", "hash": "65cb1c9710212ef2e2dd75a0428ca284abefcf402f0af0abc529a0a88a0cf731", "bytes": 22896, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/4ca52e43705e1d47ee1a10389f094dd834e515c97e807877a51de577b2a01c33.mp3", "duration_ms": 3760}, "lightning-round-practice.prompt": {"url": "http://localhost:4006/files/lesson-audio/65a8a84700516a2ce3c12b56b56151fd9db7eb3b563890c0e42afe3a16334500.mp3", "hash": "366386fbebfbaa3399db8a611daac5af4f979af735f571ab2daa4a8c2a367700", "bytes": 32976, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/65a8a84700516a2ce3c12b56b56151fd9db7eb3b563890c0e42afe3a16334500.mp3", "duration_ms": 5440}, "lightning-round-practice.explanation": {"url": "http://localhost:4006/files/lesson-audio/99202a0764dc5a0084453ca17e7fd85f8523cf558b3d29da1429a1b5ae16bb33.mp3", "hash": "d5930990e8a0fea8353c232d369230d01935ed5a3616e0c6b6bf559f99ebfb54", "bytes": 122256, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/99202a0764dc5a0084453ca17e7fd85f8523cf558b3d29da1429a1b5ae16bb33.mp3", "duration_ms": 20320}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08f47096-e44f-4b4e-822f-472c6fd87425', 'pt-BR', '1', '{"meta": {"cast": ["liruf", "rho"], "slug": "speed-tap", "title": "Compras relâmpago", "locale": "pt-BR", "subject": "mixed", "objectives": ["Tomar decisões rápidas de dinheiro comparando opções.", "Distinguir entre gastos que ajudam o posto de limonada e caprichos que não."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-speed-tap", "xp": 15, "type": "speed_tap", "hints": ["Pergunte-se: isso faz com que eu possa vender mais limonada?"], "title": "Agarra o bom!", "payload": {"items": [{"id": "limones", "text_md": "Limões", "image_url": "http://localhost:4006/files/lesson-images/e22536167eec7164cfd1be804cdb641e8ea235d498d560559e72e3eb209bad4e.webp"}, {"id": "calcomania", "text_md": "Adesivo de dinossauro"}, {"id": "vasos", "text_md": "Copos", "image_url": "http://localhost:4006/files/lesson-images/f3471dc592f13c0e8abebb27f62f5337de4ff181f9f049a8f3e2cdfe5423115f.webp"}, {"id": "dulce", "text_md": "Doce", "image_url": "http://localhost:4006/files/lesson-images/36253dbf772f2fedbd6195f49da050bd3fad7cea87c22a09f43a74be62c12a2c.webp"}, {"id": "azucar", "text_md": "Açúcar", "image_url": "http://localhost:4006/files/lesson-images/894dbc8d21895926660a080bf5d60058ca524235f485bced2254d2147c72960b.webp"}, {"id": "juguete", "text_md": "Brinquedo", "image_url": "http://localhost:4006/files/lesson-images/8edb62c42ab861adbfad2e35e153a1917f420813befb6691224c5ab975331527.webp"}, {"id": "hielo", "text_md": "Gelo", "image_url": "http://localhost:4006/files/lesson-images/b51488595260bbc4865879da7b409992918a38cf9297944430473a27325bf9d4.webp"}, {"id": "cartel", "text_md": "Cartaz chamativo", "image_url": "http://localhost:4006/files/lesson-images/397a7d79d73381f8bfcc443b20b5191918411b9b7b66f01357d28d0d4cb0bd5d.webp"}], "seconds": 30, "instruction_md": "Toque os gastos que SIM ajudam!"}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Liruf deve economizar para sua guitarra de 80 reais. Rho passa cartões: toque apenas o que ajuda o posto.", "difficulty": 2, "explanation_md": "Os limões, copos, açúcar, gelo e um cartaz chamativo te ajudam a fazer e vender mais copos de 5 reais. Os caprichos como adesivos não ajudam o posto."}], "schema_version": 1}', '{"s1-speed-tap": {"target_ids": ["limones", "vasos", "azucar", "hielo", "cartel"]}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4dcc7a9f-f2f6-4b40-abd4-a522d168e446', 'en-US', '1', '{"meta": {"cast": ["zara"], "slug": "flash-match", "title": "Help Zara organize her stand!", "locale": "en-US", "subject": "mixed", "objectives": ["Match stand words (savings, cost, profit) with their concrete examples (piggy bank, lemons, what''s left over) to understand them quickly."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-flash-match", "xp": 5, "type": "flash_match", "title": "Help Zara!", "payload": {"left": [{"id": "left-ahorro", "text_md": "Savings", "image_url": "http://localhost:4006/files/lesson-images/41779dda9013ec95d69ccbf35ed79d2791adc7328851df5586e7827007f36a9e.webp"}, {"id": "left-costo", "text_md": "Cost", "image_url": "http://localhost:4006/files/lesson-images/be687254e0f231ab2cd453a6615011b598f75a069a8f024ab52c440ff1725ee6.webp"}, {"id": "left-ganancia", "text_md": "Profit", "image_url": "http://localhost:4006/files/lesson-images/c547343fdd1bb97dcc34866e7c2540f7e2b2f8cd6624ab66edc8ab0ce4044327.webp"}], "right": [{"id": "right-alcancia", "text_md": "Piggy bank"}, {"id": "right-limones", "text_md": "Lemons"}, {"id": "right-sobrantes", "text_md": "What''s left over"}], "seconds": 25}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Zara finished her day. She has her piggy bank, the lemons, and some coins. Match each concept with what she did.", "difficulty": 1, "explanation_md": "Good! **Savings** is the money Zara puts in her piggy bank. **Cost** is what she paid for the lemons. **Profit** is what''s left over after paying everything. If you thought the cost was what''s left over, remember: cost is an expense, not a profit.", "audio_segment_id": "s1-flash-match.prompt"}], "schema_version": 1}', '{"s1-flash-match": {"pairs": [["left-ahorro", "right-alcancia"], ["left-costo", "right-limones"], ["left-ganancia", "right-sobrantes"]]}}', '{"units": {"s1-flash-match.prompt": {"url": "http://localhost:4006/files/lesson-audio/291e0e94ba7a1c3b303938e05f6fe1ebdf85c774a2df172c9ae068bcd0ed9f8c.mp3", "hash": "998bb940da5e37c334c9c8c658b494045aa049d1139d4903f042daefad2e7e81", "bytes": 45936, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/291e0e94ba7a1c3b303938e05f6fe1ebdf85c774a2df172c9ae068bcd0ed9f8c.mp3", "duration_ms": 7600}, "s1-flash-match.explanation": {"url": "http://localhost:4006/files/lesson-audio/7b392f651c649cea35738abda6eab76943488408398c2be19475a30458995f61.mp3", "hash": "80c40daabf62cab4bff6f2b096609a1e720fa62006ccdfa2b96d131f6cc9878d", "bytes": 94464, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/7b392f651c649cea35738abda6eab76943488408398c2be19475a30458995f61.mp3", "duration_ms": 15680}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a00c4534-6e88-42ac-ab77-3465a684f47d', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "story-scene", "title": "O plano de Liruf", "locale": "pt-BR", "subject": "mixed", "objectives": ["Entender que o dinheiro se ganha oferecendo algo que outros querem", "Ver que uma meta clara ajuda a começar"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-plan", "xp": 0, "type": "story_scene", "title": "O plano de Liruf", "payload": {"art": {"icon": "emoji_objects", "tint": "primary", "image_url": "http://localhost:4006/files/lesson-images/472ce52e34ae47a064483c951b954cc8265a21f4b67d54272704d854774db9db.webp"}, "action": "idle", "body_md": "Liruf desenha seu plano em um cartaz: um copo de limonada = 5 reais. Muitos copos = um violão de 80 reais. Mas… quantos copos ele precisa vender? Olha! Se ele vende 2 copos, ganha 10 reais. Já está avançando! Quantos copos para 80 reais? Vamos resolver juntos!", "emotion": "excited", "backdrop": "band", "character": "liruf"}, "narrator": {"emotion": "excited", "character": "liruf"}, "prompt_md": "Cada copo de limonada custa 5 reais. Liruf precisa de 80 reais para o violão.", "difficulty": 1, "audio_segment_id": "s1-plan.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-plan.body": {"url": "http://localhost:4006/files/lesson-audio/4f65cc14d71cc28905aa78681d1b31435fceb0b5030aaaa6e5e7fdbb7765ee90.mp3", "hash": "4825a5889f277253ccc1c0431c6f1344bfb51ce7ed76af761cbda5531c5b1d0c", "bytes": 132768, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/4f65cc14d71cc28905aa78681d1b31435fceb0b5030aaaa6e5e7fdbb7765ee90.mp3", "duration_ms": 22080}, "s1-plan.prompt": {"url": "http://localhost:4006/files/lesson-audio/70f58ad1ee9859493b4d762e2648e11dad52e54cc981cc305d148251306c4aed.mp3", "hash": "1a4f83eb32cc65f38c3d748fa6776c48172fd90ee424a4849e2e0e9f1be6958b", "bytes": 40608, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/70f58ad1ee9859493b4d762e2648e11dad52e54cc981cc305d148251306c4aed.mp3", "duration_ms": 6720}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4dcc7a9f-f2f6-4b40-abd4-a522d168e446', 'pt-BR', '1', '{"meta": {"cast": ["zara"], "slug": "flash-match", "title": "Ajude Zara a organizar seu posto!", "locale": "pt-BR", "subject": "mixed", "objectives": ["Relacionar palavras do posto (poupança, custo, lucro) com seus exemplos concretos (cofrinho, limões, o que sobra) para entendê-las rapidamente."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-flash-match", "xp": 5, "type": "flash_match", "title": "Ajude Zara!", "payload": {"left": [{"id": "left-ahorro", "text_md": "Poupança", "image_url": "http://localhost:4006/files/lesson-images/e929dc35cbc839d09e6beb3ec6d07ebf182b6fcf717549d543f122aef9cad304.webp"}, {"id": "left-costo", "text_md": "Custo", "image_url": "http://localhost:4006/files/lesson-images/7df33d24f07091e432f33835ce469b2cb533ed59d56c8dd40608a2df3e6820b2.webp"}, {"id": "left-ganancia", "text_md": "Lucro", "image_url": "http://localhost:4006/files/lesson-images/d60095220953ed68b3b702a21cb571c10dd771fc5bfca9a6afe9d0bbfa1e4e6c.webp"}], "right": [{"id": "right-alcancia", "text_md": "Cofrinho"}, {"id": "right-limones", "text_md": "Limões"}, {"id": "right-sobrantes", "text_md": "O que sobra"}], "seconds": 25}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Zara terminou seu dia. Ela tem seu cofrinho, os limões e algumas moedas. Relacione cada conceito com o que ela fez.", "difficulty": 1, "explanation_md": "Muito bem! A **poupança** é o dinheiro que Zara guarda no seu cofrinho. O **custo** é o que ela pagou pelos limões. O **lucro** é o que sobra depois de pagar tudo. Se você pensou que o custo era o que sobra, lembre-se: o custo é uma despesa, não um lucro.", "audio_segment_id": "s1-flash-match.prompt"}], "schema_version": 1}', '{"s1-flash-match": {"pairs": [["left-ahorro", "right-alcancia"], ["left-costo", "right-limones"], ["left-ganancia", "right-sobrantes"]]}}', '{"units": {"s1-flash-match.prompt": {"url": "http://localhost:4006/files/lesson-audio/e3ae4a9341aaa3df8c471e283304841c34db4981182dd71791beb4c9a4fc46f6.mp3", "hash": "daad602315994113b4431350d92cc9e0e72e39e97396dc27e3b597461f804990", "bytes": 51696, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/e3ae4a9341aaa3df8c471e283304841c34db4981182dd71791beb4c9a4fc46f6.mp3", "duration_ms": 8560}, "s1-flash-match.explanation": {"url": "http://localhost:4006/files/lesson-audio/4946e149eecfc8871493b5881aea473f4c5e0b4d33bab1c503eeea383d6d8c82.mp3", "hash": "b0c4c7feef5ac245d48921537d707bfdf01cc524a6632d15c4ea605cb6d568ad", "bytes": 95328, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/4946e149eecfc8871493b5881aea473f4c5e0b4d33bab1c503eeea383d6d8c82.mp3", "duration_ms": 15840}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('000a07f3-d716-40f9-bb5f-2d175c582162', 'es-MX', '1', '{"meta": {"cast": ["liruf"], "slug": "spot-error", "title": "Encuentra el error: la cuenta de Liruf", "locale": "es-MX", "subject": "mixed", "objectives": ["Identificar que 5+5+5 no puede dar 20 y corregir la suma de ventas."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "e1-spot-error", "xp": 15, "type": "spot_error", "title": "Encuentra el error", "payload": {"steps": [{"id": "s1", "text_md": "Lunes: vendí 1 vaso de limonada → 5 pesos."}, {"id": "s2", "text_md": "Martes: vendí otro vaso → 5 pesos."}, {"id": "s3", "text_md": "Miércoles: vendí un vaso más → 5 pesos."}, {"id": "s4", "text_md": "Total: 5 + 5 + 5 = 20 pesos."}], "context_md": "Liruf anotó lo que vendió esta semana."}, "narrator": {"emotion": "thinking", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/dce3cf691fb8fe08b892a1cfab7381eeb4151b4e29a434189135a2e3875ced58.webp", "prompt_md": "Liruf revisa su cuaderno de ventas. Toca el paso donde se equivocó.", "difficulty": 2, "explanation_md": "Cada vaso cuesta 5 pesos. Tres vasos suman 5+5+5=15. Liruf se confundió y escribió 20. ¡A revisar!", "audio_segment_id": "e1-spot-error.prompt"}], "schema_version": 1}', '{"e1-spot-error": {"error_ids": ["s4"], "correction_md": "La suma es 5 + 5 + 5 = 15, no 20. Liruf le puso un 5 extra."}}', '{"units": {"e1-spot-error.prompt": {"url": "http://localhost:4006/files/lesson-audio/945f02fb754b7c76ba8c7f861208345ccf4973ddfa96d44f4527a3b2de8e5b70.mp3", "hash": "84c315de8c7885ea80e5e2f2807e25bcf552ac4634c2e98dbd4a0ce256589590", "bytes": 33408, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/945f02fb754b7c76ba8c7f861208345ccf4973ddfa96d44f4527a3b2de8e5b70.mp3", "duration_ms": 5520}, "e1-spot-error.explanation": {"url": "http://localhost:4006/files/lesson-audio/fbd4f7ac0293dc95bf1c7469f52c1f1383d3a68e1c128d5f97457fad3d3cf8ac.mp3", "hash": "d90b51b23de919091ea3f3444122c29defa5c3c590550482c1334c99fd4cb913", "bytes": 72864, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/fbd4f7ac0293dc95bf1c7469f52c1f1383d3a68e1c128d5f97457fad3d3cf8ac.mp3", "duration_ms": 12080}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b979bce6-8935-480e-8471-33053faa2321', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "sort-buckets", "title": "Sort the stand''s purchases", "locale": "en-US", "subject": "mixed", "objectives": ["Sort purchases into stand needs and wants that can wait"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-clasifica", "xp": 10, "type": "sort_buckets", "hints": ["A need is what the stand needs to sell lemonade: lemons, cups, ice.", "A want is something you like but isn''t urgent: stickers, balloons, toys."], "title": "Need or want", "payload": {"items": [{"id": "limones", "text_md": "Lemons", "image_url": "http://localhost:4006/files/lesson-images/a5139a9e8374cf4e6806a56616e3a91cb703ab46033f89b87a82dd8c8980361d.webp"}, {"id": "vasos", "text_md": "Cups", "image_url": "http://localhost:4006/files/lesson-images/73ffd9c77580e3b11b75b6301187ca589c4e4ffd97783711268c8711e48bdb79.webp"}, {"id": "stickers", "text_md": "Stickers", "image_url": "http://localhost:4006/files/lesson-images/dc1cc302dacc0a0aded742a2d0c38de331c3030acdf12cb32c30090a047f00b1.webp"}, {"id": "globos", "text_md": "Balloons", "image_url": "http://localhost:4006/files/lesson-images/031f6c6649f48723312092e3d6817d54f9d95405f48262c23499248a139e1043.webp"}], "buckets": [{"id": "necesidad", "label": "Stand need"}, {"id": "gusto", "label": "Want that can wait"}]}, "narrator": {"emotion": "excited", "character": "dina"}, "prompt_md": "Tap each purchase and put it in the right bucket: stand need or want that can wait.", "difficulty": 1, "explanation_md": "Lemons and cups are stand needs to make and serve lemonade. Stickers and balloons are wants that can wait.", "audio_segment_id": "s1-clasifica.prompt"}], "schema_version": 1}', '{"s1-clasifica": {"assignments": {"vasos": "necesidad", "globos": "gusto", "limones": "necesidad", "stickers": "gusto"}}}', '{"units": {"s1-clasifica.hint.0": {"url": "http://localhost:4006/files/lesson-audio/0621770436d13adebf9181fe2eb261d347fddcbbff6f2c02570ed948711b2ee1.mp3", "hash": "c8c628cb4c7a88a215a2bb490d9a707450dae348ad27e24556099602bbcfdcc3", "bytes": 25344, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/0621770436d13adebf9181fe2eb261d347fddcbbff6f2c02570ed948711b2ee1.mp3", "duration_ms": 4160}, "s1-clasifica.hint.1": {"url": "http://localhost:4006/files/lesson-audio/eddd2e47d7d23e5de15b38428945aad6302d1c285151f1e8f46aa288d728ed8d.mp3", "hash": "0df35d70cf63c703b5fa274b8e843dd0016ef14ec7538368aae4fe631b9093ac", "bytes": 29664, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/eddd2e47d7d23e5de15b38428945aad6302d1c285151f1e8f46aa288d728ed8d.mp3", "duration_ms": 4880}, "s1-clasifica.prompt": {"url": "http://localhost:4006/files/lesson-audio/7af933143cb88681f275c57964ef20c13e82bcddde993862b59d778298d2cb83.mp3", "hash": "4c8274fb4f0b759a25e0c008786b29db4154d6262c26ab62ec7548cbbac688fb", "bytes": 29088, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/7af933143cb88681f275c57964ef20c13e82bcddde993862b59d778298d2cb83.mp3", "duration_ms": 4800}, "s1-clasifica.explanation": {"url": "http://localhost:4006/files/lesson-audio/831c856016dfb1ebb462607ab33520eb27fe1a2f332b275afc7e664aa942847e.mp3", "hash": "1aa519b803688b50acee95d3b2303f85cd4814b73c85c4e6939dbbf97ab060b3", "bytes": 33408, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/831c856016dfb1ebb462607ab33520eb27fe1a2f332b275afc7e664aa942847e.mp3", "duration_ms": 5520}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('29159ba6-6f90-42be-9578-fda50515f345', 'pt-BR', '1', '{"meta": {"cast": ["liruf"], "slug": "budget-fit", "title": "De compras com 20 reais!", "locale": "pt-BR", "subject": "mixed", "objectives": ["Planejar compras dentro de um orçamento fixo.", "Somar e subtrair para verificar que o total não exceda 20 reais."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-budget-fit", "xp": 15, "type": "budget_fit", "hints": ["Primeiro some o custo dos limões e do açúcar: 8 + 6.", "Subtraia esse total de 20 para saber quanto dinheiro te resta."], "title": "De compras com 20 reais!", "payload": {"items": [{"id": "limones", "icon": "eco", "need": true, "label": "Limões", "price": 8, "image_url": "http://localhost:4006/files/lesson-images/1103a85163a8db2e27c4f8c6025208461697ea99f23bfe74b4eff4d26a0e1ca2.webp"}, {"id": "azucar", "icon": "label", "need": true, "label": "Açúcar", "price": 6, "image_url": "http://localhost:4006/files/lesson-images/674566a5147ad8e7d380122f73fa21eaf1e29b7cd2d3a7b97b9bc83b6c365c30.webp"}, {"id": "hielo", "icon": "ac_unit", "need": false, "label": "Gelo", "price": 5, "image_url": "http://localhost:4006/files/lesson-images/2461464ae90701ff7895dc0d81c8c094b9f02164812f688c0755a73f430d1e44.webp"}, {"id": "popotes", "icon": "local_drink", "need": false, "label": "Canudos", "price": 3, "image_url": "http://localhost:4006/files/lesson-images/c9cc9ebc0e9c613bd4fc85b1932d011743af776206f308659dd007b6ab6de30c.webp"}, {"id": "jarra", "icon": "local_cafe", "need": false, "label": "Jarra bonita", "price": 8, "image_url": "http://localhost:4006/files/lesson-images/f6275f3daabf2789232ded068c8b2767bd54eb11d34d4c3df60bab002f4cc214.webp"}], "budget": 20, "currency": "BRL", "must_buy_needs": true}, "narrator": {"emotion": "neutral", "character": "liruf"}, "prompt_md": "Liruf DEVE comprar limões (8 reais) e açúcar (6 reais). Que extra pode acrescentar sem passar de 20 reais?", "difficulty": 2, "explanation_md": "Com limões, açúcar e gelo, você gasta 19 reais, te sobra 1 real e você tem tudo. A jarra faria você passar de 20 e o vendedor a tiraria; sem açúcar, a limonada ficaria amarga e ninguém a compraria."}], "schema_version": 1}', '{"s1-budget-fit": {}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('df879f53-8479-4b98-9651-889fcae66fdc', 'es-MX', '1', '{"meta": {"cast": ["rho", "liruf"], "slug": "repaso-true-false", "title": "Repaso: ¿Ganancia real?", "locale": "es-MX", "subject": "mixed", "objectives": ["Diferenciar entre ventas totales y ganancia real considerando los costos."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "tf1-repaso-ganancia", "xp": 10, "type": "true_false", "hints": ["Pista: Ganancia = dinero recibido - dinero gastado en hacer los vasos."], "title": "¿Ganó 50?", "payload": {"statement_md": "Liruf vendió 10 vasos a 5 pesos, entonces ganó 50.", "justifications": [{"id": "j1", "text_md": "Es verdad: 10 vasos × 5 pesos = 50 pesos. Eso fue lo que entró a la caja."}, {"id": "j2", "text_md": "Es falso: hacer cada vaso cuesta 2 pesos. Ganó solo 3 pesos por vaso; 10 × 3 = 30 pesos."}]}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Liruf vendió 10 vasos a 5 pesos; hacerlos cuesta 2 pesos. ¿Ganó 50? Elige verdad o mentira.", "difficulty": 1, "explanation_md": "Liruf recibió 50 pesos en total, pero hacer los vasos le costó 20 pesos. Por eso ganó solo 30 pesos (3 pesos por vaso).", "audio_segment_id": "tf1-repaso-ganancia.prompt"}], "schema_version": 1}', '{"tf1-repaso-ganancia": {"is_true": false, "correct_justification_id": "j2"}}', '{"units": {"tf1-repaso-ganancia.hint.0": {"url": "http://localhost:4006/files/lesson-audio/f815a43ac6f91e12021baf522ddf4440910caf87a0aad72dfb38f5444697af4f.mp3", "hash": "5cf962223e9f9204b59a3a2bc1987e113d8c9296b85d223119bc5c5d3caed94b", "bytes": 34416, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/f815a43ac6f91e12021baf522ddf4440910caf87a0aad72dfb38f5444697af4f.mp3", "duration_ms": 5680}, "tf1-repaso-ganancia.prompt": {"url": "http://localhost:4006/files/lesson-audio/01533c703c0aaa50f84da8e74bd018e62e869b9e0d506e9186f8b2ccc4af6cea.mp3", "hash": "4dcab7a6de1959d61085d942aa022e33452afd90bb5b5abffc48a15c352ab07e", "bytes": 54576, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/01533c703c0aaa50f84da8e74bd018e62e869b9e0d506e9186f8b2ccc4af6cea.mp3", "duration_ms": 9040}, "tf1-repaso-ganancia.explanation": {"url": "http://localhost:4006/files/lesson-audio/bbe06664afa7673b978abbd1ea76d14e2b79d6633512c9768cc2c59cb33d2173.mp3", "hash": "87d108e62030ce717839846da8196d78920a827b3555aec33e98e4df85ebdf5d", "bytes": 60768, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/bbe06664afa7673b978abbd1ea76d14e2b79d6633512c9768cc2c59cb33d2173.mp3", "duration_ms": 10080}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08f47096-e44f-4b4e-822f-472c6fd87425', 'es-MX', '1', '{"meta": {"cast": ["liruf", "rho"], "slug": "speed-tap", "title": "Compras relámpago", "locale": "es-MX", "subject": "mixed", "objectives": ["Tomar decisiones rápidas de dinero comparando opciones.", "Distinguir entre gastos que ayudan al puesto de limonada y caprichos que no."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-speed-tap", "xp": 15, "type": "speed_tap", "hints": ["Pregúntate: ¿esto hace que pueda vender más limonada?"], "title": "¡Agarra lo bueno!", "payload": {"items": [{"id": "limones", "text_md": "Limones", "image_url": "http://localhost:4006/files/lesson-images/23f74254e245c3d45a9332e25c01a9ccbdb0be33eef19ca830574be9aaf8542d.webp"}, {"id": "calcomania", "text_md": "Calcomanía de dinosaurio"}, {"id": "vasos", "text_md": "Vasos", "image_url": "http://localhost:4006/files/lesson-images/eb87037f80540805bb8d630b9b18628287c5fc64e99fef63a9893aff61c3cd58.webp"}, {"id": "dulce", "text_md": "Dulce", "image_url": "http://localhost:4006/files/lesson-images/dcb18c68887860dd4a4bca23749314272e34047a5f5191547ab9091dbc728e90.webp"}, {"id": "azucar", "text_md": "Azúcar", "image_url": "http://localhost:4006/files/lesson-images/a541255ac8e9de524d4c8ac1a463eb3a5b20fb42d79df839f95aea6c062e849d.webp"}, {"id": "juguete", "text_md": "Juguete", "image_url": "http://localhost:4006/files/lesson-images/e4072991efe3c4c374f5f21d1816bdb0ac07d6e047253e77ad22249845753423.webp"}, {"id": "hielo", "text_md": "Hielo", "image_url": "http://localhost:4006/files/lesson-images/65cf7775d692ffee1fe707494c55f43448d200bc492e4f62bcf617874872df31.webp"}, {"id": "cartel", "text_md": "Cartel llamativo", "image_url": "http://localhost:4006/files/lesson-images/7bc69ae6e4344814acb48759644204118b56748484638a27b20ed69abd0da098.webp"}], "seconds": 30, "instruction_md": "¡Toca los gastos que SÍ ayudan!"}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Liruf debe ahorrar para su guitarra de 80 pesos. Rho pasa tarjetas: toca solo lo que ayuda al puesto.", "difficulty": 2, "explanation_md": "Los limones, vasos, azúcar, hielo y un cartel llamativo te ayudan a hacer y vender más vasos de 5 pesos. Los caprichos como calcomanías no ayudan al puesto."}], "schema_version": 1}', '{"s1-speed-tap": {"target_ids": ["limones", "vasos", "azucar", "hielo", "cartel"]}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('29159ba6-6f90-42be-9578-fda50515f345', 'en-US', '1', '{"meta": {"cast": ["liruf"], "slug": "budget-fit", "title": "Shopping with 20 dollars!", "locale": "en-US", "subject": "mixed", "objectives": ["Plan purchases within a fixed budget.", "Add and subtract to verify that the total does not exceed 20 dollars."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-budget-fit", "xp": 15, "type": "budget_fit", "hints": ["First add the cost of the lemons and the sugar: 8 + 6.", "Subtract that total from 20 to know how much money you have left."], "title": "Shopping with 20 dollars!", "payload": {"items": [{"id": "limones", "icon": "eco", "need": true, "label": "Lemons", "price": 8, "image_url": "http://localhost:4006/files/lesson-images/2b3948e6b4480a7ea41359a77f501171f80851a8d9f187efa0d21b91cc4aa83a.webp"}, {"id": "azucar", "icon": "label", "need": true, "label": "Sugar", "price": 6, "image_url": "http://localhost:4006/files/lesson-images/326eb3fe8e52896a4c86f515fe5108f2967a36c1af69711a33606126f02ea3a5.webp"}, {"id": "hielo", "icon": "ac_unit", "need": false, "label": "Ice", "price": 5, "image_url": "http://localhost:4006/files/lesson-images/57375635ea15628d925beaf643febd078b69a45610ca6f4f4063b70fca8df735.webp"}, {"id": "popotes", "icon": "local_drink", "need": false, "label": "Straws", "price": 3, "image_url": "http://localhost:4006/files/lesson-images/48145f007cddf5cbef8e403ee482756287d397a7a95d9449ef8a1d3fc27a880b.webp"}, {"id": "jarra", "icon": "local_cafe", "need": false, "label": "Pretty pitcher", "price": 8, "image_url": "http://localhost:4006/files/lesson-images/a93d67e7532da6e7398922e059b1e7be4322fa4698fa06ced114bb78971f35a3.webp"}], "budget": 20, "currency": "USD", "must_buy_needs": true}, "narrator": {"emotion": "neutral", "character": "liruf"}, "prompt_md": "Liruf MUST buy lemons (8 dollars) and sugar (6 dollars). What extra can they add without exceeding 20 dollars?", "difficulty": 2, "explanation_md": "With lemons, sugar and ice you spend 19 dollars, you have 1 left and you have everything. The pitcher would put you over 20 and the merchant would take it away; without sugar the lemonade would be bitter and nobody would buy it."}], "schema_version": 1}', '{"s1-budget-fit": {}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9ceeee19-c270-4624-a828-92e6f501754e', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "confidence-quiz", "title": "Confidence in your calculations", "locale": "en-US", "subject": "mixed", "objectives": ["Adding two equal prices (5+5) to calculate a total sale", "Reflect on how confident you feel about your answer"], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-confidence", "xp": 10, "type": "confidence_quiz", "title": "How much did Liruf earn?", "payload": {"options": [{"id": "opt5", "text_md": "5 dollars", "rationale_md": "Did you count only one cup? Remember that Liruf sold TWO cups, not one."}, {"id": "opt10", "text_md": "10 dollars"}, {"id": "opt0", "text_md": "0 dollars", "rationale_md": "Did you subtract instead of add? The two cups are ADDED, not subtracted."}, {"id": "opt25", "text_md": "25 dollars", "rationale_md": "Did you multiply 5×5? Here you ADD 5+5, not multiply."}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf sold two cups of lemonade at 5 dollars each. How many dollars did Liruf earn?", "difficulty": 1, "explanation_md": "You added 5 + 5 and earned 10 dollars. When you practice, you can trust your calculations more.", "audio_segment_id": "s1-confidence.prompt"}], "schema_version": 1}', '{"s1-confidence": {"correct_option_id": "opt10"}}', '{"units": {"s1-confidence.prompt": {"url": "http://localhost:4006/files/lesson-audio/ecd5b5b6e6ac97436998fc61ed2f70203b30699e42bfacfe3afa6bb2ca3d85a1.mp3", "hash": "260d59cae370ce30d5e5f5b8ea5f6b021e6387c0ff71e2c221d311a836035bdd", "bytes": 30096, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/ecd5b5b6e6ac97436998fc61ed2f70203b30699e42bfacfe3afa6bb2ca3d85a1.mp3", "duration_ms": 4960}, "s1-confidence.choices": {"url": "http://localhost:4006/files/lesson-audio/047de39242c76e2aab3e0ccbbeec733c9e85c17b35ec7f2b17fbc03fd1a4093f.mp3", "hash": "fdf6330ed124996f132f9a18c0870a8c61d41199cb8d4acf3f50a2b45213aed9", "bytes": 24336, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/047de39242c76e2aab3e0ccbbeec733c9e85c17b35ec7f2b17fbc03fd1a4093f.mp3", "duration_ms": 4000}, "s1-confidence.explanation": {"url": "http://localhost:4006/files/lesson-audio/133036c3b8e49469d476e4c08013260357e540d78a7fdbe79062a04520222458.mp3", "hash": "682fb1a5b20a61afc22522efd552d1690e2cfe409b592ae08d84b4daf25e376c", "bytes": 38304, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/133036c3b8e49469d476e4c08013260357e540d78a7fdbe79062a04520222458.mp3", "duration_ms": 6320}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('35abfab2-f1da-4643-915a-3fdba69f3a63', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "fill-blank", "title": "Filling in the account book", "locale": "en-US", "subject": "mixed", "objectives": ["Calculate the profit by subtracting the cost of the ingredients from the selling price."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ganancia-liruf", "xp": 5, "type": "fill_blank", "title": "Liruf''s profit", "payload": {"bank": [{"id": "a", "text_md": "2"}, {"id": "b", "text_md": "3"}, {"id": "c", "text_md": "5"}, {"id": "d", "text_md": "7"}], "mode": "bank", "text_md": "I sold a glass of lemonade for 5 dollars and the ingredients cost 2 dollars. My profit is {{1}} dollars."}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf sells lemonade. Liruf sells each glass for 5 dollars and the ingredients cost 2 dollars. How much does Liruf earn per glass?", "difficulty": 1, "explanation_md": "The profit is 3 dollars. Subtract the cost (2) from the price (5): 5 - 2 = 3. That’s how Liruf saves for his doll!", "audio_segment_id": "s1-ganancia-liruf.prompt"}], "schema_version": 1}', '{"s1-ganancia-liruf": {"gaps": [{"gap": 1, "accept": ["3"], "bank_id": "b"}]}}', '{"units": {"s1-ganancia-liruf.prompt": {"url": "http://localhost:4006/files/lesson-audio/dce62af6d763308862001886545abd26c96a7a21e2c356580b5174bb25073eeb.mp3", "hash": "731274d6a85535a2d9eaa633d66538a848bf16653119b235faa42626cab042ed", "bytes": 48816, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/dce62af6d763308862001886545abd26c96a7a21e2c356580b5174bb25073eeb.mp3", "duration_ms": 8080}, "s1-ganancia-liruf.explanation": {"url": "http://localhost:4006/files/lesson-audio/98308499657d85f24581a1b1dadfde1bd67f1bf436dd7ad48082ae246c0366f5.mp3", "hash": "f62a1f5e017d0d871783cd3b87cb080a2fbd54f57baf92339d65b9e335ab5a57", "bytes": 54576, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/98308499657d85f24581a1b1dadfde1bd67f1bf436dd7ad48082ae246c0366f5.mp3", "duration_ms": 9040}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f9ad47f4-7031-4552-97cd-a0b426882208', 'es-MX', '1', '{"meta": {"cast": ["rho"], "slug": "code-order", "title": "La registradora paso a paso", "locale": "es-MX", "subject": "mixed", "objectives": ["Ordenar las instrucciones para operar una registradora casera."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-code-order", "xp": 15, "type": "code_order", "hints": ["Piensa: ¿qué debe hacer primero la registradora cuando alguien quiere comprar algo?"], "title": "La registradora de Rho", "payload": {"blocks": [{"id": "recibir_pago", "text_md": "Recibe el pago"}, {"id": "verificar_monto", "text_md": "Verifica el monto"}, {"id": "dar_cambio", "text_md": "Da el cambio"}, {"id": "anotar_venta", "text_md": "Anota la venta"}], "language_hint": "español"}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Rho inventó una registradora de cartón. ¿Cuál es el orden correcto de las instrucciones?", "difficulty": 2, "explanation_md": "Rho programó su registradora para primero recibir el pago, luego verificar que la cantidad sea correcta, después dar el cambio necesario y finalmente anotar la venta. Así no se olvida de ningún paso.", "audio_segment_id": "s1-code-order.prompt"}], "schema_version": 1}', '{"s1-code-order": {"order": ["recibir_pago", "verificar_monto", "dar_cambio", "anotar_venta"]}}', '{"units": {"s1-code-order.hint.0": {"url": "http://localhost:4006/files/lesson-audio/1b7fb226754e7d639c0211ab84f474ea8b205954e5ef1e7928be4bdd0c9dfe02.mp3", "hash": "e44336bce1b49af6366ab5f6bb95f17c6c2256db2dbe43914531b8eee8be676e", "bytes": 31104, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/1b7fb226754e7d639c0211ab84f474ea8b205954e5ef1e7928be4bdd0c9dfe02.mp3", "duration_ms": 5120}, "s1-code-order.prompt": {"url": "http://localhost:4006/files/lesson-audio/fd9315f017a6b02b4bef26c0c9c8696934d3c9bf3d841502c39225f8c63df431.mp3", "hash": "d4ea07adfc848390642c477b16fa0e8f3ff711491f8f7e7da7fae983e6536f19", "bytes": 36288, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/fd9315f017a6b02b4bef26c0c9c8696934d3c9bf3d841502c39225f8c63df431.mp3", "duration_ms": 6000}, "s1-code-order.explanation": {"url": "http://localhost:4006/files/lesson-audio/34bd9f568ade9eb85d27450e62a0856b36dcfb6e8b655278860d1cc7ba851f63.mp3", "hash": "cc3bd6e028611b149cd98fc5fab7d80a40a275b72c51d223d2ae21da29546d64", "bytes": 77184, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/34bd9f568ade9eb85d27450e62a0856b36dcfb6e8b655278860d1cc7ba851f63.mp3", "duration_ms": 12800}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('64ccde87-2312-4acf-a950-409fd6a622c9', 'es-MX', '1', '{"meta": {"cast": ["zara"], "slug": "read-chart", "title": "El mejor día de ventas", "locale": "es-MX", "subject": "mixed", "objectives": ["Leer la gráfica de barras de vasos vendidos por día y responder cuál fue el mejor día de la semana."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "read-chart-1", "xp": 10, "type": "read_chart", "hints": ["Cada barra muestra los vasos vendidos ese día. Fíjate en la altura."], "title": "La gráfica de Zara", "payload": {"chart": {"kind": "bar", "unit": "vasos", "series": [{"label": "Vasos vendidos", "points": [{"x": "Lun", "y": 8}, {"x": "Mar", "y": 12}, {"x": "Mié", "y": 5}, {"x": "Jue", "y": 15}, {"x": "Vie", "y": 10}]}]}, "questions": [{"id": "q1", "options": [{"id": "lunes", "text_md": "Lunes"}, {"id": "martes", "text_md": "Martes"}, {"id": "miercoles", "text_md": "Miércoles"}, {"id": "jueves", "text_md": "Jueves"}, {"id": "viernes", "text_md": "Viernes"}], "prompt_md": "¿Qué día vendió más vasos?"}]}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "Zara hizo una gráfica de barras con los vasos vendidos.", "difficulty": 1, "explanation_md": "El jueves se vendieron 15 vasos, la cantidad más alta. La barra más alta indica el mejor día de ventas.", "audio_segment_id": "read-chart-1.prompt"}], "schema_version": 1}', '{"read-chart-1": {"correct": {"q1": "jueves"}}}', '{"units": {"read-chart-1.hint.0": {"url": "http://localhost:4006/files/lesson-audio/30ce7b3e1c72b273166bc4b4174cae37938c296ef95855ecd1717c93a94f4c31.mp3", "hash": "94ff6368e38476c2975bba938d15faf20c7b3291e3c95a9a6086b7d3c084f7b0", "bytes": 28656, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/30ce7b3e1c72b273166bc4b4174cae37938c296ef95855ecd1717c93a94f4c31.mp3", "duration_ms": 4720}, "read-chart-1.prompt": {"url": "http://localhost:4006/files/lesson-audio/b58c3d461203fa1eb8f6b1d552cd21eac24c243fd68cfe3e083e96cbfac67b39.mp3", "hash": "1b608d7a78f4fe599050e7bf56f82ea9e4d8f8fc9bb043c0bce89a241e6376c6", "bytes": 21456, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/b58c3d461203fa1eb8f6b1d552cd21eac24c243fd68cfe3e083e96cbfac67b39.mp3", "duration_ms": 3520}, "read-chart-1.explanation": {"url": "http://localhost:4006/files/lesson-audio/699d7dbf25e05c9ac442b734899258f7aa818f85468cea0b6b4d42d0b6ec801e.mp3", "hash": "028897425ffe8eac42856c999feecbbc585928f5aa080cd11251b2abb3b07d6c", "bytes": 40608, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/699d7dbf25e05c9ac442b734899258f7aa818f85468cea0b6b4d42d0b6ec801e.mp3", "duration_ms": 6720}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0754f3ae-1483-4dd4-bc05-e1f681fd5bcf', 'es-MX', '1', '{"meta": {"cast": ["liruf"], "slug": "combo-narrativa-choice", "title": "El precio del día", "locale": "es-MX", "subject": "mixed", "objectives": ["Encadenar varias habilidades en una misma lección: escuchar la situación, decidir, calcular y cobrar."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-story-scene", "xp": 0, "type": "story_scene", "title": "Apertura del sábado", "payload": {"art": {"icon": "storefront", "tint": "primary", "image_url": "http://localhost:4006/files/lesson-images/87ed4acb8c047e05a6d9bfadd3dd29397dc301f8acb08a67969ce1f852a23bcf.webp"}, "action": "idle", "body_md": "Ayer descubrí que la máquina de propinas duplica: entra 1 moneda y salen 2. Hoy abro mi puesto y ¡hay 20 clientes en fila! Necesito $120 para un juego. ¿Qué precio pongo a cada vaso?", "emotion": "excited", "backdrop": "band", "character": "liruf"}, "narrator": {"emotion": "excited", "character": "liruf"}, "prompt_md": "¡Es sábado de limonada! Toca para ver la escena.", "difficulty": 1, "audio_segment_id": "s1-story-scene.prompt"}, {"id": "s2-quiz-mcq", "xp": 12, "type": "quiz_mcq", "hints": ["Piensa: ¿qué número multiplicado por 20 da 120?"], "title": "Elige el precio", "payload": {"options": [{"id": "op1", "text_md": "5 pesos", "rationale_md": "Con $5 cada vaso, 20 vasos dan solo $100. Faltarían $20 para el juego."}, {"id": "op2", "text_md": "6 pesos"}, {"id": "op3", "text_md": "8 pesos", "rationale_md": "Con $8 cada vaso, juntarías $160, mucho más de lo que necesita. Cobrar de más puede no ser justo."}], "shuffle": true}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf tiene 20 clientes y necesita $120 para un juego. ¿A qué precio debe vender cada vaso?", "difficulty": 2, "explanation_md": "Si vende 20 vasos a $6 cada uno, junta 20 × 6 = $120 exactos, lo que necesita Liruf para el juego.", "audio_segment_id": "s2-quiz-mcq.prompt"}], "schema_version": 1}', '{"s2-quiz-mcq": {"correct_option_id": "op2"}}', '{"units": {"s2-quiz-mcq.hint.0": {"url": "http://localhost:4006/files/lesson-audio/6066165cf55e8afce886adf0e1cae441679355f90c32459c2731e49ddf203c9c.mp3", "hash": "b6eff7427007fe4c735eaa7a7f7895818363f7a82440f248caa7124bb39e298f", "bytes": 24768, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/6066165cf55e8afce886adf0e1cae441679355f90c32459c2731e49ddf203c9c.mp3", "duration_ms": 4080}, "s2-quiz-mcq.prompt": {"url": "http://localhost:4006/files/lesson-audio/37b42155c3a1f70d36b3f8f8989672bffb71534a2cf1872bc05a001bda8b532e.mp3", "hash": "86b06bce2a107b13df5dd82892169db330cad74844827a1f3a2e0dda4eedb0b4", "bytes": 46944, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/37b42155c3a1f70d36b3f8f8989672bffb71534a2cf1872bc05a001bda8b532e.mp3", "duration_ms": 7760}, "s1-story-scene.body": {"url": "http://localhost:4006/files/lesson-audio/3e4d58d6b9ee607ab9e3015cfc5555897164aab1e798a2779c66021ebcaf9924.mp3", "hash": "46c6b057f8653b5802c2fcd16fc037994898766235d1e7f5733119a7d9eb63c4", "bytes": 86688, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/3e4d58d6b9ee607ab9e3015cfc5555897164aab1e798a2779c66021ebcaf9924.mp3", "duration_ms": 14400}, "s2-quiz-mcq.choices": {"url": "http://localhost:4006/files/lesson-audio/22c603411700876ba0b888c716744e7d9ead6d38c2ff6f57674a4d9d1a81e48d.mp3", "hash": "091464860aaa6cbef105203236304569fa20a63f20812263d27fa693a55d36d8", "bytes": 23328, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/22c603411700876ba0b888c716744e7d9ead6d38c2ff6f57674a4d9d1a81e48d.mp3", "duration_ms": 3840}, "s1-story-scene.prompt": {"url": "http://localhost:4006/files/lesson-audio/baa996ce794162eb824bc3e85586e19de8c1bba8dc6ad99ee62ddfd72bda112d.mp3", "hash": "0ed2a4785e5c49121d52c3320e9fbdec287b2e699ac4a56be3d359730fba34fe", "bytes": 23328, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/baa996ce794162eb824bc3e85586e19de8c1bba8dc6ad99ee62ddfd72bda112d.mp3", "duration_ms": 3840}, "s2-quiz-mcq.explanation": {"url": "http://localhost:4006/files/lesson-audio/81afbecba4b9f23eccabd903c146f09aaa36ade5ac6ac83942ba3ca7fdfb0d9f.mp3", "hash": "9d066295a5f901dec577631848b806bcc207cfc7dc4cfb39e05ae12228cabf75", "bytes": 57888, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/81afbecba4b9f23eccabd903c146f09aaa36ade5ac6ac83942ba3ca7fdfb0d9f.mp3", "duration_ms": 9600}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('97238255-709d-4d86-8930-3ea433f54f7d', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "checkpoint", "title": "La noche antes de abrir", "locale": "es-MX", "subject": "mixed", "objectives": ["Repasar la meta de 80 pesos, el precio de 5 pesos por vaso, y que la ganancia es lo que sobra después del costo.", "Reflexionar sobre el progreso hacia la meta."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-checkpoint", "xp": 0, "type": "checkpoint", "hints": [], "title": "Repaso de la gran idea", "payload": {"recap_md": "**La meta:** guitarra de 80 pesos. **Precio:** 5 pesos por vaso. **Ganancia:** lo que sobra después del costo, va al frasco de la guitarra.", "mood_prompt_md": "Liruf respira hondo. Mañana abre su puesto. ¿Ya se siente la guitarra más cerca?"}, "narrator": {"emotion": "happy", "character": "dina"}, "prompt_md": "La guitarra cuesta 80 pesos. Cada vaso de limonada cuesta 5 pesos. La ganancia de cada vaso va al frasco de la guitarra.", "difficulty": 1, "explanation_md": "Liruf ya tiene la meta de 80 pesos, el precio de 5 pesos por vaso, y sabe que la ganancia es lo que sobra tras pagar el costo.", "audio_segment_id": "s1-checkpoint.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-checkpoint.recap": {"url": "http://localhost:4006/files/lesson-audio/6938c0fbb88699175ea245df6b746e47294d71d979e72bd61e1a91825f3d3b65.mp3", "hash": "4ea76329c9c47428abb82b0f4fc43cb30b88a473806911455240d2440816e874", "bytes": 56016, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/6938c0fbb88699175ea245df6b746e47294d71d979e72bd61e1a91825f3d3b65.mp3", "duration_ms": 9280}, "s1-checkpoint.prompt": {"url": "http://localhost:4006/files/lesson-audio/e14c7ffa559ceb4e8c892a94301375baeec418725d196a3e16bc9d3a0640414e.mp3", "hash": "806d5901d1f82644c481bcd90ea0257247869a3b2f0ff1d5a69b397da5b06a45", "bytes": 57888, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/e14c7ffa559ceb4e8c892a94301375baeec418725d196a3e16bc9d3a0640414e.mp3", "duration_ms": 9600}, "s1-checkpoint.explanation": {"url": "http://localhost:4006/files/lesson-audio/cc16c4343cf6d0a2f57b1ef6917cc4f8fc516dd7944d3d735163d15d171e4ec2.mp3", "hash": "bdde760ae563f43321792cfdcfe2b0832068bcdb55a63832faeafc670d5c27c9", "bytes": 53136, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/cc16c4343cf6d0a2f57b1ef6917cc4f8fc516dd7944d3d735163d15d171e4ec2.mp3", "duration_ms": 8800}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7d51bf02-4dd4-4263-9e53-aa5ccb8a1e03', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "interest-peek", "title": "The piggy bank that rewards patience", "locale": "en-US", "subject": "money", "objectives": ["Deciding whether leaving money in a piggy bank that gives extra coins each week is better than spending it now.", "Predicting the total after waiting, understanding that it grows a little but doesn''t double."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-interest-peek", "xp": 10, "type": "interest_peek", "hints": ["Each week the piggy bank gives 2 coins of 1 peso. How many extra coins does it give in 2 weeks?", "Start with 20. Add the extra coins."], "title": "Leave the 20 or take them out now?", "payload": {"periods": 2, "currency": "MXN", "rate_pct": 10, "principal": 20, "prediction": {"kind": "choice", "options": [{"id": "opt1", "text_md": "Stays at 20"}, {"id": "opt2", "text_md": "24 dollars"}, {"id": "opt3", "text_md": "Almost 40 dollars"}]}}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf has 20 dollars saved for a guitar that costs 80. Rho tells him: ''If you keep your money in this special piggy bank, it gives you 2 extra 1-dollar coins each week for leaving it there.'' Liruf puts in his 20 dollars. He thinks: ''If I wait 2 weeks, will I have more or less than if I spend everything now?'' How much will Liruf have after 2 weeks?", "difficulty": 1, "explanation_md": "The piggy bank gives 2 coins of 1 dollar each week, so in 2 weeks it gives 4 extra dollars. 20 + 4 = 24. The money grows little by little toward the guitar! If he had spent everything now, he wouldn''t have those 4 extra dollars.", "audio_segment_id": "s1-interest-peek.prompt"}], "schema_version": 1}', '{"s1-interest-peek": {"value": 24, "tolerance": 1, "correct_option_id": "opt2"}}', '{"units": {"s1-interest-peek.hint.0": {"url": "http://localhost:4006/files/lesson-audio/4dd1d6ccf798aa5c97f749d1bbca0f429554a0e4ddb1067c914ccb754dd04ba7.mp3", "hash": "e3ea14dc8606d826d144eb6363d4368856117ed4d8f67dadc689bfe55e4c73ae", "bytes": 35424, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/4dd1d6ccf798aa5c97f749d1bbca0f429554a0e4ddb1067c914ccb754dd04ba7.mp3", "duration_ms": 5840}, "s1-interest-peek.hint.1": {"url": "http://localhost:4006/files/lesson-audio/7825f2189c180a4b293003f1af92126daa5268cd9d392ca5974129c790076a30.mp3", "hash": "f8bc08ef72f497b9b77b2307f928554ffa4b3b6cc12fc571460ffce20f85865a", "bytes": 14688, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/7825f2189c180a4b293003f1af92126daa5268cd9d392ca5974129c790076a30.mp3", "duration_ms": 2400}, "s1-interest-peek.prompt": {"url": "http://localhost:4006/files/lesson-audio/9f9c00569734ab927d477105d91b7fa638b29349b9e21f4b0475d98437fb6fe0.mp3", "hash": "8a9e8790bd658b56a8d71361c7e2330bd79a78bdf563043221ad4f46689b2c85", "bytes": 115488, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/9f9c00569734ab927d477105d91b7fa638b29349b9e21f4b0475d98437fb6fe0.mp3", "duration_ms": 19200}, "s1-interest-peek.explanation": {"url": "http://localhost:4006/files/lesson-audio/005c0228752fe743fe4aeac48b6ee8693d17a447c7266e1f24543a7bbecc407a.mp3", "hash": "daa97b2ded3a7663e072dc5c7e9c8d3543d55e7c0f139e1eee9f8808883280b7", "bytes": 86688, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/005c0228752fe743fe4aeac48b6ee8693d17a447c7266e1f24543a7bbecc407a.mp3", "duration_ms": 14400}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0c46648e-ff7a-4ad4-bf42-5829cc3fd1ac', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "story-dialogue", "title": "Ganar dinero empieza con una idea", "locale": "es-MX", "subject": "mixed", "objectives": ["Descubrir que el dinero se puede ganar ofreciendo algo que otros quieren", "Identificar una meta clara (guitarra de 80 pesos) como motivación para empezar"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-dialogue", "xp": 0, "type": "story_dialogue", "title": "La idea de Dina", "payload": {"lines": [{"action": "idle", "emotion": "thinking", "text_md": "Mira la guitarra de 80 pesos… está padrísima, pero no tengo dinero.", "character": "liruf"}, {"action": "idle", "emotion": "excited", "text_md": "¿Y si la ganas tú mismo? Podrías vender limonada en tu calle.", "character": "dina"}, {"action": "idle", "emotion": "surprised", "text_md": "¿Vender limonada? ¿Y la gente me pagaría?", "character": "liruf"}, {"action": "idle", "emotion": "encouraging", "text_md": "Claro. Cada vaso a 5 pesos. Si vendes 16 vasos, ¡tienes los 80!", "character": "dina"}, {"action": "idle", "emotion": "thinking", "text_md": "16 vasos… ¿cuántos son? ¿Alcanzarán?", "character": "liruf"}, {"action": "idle", "emotion": "happy", "text_md": "Piénsalo: 5 pesos cada uno. ¿Cuántos necesitas para juntar 80?", "character": "dina"}, {"action": "idle", "emotion": "happy", "text_md": "¡Sí! Voy a hacer un puesto este sábado.", "character": "liruf"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/611970697abec87e23f5a4fc2cd2b07a5dd181757e84cf3f5e0f0edc99deda8e.webp", "prompt_md": "Liruf y Dina platican frente a la tienda de música.", "difficulty": 1, "audio_segment_id": "s1-dialogue.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-dialogue.line.0": {"url": "http://localhost:4006/files/lesson-audio/5dfd01e96ee14370708d0bf0b835d478988773c14f3b1c5b3ffb2e3789a45fc3.mp3", "hash": "b370023092cc328a04af978d10c7f178352b08451875a6fd85e0f249fee813db", "bytes": 32976, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/5dfd01e96ee14370708d0bf0b835d478988773c14f3b1c5b3ffb2e3789a45fc3.mp3", "duration_ms": 5440}, "s1-dialogue.line.1": {"url": "http://localhost:4006/files/lesson-audio/eaa4ae71b47e9484040e66951ba8ba7befd3f43d9e957c0a99ba7af98427d5ec.mp3", "hash": "faee927fdaf8d4b8337032e289df0ff29bb65ca572bd6f6da149ab03a21eec41", "bytes": 26784, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/eaa4ae71b47e9484040e66951ba8ba7befd3f43d9e957c0a99ba7af98427d5ec.mp3", "duration_ms": 4400}, "s1-dialogue.line.2": {"url": "http://localhost:4006/files/lesson-audio/7e875381cf99299c749249f1d7fe679b1385e51e3bd355217b9039fc71ea0bc8.mp3", "hash": "3b16291ecb011800c80ae0e4f2d009a4f7302dc654a3b27008d91dd6cef672d8", "bytes": 19584, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/7e875381cf99299c749249f1d7fe679b1385e51e3bd355217b9039fc71ea0bc8.mp3", "duration_ms": 3200}, "s1-dialogue.line.3": {"url": "http://localhost:4006/files/lesson-audio/d2ef8e73855bee37d2f1ed5b25b33941d7694fd46c07b96789919649a11bb1bb.mp3", "hash": "71a067b76d7d4b3f5f817b14883d8360eda37f12f8903e333334b7905e2393f3", "bytes": 38304, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/d2ef8e73855bee37d2f1ed5b25b33941d7694fd46c07b96789919649a11bb1bb.mp3", "duration_ms": 6320}, "s1-dialogue.line.4": {"url": "http://localhost:4006/files/lesson-audio/56d8cbed92df6b223c6aee58680a9c42cf7a4704c7d3f173574452b36f88167c.mp3", "hash": "312ac2037712b56fd95955dc4c75bfa9b13d36b85cf8efb0f6a076dd8b3f1411", "bytes": 25776, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/56d8cbed92df6b223c6aee58680a9c42cf7a4704c7d3f173574452b36f88167c.mp3", "duration_ms": 4240}, "s1-dialogue.line.5": {"url": "http://localhost:4006/files/lesson-audio/dfc39fe4f774bd1685ddfc030705292b101bce3c398413a13eef7ddd9c2c5d42.mp3", "hash": "58938b876df729430fe851ffc857ff14efb17922fec58d13f62c40d42974d375", "bytes": 32976, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/dfc39fe4f774bd1685ddfc030705292b101bce3c398413a13eef7ddd9c2c5d42.mp3", "duration_ms": 5440}, "s1-dialogue.line.6": {"url": "http://localhost:4006/files/lesson-audio/fe96d552cae8709ea0bd1f04e5d813825767bbb1e2f16855e7994429160ea07f.mp3", "hash": "e3db86524b06295cc01f3e8065e9e73a4b4e740ff25a1a87d31f254314ad0198", "bytes": 20016, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/fe96d552cae8709ea0bd1f04e5d813825767bbb1e2f16855e7994429160ea07f.mp3", "duration_ms": 3280}, "s1-dialogue.prompt": {"url": "http://localhost:4006/files/lesson-audio/1220c453c9ab0fa17d344e2c06a21666c78334f9ef858d0e199ac47c933d5c1b.mp3", "hash": "c31d3a2b9cd3b99d0ab615165410bbb22a20cb533c80ed5fcf9a6c8ba3e6cf7c", "bytes": 21456, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/1220c453c9ab0fa17d344e2c06a21666c78334f9ef858d0e199ac47c933d5c1b.mp3", "duration_ms": 3520}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ec92e8b8-2834-4bff-88e8-59733b2e617a', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "repaso-quiz-mcq", "title": "Revisão Rápida: Lucro por Copo", "locale": "pt-BR", "subject": "mixed", "objectives": ["Revisar o cálculo do lucro por copo subtraindo o custo dos ingredientes do preço de venda."], "estimated_minutes": 1}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-mcq-review", "xp": 5, "type": "quiz_mcq", "title": "Revisão: Lucro por Copo", "payload": {"options": [{"id": "3", "text_md": "3 reais"}, {"id": "7", "text_md": "7 reais", "rationale_md": "Você somou o preço e o custo em vez de subtraí-los."}, {"id": "5", "text_md": "5 reais", "rationale_md": "Você pensou que todo o preço é lucro, mas é preciso subtrair os ingredientes."}, {"id": "2", "text_md": "2 reais", "rationale_md": "Você confundiu o custo dos ingredientes com o lucro."}], "shuffle": true}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf vende copos a R$5. Os ingredientes custam R$2. Quanto ele ganha por copo?", "difficulty": 1, "explanation_md": "Para calcular o lucro, subtraia o custo dos ingredientes (R$2) do preço de venda (R$5). Liruf ganha 3 reais por copo.", "audio_segment_id": "s1-mcq-review.prompt"}], "schema_version": 1}', '{"s1-mcq-review": {"correct_option_id": "3"}}', '{"units": {"s1-mcq-review.prompt": {"url": "http://localhost:4006/files/lesson-audio/1c3920877d24d391f78e484fdcfad1b15296ceea3ef129090df829cb8c6853fa.mp3", "hash": "dc684d8d712c46b9a5c76959a2249c79ed5de0cbe3eebe7da6d3d11ba59f2b98", "bytes": 44064, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/1c3920877d24d391f78e484fdcfad1b15296ceea3ef129090df829cb8c6853fa.mp3", "duration_ms": 7280}, "s1-mcq-review.choices": {"url": "http://localhost:4006/files/lesson-audio/23e2d9405749f3af83e5d71564c9c4cdf1938f2fff979f2ed5304f171299f336.mp3", "hash": "8be6e4be59556a0815df6e880c3053b997042fb896e9273b1bbe278a57a8ed58", "bytes": 30528, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/23e2d9405749f3af83e5d71564c9c4cdf1938f2fff979f2ed5304f171299f336.mp3", "duration_ms": 5040}, "s1-mcq-review.explanation": {"url": "http://localhost:4006/files/lesson-audio/72aa7756ca7176ed29f5c57edb618dd4a25dd6f19b4c1b712bfa63842c4bd663.mp3", "hash": "dcd81ce6deccaa75c745713156546df00f91b1198970a9d6fa0fa02cb9d6784e", "bytes": 61776, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/72aa7756ca7176ed29f5c57edb618dd4a25dd6f19b4c1b712bfa63842c4bd663.mp3", "duration_ms": 10240}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b831d60b-c492-4356-824e-7fce5f662a0a', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "match-pairs", "title": "The wind blew the prices away!", "locale": "en-US", "subject": "mixed", "objectives": ["Match each item at the stand with its correct price."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-pairs", "xp": 15, "type": "match_pairs", "payload": {"left": [{"id": "vaso", "text_md": "Cup of lemonade", "image_url": "http://localhost:4006/files/lesson-images/de7082b4496af7b12f4888e76445e5cfb458465527830cb545bb92581b18b305.webp"}, {"id": "jarra", "text_md": "Pitcher of lemonade", "image_url": "http://localhost:4006/files/lesson-images/e43bb1e9dbe6671ca67053ce7f3558eeac4a06c58adbbd6b548010f025170112.webp"}, {"id": "galleta", "text_md": "Cookie", "image_url": "http://localhost:4006/files/lesson-images/c337df20dd44ff2cdc5a5ae3f09ac6b6d4c33a9f28fa18486ae34d7e8a34f266.webp"}], "right": [{"id": "precio-5", "text_md": "5 dollars"}, {"id": "precio-20", "text_md": "20 dollars"}, {"id": "precio-3", "text_md": "3 dollars"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina sold these three things yesterday. Can you help her put the correct price on each one?", "difficulty": 2, "explanation_md": "The big pitcher gives more lemonade, that''s why it costs 20 dollars. The medium cup costs 5 dollars, and the little cookie only 3 dollars. They''re all in order now!"}], "schema_version": 1}', '{"s1-match-pairs": {"pairs": [["vaso", "precio-5"], ["jarra", "precio-20"], ["galleta", "precio-3"]]}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7f76a2de-27d1-4660-8203-c9ddad8fb861', 'es-MX', '1', '{"meta": {"cast": ["zara"], "slug": "estimate-slider", "title": "Estimar vasos de limonada", "locale": "es-MX", "subject": "mixed", "objectives": ["Estimar cantidades usando una barra deslizante", "Desarrollar sentido numérico al estimar antes de contar"], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-estimate-slider", "xp": 10, "type": "estimate_slider", "hints": ["Piensa en una jarra mediana: ni muy chica ni muy grande.", "Si cada vaso es de 5 pesos, la jarra no da para 100 vasos ni para 1 solo."], "title": "¿Cuántos vasos salen?", "payload": {"max": 20, "min": 1, "step": 1, "unit": "vasos", "scale": "linear"}, "narrator": {"emotion": "thinking", "character": "zara"}, "image_url": "http://localhost:4006/files/lesson-images/6fa16c00df447c5534253e58a22f50c32c5a883c1a4b6b3e1d7c7e0c29084000.webp", "prompt_md": "Zara llenó la jarra. Sin contar, desliza para estimar: ¿cuántos vasos de 5 pesos crees que salgan de esta jarra?", "difficulty": 1, "explanation_md": "La jarra tiene espacio para unos 8 vasos. Zara estimó bien al pensar en un número ni muy chico ni muy grande.", "audio_segment_id": "s1-estimate-slider.prompt"}], "schema_version": 1}', '{"s1-estimate-slider": {"value": 8, "full_credit_delta": 2, "zero_credit_delta": 5}}', '{"units": {"s1-estimate-slider.hint.0": {"url": "http://localhost:4006/files/lesson-audio/8db9e13e80dbc7239285e3ceff36545f6e2c36b5690e8ea8f926e5a9ff337e91.mp3", "hash": "025be524964f2cbef244ff9ad8f9691a4bb8b7a1b0962f6b78dfb457e48ec5ef", "bytes": 22896, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/8db9e13e80dbc7239285e3ceff36545f6e2c36b5690e8ea8f926e5a9ff337e91.mp3", "duration_ms": 3760}, "s1-estimate-slider.hint.1": {"url": "http://localhost:4006/files/lesson-audio/87575c592aa37360b3c998bdd949db4695f5fda74eecbbe92e0b356499b386c7.mp3", "hash": "48f7bc283dca5f55935e396af31079f794722b3a30b7dd870221f99b2aa3e32b", "bytes": 32976, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/87575c592aa37360b3c998bdd949db4695f5fda74eecbbe92e0b356499b386c7.mp3", "duration_ms": 5440}, "s1-estimate-slider.prompt": {"url": "http://localhost:4006/files/lesson-audio/1d5a0c9d645f05b2b6230f8dc3738bd14f151d9dc3013dcdbfa98f056ab24559.mp3", "hash": "cd1f5bfed748073e404a7ab7ce6c0fc67bb426f2d0b096f8c856c56d43db4933", "bytes": 47376, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/1d5a0c9d645f05b2b6230f8dc3738bd14f151d9dc3013dcdbfa98f056ab24559.mp3", "duration_ms": 7840}, "s1-estimate-slider.explanation": {"url": "http://localhost:4006/files/lesson-audio/2ec922410346c6494cdda5b40ddbb79b9e4f4222c23dfbf4ac26852f3d8f8290.mp3", "hash": "0427fde283ff9bb27769557c004b0a1e7756acc239be032be4699a8a084135d9", "bytes": 39168, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/2ec922410346c6494cdda5b40ddbb79b9e4f4222c23dfbf4ac26852f3d8f8290.mp3", "duration_ms": 6480}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4b45b37b-19f0-4fd5-99c2-0bcf9fabfbcd', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "machine-io", "title": "The Tip Machine", "locale": "en-US", "subject": "mixed", "objectives": ["Discover the rule of the tip machine: it doubles the number of coins that go in."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-machine-io", "xp": 10, "type": "machine_io", "hints": ["Look at the pattern: 1 goes in → 2 comes out, 2 go in → 4 come out. What operation turns the input number into the output number?"], "title": "The Tip Machine", "payload": {"options": [{"id": "a", "text_md": "4"}, {"id": "b", "text_md": "6"}, {"id": "c", "text_md": "8"}, {"id": "d", "text_md": "12"}], "examples": [{"in": 1, "out": 2}, {"in": 2, "out": 4}, {"in": 3, "out": 6}], "probe_in": 4}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Coins go in and more coins come out. If 1 goes in, 2 come out; if 2 go in, 4 come out; if 3 go in, 6 come out. What comes out if 4 go in?", "difficulty": 1, "explanation_md": "The machine doubles: each coin that goes in turns into two. That''s why when you put in 4, 8 coins come out (4 × 2 = 8).", "audio_segment_id": "s1-machine-io.prompt"}], "schema_version": 1}', '{"s1-machine-io": {"value": 8, "correct_option_id": "c"}}', '{"units": {"s1-machine-io.hint.0": {"url": "http://localhost:4006/files/lesson-audio/4dc28b5cc91bddcbfda92fd859ca5809ec4dbc0bb5419a9bbded6ebae98b1a71.mp3", "hash": "1bd20d988f0ad9071b27cd892f3a362f798f1bdb2f9557c762e05a5b2c474088", "bytes": 47376, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/4dc28b5cc91bddcbfda92fd859ca5809ec4dbc0bb5419a9bbded6ebae98b1a71.mp3", "duration_ms": 7840}, "s1-machine-io.prompt": {"url": "http://localhost:4006/files/lesson-audio/4abbfb26ece331e69f11a10de954498db5c3e2ac52203bbaf6dc8ff4ba817e62.mp3", "hash": "b4e805b275ccbff245b97044ffa3f8723adaba4283012523cc59d4a03d580502", "bytes": 54576, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/4abbfb26ece331e69f11a10de954498db5c3e2ac52203bbaf6dc8ff4ba817e62.mp3", "duration_ms": 9040}, "s1-machine-io.explanation": {"url": "http://localhost:4006/files/lesson-audio/c2e44809b5f8048d6f2d1a45f4bc15a55062145aa12290cd0765b60ec762857a.mp3", "hash": "22a986c19a561d54ddcc589bd949207ac1d8057cee25214f76746746d7beaedd", "bytes": 48384, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/c2e44809b5f8048d6f2d1a45f4bc15a55062145aa12290cd0765b60ec762857a.mp3", "duration_ms": 8000}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f75b3e23-fb31-40cf-9b58-e918769e51b9', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "yes-no-cases", "title": "Decir sí o no, caso por caso", "locale": "es-MX", "subject": "mixed", "objectives": ["Decir sí o no, caso por caso: ¿este gasto ayuda al puesto? (más limones: sí; un juguete nuevo hoy: no, todavía no)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-yes-no-cases", "xp": 10, "type": "yes_no_cases", "hints": ["Piensa: ¿esto ayuda a vender más limonada o a guardar el dinero?", "Un gasto que ayuda al puesto es algo que necesitas para hacer o vender limonada."], "title": "¿Sí o no?", "payload": {"cases": [{"id": "c1", "text_md": "Comprar más limones para hacer más limonada.", "image_url": "http://localhost:4006/files/lesson-images/38c930bc0a4c08926579651c33a929f604135614a87b0833c005da2524c346ba.webp"}, {"id": "c2", "text_md": "Comprar un juguete nuevo en la tienda.", "image_url": "http://localhost:4006/files/lesson-images/72c17d2f21ca0bf7e11424339bb06eef1736569f38e07aeb1dedbd94a6219b1d.webp"}, {"id": "c3", "text_md": "Comprar un cartel bonito para el puesto.", "image_url": "http://localhost:4006/files/lesson-images/b16ad3e2eda6aac0bbb0413360a1ff09a985eb43bf33cf8035321977e052f0f5.webp"}, {"id": "c4", "text_md": "Comprar dulces para ti.", "image_url": "http://localhost:4006/files/lesson-images/5a881b9f0e33c520ce2e8f11f687286b8dd38147ba887d435bf2af5a3ba6bb1e.webp"}], "rule_md": "Di **sí** si el gasto ayuda al puesto de limonada (más limones, un cartel, una jarra nueva). Di **no** si es algo que no necesitas hoy (un juguete, un videojuego, dulces)."}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf tiene su lista. Toca cada caso: ¿este gasto ayuda al puesto de limonada?", "difficulty": 1, "explanation_md": "Comprar más limones ayuda a hacer más limonada y vender más. Un juguete nuevo no ayuda al puesto hoy.", "audio_segment_id": "s1-yes-no-cases.prompt"}], "schema_version": 1}', '{"s1-yes-no-cases": {"applies_ids": ["c1", "c3"]}}', '{"units": {"s1-yes-no-cases.hint.0": {"url": "http://localhost:4006/files/lesson-audio/12c7c36c9f9eb0041d58cf399c59d5b31c223e93b0db3877495f5f083bfe5bc6.mp3", "hash": "044b07769748e6c780414cee4bfbb179fa9cb31b50d74f725faecb8a35623810", "bytes": 28224, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/12c7c36c9f9eb0041d58cf399c59d5b31c223e93b0db3877495f5f083bfe5bc6.mp3", "duration_ms": 4640}, "s1-yes-no-cases.hint.1": {"url": "http://localhost:4006/files/lesson-audio/e03f0b99a9be35adee9988fdd1abafabdb22079f420d7b942f4893839efce75a.mp3", "hash": "b373c41190257d5c22057a61e38aeb04ee70bc674d502eb0129369592b2751aa", "bytes": 31536, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/e03f0b99a9be35adee9988fdd1abafabdb22079f420d7b942f4893839efce75a.mp3", "duration_ms": 5200}, "s1-yes-no-cases.prompt": {"url": "http://localhost:4006/files/lesson-audio/6124409cb388b93a708e939947c2b538e657bd2a58fda8fd2038ea6f8658b371.mp3", "hash": "c4810992d41b00c8001a5aaf5384e1c3c0ad5b222a102e67d0a76005b4349edb", "bytes": 35424, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/6124409cb388b93a708e939947c2b538e657bd2a58fda8fd2038ea6f8658b371.mp3", "duration_ms": 5840}, "s1-yes-no-cases.choices": {"url": "http://localhost:4006/files/lesson-audio/883ab86c67ae28ef35b2c45624482702d81beaf46947bf62c81b1b3590518f4a.mp3", "hash": "d2f47a8d80604ad3c9f040b282a3ae6b0697cbf3e96d1252665c59e9bdc64ef7", "bytes": 60768, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/883ab86c67ae28ef35b2c45624482702d81beaf46947bf62c81b1b3590518f4a.mp3", "duration_ms": 10080}, "s1-yes-no-cases.explanation": {"url": "http://localhost:4006/files/lesson-audio/b3e50b70ac8ee1449c8bb210a49a8ffc821224e4214af033239974597d7f8b99.mp3", "hash": "bd0aaf18e2bddc9926eb870663bc1c58238f14614ace606eee807b9a6e0832e1", "bytes": 44496, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/b3e50b70ac8ee1449c8bb210a49a8ffc821224e4214af033239974597d7f8b99.mp3", "duration_ms": 7360}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a6e01e69-b662-4c31-9021-3de01a60bbc7', 'es-MX', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "odd-one-out", "title": "El ingrediente extraño", "locale": "es-MX", "subject": "mixed", "objectives": ["Detectar cuál NO es un ingrediente de la limonada (limones, azúcar, agua… ¿y una pelota?): separar lo que sí cuesta dinero producir."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-odd-ingredient", "xp": 10, "type": "odd_one_out", "hints": ["Piensa en lo que necesitas para hacer limonada: limones, agua, azúcar...", "La pelota no se come ni se bebe, no es para la limonada."], "title": "El ingrediente extraño", "payload": {"items": [{"id": "limones", "text_md": "Limones", "image_url": "http://localhost:4006/files/lesson-images/cdf4e1fb2d740d9b9f24ce284dbdccac17fe3dea62e7d624535c15b94fdbf951.webp"}, {"id": "azucar", "text_md": "Azúcar", "image_url": "http://localhost:4006/files/lesson-images/1f3d4feb4d5a87ceba75a236aebbb54959e98f39ec7f8285d0d0a2f3ae418fe5.webp"}, {"id": "agua", "text_md": "Agua", "image_url": "http://localhost:4006/files/lesson-images/bd6a7dfc88fd007c7d8b8fdef228bd895a2ac60a311b5f7344094833df979be5.webp"}, {"id": "pelota", "text_md": "Pelota", "image_url": "http://localhost:4006/files/lesson-images/3e0c38763c34a64542d91e25aac80e5c4d625d4507d53e4d4f2a2986867bd2c0.webp"}], "reasons": [{"id": "r1", "text_md": "No es un ingrediente para hacer limonada."}, {"id": "r2", "text_md": "Sí es un ingrediente de la limonada."}]}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Rho tiene $10 para hacer limonada. ¿Qué NO necesita comprar?", "difficulty": 1, "explanation_md": "La pelota no es un ingrediente de la limonada, así que no cuesta dinero para hacerla. Los limones, el agua y el azúcar sí cuestan dinero.", "audio_segment_id": "s1-odd-ingredient.prompt"}], "schema_version": 1}', '{"s1-odd-ingredient": {"odd_item_id": "pelota", "correct_reason_id": "r1"}}', '{"units": {"s1-odd-ingredient.hint.0": {"url": "http://localhost:4006/files/lesson-audio/908aa8fd51490b6ab31ed5e4f064f355c5e5e2510dd99f7d3842bfca8fb0ed8e.mp3", "hash": "1032cbf84275fc8ac56611704850fac8dcad37cb815b819118054a82fbc0a252", "bytes": 37296, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/908aa8fd51490b6ab31ed5e4f064f355c5e5e2510dd99f7d3842bfca8fb0ed8e.mp3", "duration_ms": 6160}, "s1-odd-ingredient.hint.1": {"url": "http://localhost:4006/files/lesson-audio/cc8cf3fdcf278e772a8ec2c4f3217d061c6e81eccd1db6a36209bc9c53295325.mp3", "hash": "207b413000e2638609ac67092b2597aba43e1b547a61b9239811577339f7e3d5", "bytes": 24768, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/cc8cf3fdcf278e772a8ec2c4f3217d061c6e81eccd1db6a36209bc9c53295325.mp3", "duration_ms": 4080}, "s1-odd-ingredient.prompt": {"url": "http://localhost:4006/files/lesson-audio/61cc37addc77d53d2918c539be088700fa9c3e91d986f9233aa8592d4740c4b5.mp3", "hash": "4cd954e31ab94758b3d60f54df7a89d5e8f55ff413542e70529152c4ab2779e2", "bytes": 31536, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/61cc37addc77d53d2918c539be088700fa9c3e91d986f9233aa8592d4740c4b5.mp3", "duration_ms": 5200}, "s1-odd-ingredient.choices": {"url": "http://localhost:4006/files/lesson-audio/b16660be357759bd0b3f08ff1e96b1644cabb9d08b85d17d2fddb23ce06aae02.mp3", "hash": "a1a2bef575005d71f01810e0c5e01bc1f3b3ffeba747c0b6eca175da695f8cc5", "bytes": 21456, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/b16660be357759bd0b3f08ff1e96b1644cabb9d08b85d17d2fddb23ce06aae02.mp3", "duration_ms": 3520}, "s1-odd-ingredient.explanation": {"url": "http://localhost:4006/files/lesson-audio/deab1a047cbc53b7c19ee6f1043eaa97853979aeebe686e9c7a36639ea099cbf.mp3", "hash": "8b1a8d7335831c56f288f9db9602bb2df0fd57ff2c2fce0868d03a86d562e830", "bytes": 61776, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/deab1a047cbc53b7c19ee6f1043eaa97853979aeebe686e9c7a36639ea099cbf.mp3", "duration_ms": 10240}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('105d5cdf-c98a-4076-a3ed-440deb643d64', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "would-you-rather", "title": "Dilema del vendedor", "locale": "es-MX", "subject": "mixed", "objectives": ["Tomar decisiones entre ganancias inmediatas y ahorro futuro."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "wyr1-dilema", "xp": 10, "type": "would_you_rather", "title": "Dilema del vendedor", "payload": {"a": {"icon": "cake", "text_md": "Gastar 10 en un dulce ahora", "image_url": "http://localhost:4006/files/lesson-images/6e254b4a7884f4b83e802b8b66d58bd676b50f8e4d017d6e356e8552ef586733.webp"}, "b": {"icon": "savings", "text_md": "Esperar 1 semana y recibir 5 pesos", "image_url": "http://localhost:4006/files/lesson-images/576afcb39d9a5b7d4b0607344a5a83ae571add74c27441044fc7af0104fdcc97.webp"}, "followup_md": "¿Cómo llegaste a tu decisión? Comparte tus cuentas con Dina."}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Dina tiene 20 pesos; quiere un libro de 25. Hoy puede gastar 10 en un dulce, o esperar una semana y tener 5 más. ¿Qué debe hacer?", "difficulty": 2, "explanation_md": "A veces esperar nos permite alcanzar una meta mayor. Dina necesita 25 pesos para su libro; al no gastar y ahorrar, logra lo justo para comprarlo.", "audio_segment_id": "wyr1-dilema.prompt"}], "schema_version": 1}', '{"wyr1-dilema": {"qualities": {"a": 0, "b": 100}, "reveal_md": "Si Dina gasta 10 en un dulce, le quedarán 10. Con los 5 extra después, tendrá 15, no suficiente para el libro (25). Si espera, juntará 20+5=25 y podrá comprarlo. ¡Esperar es la mejor opción!"}}', '{"units": {"wyr1-dilema.prompt": {"url": "http://localhost:4006/files/lesson-audio/f1e798959dee5d15a8e6876c4d399ee7d01cf3379cc702a5cfd18fe4111e21bf.mp3", "hash": "612efd755c02033ba29ffa21d239fb830c6cbba5fc0eaddc976af79ccf3f2406", "bytes": 65088, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/f1e798959dee5d15a8e6876c4d399ee7d01cf3379cc702a5cfd18fe4111e21bf.mp3", "duration_ms": 10800}, "wyr1-dilema.choices": {"url": "http://localhost:4006/files/lesson-audio/7f2d59e5f14691649f96d1125bd542e32521f74f8762fd3c930599a99b12cf96.mp3", "hash": "262bcd29f832e97b5401ae071e1642628520fc58881bbc1833735bd6c9dc71eb", "bytes": 35856, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/7f2d59e5f14691649f96d1125bd542e32521f74f8762fd3c930599a99b12cf96.mp3", "duration_ms": 5920}, "wyr1-dilema.explanation": {"url": "http://localhost:4006/files/lesson-audio/2d34040a810b305528c5c80e22fc07b45f0dbb34384b0e3850d222d8d382232c.mp3", "hash": "b8cc768c394c32e6ad970b32bc551a066e886f345fd4e2a1b8bca04883363a4a", "bytes": 64224, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/2d34040a810b305528c5c80e22fc07b45f0dbb34384b0e3850d222d8d382232c.mp3", "duration_ms": 10640}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4dcc7a9f-f2f6-4b40-abd4-a522d168e446', 'es-MX', '1', '{"meta": {"cast": ["zara"], "slug": "flash-match", "title": "¡Ayuda a Zara a ordenar su puesto!", "locale": "es-MX", "subject": "mixed", "objectives": ["Relacionar palabras del puesto (ahorro, costo, ganancia) con sus ejemplos concretos (alcancía, limones, lo que sobra) para entenderlas rápidamente."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-flash-match", "xp": 5, "type": "flash_match", "title": "¡Ayuda a Zara!", "payload": {"left": [{"id": "left-ahorro", "text_md": "Ahorro", "image_url": "http://localhost:4006/files/lesson-images/0ffd40525f559f89a315c28cefae3c02f0b06eb86bb5bca46e6212cc64565c29.webp"}, {"id": "left-costo", "text_md": "Costo", "image_url": "http://localhost:4006/files/lesson-images/0d509723d405ac4490776ca106a380b1285ea97752afcbfb4031a751741ffb42.webp"}, {"id": "left-ganancia", "text_md": "Ganancia", "image_url": "http://localhost:4006/files/lesson-images/9d42d4f12229d80a4c4fabb3876248a54911c4f019921e8a6490615204aadcc2.webp"}], "right": [{"id": "right-alcancia", "text_md": "Alcancía"}, {"id": "right-limones", "text_md": "Limones"}, {"id": "right-sobrantes", "text_md": "Lo que sobra"}], "seconds": 25}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Zara terminó su día. Tiene su alcancía, los limones y unas monedas. Relaciona cada concepto con lo que hizo.", "difficulty": 1, "explanation_md": "¡Bien! El **ahorro** es el dinero que Zara guarda en su alcancía. El **costo** es lo que pagó por los limones. La **ganancia** es lo que le sobra después de pagar todo. Si pensaste que el costo era lo que sobra, recuerda: el costo es un gasto, no una ganancia.", "audio_segment_id": "s1-flash-match.prompt"}], "schema_version": 1}', '{"s1-flash-match": {"pairs": [["left-ahorro", "right-alcancia"], ["left-costo", "right-limones"], ["left-ganancia", "right-sobrantes"]]}}', '{"units": {"s1-flash-match.prompt": {"url": "http://localhost:4006/files/lesson-audio/94b4e672c8c59c8cfb0759f91bc87cf19a8566a89f6907a0a5590d2fc391b87c.mp3", "hash": "dbc496836518f40f2b89e6c9934eeb77ac044451e519ec458057375ce2e89016", "bytes": 43488, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/94b4e672c8c59c8cfb0759f91bc87cf19a8566a89f6907a0a5590d2fc391b87c.mp3", "duration_ms": 7200}, "s1-flash-match.explanation": {"url": "http://localhost:4006/files/lesson-audio/a9c9cfe9dcff66cde6cd0fec6a9ccc68d58d78887ae8c4e0b1403fcb9275c279.mp3", "hash": "e3a4ed01452c834c09a7da27375e5ee0390cfc5117aeacf1158657f2ac6bb8af", "bytes": 96336, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/a9c9cfe9dcff66cde6cd0fec6a9ccc68d58d78887ae8c4e0b1403fcb9275c279.mp3", "duration_ms": 16000}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
